def resource_path(filename):
    """مسار ملف مرفق مع البرنامج، يعمل في التشغيل العادي وداخل ملف exe معاً"""
    base = getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(__file__)))
    return os.path.join(base, filename)


def screen_work_area(widget):
    """مساحة العمل الفعلية بالبكسل (الشاشة الرئيسية بلا شريط المهام): (x, y, العرض, الارتفاع)"""
    if sys.platform.startswith("win"):
        try:
            import ctypes
            from ctypes import wintypes
            rect = wintypes.RECT()
            if ctypes.windll.user32.SystemParametersInfoW(0x0030, 0, ctypes.byref(rect), 0):   # SPI_GETWORKAREA
                return rect.left, rect.top, rect.right - rect.left, rect.bottom - rect.top
        except Exception:
            pass
    return 0, 0, widget.winfo_screenwidth(), max(400, widget.winfo_screenheight() - 48)


# أصغر مساحة عمل (بوحدات الواجهة) صُمّمت لها الشاشات، وأدنى تصغير مقبول للقراءة
DESIGN_WORK_AREA = (1280, 680)
MIN_UI_FIT = 0.7


def screen_fit_factor(win):
    """نسبة تصغير الواجهة لتتسع لها الشاشة كاملة (١٫٠ = بلا تصغير).

    حاسوب محمول ١٣٦٦×٧٦٨ بتكبير عرض ١٥٠٪ لا يتسع فعلياً إلا لـ ٩١٠×٥١٢ من
    وحدات الواجهة: كان زر «دخول» يقع تحت حافة الشاشة، وجدول المبيعات بلا صف
    واحد ظاهر. النسبة تُحسب من مساحة العمل (بلا شريط المهام) مقسومة على تكبير
    العرض، ولا تنزل عن ٠٫٧ — أي ما يقارب حجم الخط على شاشة عادية بلا تكبير.
    """
    try:
        dpi = float(ctk.ScalingTracker.get_window_scaling(win)) or 1.0
        _x, _y, w, h = screen_work_area(win)
        fit = min(w / dpi / DESIGN_WORK_AREA[0], h / dpi / DESIGN_WORK_AREA[1])
    except Exception:
        return 1.0
    return max(MIN_UI_FIT, min(1.0, round(fit, 2)))


def apply_screen_fit(win):
    """يطبّق نسبة التصغير على كل عناصر الواجهة قبل بنائها (مرة واحدة لكل قيمة)"""
    fit = screen_fit_factor(win)
    try:
        if abs(float(ctk.ScalingTracker.widget_scaling) - fit) > 0.005:
            ctk.set_widget_scaling(fit)
    except Exception:
        pass
    return fit

def fill_work_area(win):
    """بديل أخير: حجم النافذة = مساحة العمل (الشاشة بلا شريط المهام) بالبكسل الفعلي.

    wm_geometry مباشرة لا geometry: customtkinter يضرب أبعاد geometry في
    تكبير العرض، فكان البديل القديم يُخرج النافذة عن الشاشة بتكبير ١٢٥٪.
    """
    try:
        x, y, w, h = screen_work_area(win)
        tk.Tk.wm_geometry(win, f"{w}x{h}+{x}+{y}")
    except Exception:
        pass


def maximize_window(win):
    """يكبّر النافذة لملء الشاشة المتاحة على أي جهاز وأي دقة وأي تكبير للعرض.

    يُطلب التكبير في كل نداء ولا نكتفي بسؤال النافذة عن حالتها: ويندوز قد
    يسجّلها «مكبّرة» وهي لم تُكبَّر فعلاً إن طُلب التكبير قبل ظهورها.
    """
    try:
        win.state("zoomed")
        return
    except Exception:
        pass
    try:
        win.attributes("-zoomed", True)
        return
    except Exception:
        pass
    fill_work_area(win)


def ensure_fills_screen(win):
    """بعد الظهور: إن لم تملأ النافذة الشاشة فعلاً تُكبَّر من جديد، وإلا تُضبط
    على مساحة العمل مباشرة — فتظهر كاملة على أي جهاز"""
    try:
        if win.state() in ("iconic", "withdrawn"):
            return          # مصغّرة في شريط المهام: لا تُكبَّر رغماً عن المستخدم
        x, y, w, h = screen_work_area(win)
        if win.winfo_width() >= w * 0.9 and win.winfo_height() >= h * 0.85:
            return
        # ويندوز قد يعدّها «مكبّرة» وهي بحجمها الصغير، فيُتجاهل طلب تكبيرها
        # من جديد: تُعاد لحالتها العادية أولاً ثم تُكبَّر
        try:
            if win.state() == "zoomed":
                win.state("normal")
        except Exception:
            pass
        maximize_window(win)
        win.update_idletasks()
        if win.winfo_width() < w * 0.9 or win.winfo_height() < h * 0.85:
            fill_work_area(win)
    except Exception:
        pass


def keep_maximized_after_show(win):
    """يعيد التكبير بعد أن تُظهر customtkinter النافذة فعلاً.

    المكتبة على ويندوز تُخفي النافذة عند إنشائها ثم تُظهرها عند mainloop بأمر
    «الحجم العادي» — فتفقد النافذة التي كُبّرت أثناء بنائها تكبيرها وتظهر
    بحجمها الصغير على بعض الأجهزة. التكبير يُعاد بعد الظهور، ثم يُتحقَّق منه.
    """
    win._opened_at = time.monotonic()
    for ms in (60, 350):
        win.after(ms, lambda: maximize_window(win))
    win.after(1100, lambda: ensure_fills_screen(win))


class StableWindowMixin:
    """يمنع customtkinter من تصغير النافذة عند اكتشاف تكبير عرض مختلف.

    إن اكتُشف تكبير للشاشة بعد ظهور النافذة (جهاز بشاشتين بتكبيرين مختلفين،
    أو تغيير التكبير من إعدادات ويندوز) كانت المكتبة تفرض على النافذة حجمها
    الابتدائي ٦٠٠×٥٠٠ وتثبّته حداً أدنى وأعلى — فتنكمش شاشة الدخول والنظام
    المكبّر. هنا تُحدَّث مقاييس العناصر كما هي، ويبقى حجم النافذة كما هو،
    ثم تُصحَّح النافذة بدالة _after_scaling_change الخاصة بها.
    """
    def _set_scaling(self, new_widget_scaling, new_window_scaling):
        super(ctk.CTk, self)._set_scaling(new_widget_scaling, new_window_scaling)
        hook = getattr(self, "_after_scaling_change", None)
        if hook is not None:
            try:
                self.after(150, hook)
            except Exception:
                pass


def shade_color(hex_color, factor):
    """يغمّق اللون (factor < 1) أو يفتّحه (factor > 1) بالنسبة نفسها لكل قناة"""
    rgb = [int(hex_color[i:i + 2], 16) for i in (1, 3, 5)]
    return "#" + "".join(f"{max(0, min(255, round(v * factor))):02X}" for v in rgb)


def logo_tint_for(color, darker=0.80, lighter=1.15):
    """تدرّج (غامق، فاتح) حول لون واحد، متوسطه على الشعار = اللون نفسه تقريباً:
    تبقى ظلال الشريط وانحناءاته، ويُرى الشعار كله بذلك اللون"""
    return shade_color(color, darker), shade_color(color, lighter)


def crisp_ctk_image(light, dark=None, size=(1, 1), widget=None):
    """صورة واجهة حادّة: تُصغَّر مسبقاً بفلتر LANCZOS إلى بكسلات العرض الفعلية
    (الحجم × تكبير ويندوز)، فلا تعيد المكتبة تحجيمها بفلترها الأنعم — الشعار
    وحروفه الدقيقة تبقى حادّة على كل شاشة وكل نسبة تكبير."""
    try:
        s = float(ctk.ScalingTracker.get_widget_scaling(widget)) if widget is not None else 1.0
    except Exception:
        s = 1.0
    px = (max(1, round(size[0] * s)), max(1, round(size[1] * s)))
    try:
        lanczos = Image.Resampling.LANCZOS
    except AttributeError:
        lanczos = Image.LANCZOS

    def prep(img):
        if img is None or img.size == px:
            return img
        try:
            return img.resize(px, lanczos, reducing_gap=3.0)
        except Exception:
            return img
    light_px = prep(light)
    return ctk.CTkImage(light_image=light_px, dark_image=prep(dark) if dark is not None else light_px,
                        size=size)


def tint_logo(img, dark, light, opacity=1.0):
    """يعيد تلوين الشعار بتدرّج لونين مع حفظ شفافيته وتفاصيل إضاءته.

    السطوع في الشعار الأصلي (الذهبي) يصير تدرّجاً من dark إلى light، فتبقى
    ظلال الشريط وانحناءاته كما هي بلون جديد.
    """
    from PIL import ImageOps
    img = img.convert("RGBA")
    alpha = img.getchannel("A")
    lum = img.convert("L")
    try:
        # التباين يُحسب من بكسلات الشعار وحدها (الشفافة سوداء وتُفسد المدى)
        mask = alpha.point(lambda v: 255 if v > 32 else 0)
        lum = ImageOps.autocontrast(lum, cutoff=1, mask=mask)
    except TypeError:          # Pillow قديم بلا وسيط mask
        lum = ImageOps.autocontrast(lum, cutoff=1)
    out = ImageOps.colorize(lum, black=dark, white=light).convert("RGBA")
    out.putalpha(alpha.point(lambda v: int(v * opacity)) if opacity < 1 else alpha)
    return out


def apply_app_icon(window):
    """يضبط أيقونة البرنامج على النافذة (شعار جاديت).

    يُستدعى لكل نافذة رئيسية: ويندوز يأخذ أيقونة شريط المهام من النافذة
    الأولى، وأيقونة الملف التنفيذي تُضبط عند البناء بـ --icon.
    """
    try:
        ico = resource_path("jadeite.ico")
        if os.path.exists(ico):
            window.iconbitmap(ico)
    except Exception:
        pass   # غياب الأيقونة لا يمنع تشغيل البرنامج


def reset_local_cache(db_path):
    """يمسح النسخة المحلية المؤقتة قبل السحب من السحابة (نسخة المدير فقط).

    الخطر الذي يمنعه: السحب دمج لا استبدال، فلو بقيت نسخة قديمة على جهاز
    المدير لظهرت له حركة حذفها العميل فعلياً، وقد يبني عليها قراراً محاسبياً.
    الحذف آمن هنا: هذه القاعدة ذاكرة عرض مؤقتة، ومصدر الحقيقة السحابة وجهاز
    العميل — لا تُحذف بيانات أحد.
    """
    for suffix in ("", "-journal", "-wal", "-shm"):
        path = db_path + suffix
        try:
            if os.path.exists(path):
                os.remove(path)
        except Exception as e:
            log_cloud_error("تعذّر تنظيف النسخة المؤقتة", e)


def migrate_legacy_file(filename, target_path):
    """ينقل أي ملف قديم كان يُنشأ بجوار البرنامج إلى المجلد المنظّم الجديد (نسخ آمن، بدون فقدان بيانات)"""
    if os.path.exists(target_path):
        return True
    for folder in {os.getcwd(), get_app_base_dir()}:
        try:
            old = os.path.join(folder, filename)
            if os.path.exists(old) and os.path.abspath(old) != os.path.abspath(target_path):
                shutil.copy2(old, target_path)
                return True
        except Exception:
            pass
    return False


def cleanup_old_files(folder, keep=100, suffix=""):
    """يبقي أحدث عدد من الملفات في مجلد ويحذف الأقدم، حتى لا تتراكم الملفات بلا حدود"""
    try:
        files = [os.path.join(folder, f) for f in os.listdir(folder)
                 if f.lower().endswith(suffix) and os.path.isfile(os.path.join(folder, f))]
        files.sort(key=lambda p: os.path.getmtime(p))
        while len(files) > keep:
            try:
                os.remove(files.pop(0))
            except Exception:
                pass
    except Exception:
        pass

try:
    from supabase import create_client as _sb_create_client
    SUPABASE_AVAILABLE = True
except ImportError:
    SUPABASE_AVAILABLE = False

CLOUD_LOG_FILE = os.path.join(LOGS_DIR, "cloud_errors.log")


def log_cloud_error(context: str, error) -> None:
    """يسجّل أي خطأ متعلق بالسحابة في ملف محلي (عشان ميضيعش صامت في نسخة exe بدون شاشة كونسول)"""
    try:
        with open(CLOUD_LOG_FILE, "a", encoding="utf-8") as f:
            f.write(f"[{datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] {context}: {error}\n")
    except Exception:
        pass
    print(f"{context}: {error}")


def hash_password(raw_password: str) -> str:
    """تشفير بسيط لكلمة المرور — لا تُخزَّن كلمة المرور الحقيقية أبداً بالسحابة"""
    return hashlib.sha256(raw_password.encode("utf-8")).hexdigest()


_SB_CLIENTS = {}
_SB_LOCK = threading.Lock()


def _shared_supabase_client(kind, key, timeout):
    """عميل سحابي واحد لكل نوع، يُعاد استخدامه طوال تشغيل البرنامج.

    كان كل طلب يُنشئ عميلاً جديداً — أي اتصالاً ومصافحة تشفير جديدين (نصف
    ثانية تقريباً على الإنترنت العادي) — والدخول وحده يرسل عدة طلبات.
    العميل الواحد يُبقي الاتصال مفتوحاً فتصل الطلبات التالية فوراً، وهو آمن
    للاستخدام من أكثر من خيط. والمهلة محدّدة: الافتراضي في المكتبة ١٢٠ ثانية،
    فكان ضعف الإنترنت يُظهر البرنامج معلّقاً دقيقتين.
    """
    if not SUPABASE_AVAILABLE or not key:
        return None
    with _SB_LOCK:
        client = _SB_CLIENTS.get(kind)
        if client is None:
            try:
                try:
                    from supabase import ClientOptions
                    client = _sb_create_client(SUPABASE_URL, key,
                                               options=ClientOptions(postgrest_client_timeout=timeout))
                except (ImportError, TypeError):
                    client = _sb_create_client(SUPABASE_URL, key)
                try:
                    client.postgrest       # يُجهَّز الآن داخل القفل لا عند أول طلبين متزامنين
                except Exception:
                    pass
            except Exception:
                return None
            _SB_CLIENTS[kind] = client
        return client


def get_supabase_public_client():
    """عميل سحابي بصلاحيات محدودة — يُستخدم لدخول العملاء ورفع/تنزيل نسخهم فقط (آمن للتوزيع)"""
    return _shared_supabase_client("public", SUPABASE_PUBLISHABLE_KEY, 60)


def get_supabase_login_client():
    """عميل التحقق من الدخول: مهلة قصيرة، فانقطاع الإنترنت تظهر رسالته خلال ثوانٍ"""
    return _shared_supabase_client("login", SUPABASE_PUBLISHABLE_KEY, 12)


def prewarm_supabase_clients():
    """يُجهّز عميلَي السحابة في الخلفية أثناء شاشة الترحيب، فلا يدفع الدخول ثمن إنشائهما"""
    def work():
        get_supabase_login_client()
        get_supabase_public_client()
    threading.Thread(target=work, name="JadeitePrewarm", daemon=True).start()


def save_admin_secret_key(key):
    """يحفظ مفتاح المدير على هذا الجهاز (مجلد بيانات البرنامج للمستخدم) ويفعّله فوراً.

    يُحفظ خارج المستودع وخارج exe: لا يُرفع ولا يُوزَّع مع أي نسخة. يرجع (True, None)
    أو (False, السبب) — ويُختبر قبل الحفظ بطلب قراءة فعلي فلا يُحفظ مفتاح خاطئ.
    """
    global SUPABASE_SECRET_KEY
    key = (key or "").strip()
    if not key:
        return False, "الصق المفتاح أولاً."
    if not SUPABASE_AVAILABLE:
        return False, "مكتبة الاتصال بالسحابة غير متوفرة في هذه النسخة."
    try:
        sb = _sb_create_client(SUPABASE_URL, key)
        sb.table("clients").select("client_id").limit(1).execute()
    except Exception as e:
        return False, f"المفتاح غير صحيح أو لا يوجد اتصال بالإنترنت:\n{e}"
    try:
        folder = admin_secret_dir()
        os.makedirs(folder, exist_ok=True)
        with open(os.path.join(folder, "admin_secret.key"), "w", encoding="utf-8") as f:
            f.write(key)
    except OSError as e:
        return False, f"تعذّر حفظ المفتاح على هذا الجهاز: {e}"
    SUPABASE_SECRET_KEY = key
    with _SB_LOCK:
        _SB_CLIENTS.pop("admin", None)       # عميل جديد بالمفتاح الجديد
    return True, None


def get_supabase_admin_client():
    """عميل سحابي بصلاحيات كاملة (المدير فقط) — يتخطى كل الحمايات"""
    if not SUPABASE_AVAILABLE:
        return None
    if not SUPABASE_SECRET_KEY:
        log_cloud_error("مفتاح المدير غير مضبوط",
                        "ضع المفتاح في متغيّر البيئة JADEITE_SUPABASE_SECRET_KEY "
                        "أو في ملف admin_secret.key بجانب البرنامج")
        return None
    return _shared_supabase_client("admin", SUPABASE_SECRET_KEY, 60)


CURRENT_SYNC_TOKEN = None   # رمز مزامنة الجلسة الحالية (ذاكرة فقط)


def cloud_verify_client_login(username, password, touch=True):
    """يتحقق من بيانات دخول عميل عبر السحابة. يرجع (client_id, business_name, can_edit) أو (None, None, False)

    touch: يسجّل وقت الدخول للمدير — في خيط خلفي، فلا ينتظر الدخول طلباً إضافياً.
    """
    sb = get_supabase_login_client()
    if sb is None:
        return None, None, False
    try:
        # نجرّب أولاً الدالة الموسّعة التي ترجع رمز المزامنة معها،
        # ونرجع للقديمة تلقائياً لو لم تكن مثبّتة في السحابة بعد
        try:
            res = sb.rpc("client_login_full", {"p_username": username, "p_password_hash": hash_password(password)}).execute()
        except Exception:
            res = sb.rpc("verify_client_login", {"p_username": username, "p_password_hash": hash_password(password)}).execute()

        if res.data:
            row = res.data[0]
            client_id = row.get("out_client_id")
            # رمز المزامنة يبقى في الذاكرة فقط طوال تشغيل البرنامج
            global CURRENT_SYNC_TOKEN
            CURRENT_SYNC_TOKEN = row.get("out_sync_token")
            # تسجيل وقت الدخول ليظهر للمدير في لوحته — في الخلفية
            if touch:
                touch_client_login_async(client_id)
            return client_id, row.get("out_business_name"), bool(row.get("out_can_edit"))
    except Exception as e:
        log_cloud_error("تعذر التحقق من بيانات الدخول عبر السحابة", e)
    return None, None, False


# يتحوّل إلى False لو تبيّن أن أعمدة تتبّع النشاط غير موجودة، فلا نكرر المحاولة ولا نملأ ملف السجل
_ACTIVITY_TRACKING_SUPPORTED = True


def cloud_touch_client_activity(client_id, is_login=False):
    """يحدّث (آخر ظهور) للعميل — و(آخر دخول) عند تسجيل الدخول — ليراهما المدير في لوحته.
    عملية خفيفة جداً (سطر واحد)، وتتوقف بهدوء لو لم تكن أعمدة التتبّع مضافة في السحابة."""
    global _ACTIVITY_TRACKING_SUPPORTED
    if not client_id or not _ACTIVITY_TRACKING_SUPPORTED:
        return False

    now_iso = datetime.datetime.now(datetime.timezone.utc).isoformat()
    payload = {"last_seen": now_iso}
    if is_login:
        payload["last_login"] = now_iso

    last_err = None
    # عميل المدير فقط حيث يوجد مفتاحه (نسخة العميل بلا مفتاح: كان كل تسجيل
    # نشاط — كل ١٠ ثوانٍ — يكتب «مفتاح المدير غير مضبوط» في ملف السجل)
    getters = ((get_supabase_admin_client,) if SUPABASE_SECRET_KEY else ()) + (get_supabase_public_client,)
    for getter in getters:
        sb = getter()
        if sb is None:
            continue
        try:
            sb.table("clients").update(payload).eq("client_id", client_id).execute()
            return True
        except Exception as e:
            last_err = e

    _ACTIVITY_TRACKING_SUPPORTED = False
    log_cloud_error("تعذّر تسجيل نشاط العميل (تأكد من إضافة عمودي last_login و last_seen بجدول clients)", last_err)
    return False


def touch_client_login_async(client_id):
    """تسجيل وقت دخول العميل للمدير في خيط خلفي (لا يؤخّر فتح النظام)"""
    def work():
        try:
            cloud_touch_client_activity(client_id, is_login=True)
        except Exception:
            pass
    threading.Thread(target=work, name="JadeiteLoginTouch", daemon=True).start()


def cloud_check_can_edit(client_id):
    """فحص خفيف لصلاحية التعديل الحالية (للتحديث الدوري أثناء تشغيل البرنامج)"""
    sb = get_supabase_public_client()
    if sb is None or not client_id:
        return None
    try:
        res = sb.rpc("check_client_can_edit", {"p_client_id": client_id}).execute()
        if res.data is not None:
            return bool(res.data)
    except Exception as e:
        log_cloud_error("تعذر فحص صلاحية التعديل", e)
    return None


def cloud_set_client_can_edit(client_id, value):
    """(المدير فقط) يفتح/يقفل صلاحية التعديل لعميل معيّن"""
    sb = get_supabase_admin_client()
    if sb is None:
        return False
    try:
        sb.table("clients").update({"can_edit": value}).eq("client_id", client_id).execute()
        return True
    except Exception as e:
        log_cloud_error("فشل تغيير صلاحية التعديل", e)
        return False


# ختم اللقطة المرفوعة (يُكتب في النسخة المرفوعة وحدها، لا في قاعدة العميل):
# وقت أخذها على جهاز العميل، وإصدار برنامجه — ليعرف المدير حداثتها وتطابق الإصدارين
MIRROR_META_TIME = "_mirror_snapshot_at"
MIRROR_META_VERSION = "_mirror_app_version"


def _remove_db_files(path):
    for suffix in ("", "-journal", "-wal", "-shm"):
        try:
            os.remove(path + suffix)
        except OSError:
            pass


# جداول حالة المزامنة المحلية: تتغيّر وحدها كل دقيقة ولا تخص المدير، فلا تدخل في بصمة «هل تغيّرت البيانات؟»
DIGEST_SKIP_TABLES = ("sync_state", "sync_outbox")


def db_content_digest(con):
    """بصمة محتوى القاعدة: كل الجداول وصفوفها بترتيب ثابت — تتغيّر فقط إن تغيّرت البيانات نفسها
    (لا تتأثر بترتيب الصفحات ولا بعدّاد الكتابة في رأس الملف)"""
    h = hashlib.sha256()
    names = [r[0] for r in con.execute(
        "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")]
    for name in names:
        if name in DIGEST_SKIP_TABLES:
            continue
        h.update(f"\x00{name}\x00".encode("utf-8"))
        try:
            rows = con.execute(f'SELECT * FROM "{name}" ORDER BY rowid')
        except sqlite3.OperationalError:        # جدول بلا rowid
            rows = con.execute(f'SELECT * FROM "{name}" ORDER BY 1')
        for row in rows:
            h.update(repr(row).encode("utf-8"))
    return h.hexdigest()


def snapshot_db_bytes(db_path, slim=False, with_digest=False):
    """لقطة كاملة ومتّسقة لقاعدة العميل كما هي الآن، في ملف واحد (بايتات).

    قراءة ملف القاعدة مباشرة كانت تُفوّت آخر ما سُجّل: القاعدة تعمل بنظام WAL،
    فأحدث الحركات تبقى في الملف المجاور ‎-wal‎ حتى تُدمج — فتصل للسحابة نسخة
    ناقصة ويرى المدير أرقاماً غير أرقام العميل. النسخ عبر sqlite3.backup يجمع كل
    شيء في ملف واحد متّسق (قراءة واحدة لا تتخلّلها كتابة).

    slim (نسخة السحابة): بلا فهارس وبلا صفحات فارغة — البيانات نفسها كاملة، والفهارس
    (~٤٠٪ من حجم القاعدة) يعيد البرنامج بناءها وحده عند فتحها (init_database).
    with_digest: يرجع (البايتات، بصمة المحتوى) — البصمة قبل إضافة وقت اللقطة.
    """
    # اسم مؤقت فريد: رفع دوري ورفع عند الإغلاق ورفع يدوي قد تتزامن
    tmp = f"{db_path}.snapshot-{threading.get_ident()}-{time.time_ns()}"
    _remove_db_files(tmp)
    digest = None
    src = sqlite3.connect(db_path, timeout=30)
    try:
        dst = sqlite3.connect(tmp)
        try:
            src.backup(dst)
            dst.execute("PRAGMA journal_mode=DELETE")
            if slim:
                for (index_name,) in dst.execute(
                        "SELECT name FROM sqlite_master WHERE type='index' AND sql IS NOT NULL").fetchall():
                    dst.execute(f'DROP INDEX IF EXISTS "{index_name}"')
                dst.commit()
            if with_digest:
                digest = db_content_digest(dst)
            dst.execute("CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT)")
            dst.executemany("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", [
                (MIRROR_META_TIME, datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")),
                (MIRROR_META_VERSION, APP_VERSION)])
            dst.commit()
            if slim:
                dst.execute("VACUUM")          # يحذف الصفحات الفارغة التي تركتها الفهارس
        finally:
            dst.close()
    finally:
        src.close()
    try:
        with open(tmp, "rb") as f:
            data = f.read()
        return (data, digest) if with_digest else data
    finally:
        _remove_db_files(tmp)


# النسخة الكاملة تُرفع مضغوطة (قاعدة SQLite تنضغط عدة أضعاف) وبعلامة في أولها تميّزها؛
# والقراءة تقبل كل الصيغ، فنسخ العملاء الأقدم تُفتح كما هي:
#   JADEX1 → ضغط xz (الدفعة ٢٠: أصغر ~٣٠٪ من zlib)   JADEZ1 → zlib (الدفعة ١٥)   بلا علامة → غير مضغوطة
# ⚠️ حدّث نسخة المدير قبل العملاء (أو معهم): المدير القديم لا يعرف الصيغة الأحدث.
BACKUP_MAGIC = b"JADEZ1\n"
BACKUP_MAGIC_XZ = b"JADEX1\n"
SQLITE_HEADER = b"SQLite format 3\x00"


def encode_backup_payload(raw):
    """بايتات قاعدة SQLite ← نص base64 للرفع: مضغوطة بـ xz وفي أولها العلامة"""
    return base64.b64encode(BACKUP_MAGIC_XZ + lzma.compress(raw, preset=6)).decode("ascii")


def decode_backup_payload(text):
    """نص النسخة من السحابة ← بايتات قاعدة SQLite (xz أو zlib أو قديمة غير مضغوطة).
    يرمي ValueError لأي محتوى آخر، فلا يُكتب ملف تالف مكان القاعدة."""
    blob = base64.b64decode(text)
    if blob.startswith(BACKUP_MAGIC_XZ):
        try:
            blob = lzma.decompress(blob[len(BACKUP_MAGIC_XZ):])
        except lzma.LZMAError as e:
            raise ValueError(f"النسخة السحابية المضغوطة تالفة: {e}") from e
    elif blob.startswith(BACKUP_MAGIC):
        try:
            blob = zlib.decompress(blob[len(BACKUP_MAGIC):])
        except zlib.error as e:
            raise ValueError(f"النسخة السحابية المضغوطة تالفة: {e}") from e
    if not blob.startswith(SQLITE_HEADER):
        raise ValueError("النسخة السحابية ليست قاعدة بيانات صالحة")
    return blob


def rpc_missing(error):
    """هل فشل الطلب لأن الدالة غير مثبّتة على السحابة بعد؟ (فنرجع للمسار القديم)"""
    text = str(error)
    return "PGRST202" in text or "42883" in text or "Could not find the function" in text


# بصمة آخر نسخة وصلت السحابة لكل عميل (في هذه الجلسة): نسخة مطابقة لا تُرفع مرة أخرى
_LAST_BACKUP_DIGEST = {}
BACKUP_UNCHANGED = "unchanged"


def cloud_upload_backup(client_id, db_path, force=False):
    """يرفع نسخة كاملة من قاعدة البيانات المحلية للسحابة — تعمل في الخلفية ولا تعطّل البرنامج عند فشلها.

    هذه النسخة هي ما يفتحه المدير بالضبط (مرآة حرفية لجهاز العميل): البيانات كلها،
    بلا الفهارس (يبنيها البرنامج عند فتحها) ومضغوطة بـ xz — أصغر ~٦٠٪ من قبل.
    لا تُرفع إن لم يتغيّر محتواها منذ آخر رفع ناجح (يرجع BACKUP_UNCHANGED) إلا مع force.
    الرفع برمز مزامنة الجلسة عبر upload_backup_secure (لا يكتب فوق نسخة عميل إلا جهازه)؛
    وإن لم تُثبَّت تلك الدالة بعد (17_backup_security.sql) فبالدالة القديمة."""
    # نسخة المدير مرآة للقراءة: قاعدتها مبنية مما رفعه العميل، فرفعها كان يطمس
    # نسخة العميل الاحتياطية على السحابة بنسخة المدير (كل ١٠ دقائق أثناء التصفّح)
    if IS_ADMIN_BUILD:
        return False
    sb = get_supabase_public_client()
    if sb is None or not client_id or not os.path.exists(db_path):
        return False
    try:
        raw, digest = snapshot_db_bytes(db_path, slim=True, with_digest=True)
        if not force and digest and _LAST_BACKUP_DIGEST.get(client_id) == digest:
            return BACKUP_UNCHANGED          # السحابة فيها النسخة نفسها: لا رفع ولا مساحة
        encoded = encode_backup_payload(raw)
        token = CURRENT_SYNC_TOKEN
        sent = False
        if token:
            try:
                sb.rpc("upload_backup_secure", {"p_client_id": client_id, "p_sync_token": token,
                                                "p_backup_data": encoded}).execute()
                sent = True
            except Exception as e:
                if not rpc_missing(e):
                    raise
        if not sent:
            sb.rpc("upload_backup", {"p_client_id": client_id, "p_backup_data": encoded}).execute()
        _LAST_BACKUP_DIGEST[client_id] = digest
        return True
    except Exception as e:
        log_cloud_error("فشل رفع النسخة الاحتياطية للسحابة (سيُعاد المحاولة تلقائياً)", e)
        return False


def cloud_error_kind(error):
    """نوع فشل طلب سحابي: «network» انقطاع أو مهلة، «missing» الدالة غير مثبّتة،
    «denied» السحابة ردّت برفض (صلاحية أو رمز)"""
    names = {c.__name__ for c in type(error).__mro__}
    if isinstance(error, OSError) or names & {"TransportError", "TimeoutException", "NetworkError",
                                               "ConnectError", "ConnectTimeout", "ReadTimeout"}:
        return "network"
    if rpc_missing(error):
        return "missing"
    return "denied"


# سبب تعذّر تنزيل نسخة العميل — نصّ يفهمه المدير ويعرف منه ماذا يفعل
BACKUP_DOWNLOAD_PROBLEMS = {
    "no_copy": "لم يرفع برنامج العميل نسخته الكاملة إلى السحابة بعد.\n"
               "افتح برنامج العميل على جهازه وهو متصل بالإنترنت دقيقة واحدة — "
               "وتظهر بياناته هنا تلقائياً فور وصولها.",
    "denied": "السحابة لم تسمح لهذا الدخول بتنزيل نسخة العميل.\n"
              "شغّل الملف supabase/20_admin_download.sql مرة واحدة في Supabase ← SQL Editor، "
              "أو ادخل من لوحة المدير بمفتاح المدير.",
    "network": "تعذّر الاتصال بالسحابة — تحقق من الإنترنت ثم أعد الدخول.",
    "invalid": "وصلت نسخة العميل لكنها غير صالحة — حدّث برنامج المدير لآخر إصدار.",
}


def _backup_download_attempts(client_id):
    """طرق تنزيل نسخة العميل بالترتيب: مفتاح المدير، ثم رمز مزامنة العميل (دخول برنامج
    المدير باسم العميل وكلمة مروره — 20_admin_download.sql)، ثم الدالة القديمة بالمفتاح
    العام (قواعد لم يُشغَّل فيها 17_backup_security.sql)"""
    attempts = []
    if SUPABASE_SECRET_KEY:
        attempts.append((get_supabase_admin_client, "download_backup", {"p_client_id": client_id}))
    if CURRENT_SYNC_TOKEN:
        attempts.append((get_supabase_public_client, "download_backup_secure",
                         {"p_client_id": client_id, "p_sync_token": CURRENT_SYNC_TOKEN}))
    attempts.append((get_supabase_public_client, "download_backup", {"p_client_id": client_id}))
    return attempts


def cloud_download_backup_checked(client_id, target_db_path):
    """(نسخة المدير) ينزّل آخر نسخة كاملة رفعها العميل ويكتبها محلياً.
    يرجع (True, None) أو (False, السبب) — السبب مفتاح في BACKUP_DOWNLOAD_PROBLEMS.
    نسخة العميل لا تنزّل من السحابة أبداً: بياناتها المحلية هي الحقيقة."""
    if not IS_ADMIN_BUILD or not client_id:
        return False, "no_copy"
    problems = []
    for getter, fn, args in _backup_download_attempts(client_id):
        sb = getter()
        if sb is None:
            problems.append("network")
            continue
        try:
            res = sb.rpc(fn, args).execute()
        except Exception as e:
            problems.append(cloud_error_kind(e))
            log_cloud_error(f"تعذّر تنزيل نسخة العميل ({fn})", e)
            continue
        rows = res.data or []
        data = rows[0].get("out_backup_data") if rows and isinstance(rows[0], dict) else None
        if not data:
            return False, "no_copy"        # طريق مصرّح أجاب: لا نسخة لهذا العميل بعد
        try:
            raw = decode_backup_payload(data)
        except (ValueError, TypeError) as e:
            log_cloud_error("النسخة المنزّلة من السحابة غير صالحة", e)
            return False, "invalid"
        with open(target_db_path, "wb") as f:
            f.write(raw)
        return True, None
    return False, ("network" if problems and all(p == "network" for p in problems) else "denied")


def cloud_download_backup(client_id, target_db_path):
    """ينزّل آخر نسخة كاملة رفعها العميل ويكتبها محلياً. يرجع True لو نجح"""
    return cloud_download_backup_checked(client_id, target_db_path)[0]


def cloud_backup_stamp(client_id):
    """وقت آخر نسخة كاملة وصلت من العميل (طلب خفيف لمعرفة هل تغيّرت).
    يرجع النص، أو "" إن لم تصل نسخة، أو None إن تعذّر معرفته.

    جواب فارغ من المفتاح العام لا يعني «لا نسخة»: قد تحجب الصلاحيات الجدول عنه —
    فيُعدّ «غير معروف» ويُعتمد التنزيل الدوري (وإلا توقّف التحديث التلقائي)."""
    admin = get_supabase_admin_client() if SUPABASE_SECRET_KEY else None
    if admin is None and CURRENT_SYNC_TOKEN:
        # دخول برنامج المدير باسم العميل: وقت آخر نسخة برمز مزامنته (20_admin_download.sql)
        sb = get_supabase_public_client()
        try:
            res = sb.rpc("backup_stamp_secure", {"p_client_id": client_id,
                                                 "p_sync_token": CURRENT_SYNC_TOKEN}).execute() if sb else None
            stamp = res.data if res is not None else None
            if isinstance(stamp, list):
                stamp = stamp[0] if stamp else None
            if isinstance(stamp, dict):
                stamp = next(iter(stamp.values()), None)
            if isinstance(stamp, str):
                return stamp
        except Exception:
            pass
    for sb, authoritative in ((admin, True), (get_supabase_public_client(), False)):
        if sb is None:
            continue
        try:
            res = sb.table("db_backups").select("updated_at").eq("client_id", client_id).limit(1).execute()
        except Exception:
            continue
        rows = res.data or []
        if rows:
            return str(rows[0].get("updated_at") or "") or None
        return "" if authoritative else None
    return None



def load_client_mirror(client_id, db_path):
    """نسخة المدير: تستبدل النسخة المحلية بآخر لقطة كاملة لقاعدة العميل — كما هي على
    جهازه حرفياً: كل حركة وفترة واسم وترتيب وإعداد. يرجع (True, None) أو (False, السبب)"""
    tmp = f"{db_path}.mirror_tmp"
    _remove_db_files(tmp)
    ok, problem = cloud_download_backup_checked(client_id, tmp)
    if not ok:
        _remove_db_files(tmp)
        return False, BACKUP_DOWNLOAD_PROBLEMS.get(problem, BACKUP_DOWNLOAD_PROBLEMS["denied"])
    if not is_sqlite_db_healthy(tmp):
        _remove_db_files(tmp)
        return False, "النسخة المنزّلة من السحابة غير سليمة"
    mark_mirror_source(tmp)
    reset_local_cache(db_path)
    os.replace(tmp, db_path)
    return True, None


MIRROR_META_SOURCE = "_mirror_source"


def mark_mirror_source(db_path):
    """علامة محلية (على جهاز المدير فقط): هذه القاعدة نسخة العميل الكاملة لا إعادة بناء"""
    try:
        with contextlib.closing(sqlite3.connect(db_path)) as con:
            con.execute("CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT)")
            con.execute("INSERT OR REPLACE INTO settings (key, value) VALUES (?, 'snapshot')",
                        (MIRROR_META_SOURCE,))
            con.commit()
    except Exception as e:
        log_cloud_error("تعذّر تعليم نسخة العميل", e)


def cloud_create_client_account(business_name, username, password):
    """(المدير فقط) ينشئ حساب عميل جديد بالسحابة. يرجع (True, client_id) أو (False, رسالة الخطأ)"""
    sb = get_supabase_admin_client()
    if sb is None:
        return False, "تعذر الاتصال بالسحابة (تأكد من الإنترنت)."
    try:
        result = sb.table("clients").insert({
            "business_name": business_name, "username": username, "password_hash": hash_password(password),
        }).execute()
        return True, result.data[0]["client_id"]
    except Exception as e:
        return False, str(e)


def cloud_list_clients():
    """(المدير فقط) يرجع قائمة كل العملاء المسجلين بالسحابة، مع وقت آخر نسخة احتياطية وصلت لكل واحد منهم"""
    return cloud_list_clients_checked()[0]


def cloud_list_clients_checked():
    """مثل cloud_list_clients ومعه سبب الفشل إن وُجد: (العملاء، None) أو ([]، السبب).

    السبب «no_key» = مفتاح المدير غير مضبوط على هذا الجهاز. كانت القائمة تظهر فارغة
    بلا تفسير فيبدو أن الحسابات اختفت.
    """
    if not SUPABASE_AVAILABLE:
        return [], "مكتبة الاتصال بالسحابة غير متوفرة في هذه النسخة."
    if not SUPABASE_SECRET_KEY:
        return [], "no_key"
    sb = get_supabase_admin_client()
    if sb is None:
        return [], "تعذّر تجهيز الاتصال بالسحابة بمفتاح المدير."
    try:
        # نحاول أولاً جلب أعمدة تتبّع النشاط، وإن لم تكن مضافة في السحابة نرجع للأعمدة الأساسية بدون تعطّل
        base_cols = "client_id, business_name, username, is_active, can_edit, created_at"
        try:
            result = sb.table("clients").select(base_cols + ", last_login, last_seen").order("created_at", desc=True).execute()
        except Exception:
            result = sb.table("clients").select(base_cols).order("created_at", desc=True).execute()
        clients = result.data or []
        try:
            backups = sb.table("db_backups").select("client_id, updated_at").execute()
            backup_map = {b["client_id"]: b["updated_at"] for b in (backups.data or [])}
        except Exception as e:
            log_cloud_error("تعذر جلب أوقات النسخ الاحتياطية", e)
            backup_map = {}
        for c in clients:
            c["last_backup"] = backup_map.get(c["client_id"])
        return clients, None
    except Exception as e:
        log_cloud_error("تعذر جلب قائمة العملاء", e)
        text = str(e)
        if any(k in text for k in ("401", "403", "Invalid API key", "JWT", "apikey", "permission denied")):
            return [], f"مفتاح المدير المحفوظ على هذا الجهاز مرفوض من السحابة (ربما تغيّر):\n{text[:200]}"
        return [], f"تعذّر الاتصال بالسحابة — تحقق من الإنترنت:\n{text[:200]}"


def cloud_verify_sub_admin_login(username, password):
    """يتحقق هل هذا مستخدم 'مدير مساعد' (صلاحيات محدودة: انتحال شخصية فقط)"""
    sb = get_supabase_login_client()
    if sb is None:
        return False
    try:
        res = sb.rpc("verify_sub_admin_login", {"p_username": username, "p_password_hash": hash_password(password)}).execute()
        return bool(res.data)
    except Exception as e:
        log_cloud_error("تعذر التحقق من دخول المدير المساعد", e)
        return False


def cloud_create_sub_admin(username, password):
    """(المدير الرئيسي فقط) ينشئ حساب مدير مساعد جديد (يقدر فقط على انتحال شخصية العملاء)"""
    sb = get_supabase_admin_client()
    if sb is None:
        return False, "تعذر الاتصال بالسحابة."
    try:
        sb.table("sub_admins").insert({"username": username, "password_hash": hash_password(password)}).execute()
        return True, None
    except Exception as e:
        return False, str(e)


def cloud_delete_client(client_id):
    """(المدير الرئيسي فقط) يحذف حساب عميل نهائياً من السحابة، وكل بياناته المرتبطة (نسخ احتياطية وأي جداول مرتبطة به).
    السجلات التابعة تُحذف أولاً، لأن قيود المفاتيح الأجنبية تمنع حذف العميل قبل حذف ما يشير إليه."""
    sb = get_supabase_admin_client()
    if sb is None:
        return False, "تعذر الاتصال بالسحابة."

    # الجداول التابعة المعروفة تُحذف مباشرة
    for child_table in ("db_backups",):
        try:
            sb.table(child_table).delete().eq("client_id", client_id).execute()
        except Exception as e:
            log_cloud_error(f"تعذر حذف سجلات ({child_table}) المرتبطة بالعميل", e)

    # أي جدول تابع آخر يُكتشف تلقائياً من رسالة قيد المفتاح الأجنبي ثم يُحذف، ثم يُعاد المحاولة
    last_err = None
    cleared = set()
    for _ in range(8):
        try:
            sb.table("clients").delete().eq("client_id", client_id).execute()
            return True, None
        except Exception as e:
            last_err = e
            # اسم الجدول المرتبط يُستخرج من رسالة قاعدة البيانات مهما كان شكل الاقتباس فيها
            match = re.search(r'referenced from table\s+\\?["\']([^"\'\\]+)', str(e))
            if not match:
                break
            ref_table = match.group(1)
            if ref_table in cleared:
                break
            cleared.add(ref_table)
            try:
                sb.table(ref_table).delete().eq("client_id", client_id).execute()
            except Exception as e2:
                log_cloud_error(f"تعذر حذف سجلات ({ref_table}) المرتبطة بالعميل", e2)
                break

    return False, str(last_err) if last_err else "تعذر حذف الحساب لسبب غير معروف."


def cloud_list_sub_admins():
    """(المدير الرئيسي فقط) يرجع قائمة كل المدراء المساعدين"""
