class ScreenRouter(ctk.CTkFrame):
    """بديل خفيف عن CTkTabview: نفس واجهة add()/tab() المستخدمة في كل شاشات النظام،
    لكن بدل شريط تبويبات جانبي، يعرض شاشة واحدة فقط في كل مرة مع زر عودة للقائمة الرئيسية،
    وتبقى بقية الشاشات مغلقة حتى يتم اختيارها من القائمة الرئيسية.

    meta: {اسم الشاشة: (أيقونة، العنوان المعروض، وصف قصير)} — لرأس كل شاشة.
    """

    def __init__(self, master, go_home_callback=None, meta=None, **kwargs):
        super().__init__(master, fg_color="transparent", **kwargs)
        self._contents = {}   # name -> إطار المحتوى (نفس ما كانت ترجعه tabview.tab())
        self._wrappers = {}   # name -> الإطار الكامل (شريط علوي + محتوى)
        self._screen_info_labels = {}   # name -> عناوين الفترة والأرصدة في شريط الشاشة
        self._title_labels = {}
        self.go_home_callback = go_home_callback
        self.meta = meta or {}
        self.current_screen = None

    def update_screen_info(self, period_text, treasury_text, total_text):
        """يحدّث الفترة والأرصدة في شريط كل شاشة (تُستدعى من recalculate_all)"""
        # تُحفظ لرؤوس الشاشات التي تُبنى لاحقاً عند أول فتح لها
        self._last_info = (period_text, treasury_text, total_text)
        for labels in self._screen_info_labels.values():
            try:
                # مسافة حول النص: الشارة ملوّنة الخلفية فتحتاج هامشاً داخلياً
                labels["period"].configure(text=f"   {period_text}   ")
                labels["treasury"].configure(text=f"   {treasury_text}   ")
                labels["total"].configure(text=f"   {total_text}   ")
            except Exception:
                pass

    def set_title(self, name, title):
        """بعد تغيير اسم الشاشة من الشريط الجانبي يتغيّر عنوانها هنا أيضاً"""
        lbl = self._title_labels.get(name)
        if lbl is not None:
            try:
                lbl.configure(text=title)
            except Exception:
                pass
        elif name in self.meta:
            # الرأس لم يُبنَ بعد: يُبنى لاحقاً بالعنوان الجديد
            icon, _old, subtitle = self.meta[name]
            self.meta[name] = (icon, title, subtitle)

    def add(self, name):
        """يسجّل الشاشة بإطارين فارغين فقط — رأسها يُبنى عند أول فتح لها (_ensure_header).

        كان رأس كل شاشة (بطاقة وأيقونة وعنوان وثلاث شارات وزر) يُبنى للشاشات
        الأربع عشرة كلها عند الدخول، ونصف ثانية تقريباً من فتح النظام تذهب
        لرؤوس شاشات قد لا تُفتح أصلاً.
        """
        wrapper = ctk.CTkFrame(self, fg_color="transparent")
        content = ctk.CTkFrame(wrapper, fg_color="transparent")
        content.pack(fill="both", expand=True)
        self._contents[name] = content
        self._wrappers[name] = wrapper
        return content

    def _ensure_header(self, name):
        if name in self._screen_info_labels or name not in self._wrappers:
            return
        icon, title, subtitle = self.meta.get(name, ("", name, ""))
        wrapper = self._wrappers[name]
        content = self._contents[name]

        # ═══ رأس الشاشة: إطار علوي كحلي قوي بحافة ذهبية رفيعة ═══
        #   يؤطّر مساحة العمل مع الشريط السفلي الداكن، ويبقى بلونه في المظهرين
        #   يمين: أيقونة الشاشة في شارة + عنوانها + وصف قصير لوظيفتها
        #   وسط:  الفترة والأرصدة شارات ملوّنة صغيرة (كانت شريطاً كاملاً)
        #   يسار: العودة للقائمة الرئيسية (أو زر Esc)
        head = (UI["header"], UI["header"])
        top_bar = ctk.CTkFrame(wrapper, fg_color=head, corner_radius=14,
                               border_width=1, border_color=(UI["header_edge"], UI["header_edge"]))
        top_bar.pack(fill="x", padx=5, pady=(5, 8), before=content)

        btn_back = ctk.CTkButton(top_bar, text="🏠  القائمة الرئيسية", font=("Cairo", 14, "bold"),
                                  fg_color="transparent", border_width=1,
                                  border_color=("#3D5475", "#3D5475"),
                                  text_color=(UI["header_text"], UI["header_text"]),
                                  hover_color=(UI["header_2"], UI["header_2"]),
                                  width=176, height=40, command=self._go_home)
        btn_back.pack(side="left", padx=(12, 4), pady=10)
        ctk.CTkLabel(top_bar, text="Esc", font=("Cairo", 11, "bold"), width=34, height=22,
                     corner_radius=6, fg_color=(UI["header_2"], UI["header_2"]),
                     text_color=(UI["header_muted"], UI["header_muted"])).pack(side="left", padx=(0, 8))

        title_box = ctk.CTkFrame(top_bar, fg_color="transparent")
        title_box.pack(side="right", padx=(8, 12), pady=8)
        if icon:
            ctk.CTkLabel(title_box, text=icon, font=("Segoe UI Emoji", 22), width=48, height=48,
                         corner_radius=12, fg_color=("#2B2A1C", "#2B2A1C"),
                         text_color=("#E9C75C", "#E9C75C")).pack(side="right", padx=(10, 0))
        texts = ctk.CTkFrame(title_box, fg_color="transparent")
        texts.pack(side="right")
        lbl_title = ctk.CTkLabel(texts, text=title, anchor="e", height=26,
                                 font=ctk.CTkFont(family="Cairo", size=19, weight="bold"),
                                 text_color=(UI["header_text"], UI["header_text"]))
        lbl_title.pack(anchor="e")
        self._title_labels[name] = lbl_title
        if subtitle:
            ctk.CTkLabel(texts, text=subtitle, anchor="e", height=18, font=("Cairo", 12),
                         text_color=(UI["header_muted"], UI["header_muted"])).pack(anchor="e")

        info_box = ctk.CTkFrame(top_bar, fg_color="transparent")
        info_box.pack(side="right", padx=10, pady=10)

        def pill(bg, fg):
            lbl = ctk.CTkLabel(info_box, text="   —   ", height=32, corner_radius=16,
                               font=ctk.CTkFont(family="Cairo", size=13, weight="bold"),
                               fg_color=bg, text_color=fg)
            lbl.pack(side="right", padx=4)
            return lbl

        # الشارات بلون واحد هادئ على الإطار الكحلي؛ الخزينة وحدها بالذهبي (لون الشعار)
        lbl_period = pill((UI["header_2"], UI["header_2"]), (UI["header_pill_text"], UI["header_pill_text"]))
        lbl_treasury = pill((UI["header_2"], UI["header_2"]), ("#F0CF6A", "#F0CF6A"))
        lbl_total = pill((UI["header_2"], UI["header_2"]), (UI["header_pill_text"], UI["header_pill_text"]))

        self._screen_info_labels[name] = {
            "period": lbl_period, "treasury": lbl_treasury, "total": lbl_total}
        last = getattr(self, "_last_info", None)
        if last:
            lbl_period.configure(text=f"   {last[0]}   ")
            lbl_treasury.configure(text=f"   {last[1]}   ")
            lbl_total.configure(text=f"   {last[2]}   ")

    def tab(self, name):
        return self._contents[name]

    def show(self, name):
        self.current_screen = name
        self._ensure_header(name)
        self.pack(fill="both", expand=True)
        for w in self._wrappers.values():
            w.pack_forget()
        if name in self._wrappers:
            self._wrappers[name].pack(fill="both", expand=True)

    def _go_home(self):
        self.pack_forget()
        if self.go_home_callback:
            self.go_home_callback()


class GoldSystemApp(StableWindowMixin, ctk.CTk):
    def __init__(self, client_id=None, client_name=None, supabase_client=None, is_admin_session=False, initial_can_edit=False, intro=None):
        super().__init__()
        apply_screen_fit(self)      # قبل أي عنصر: الواجهة كلها تتسع للشاشات الصغيرة
        # intro: قادم من شاشة الدخول — يُبنى النظام مخفياً تماماً خلف آخر إطار منها،
        # ثم يظهر فوقه بالإطار نفسه وتنحسر الأمواج عن الرئيسية (_intro_show)
        self._intro = intro
        self._intro_cv = None
        self._opened_at = time.monotonic()
        if intro:
            try:
                self.withdraw()
            except Exception:
                pass

        self.client_id = client_id
        self.client_name = client_name
        self.supabase = supabase_client
        self.is_admin_session = is_admin_session
        # صلاحية التعديل: المدير/الجلسة المحلية بدون عميل = مسموح دائماً، العميل العادي حسب ما فتحه المدير له
        self.can_edit = True if (is_admin_session or not client_id) else bool(initial_can_edit)

        # تم تغيير مسمى النظام + ضبط حجم الشاشة تلقائياً حسب دقة جهاز المستخدم (بدل الحجم الثابت)
        title_suffix = f" - {client_name}" if client_name else ""
        self.title(f"نظام قسم التصنيع - الإصدار المحاسبي المتكامل{title_suffix}")
        apply_app_icon(self)
        self.update_idletasks()
        # الحجم «العادي» للنافذة = الشاشة كاملة (بلا شريط المهام) قبل أي ظهور: إن
        # أعادها ويندوز أو المكتبة من التكبير إلى حجمها العادي تبقى تملأ الشاشة —
        # لا نصف شاشة كما ظهر على بعض الحواسيب المحمولة الصغيرة
        fill_work_area(self)
        if not intro:
            # القادم من شاشة الدخول يبقى مخفياً ويُكبَّر عند ظهوره
            self.force_maximize()
        self.safe_minsize(1000, 650)
        # المظهر المحفوظ على هذا الجهاز: فاتح أو داكن أو تلقائي (يتبع ويندوز)
        self.current_theme = load_ui_prefs().get("theme", "Light")
        if self.current_theme not in self.THEME_CYCLE:
            self.current_theme = "Light"
        try:
            ctk.set_appearance_mode(self.current_theme)
        except Exception:
            self.current_theme = "Light"
        try:
            # تغيّر المظهر (من الزر أو من ويندوز في الوضع التلقائي) ← الجداول تتبعه فوراً
            ctk.AppearanceModeTracker.add(lambda _mode: self.after(40, self.apply_design_system), self)
        except Exception:
            pass

        # قاعدة البيانات والنسخ الاحتياطية داخل المجلد المنظّم على القرص المحلي
        old_generic_path = os.path.join(DATA_DIR, "gold_workshop.db")
        self.db_path = os.path.join(DATA_DIR, f"client_data_{client_id}.db") if client_id else old_generic_path
        self.backup_dir = _make_dir(os.path.join(BACKUPS_DIR, str(client_id) if client_id else "local"))

        # ترحيل أي قاعدة بيانات قديمة كانت بجوار البرنامج إلى المجلد الجديد (مرة واحدة، بدون فقدان بيانات)
        if client_id:
            migrate_legacy_file(f"client_data_{client_id}.db", self.db_path)
        migrate_legacy_file("gold_workshop.db", old_generic_path)

        # تنظيف تراكم ملفات PDF والنسخ القديمة حتى يبقى المجلد مرتباً
        cleanup_old_files(INVOICES_DIR, keep=120, suffix=".pdf")
        self.archive_data_map = {}
        self.current_display_month = datetime.datetime.now().strftime("%Y-%m")
        
        self.setup_treeview_styles()

        # ترحيل آمن: لو فيه قاعدة بيانات قديمة بالاسم العام القديم (من نسخة سابقة) ومفيش قاعدة جديدة بعد لهذا العميل تحديدًا،
        # ننقلها بدل ما نفقدها أو نستبدلها بنسخة أقدم من السحابة. نسخة العميل وحدها: قاعدة
        # المدير مرآة لجهاز العميل، وقاعدة قديمة على جهاز المدير ليست بيانات هذا العميل
        if (client_id and not IS_ADMIN_BUILD and not os.path.exists(self.db_path)
                and os.path.exists(old_generic_path)):
            try:
                import shutil
                shutil.copy2(old_generic_path, self.db_path)
            except Exception as e:
                log_cloud_error("فشل ترحيل قاعدة البيانات القديمة للاسم الجديد الخاص بالعميل", e)

        # لا توجد قاعدة لهذا الحساب على الجهاز:
        #   • نسخة العميل: تُسترجع من أحدث نسخة احتياطية سليمة في مجلد النسخ على
        #     جهازه نفسه (Backups). لا تسحب من السحابة أبداً — بياناتها المحلية
        #     هي مصدر الحقيقة، والسحابة تستقبل منها فقط (RECOVERY_AR.md).
        #   • نسخة المدير (مرآة للقراءة): نزّلت نسخة العميل قبل الفتح (SyncDownWindow)، وإن
        #     تعذّرت أُبلغ المدير بسببها هناك مرة واحدة — والتحديث التلقائي يعرضها فور وصولها.
        #     (كانت تُنزَّل هنا ثانيةً وتُظهر تنبيهاً ثانياً موجّهاً للعميل: «تواصل مع المدير»)
        if self.client_id and not os.path.exists(self.db_path) and not IS_ADMIN_BUILD:
            self.restore_missing_db_from_local_backup()
        
        # فحص سلامة قاعدة البيانات، ومحاولة إصلاحها تلقائياً من أحدث نسخة احتياطية سليمة أو من السحابة
        if os.path.exists(self.db_path) and not is_sqlite_db_healthy(self.db_path):
            self.recover_corrupt_database()

        # تهيئة قاعدة البيانات والنسخ الاحتياطي
        self.init_database()
        self.perform_backup()       # أخذ نسخة احتياطية عند تشغيل البرنامج
        self.schedule_backup()      # جدولة النسخ الاحتياطي التلقائي كل 15 دقيقة
        if self.client_id:
            if not IS_ADMIN_BUILD:
                # الرفع الدوري لنسخة العميل وحدها (المدير يقرأ فقط، ولا يُحسب ظهوره حضوراً للعميل)
                self.schedule_cloud_backup()   # دورة المزامنة السحابية كل ١٠ ثواني
            self.protocol("WM_DELETE_WINDOW", self.on_app_closing)
            if not self.is_admin_session:
                self.schedule_permission_refresh()   # تحديث دوري لصلاحية التعديل (كل دقيقة)
        
        self.load_data_from_db()
        self.sync_working_period()

        self.apply_design_system()
        try:
            # حدّ أدنى يمنع تشوّه الجداول لو صغّر المستخدم النافذة
            self.safe_minsize(1100, 620)
            # تُخفى النافذة حتى تكتمل الواجهة: بدون ذلك يرى المستخدم الشريط
            # الجانبي والشعار والأزرار تُرسم واحدةً تلو الأخرى عند الدخول
            self.withdraw()
        except Exception:
            pass

        self.create_layout()
        self.update_period_selector()
        self.start_admin_mirror_watch()

        # النافذة تُكبَّر وتُرسم **أولاً** ثم تُحسب الأرقام.
        # كان الحساب الأول يسبق أول رسم، فتظهر نافذة مصغّرة فارغة ثوانٍ قبل
        # أن يبدأ النظام — والحساب يمسح كل الحركات فيأخذ وقته.
        # تُبنى الواجهة كاملة وهي مخفية، ثم تظهر مرة واحدة جاهزة
        self.update_idletasks()
        if self._intro:
            try:
                self._intro_show()
            except Exception as e:
                log_cloud_error("تعذّر انتقال الدخول المتحرك — يظهر النظام مباشرة", e)
                self._intro_abort()
            return
        try:
            self.deiconify()
        except Exception:
            pass
        self.force_maximize()
        try:
            # يثبّت ظهور النافذة الآن: وإلا تخفيها customtkinter عند mainloop ثم
            # تعيدها بحجمها العادي (وميض، ونافذة غير مكبّرة على بعض الأجهزة)
            self.update()
        except Exception:
            pass
        self.after(30, self._startup_first_calc)
        # إعادة التكبير بعد ظهور النافذة فعلياً: النداء قبل الظهور يُتجاهل
        # أحياناً على ويندوز فتبقى النافذة بحجمها الصغير
        self.after(220, self.force_maximize)
        self.after(700, self.force_maximize)
        self.after(1100, self._ensure_fills_screen)

    def force_maximize(self):
        """يكبّر النظام لملء الشاشة (maximize_window) — والتحقق النهائي في _ensure_fills_screen"""
        maximize_window(self)

    def _ensure_fills_screen(self):
        """بعد ظهور النظام: إن لم يملأ الشاشة فعلاً يُكبَّر من جديد (ensure_fills_screen)"""
        ensure_fills_screen(self)

    def _after_scaling_change(self):
        """اكتُشف تكبير عرض مختلف: الحد الأدنى يُعاد حسابه على المقياس الجديد،
        وفي الثواني الأولى من الفتح يُتحقَّق أن النظام ما زال يملأ الشاشة"""
        try:
            self.safe_minsize(*getattr(self, "_min_request", (1100, 620)))
        except Exception:
            pass
        if time.monotonic() - getattr(self, "_opened_at", 0.0) < 15:
            self._ensure_fills_screen()

    def _startup_first_calc(self):
        """أول حساب شامل بعد ظهور النافذة، مع مؤشّر انتظار واضح"""
        try:
            self.configure(cursor="watch")
            self.update_idletasks()
        except Exception:
            pass
        # الشاشات الثلاث الأكثر استخداماً تُبنى في الخلفية بعد ظهور النظام،
        # فتفتح **فوراً** بلا «تكوّن» أمام المستخدم. البناء متدرّج (شاشة كل
        # ١٢٠ ملّي ثانية) حتى لا تتجمّد الواجهة أثناء التجهيز.
        def prebuild():
            self._prebuild_screens(["المبيعات", "مراحل التصنيع", "صناديق الخياس"])

        try:
            self.recalculate_all()
        finally:
            try:
                self.configure(cursor="")
            except Exception:
                pass
            if self._intro_cv is not None:
                # القادم من شاشة الدخول: تنحسر الأمواج أولاً ثم التجهيز (لا يقطع الحركة).
                # داخل finally: حتى لو فشل الحساب لا يبقى الغطاء فوق النظام
                self.after(0, lambda: self._intro_reveal(then=prebuild))
        if self._intro_cv is None:
            self.after(120, prebuild)

    # ------------------------------------------------------------------ الانتقال من شاشة الدخول
    _INTRO_FADE_S = 0.16      # ظهور النظام فوق آخر إطار من شاشة الدخول
    _INTRO_REVEAL_S = 0.75    # انحسار الأمواج عن الرئيسية

    def _intro_show(self):
        """يُظهر النظام فوق شاشة الدخول بغطاء مطابق لآخر إطار منها، ثم يغلقها.

        الغطاء لوحة رسم بلون الموج نفسه، والشعار والترحيب في مكانهما على الشاشة
        تماماً (بإحداثيات الشاشة لا النافذة) — فتبدو شاشة الدخول وكأنها صارت
        نافذة النظام: لا إغلاق ولا فراغ ولا وميض.
        """
        spec = self._intro
        try:
            self.attributes("-alpha", 0.0)       # ويندوز: يظهر تدريجياً فوق شاشة الدخول
        except Exception:
            pass
        try:
            self.deiconify()
        except Exception:
            pass
        self.force_maximize()
        cv = tk.Canvas(self, bg=spec.get("color", "#142A4C"), highlightthickness=0, bd=0)
        cv.place(x=0, y=0, relwidth=1, relheight=1)
        tk.Misc.tkraise(cv)                      # فوق كل الواجهة (lift في Canvas تخص عناصرها)
        self._intro_cv = cv
        # الشعار والترحيب يُرسمان قبل أول ظهور (فلا إطار واحد بلا محتوى)، ثم يُصحَّح
        # مكانهما بعد أن تستقر النافذة (شريط العنوان يزيح منطقة الرسم قليلاً)
        try:
            self.update_idletasks()
        except Exception:
            pass
        self._intro_draw()
        try:
            # يرسم النافذة ويثبّت ظهورها (وإلا تخفيها customtkinter وتعيدها عند mainloop)
            self.update()
        except Exception:
            pass
        self._intro_realign()
        try:
            self.lift()
            self.focus_force()
        except Exception:
            pass
        self._intro_fade(time.perf_counter())
        self.after(20000, self._intro_watchdog)
        # إعادة التكبير بعد الظهور الفعلي: النداء الأول يُتجاهل أحياناً على ويندوز
        self.after(220, self.force_maximize)
        self.after(700, self.force_maximize)
        self.after(1100, self._ensure_fills_screen)

    def _intro_abort(self):
        """احتياط: أي خلل في الانتقال يُظهر النظام مباشرة ويغلق شاشة الدخول"""
        cv, self._intro_cv = self._intro_cv, None
        login = (self._intro or {}).get("handoff")
        self._intro = None
        for action in (lambda: cv is not None and cv.destroy(),
                       lambda: self.attributes("-alpha", 1.0),
                       self.deiconify, self.force_maximize,
                       lambda: login is not None and login.destroy()):
            try:
                action()
            except Exception:
                pass
        self.after(30, self._startup_first_calc)

    def _intro_watchdog(self):
        """لا يبقى الغطاء فوق النظام أبداً: إن لم تنحسر الأمواج لأي سبب تُزال"""
        if self._intro_cv is not None and not getattr(self, "_intro_revealing", False):
            log_cloud_error("غطاء انتقال الدخول بقي أطول من المتوقع — أُزيل", None)
            login = (self._intro or {}).get("handoff")
            if login is not None:
                try:
                    login.destroy()
                except Exception:
                    pass
            try:
                self.attributes("-alpha", 1.0)
            except Exception:
                pass
            self._intro_finish()

    def _intro_draw(self):
        spec, cv = self._intro, self._intro_cv
        try:
            ox, oy = cv.winfo_rootx(), cv.winfo_rooty()
        except Exception:
            ox = oy = 0
        self._intro_off = (ox, oy)
        self._intro_imgs = []
        if spec.get("logo") is not None:
            try:
                from PIL import ImageTk
                img = ImageTk.PhotoImage(spec["logo"], master=self)
                self._intro_imgs.append(img)
                cv.create_image(spec["logo_x"] - ox, spec["logo_y"] - oy, image=img)
            except Exception as e:
                log_cloud_error("تعذّر رسم الشعار في انتقال الدخول", e)
        for t in spec.get("texts", []):
            try:
                cv.create_text(t["x"] - ox, t["y"] - oy, text=t["text"], font=t["font"], fill=t["fill"])
            except Exception:
                pass

    def _intro_realign(self):
        """يطابق مكان الشعار والترحيب على الشاشة تماماً بعد استقرار النافذة"""
        cv = self._intro_cv
        try:
            ox, oy = cv.winfo_rootx(), cv.winfo_rooty()
            px, py = getattr(self, "_intro_off", (ox, oy))
            if (ox, oy) != (px, py):
                cv.move("all", px - ox, py - oy)
                self._intro_off = (ox, oy)
        except Exception:
            pass

    def _intro_fade(self, t0):
        p = min(1.0, (time.perf_counter() - t0) / self._INTRO_FADE_S)
        try:
            self.attributes("-alpha", p)
        except Exception:
            p = 1.0
        if p < 1.0:
            self.after(15, lambda: self._intro_fade(t0))
            return
        # النظام ظاهر الآن فوق شاشة الدخول بالإطار نفسه: تُغلق هي تحته بلا أثر
        login = self._intro.get("handoff") if self._intro else None
        if login is not None:
            self._intro["handoff"] = None
            try:
                login.destroy()
            except Exception:
                pass
        self.after(30, self._startup_first_calc)

    @staticmethod
    def _ease_in_out(t):
        t = max(0.0, min(1.0, t))
        return 4 * t ** 3 if t < 0.5 else 1 - (-2 * t + 2) ** 3 / 2

    def _intro_reveal(self, then=None):
        """الأمواج تنحسر للأسفل كاشفةً الرئيسية من أعلاها: حافة الماء موجة بخطّين من ذهب"""
        cv = self._intro_cv
        if cv is None or getattr(self, "_intro_revealing", False):
            return
        self._intro_revealing = True
        try:
            w, h = max(1, cv.winfo_width()), max(1, cv.winfo_height())
            s = float(ctk.ScalingTracker.get_window_scaling(self))
        except Exception:
            return self._intro_finish(then)
        page = UI["canvas"] if ctk.get_appearance_mode() == "Light" else "#10141A"
        amp = 11 * s
        # أرقام الرئيسية تبدأ من الصفر وتُعدّ بعد الانكشاف
        labels = getattr(self, "home_stat_labels", None) or {}
        for key, lbl in labels.items():
            try:
                lbl.configure(text=f"{en(0)} جم")
            except Exception:
                pass
        band = cv.create_polygon(0, 0, 1, 1, 2, 2, fill=page, outline="", smooth=True)
        crest = cv.create_line(0, 0, 1, 1, fill=UI["gold"], width=max(2, round(2 * s)), smooth=True)
        crest2 = cv.create_line(0, 0, 1, 1, fill="#6E5A1E", width=1, smooth=True)
        step = max(16, w // 80)
        xs = list(range(-step, w + 2 * step, step))
        t0 = time.perf_counter()

        def frame():
            now = time.perf_counter() - t0
            p = now / self._INTRO_REVEAL_S
            try:
                ph = now * 5.0
                pts = []
                for x in xs:
                    pts += (x, 2.4 * amp + amp * math.sin(x * 0.011 + ph)
                            + 0.35 * amp * math.sin(x * 0.027 - ph * 0.7))
                cv.coords(band, *pts, xs[-1], -4, xs[-1], -4, xs[0], -4, xs[0], -4)
                cv.coords(crest, *pts)
                cv.coords(crest2, *[v + 0.9 * amp if i % 2 else v for i, v in enumerate(pts)])
                cv.place_configure(y=int(self._ease_in_out(p) * (h + 4 * amp)))
            except Exception:
                p = 1.0
            if p < 1.0:
                self.after(16, frame)
            else:
                self._intro_finish(then)
        frame()

    def _intro_finish(self, then=None):
        cv, self._intro_cv = self._intro_cv, None
        if cv is not None:
            try:
                cv.destroy()
            except Exception:
                pass
        self._intro_imgs = []
        self._intro = None
        self._home_count_up(time.perf_counter())
        self._sidebar_shimmer()
        if then is not None:
            self.after(450, then)

    def _home_count_up(self, t0):
        """أرقام الرئيسية تُعدّ من الصفر لقيمتها خلال أقل من ثانية"""
        raw = getattr(self, "_home_stat_raw", None)
        labels = getattr(self, "home_stat_labels", None)
        if not raw or not labels:
            return
        p = min(1.0, (time.perf_counter() - t0) / 0.7)
        e = 1 - (1 - p) ** 3
        try:
            for key, val in raw.items():
                labels[key].configure(text=f"{en(val * e)} جم")
        except Exception:
            return
        if p < 1.0:
            self.after(30, lambda: self._home_count_up(t0))
        else:
            self.refresh_home_stats()     # القيم الدقيقة من الدفتر نفسه

    def _sidebar_shimmer(self):
        """حواف أزرار الشريط تلمع بالذهبي واحداً بعد الآخر ثم تعود"""
        def paint(card, color):
            try:
                if card.winfo_exists():
                    card.configure(border_color=color)
            except Exception:
                pass

        for i, (card, normal) in enumerate(getattr(self, "_sidebar_cards", [])):
            self.after(70 * i, lambda c=card: paint(c, UI["gold"]))
            self.after(70 * i + 300, lambda c=card, n=normal: paint(c, n))

    def _note_user_input(self, _event=None):
        self._last_user_input = time.monotonic()

    def _prebuild_screens(self, names):
        """يبني الشاشات المطلوبة تباعاً في الخلفية بلا إظهارها.

        لا يبني شاشة والمستخدم يكتب أو ينقر: ينتظر هدوءاً قصيراً ثم يكمل —
        فلا يحسّ المستخدم بأي توقّف لحظة بدئه العمل بعد الدخول مباشرة.
        """
        if not names:
            return
        if not getattr(self, "_input_watch", False):
            self._input_watch = True
            for seq in ("<KeyPress>", "<ButtonPress>"):
                try:
                    self.bind_all(seq, self._note_user_input, add="+")
                except Exception:
                    pass
        if time.monotonic() - getattr(self, "_last_user_input", 0.0) < 1.5:
            self.after(700, lambda: self._prebuild_screens(names))
            return
        name, rest = names[0], names[1:]
        try:
            self.ensure_screen_built(name)
            self.refresh_pending_screen(name)
        except Exception as e:
            log_cloud_error(f"تعذّر تجهيز شاشة ({name}) مسبقاً", e)
        if rest:
            self.after(120, lambda: self._prebuild_screens(rest))

    def schedule_permission_refresh(self):
        self.after(30000, self.refresh_edit_permission)   # كل ٣٠ ثانية — ليصل فتح المدير للعميل بسرعة

    def refresh_edit_permission(self):
        def _check():
            result = cloud_check_can_edit(self.client_id)
            if result is not None:
                def _apply():
                    changed = (self.can_edit != result)
                    self.can_edit = result
                    self.update_edit_status_ui()
                    if changed and result:
                        try:
                            messagebox.showinfo("تم فتح التعديل ✅", "قام المدير بفتح صلاحية التعديل على حسابك الآن.")
                        except Exception:
                            pass
                self.after(0, _apply)
        threading.Thread(target=_check, daemon=True).start()
        self.schedule_permission_refresh()

    def is_edit_locked(self):
        """هل التعديل مقفول حالياً؟ (يخص العملاء فقط — المدير والجلسة المحلية مفتوحة دائماً)"""
        if self.is_admin_session or not self.client_id:
            return False
        return not self.can_edit

    def check_edit_permission(self, silent=False):
        """يُستدعى قبل أي *تعديل* على حركة مسجّلة — يمنعه لو أقفل المدير التعديل على هذا الحساب.
        ملاحظة: الحذف وتسجيل الحركات الجديدة يظلّان مسموحين دائماً."""
        if not self.is_edit_locked():
            return True
        if not silent:
            try:
                messagebox.showwarning(
                    "التعديل مقفول 🔒",
                    "التعديل مقفول حالياً على حسابك من قِبل المدير.\n\n"
                    "ما زال بإمكانك تسجيل حركات جديدة وحذف الحركات الخاطئة.\n"
                    "لتعديل حركة مسجّلة، تواصل مع المدير ليفتح لك التعديل من جهازه — "
                    "وسيُفعَّل عندك تلقائياً خلال أقل من دقيقة عبر الإنترنت.")
            except Exception:
                pass
        return False

    def check_delete_permission(self):
        """الحذف مسموح دائماً — قفل المدير يخص التعديل فقط"""
        return True

    def update_edit_status_ui(self):
        """يحدّث مؤشر حالة التعديل أعلى الشاشة ليعرف المستخدم فوراً إن كان التعديل مفتوحاً أو مقفولاً"""
        if not hasattr(self, 'lbl_edit_status'):
            return
        if IS_ADMIN_BUILD and self.client_id:
            # نسخة المدير: مرآة لجهاز العميل — ما يُعدَّل هنا لا يصله ويُستبدل بنسخته التالية
            self.lbl_edit_status.configure(text="👁️ مرآة جهاز العميل", text_color=UI["primary"])
        elif not self.client_id or self.is_admin_session:
            self.lbl_edit_status.configure(text="🔓 التعديل: مفتوح (جلسة مدير)", text_color="#2ecc71")
        elif self.can_edit:
            self.lbl_edit_status.configure(text="🔓 التعديل: مفتوح", text_color="#2ecc71")
        else:
            self.lbl_edit_status.configure(text="🔒 التعديل: مقفول (الحذف متاح)", text_color="#e67e22")

    def refresh_edit_permission_now(self):
        """تحديث فوري يدوي لصلاحية التعديل من السحابة (بعد ما يفتحها المدير)"""
        if not self.client_id:
            messagebox.showinfo("صلاحية التعديل", "هذه جلسة محلية/مدير — التعديل مفتوح دائماً.")
            return

        def _check():
            result = cloud_check_can_edit(self.client_id)
            def _apply():
                if result is None:
                    messagebox.showwarning("تعذّر التحديث", "تعذّر الاتصال بالإنترنت للتحقق من صلاحية التعديل.\nتأكد من الاتصال وحاول مرة أخرى.")
                    return
                self.can_edit = result
                self.update_edit_status_ui()
                messagebox.showinfo("صلاحية التعديل",
                                    "✅ تم فتح التعديل على حسابك." if result else "التعديل ما زال مقفولاً من المدير.")
            self.after(0, _apply)

        threading.Thread(target=_check, daemon=True).start()

    def apply_edit_lock_to_button(self, btn, parent_window=None):
        """يعطّل زر الحفظ/التعديل لو كان التعديل مقفولاً، مع بيان واضح للسبب (وتبقى أزرار الحذف شغّالة)"""
        if not self.is_edit_locked():
            return
        try:
            btn.configure(state="disabled", text="التعديل مقفول 🔒", fg_color="#555555", hover_color="#555555")
            if parent_window is not None:
                ctk.CTkLabel(parent_window, text="التعديل مقفول من المدير — الحذف ما زال متاحاً",
                             font=("Cairo", 12, "bold"), text_color="#e67e22").pack(pady=(0, 6))
        except Exception:
            pass

    def mark_backup_dirty(self):
        """تُستدعى بعد أي تعديل فعلي ناجح بقاعدة البيانات — تعلّم إن فيه بيانات جديدة محتاجة رفع للسحابة"""
        self._backup_dirty = True
        # وتُبطل فهرس الحركات بالاسم (invoices_by_name) فيُبنى من جديد عند أول حساب
        self._inv_version = getattr(self, "_inv_version", 0) + 1

    def invoices_by_period(self):
        """الحركات مجمّعة بفترتها المحاسبية — بالشروط نفسها التي تُبطل فهرس الأسماء"""
        sig = (id(self.invoices), len(self.invoices), getattr(self, "invoice_counter", 0),
               getattr(self, "_inv_version", 0))
        if getattr(self, "_period_idx_sig", None) != sig:
            idx = {}
            for inv in self.invoices.values():
                idx.setdefault(self.inv_period(inv), []).append(inv)
            self._period_idx, self._period_idx_sig = idx, sig
        return self._period_idx

    def period_invoices(self, month):
        """حركات فترة واحدة (أو كل الحركات إن لم تُحدَّد فترة) — بلا مسح لكل الحركات"""
        if not month:
            return self.invoices.values()
        return self.invoices_by_period().get(month, ())

    def invoices_by_name(self):
        """الحركات مجمّعة بالاسم — تُبنى مرة واحدة وتُعاد ما دامت البيانات لم تتغيّر.

        كان كل حساب لدفتر عامل يمسح **كل** الحركات بحثاً عن حركاته، ويتكرر ذلك
        لكل عامل في كل حساب شامل: مع ٢٠ ألف حركة كان الحساب الأول بعد الدخول
        يأخذ ثانيتين تقريباً. الفهرس يُبطَل بأي حفظ أو حذف (mark_backup_dirty)
        أو إعادة تحميل (قاموس حركات جديد)، والقوائم تحمل كائنات الحركات نفسها
        فأي تعديل على وزن أو حالة يظهر فوراً. ترتيب الحركات داخل كل اسم هو
        ترتيبها الأصلي نفسه.
        """
        sig = (id(self.invoices), len(self.invoices), getattr(self, "invoice_counter", 0),
               getattr(self, "_inv_version", 0))
        if getattr(self, "_name_idx_sig", None) != sig:
            idx = {}
            for inv in self.invoices.values():
                idx.setdefault(inv.get("الاسم"), []).append(inv)
            self._name_idx, self._name_idx_sig = idx, sig
        return self._name_idx

    # ═══ السحابة الخفيفة: الرفع عند التغيير فقط ═══
    # يُفحص كل ١٠ ثوانٍ، لكن النسخة لا تُرفع إلا إن تغيّرت البيانات فعلاً (بصمة المحتوى)،
    # ولا أكثر من مرة كل ٣٠ ثانية أثناء الإدخال المتتابع؛ ونسخة يومية احتياطية ولو بلا تغيير،
    # وإعادة المحاولة تلقائياً بعد أي فشل. و«آخر ظهور» مرة في الدقيقة (لوحة المدير تعدّ
    # العميل متصلاً إن ظهر خلال دقيقتين).
    CLOUD_CHECK_MS = 10000
    CLOUD_UPLOAD_MIN_GAP = 30
    CLOUD_FORCED_EVERY = 24 * 3600
    CLOUD_TOUCH_EVERY = 60

    def schedule_cloud_backup(self):
        self.after(self.CLOUD_CHECK_MS, self.auto_cloud_backup_trigger)

    def auto_cloud_backup_trigger(self):
        """كل ١٠ ثوانٍ: يقرّر هل يرفع النسخة (تغيّرت البيانات، أو حان الرفع اليومي) وهل يسجّل الظهور"""
        if not self.client_id:
            return

        now = datetime.datetime.now()
        def since(attr):
            t = getattr(self, attr, None)
            return None if t is None else (now - t).total_seconds()

        forced_age, upload_age, touch_age = (since("_last_forced_cloud_upload"), since("_last_cloud_upload_try"),
                                             since("_last_cloud_touch"))
        force_due = forced_age is None or forced_age >= self.CLOUD_FORCED_EVERY
        need_upload = force_due or (getattr(self, '_backup_dirty', False)
                                    and (upload_age is None or upload_age >= self.CLOUD_UPLOAD_MIN_GAP))
        touch_due = touch_age is None or touch_age >= self.CLOUD_TOUCH_EVERY

        if need_upload:
            self._backup_dirty = False
            self._last_cloud_upload_try = now
            if force_due:
                self._last_forced_cloud_upload = now
        if touch_due:
            self._last_cloud_touch = now
        if need_upload or touch_due:
            self.run_cloud_sync_cycle(upload=need_upload, force=force_due, touch=touch_due)

        self.schedule_cloud_backup()

    def run_cloud_sync_cycle(self, upload=True, force=False, touch=True):
        """دورة مزامنة واحدة في الخلفية: رفع النسخة (عند الحاجة) + تسجيل آخر ظهور، ثم تحديث المؤشر"""
        def _work():
            ok = True
            if upload:
                ok = cloud_upload_backup(self.client_id, self.db_path, force=force)
            if touch:
                cloud_touch_client_activity(self.client_id)
            self.after(0, lambda: self.update_cloud_sync_ui(ok, upload))

        threading.Thread(target=_work, daemon=True).start()

    def update_cloud_sync_ui(self, ok, uploaded):
        """مؤشر صغير أعلى الشاشة يوضح آخر رفع ناجح للسحابة"""
        if uploaded and not ok:
            self._backup_dirty = True       # فشل الرفع: يُعاد في الدورة التالية (بعد ٣٠ ثانية)
        if not hasattr(self, 'lbl_cloud_sync'):
            return
        if ok:
            if uploaded and ok != BACKUP_UNCHANGED:
                self._last_cloud_sync_ok = datetime.datetime.now().strftime("%H:%M:%S")
            stamp = getattr(self, '_last_cloud_sync_ok', None)
            self.lbl_cloud_sync.configure(text=f"☁️ آخر رفع: {stamp}" if stamp else "☁️ المزامنة: جاهزة",
                                          text_color="#2ecc71")
        else:
            self.lbl_cloud_sync.configure(text="☁️ تعذّر الرفع — تحقق من الإنترنت", text_color="#e74c3c")

    # ══════════════════════════════════════════════════════════════════════
    #  نسخة المدير: مرآة حيّة لجهاز العميل
    #
    #  ما يُعرض هو قاعدة العميل نفسها كما رفعها جهازه (load_client_mirror)، وكل
    #  دقيقة فحص خفيف: إن رفع العميل نسخة أحدث تُنزَّل وتُعرض مكانها تلقائياً —
    #  فأي حركة أو تعديل أو إعداد عند العميل يظهر هنا خلال دقيقة تقريباً.
    # ══════════════════════════════════════════════════════════════════════
    ADMIN_MIRROR_POLL_MS = 60_000
    ADMIN_MIRROR_FULL_EVERY = 3        # إن تعذّرت معرفة وقت النسخة: تنزيل كامل كل ٣ فحوص

    def start_admin_mirror_watch(self):
        if not (IS_ADMIN_BUILD and self.client_id):
            return
        self._mirror_stamp = None
        self._mirror_ticks = 0
        self._mirror_busy = False
        self.show_admin_mirror_status()

        def baseline():
            stamp = cloud_backup_stamp(self.client_id)
            self._mirror_stamp = stamp or None

        threading.Thread(target=baseline, daemon=True).start()
        self.after(self.ADMIN_MIRROR_POLL_MS, self._admin_mirror_tick)

    def admin_mirror_info(self):
        """(وقت لقطة العميل المعروضة، إصدار برنامجه، هل هي نسخته الكاملة)"""
        try:
            return (self.get_setting(MIRROR_META_TIME, "") or "",
                    self.get_setting(MIRROR_META_VERSION, "") or "",
                    self.get_setting(MIRROR_META_SOURCE, "") == "snapshot")
        except Exception:
            return "", "", False

    def show_admin_mirror_status(self, updated=False):
        if not hasattr(self, "lbl_cloud_sync"):
            return
        at, version, is_snapshot = self.admin_mirror_info()
        if not is_snapshot:
            text, color = "⏳ لم تصل نسخة العميل بعد — تظهر هنا تلقائياً فور وصولها", "#e67e22"
        elif not at:
            # نسخة كاملة من برنامج عميل أقدم من هذا التحديث (بلا ختم وقت وإصدار)
            text, color = "📥 نسخة العميل — ⚠️ برنامج العميل أقدم: حدّثه ليصل كل تعديل كاملاً", "#e67e22"
        else:
            text = f"{'🔄 وصل تحديث من العميل' if updated else '📥 نسخة العميل'}: {at[:16]}"
            color = "#2ecc71"
            if version and version != APP_VERSION:
                text += f"\n⚠️ برنامج العميل {version} وبرنامجك {APP_VERSION} — حدّث الأقدم ليتطابق الحساب"
                color = "#e67e22"
        self.lbl_cloud_sync.configure(text=text, text_color=color)

    def _admin_ui_busy(self):
        """نافذة فرعية مفتوحة (تعديل، تفاصيل…) — لا تُستبدل البيانات تحتها"""
        try:
            return any(isinstance(w, tk.Toplevel) and w.winfo_viewable() for w in self.winfo_children())
        except Exception:
            return False

    def _admin_mirror_tick(self):
        try:
            self.refresh_admin_mirror(manual=False)
        finally:
            try:
                self.after(self.ADMIN_MIRROR_POLL_MS, self._admin_mirror_tick)
            except Exception:
                pass

    def refresh_admin_mirror(self, manual=True):
        """ينزّل آخر نسخة رفعها العميل ويعرضها مكان الحالية إن كانت أحدث.
        manual: من زر «تحديث من العميل» — تنزيل فوري دون انتظار الفحص الخفيف"""
        if not (IS_ADMIN_BUILD and self.client_id) or getattr(self, "_mirror_busy", False):
            return
        if not manual and self._admin_ui_busy():
            return
        self._mirror_busy = True
        self._mirror_ticks = getattr(self, "_mirror_ticks", 0) + 1
        known_stamp = getattr(self, "_mirror_stamp", None)
        current_at, _version, is_snapshot = self.admin_mirror_info()
        if not is_snapshot:
            current_at = None       # المعروض إعادة بناء: أي نسخة كاملة تصل أولى منه
        full_due = manual or self._mirror_ticks % self.ADMIN_MIRROR_FULL_EVERY == 0
        if manual and hasattr(self, "lbl_cloud_sync"):
            self.lbl_cloud_sync.configure(text="⏳ جارٍ تنزيل آخر نسخة من العميل…", text_color="#1f77b4")

        known_hash = getattr(self, "_mirror_hash", None)

        def work():
            result = ("same", None, None, None)
            try:
                stamp = cloud_backup_stamp(self.client_id)
                if not manual and (stamp == "" or (stamp and stamp == known_stamp)
                                   or (stamp is None and not full_due)):
                    result = ("same", None, stamp, None)
                else:
                    tmp = f"{self.db_path}.mirror_new"
                    _remove_db_files(tmp)
                    if cloud_download_backup(self.client_id, tmp) and is_sqlite_db_healthy(tmp):
                        with open(tmp, "rb") as f:
                            new_hash = hashlib.sha256(f.read()).hexdigest()
                        with contextlib.closing(sqlite3.connect(tmp)) as con:
                            row = con.execute("SELECT value FROM settings WHERE key = ?",
                                              (MIRROR_META_TIME,)).fetchone()
                        new_at = row[0] if row else ""
                        if (new_at and new_at == current_at) or new_hash == known_hash:
                            _remove_db_files(tmp)
                            result = ("same", None, stamp, new_hash)
                        else:
                            result = ("new", tmp, stamp, new_hash)
                    else:
                        _remove_db_files(tmp)
                        result = ("failed", None, None, None)
            except Exception as e:
                log_cloud_error("تعذّر تحديث نسخة العميل للمدير", e)
                result = ("failed", None, None, None)
            self.after(0, lambda: self._apply_admin_mirror(*result, manual=manual))

        threading.Thread(target=work, daemon=True).start()

    def _apply_admin_mirror(self, status, tmp_path, stamp, content_hash=None, manual=False):
        self._mirror_busy = False
        if status != "failed" and content_hash:
            self._mirror_hash = content_hash
        if status == "failed":
            if manual and hasattr(self, "lbl_cloud_sync"):
                self.lbl_cloud_sync.configure(text="⚠️ تعذّر تنزيل نسخة العميل — تحقق من الإنترنت",
                                              text_color="#e74c3c")
            return
        if status == "same":
            if stamp:
                self._mirror_stamp = stamp
            if manual:
                self.show_admin_mirror_status()
            return
        if not manual and self._admin_ui_busy():
            _remove_db_files(tmp_path)         # تُعاد في الفحص التالي بعد إغلاق النافذة
            return
        try:
            month = self.current_display_month
            mark_mirror_source(tmp_path)
            reset_local_cache(self.db_path)
            os.replace(tmp_path, self.db_path)
            self.init_database()
            self.load_data_from_db()
            # الفترة التي يتصفّحها المدير تبقى كما هي
            self.current_display_month = month
            self.update_period_selector()
            self.recalculate_all()
            # معلقات المبيعات من نسخة العميل نفسها (ليست حركات فلا يحدّثها recalculate_all)
            if hasattr(self, "sales_subtab_buttons"):
                self.update_suspended_count()
                if getattr(self, "current_sales_subtab", "") == "المعلقات":
                    self.refresh_suspended_sales_table()
            if stamp:
                self._mirror_stamp = stamp
            self.show_admin_mirror_status(updated=True)
            self.after(8000, self.show_admin_mirror_status)
        except Exception as e:
            log_cloud_error("تعذّر عرض النسخة الجديدة من العميل", e)
            _remove_db_files(tmp_path)

    def on_app_closing(self):
        try:
            if getattr(self, 'gold_watcher', None):
                self.gold_watcher.stop()
        except Exception:
            pass
        try:
            if getattr(self, 'scale_reader', None):
                self.scale_reader.stop(timeout=0.5)
        except Exception:
            pass
        """يحاول رفع نسخة أخيرة للسحابة قبل إغلاق البرنامج (بدون تعطيل الإغلاق لو فشل الاتصال)"""
        if not IS_ADMIN_BUILD:
            try:
                threading.Thread(target=cloud_upload_backup, args=(self.client_id, self.db_path), daemon=True).start()
            except Exception:
                pass
        self.destroy()

    def list_local_backups(self):
        """يرجع مسارات النسخ الاحتياطية المحلية لهذا الحساب، من الأحدث للأقدم"""
        try:
            files = [os.path.join(self.backup_dir, f) for f in os.listdir(self.backup_dir)
                     if f.lower().endswith(".db")]
            files.sort(key=lambda p: os.path.getmtime(p), reverse=True)
            return files
        except Exception:
            return []

    def describe_backup(self, path):
        """وصف مقروء لنسخة احتياطية: وقتها، حجمها، وعدد حركاتها"""
        try:
            mtime = datetime.datetime.fromtimestamp(os.path.getmtime(path))
            size_kb = max(1, os.path.getsize(path) // 1024)
        except Exception:
            return None

        rows = periods = "?"
        try:
            con = sqlite3.connect(f"file:{path}?mode=ro", uri=True)
            rows = con.execute("SELECT COUNT(*) FROM invoices").fetchone()[0]
            cols = [c[1] for c in con.execute("PRAGMA table_info(invoices)")]
            if "period" in cols:
                periods = con.execute(
                    "SELECT COUNT(DISTINCT COALESCE(NULLIF(period,''), substr(date_time,1,7))) "
                    "FROM invoices").fetchone()[0]
            else:
                periods = con.execute(
                    "SELECT COUNT(DISTINCT substr(date_time,1,7)) FROM invoices").fetchone()[0]
            con.close()
        except Exception:
            pass

        delta = datetime.datetime.now() - mtime
        if delta.days >= 1:
            ago = f"قبل {delta.days} يوم"
        elif delta.seconds >= 3600:
            ago = f"قبل {delta.seconds // 3600} ساعة"
        else:
            ago = f"قبل {max(1, delta.seconds // 60)} دقيقة"

        return {"path": path, "when": mtime.strftime("%Y-%m-%d  %H:%M"), "ago": ago,
                "rows": rows, "periods": periods, "size": f"{size_kb} كيلوبايت"}

    def open_backup_restore_window(self):
        """شاشة استعادة نسخة احتياطية سابقة.

        تعرض كل النسخ المحفوظة بوقتها وعدد حركاتها وفتراتها، فيختار المستخدم
        النسخة الصحيحة بنفسه — لا تخمين ولا استعادة عمياء.
        """
        backups = self.list_local_backups()
        if not backups:
            messagebox.showinfo(
                "لا توجد نسخ",
                f"لم يُعثر على نسخ احتياطية في:\n{self.backup_dir}")
            return

        win = ctk.CTkToplevel(self)
        win.title("استعادة نسخة احتياطية")
        win.geometry("820x560")
        win.transient(self)
        win.grab_set()
        win.focus_force()

        ctk.CTkLabel(win, text="🗄️ استعادة نسخة احتياطية سابقة",
                     font=("Cairo", 20, "bold"), text_color="#d4af37").pack(pady=(16, 2))
        ctk.CTkLabel(win,
                     text="اختر النسخة التي تريد الرجوع إليها — الأحدث أولاً.\n"
                          "قبل الاستعادة تُحفظ نسخة من وضعك الحالي تلقائياً، فلا تفقد شيئاً.",
                     font=("Cairo", 12), text_color="#8b8f95", justify="center").pack(pady=(0, 10))

        frame = ttk.Frame(win)
        frame.pack(fill="both", expand=True, padx=18, pady=6)

        cols = ("وقت النسخة", "منذ", "عدد الحركات", "عدد الفترات", "الحجم")
        tree = self.create_standard_treeview(frame, cols, height=14)
        for c, w in zip(cols, (200, 130, 130, 120, 130)):
            tree.column(c, width=w, anchor="center")

        info_by_iid = {}
        for path in backups:
            info = self.describe_backup(path)
            if not info:
                continue
            iid = tree.insert("", "end", values=(
                info["when"], info["ago"], info["rows"], info["periods"], info["size"]))
            info_by_iid[iid] = info

        if not info_by_iid:
            messagebox.showwarning("تعذّر", "لم يمكن قراءة أي نسخة احتياطية.", parent=win)
            win.destroy()
            return

        def do_restore():
            sel = tree.selection()
            if not sel:
                messagebox.showwarning("تنبيه", "اختر النسخة المراد استعادتها.", parent=win)
                return
            info = info_by_iid[sel[0]]

            if not messagebox.askyesno(
                    "تأكيد الاستعادة",
                    f"استعادة نسخة {info['when']} ({info['ago']})\n"
                    f"عدد حركاتها: {info['rows']}  |  فتراتها: {info['periods']}\n\n"
                    "سيُستبدل وضعك الحالي ببيانات هذه النسخة.\n"
                    "وستُحفظ نسخة من وضعك الحالي قبل ذلك تلقائياً.\n\n"
                    "هل تريد المتابعة؟", parent=win):
                return

            ok, msg = self.restore_from_backup(info["path"])
            win.destroy()
            if ok:
                messagebox.showinfo(
                    "تمت الاستعادة",
                    f"تمت استعادة نسخة {info['when']} بنجاح.\n\n"
                    "سيُغلق البرنامج الآن — افتحه من جديد لتظهر بياناتك المستعادة.")
                self.destroy()
            else:
                messagebox.showerror("تعذّرت الاستعادة", msg)

        btns = ctk.CTkFrame(win, fg_color="transparent")
        btns.pack(pady=12)
        ctk.CTkButton(btns, text="↩️ استعادة النسخة المحددة", font=("Cairo", 15, "bold"),
                      fg_color="#1e8449", hover_color="#145a32", width=250, height=44,
                      command=do_restore).pack(side="left", padx=6)
        ctk.CTkButton(btns, text="📂 فتح مجلد النسخ", font=("Cairo", 13),
                      fg_color="#555555", hover_color="#333333", width=160, height=44,
                      command=lambda: self.open_folder(self.backup_dir)).pack(side="left", padx=6)
        ctk.CTkButton(btns, text="إغلاق", font=("Cairo", 13), fg_color="#555555",
                      hover_color="#333333", width=120, height=44,
                      command=win.destroy).pack(side="left", padx=6)

    def restore_from_backup(self, backup_path):
        """يستعيد قاعدة البيانات من نسخة احتياطية.

        الترتيب مقصود: نحفظ الوضع الحالي أولاً، ثم نتحقق من سلامة النسخة
        المختارة، ثم نستبدل — فلا يُفقد شيء حتى لو كانت النسخة تالفة.
        يرجع: (نجح؟، رسالة)
        """
        try:
            # (١) حفظ الوضع الحالي قبل أي تغيير
            stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            safety = os.path.join(self.backup_dir, f"before_restore_{stamp}.db")
            with sqlite3.connect(self.db_path) as srccon, sqlite3.connect(safety) as dst:
                srccon.backup(dst)

            # (٢) التحقق من سلامة النسخة المختارة قبل الاعتماد عليها
            probe = sqlite3.connect(f"file:{backup_path}?mode=ro", uri=True)
            try:
                integrity = probe.execute("PRAGMA integrity_check").fetchone()[0]
                if integrity != "ok":
                    return False, f"النسخة تالفة (فحص السلامة: {integrity}).\nلم يتغيّر شيء."
                probe.execute("SELECT COUNT(*) FROM invoices").fetchone()
            finally:
                probe.close()

            # (٣) الاستبدال
            with sqlite3.connect(backup_path) as srccon, sqlite3.connect(self.db_path) as dst:
                srccon.backup(dst)

            log_cloud_error("تمت استعادة نسخة احتياطية",
                            Exception(f"{backup_path} (نسخة الأمان: {safety})"))
            return True, "تمت الاستعادة"
        except Exception as e:
            return False, f"تعذّرت الاستعادة:\n{e}\n\nلم يتغيّر شيء في بياناتك الحالية."

    def open_folder(self, path):
        """يفتح مجلداً في مستكشف الملفات"""
        try:
            if sys.platform.startswith("win"):
                os.startfile(path)
            elif sys.platform == "darwin":
                subprocess.Popen(["open", path])
            else:
                subprocess.Popen(["xdg-open", path])
        except Exception as e:
            messagebox.showinfo("المسار", f"{path}\n\n({e})")

    def restore_missing_db_from_local_backup(self):
        """ملف قاعدة العميل غير موجود على الجهاز: تُسترجع من أحدث نسخة احتياطية
        سليمة في مجلد النسخ على الجهاز نفسه (النسخ تُؤخذ كل ١٥ دقيقة).

        نسخ فقط — لا يُحذف ولا يُعاد تسمية أي ملف في مجلد العميل. ولا يُنزَّل
        شيء من السحابة. يرجع مسار النسخة المستعادة، أو None إن لم توجد.
        """
        for backup in self.list_local_backups():
            if not is_sqlite_db_healthy(backup):
                continue
            try:
                shutil.copy2(backup, self.db_path)
            except Exception:
                continue
            name = os.path.basename(backup)
            log_cloud_error("استرجاع قاعدة العميل من نسخة احتياطية محلية", Exception(backup))
            try:
                self.after(600, lambda: messagebox.showinfo(
                    "استرجاع البيانات",
                    "لم يُعثر على ملف بياناتك، فتم استرجاعها تلقائياً من آخر نسخة احتياطية "
                    f"على جهازك:\n{name}"))
            except Exception:
                pass
            return backup
        return None

    def recover_corrupt_database(self):
        """يُستدعى تلقائياً لو كان ملف قاعدة البيانات تالفاً:
        يعزل الملف التالف، ثم يسترجع من أحدث نسخة احتياطية محلية سليمة على الجهاز
        (ونسخة المدير وحدها تلجأ للسحابة إن لم توجد نسخة محلية)."""
        stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        broken_path = f"{self.db_path}.corrupt_{stamp}"
        try:
            shutil.move(self.db_path, broken_path)
        except Exception:
            try:
                os.remove(self.db_path)
            except Exception:
                pass

        restored_from = None
        for backup in self.list_local_backups():
            if is_sqlite_db_healthy(backup):
                try:
                    shutil.copy2(backup, self.db_path)
                    restored_from = f"نسخة احتياطية محلية ({os.path.basename(backup)})"
                    break
                except Exception:
                    continue

        # السحابة ملاذ نسخة المدير فقط — نسخة العميل لا تسحب منها أبداً
        if not restored_from and self.client_id and IS_ADMIN_BUILD:
            if cloud_download_backup(self.client_id, self.db_path) and is_sqlite_db_healthy(self.db_path):
                restored_from = "النسخة المحفوظة على السحابة"
            elif os.path.exists(self.db_path):
                try:
                    os.remove(self.db_path)
                except Exception:
                    pass

        msg = (f"تم اكتشاف تلف في ملف قاعدة البيانات، وتم عزله في:\n{broken_path}\n\n"
               + (f"✅ وتم استرجاع بياناتك من: {restored_from}"
                  if restored_from else
                  "⚠️ لم يتم العثور على نسخة احتياطية سليمة، وسيبدأ البرنامج بقاعدة بيانات جديدة.\n"
                  "لا تُدخل بيانات جديدة قبل التواصل مع المدير لمحاولة الاسترجاع."))
        log_cloud_error("استرجاع قاعدة بيانات تالفة", msg.replace("\n", " | "))
        try:
            self.after(600, lambda: messagebox.showwarning("استرجاع قاعدة البيانات", msg))
        except Exception:
            pass

    def open_backup_manager(self):
        """نافذة إدارة النسخ الاحتياطية والسحابة: رفع فوري، استرجاع، وعرض مسارات الملفات"""
        win = ctk.CTkToplevel(self)
        win.title("النسخ الاحتياطي والسحابة")
        win.geometry("640x520")
        win.transient(self)
        win.grab_set()
        win.focus_force()

        ctk.CTkLabel(win, text="☁️ النسخ الاحتياطي واسترجاع البيانات", font=("Cairo", 18, "bold"), text_color="#d4af37").pack(pady=(14, 6))

        info = ctk.CTkFrame(win)
        info.pack(fill="x", padx=18, pady=8)
        ctk.CTkLabel(info, text=f"مجلد ملفات النظام:\n{APP_DATA_DIR}", font=("Cairo", 12), justify="right", anchor="e").pack(fill="x", padx=10, pady=(8, 2))
        ctk.CTkLabel(info, text=f"قاعدة البيانات:\n{self.db_path}", font=("Cairo", 12), justify="right", anchor="e").pack(fill="x", padx=10, pady=2)
        ctk.CTkLabel(info, text=f"النسخ الاحتياطية المحلية:\n{self.backup_dir}", font=("Cairo", 12), justify="right", anchor="e").pack(fill="x", padx=10, pady=(2, 8))

        lbl_status = ctk.CTkLabel(win, text="", font=("Cairo", 13, "bold"), text_color="#2ecc71")
        lbl_status.pack(pady=4)

        backups = self.list_local_backups()
        ctk.CTkLabel(win, text=f"عدد النسخ الاحتياطية المحلية المتاحة: {len(backups)}", font=("Cairo", 13, "bold"), text_color="#1f77b4").pack(pady=(2, 8))

        def do_backup_now():
            self.perform_backup()
            lbl_status.configure(text="✅ تم أخذ نسخة احتياطية محلية جديدة", text_color="#2ecc71")

        def do_upload_now():
            if not self.client_id:
                lbl_status.configure(text="هذه جلسة محلية بدون حساب سحابي.", text_color="#e67e22")
                return
            lbl_status.configure(text="⏳ جاري الرفع للسحابة...", text_color="#1f77b4")

            def _work():
                ok = cloud_upload_backup(self.client_id, self.db_path, force=True)   # الرفع اليدوي يُرفع دائماً
                self.after(0, lambda: lbl_status.configure(
                    text="✅ تم رفع نسخة محدّثة للسحابة" if ok else "⚠️ تعذّر الرفع — تأكد من الاتصال بالإنترنت",
                    text_color="#2ecc71" if ok else "#e74c3c"))

            threading.Thread(target=_work, daemon=True).start()

        def do_cloud_restore():
            if not self.client_id:
                lbl_status.configure(text="هذه جلسة محلية بدون حساب سحابي.", text_color="#e67e22")
                return
            if not messagebox.askyesno(
                    "استرجاع من السحابة",
                    "سيتم استبدال البيانات الحالية على هذا الجهاز بآخر نسخة محفوظة على السحابة لحسابك.\n\n"
                    "سيتم أولاً حفظ نسخة احتياطية من البيانات الحالية تلقائياً.\n"
                    "هل تريد المتابعة؟", parent=win):
                return

            self.perform_backup()   # نسخة أمان من الوضع الحالي قبل أي استبدال
            tmp_path = f"{self.db_path}.cloud_tmp"
            lbl_status.configure(text="⏳ جاري التنزيل من السحابة...", text_color="#1f77b4")

            def _work():
                ok = cloud_download_backup(self.client_id, tmp_path) and is_sqlite_db_healthy(tmp_path)

                def _apply():
                    if not ok:
                        try:
                            os.remove(tmp_path)
                        except Exception:
                            pass
                        lbl_status.configure(text="⚠️ تعذّر الاسترجاع — لا توجد نسخة سليمة أو لا يوجد اتصال", text_color="#e74c3c")
                        return
                    try:
                        shutil.move(tmp_path, self.db_path)
                    except Exception as e:
                        lbl_status.configure(text=f"⚠️ تعذّر استبدال الملف: {e}", text_color="#e74c3c")
                        return
                    self.load_data_from_db()
                    self.update_period_selector()
                    self.recalculate_all()
                    lbl_status.configure(text="✅ تم استرجاع البيانات من السحابة وتحديث كل الشاشات", text_color="#2ecc71")

                self.after(0, _apply)

            threading.Thread(target=_work, daemon=True).start()

        btns = ctk.CTkFrame(win, fg_color="transparent")
        btns.pack(pady=10)
        ctk.CTkButton(btns, text="💾 نسخة احتياطية الآن", font=("Cairo", 14, "bold"), width=185, height=42,
                      fg_color="#1e8449", hover_color="#145a32", command=do_backup_now).pack(side="right", padx=6)
        if not IS_ADMIN_BUILD:
            ctk.CTkButton(btns, text="⬆️ رفع للسحابة الآن", font=("Cairo", 14, "bold"), width=185, height=42,
                          fg_color="#1f77b4", hover_color="#144d75", command=do_upload_now).pack(side="right", padx=6)

        # الاستعادة المحلية أولاً وأبرز: النسخ على جهازك هي الأوثق، والسحابة
        # قد تحمل حالة لا تريدها
        ctk.CTkButton(win, text="🗄️ استعادة نسخة احتياطية من جهازي", font=("Cairo", 15, "bold"),
                      width=340, height=48, fg_color="#1e8449", hover_color="#145a32",
                      command=lambda: (win.destroy(), self.open_backup_restore_window())).pack(pady=(10, 6))

        # نسخة العميل لا تسحب من السحابة أبداً: بياناتها على جهازها هي مصدر الحقيقة،
        # وتستعيد من نسخها المحلية فقط (الزر أعلاه). السحب لنسخة المدير وحدها.
        if IS_ADMIN_BUILD:
            ctk.CTkButton(win, text="⬇️ استرجاع آخر نسخة من السحابة", font=("Cairo", 14, "bold"), width=300, height=44,
                          fg_color="#b8860b", hover_color="#daa520", command=do_cloud_restore).pack(pady=8)

        ctk.CTkButton(win, text="📂 فتح مجلد ملفات النظام", font=("Cairo", 13, "bold"), width=240, height=38,
                      fg_color="#555555", hover_color="#333333", command=self.open_app_data_folder).pack(pady=(4, 14))

    def perform_backup(self):
        """نظام النسخ الاحتياطي الآمن لقاعدة البيانات"""
        try:
            if not os.path.exists(self.backup_dir):
                os.makedirs(self.backup_dir)
            
            timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            backup_path = os.path.join(self.backup_dir, f"gold_backup_{timestamp}.db")
            
            # النسخ الآمن باستخدام مكتبة sqlite3 لمنع التلف أثناء النسخ
            with sqlite3.connect(self.db_path) as src:
                with sqlite3.connect(backup_path) as dst:
                    src.backup(dst)
            
            # الاحتفاظ بأحدث 20 نسخة فقط لتوفير المساحة
            backups = sorted(os.listdir(self.backup_dir))
            while len(backups) > 20:
                oldest = backups.pop(0)
                os.remove(os.path.join(self.backup_dir, oldest))
        except Exception as e:
            print("فشل النسخ الاحتياطي التلقائي:", e)

    def schedule_backup(self):
        """جدولة النسخ الاحتياطي كل 15 دقيقة (900000 ملي ثانية)"""
        self.after(900000, self.auto_backup_trigger)

    def auto_backup_trigger(self):
        self.perform_backup()
        self.schedule_backup()

    def setup_treeview_styles(self):
        """تنسيق الجداول يأتي من نظام التصميم وحده (apply_design_system)"""
        self.apply_design_system()

    # المظاهر بالترتيب الذي يدور عليه زر المظهر، ونص الزر لكل منها
    THEME_CYCLE = ("Light", "Dark", "System")
    # نص قصير يسعه الزر حتى على شريط اللابتوب الصغير
    THEME_LABELS = {"Light": "☀️ فاتح", "Dark": "🌙 داكن", "System": "🖥️ تلقائي"}

    def toggle_theme(self):
        """فاتح ← داكن ← تلقائي (يتبع إعداد ويندوز نهاراً وليلاً) ← فاتح.

        الاختيار يُحفظ على هذا الجهاز ويُفتح به البرنامج في المرة التالية. التنسيق
        الموحّد للجداول يُطبَّق فوراً (لا نمط قديم يومض ثم يُستبدل).
        """
        cycle = self.THEME_CYCLE
        cur = self.current_theme if self.current_theme in cycle else "Light"
        self.current_theme = cycle[(cycle.index(cur) + 1) % len(cycle)]
        ctk.set_appearance_mode(self.current_theme)
        save_ui_pref("theme", self.current_theme)
        try:
            self.btn_theme.configure(text=self.THEME_LABELS[self.current_theme])
        except Exception:
            pass
        self.apply_design_system()
        self.recalculate_all()


    def init_database(self):
        with sqlite3.connect(self.db_path) as conn:
            cursor = conn.cursor()
            
            # تفعيل نظام (WAL) للحماية القصوى ضد انقطاع الكهرباء
            cursor.execute("PRAGMA journal_mode=WAL;")
            cursor.execute("PRAGMA synchronous=NORMAL;")
            
            cursor.execute("""
                CREATE TABLE IF NOT EXISTS names (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT UNIQUE,
                    category TEXT
                )
            """)

            cursor.execute("""
                CREATE TABLE IF NOT EXISTS settings (
                    key TEXT PRIMARY KEY,
                    value TEXT
                )
            """)
            
            # تثبيت المسميات المطلوبة في قسم الآلة/المكائن تلقائياً
            cursor.execute("INSERT OR IGNORE INTO names (name, category) VALUES ('الكاستينج', 'الآلة/المكائن')")
            cursor.execute("INSERT OR IGNORE INTO names (name, category) VALUES ('التلميع النهائي', 'الآلة/المكائن')")

            cursor.execute("""
                CREATE TABLE IF NOT EXISTS invoices (
                    invoice_id INTEGER PRIMARY KEY,
                    date_time TEXT,
                    name TEXT,
                    op_type TEXT,
                    weight REAL,
                    before_w REAL,
                    after_w REAL,
                    note TEXT,
                    settled_status TEXT DEFAULT 'ACTIVE',
                    trees_count REAL DEFAULT 0,
                    set_number TEXT DEFAULT '',
                    period TEXT DEFAULT ''
                )
            """)
            cursor.execute("""
                CREATE TABLE IF NOT EXISTS monthly_archive (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    archive_date TEXT,
                    name TEXT,
                    category TEXT,
                    sarf REAL DEFAULT 0,
                    qabd REAL DEFAULT 0,
                    leez REAL DEFAULT 0,
                    polish REAL DEFAULT 0,
                    mufanish_8 REAL DEFAULT 0,
                    mufanish_4 REAL DEFAULT 0,
                    salk_rajia REAL DEFAULT 0,
                    ayar_fahs REAL DEFAULT 0,
                    before_w REAL DEFAULT 0,
                    after_w REAL DEFAULT 0,
                    khayas REAL DEFAULT 0,
                    production REAL DEFAULT 0,
                    note TEXT,
                    linked_inv_id INTEGER DEFAULT 0,
                    trees_count REAL DEFAULT 0
                )
            """)
            
            # الفواتير المعلّقة في شاشة المبيعات (لا حركات محاسبية — مسودّات تُستكمل لاحقاً)
            cursor.execute(self.SUSPENDED_TABLE_SQL)
            cursor.execute("CREATE INDEX IF NOT EXISTS idx_inv_date ON invoices(date_time)")
            cursor.execute("CREATE INDEX IF NOT EXISTS idx_inv_name ON invoices(name)")
            cursor.execute("CREATE INDEX IF NOT EXISTS idx_inv_status ON invoices(settled_status)")
            cursor.execute("CREATE INDEX IF NOT EXISTS idx_arch_date ON monthly_archive(archive_date)")
            cursor.execute("CREATE INDEX IF NOT EXISTS idx_arch_cat ON monthly_archive(category)")

            cursor.execute("PRAGMA table_info(invoices)")
            columns = [col[1] for col in cursor.fetchall()]
            if "settled_status" not in columns:
                cursor.execute("ALTER TABLE invoices ADD COLUMN settled_status TEXT DEFAULT 'ACTIVE'")
            if "trees_count" not in columns:
                cursor.execute("ALTER TABLE invoices ADD COLUMN trees_count REAL DEFAULT 0")
            if "set_number" not in columns:
                cursor.execute("ALTER TABLE invoices ADD COLUMN set_number TEXT DEFAULT ''")
            if "row_number" not in columns:
                cursor.execute("ALTER TABLE invoices ADD COLUMN row_number TEXT DEFAULT ''")
            if "manual_no" not in columns:
                # رقم الفاتورة اليدوي (يُدخله المستخدم في شاشة المبيعات ويُعتمد كرقم للفاتورة)
                cursor.execute("ALTER TABLE invoices ADD COLUMN manual_no TEXT DEFAULT ''")
            if "period" not in columns:
                # الفترة المحاسبية صراحةً، منفصلة عن تاريخ العملية الحقيقي
                cursor.execute("ALTER TABLE invoices ADD COLUMN period TEXT DEFAULT ''")
            # ═══════════════════════════════════════════════════════════
            #  ترحيل السطور المعلوماتية المسجّلة قبل هذا التحديث
            #
            #  خياس البوليش وخياس المركب وصافي الطقم كانت تُسجَّل بحالة
            #  SETTLED_INOUT التي **تُحتسب** في الخزينة. فتظهر في كشف حساب
            #  الخزينة وتُنقص رصيدها رغم أنها معلوماتية بحتة.
            #
            #  تُحوَّل هنا إلى MEMO — الحالة التي ترفضها كل الفلاتر المحاسبية —
            #  فتختفي من الكشف ويعود الرصيد صحيحاً بأثر رجعي.
            #  (خياس التلميع النهائي بعلامة 0.0 يبقى ACTIVE كما هو)
            # ═══════════════════════════════════════════════════════════
            cursor.execute("""
                UPDATE invoices
                   SET settled_status = ?
                 WHERE op_type = 'خياس طقوم'
                   AND settled_status IN ('ACTIVE', 'SETTLED_INOUT')
                   AND trees_count IN (?, ?, ?)
            """, (MEMO_STATUS, KHAYAS_MARK_POLISH, KHAYAS_MARK_ASSEMBLER, KHAYAS_MARK_NET))
            _memo_fixed = cursor.rowcount or 0
            if _memo_fixed:
                log_cloud_error("ترحيل السطور المعلوماتية",
                                Exception(f"حُوّل {_memo_fixed} سطراً إلى MEMO"))

            # بقايا مزامنة الويب (أُزيل) تُحذف قبل أي تعديل جماعي، فلا تتراكم في صندوق صادر
            drop_web_sync_artifacts(cursor)
            # الحركات القديمة: الفترة = شهر تاريخها (نفس السلوك السابق حرفياً)
            cursor.execute("UPDATE invoices SET period = substr(date_time, 1, 7) "
                           "WHERE period IS NULL OR period = ''")
                    
            cursor.execute("PRAGMA table_info(monthly_archive)")
            arch_cols = [col[1] for col in cursor.fetchall()]
            needed_cols = {
                "archive_date": "TEXT", "sarf": "REAL DEFAULT 0", "qabd": "REAL DEFAULT 0", "leez": "REAL DEFAULT 0",
                "polish": "REAL DEFAULT 0", "mufanish_8": "REAL DEFAULT 0", "mufanish_4": "REAL DEFAULT 0", 
                "salk_rajia": "REAL DEFAULT 0", "ayar_fahs": "REAL DEFAULT 0", "before_w": "REAL DEFAULT 0", 
                "after_w": "REAL DEFAULT 0", "khayas": "REAL DEFAULT 0", "production": "REAL DEFAULT 0", 
                "linked_inv_id": "INTEGER DEFAULT 0", "trees_count": "REAL DEFAULT 0"
            }
            for col_name, col_type in needed_cols.items():
                if col_name not in arch_cols:
                    cursor.execute(f"ALTER TABLE monthly_archive ADD COLUMN {col_name} {col_type}")
            conn.commit()

    def load_data_from_db(self):
        # بيانات أُعيد تحميلها (استعادة نسخة مثلاً): خطوات التراجع السابقة لم تعد تخصّها
        self._undo_stack, self._undo_open = [], None
        self.categories = {"المصنعين": [], "المركبين": [], "الآلة/المكائن": [], "الكاستنج": [], "التلميع": [], "التلميع/البف": [], "الموردين": [], "حسابات إضافية": [], "أقسام_خياس_إضافية": [], "نسب_خصم_احجار": []}
        self.invoices = {}
        self.opening_balance = 0.0

        with sqlite3.connect(self.db_path) as conn:
            cursor = conn.cursor()
            cursor.execute("SELECT name, category FROM names")
            for row in cursor.fetchall():
                if row[1] in self.categories:
                    self.categories[row[1]].append(row[0])

            cursor.execute(f"SELECT {self.INVOICE_COLUMNS} FROM invoices")
            for row in cursor.fetchall():
                self.invoices[row[0]] = self.invoice_from_row(row)
                if row[3] == "رصيد افتتاحي":
                    self.opening_balance = row[4]
                    
            cursor.execute("SELECT MAX(invoice_id) FROM invoices")
            max_id = cursor.fetchone()[0]

        self.invoice_counter = max_id if max_id else 1000

        # الفترة المعروضة = الشهر الحالي فعلياً حسب تاريخ الجهاز، دائماً.
        #
        # سابقاً كانت تُضبط على (أحدث شهر فيه حركات)، فكان البرنامج يفتح على
        # الشهر السابق في بداية كل شهر جديد قبل تسجيل أول حركة فيه — وتُعبّأ
        # خانات التاريخ بأول يوم من الشهر الماضي، فتُسجَّل حركات الشهر الجديد
        # في الشهر الخطأ. الاختيار اليدوي من قائمة الفترات يبقى متاحاً كما هو.
        self.current_display_month = datetime.datetime.now().strftime("%Y-%m")
        self.neutralize_auto_recovery_closings()
        self.migrate_casting_returns()
        self.migrate_row_extras()

    AUTO_RECOVERY_CLOSE_NOTE = "مسترجع — أُلغي: كان إقفالاً تلقائياً عند الوارد (الإقفال بالزر وحده)"

    def neutralize_auto_recovery_closings(self):
        """يلغي أثر «الإقفال التلقائي عند وارد المسترجع» في البيانات السابقة.

        كان كل وارد باسم مسترجع صندوق يُتبَع آلياً بقيد بين «حساب الخسائر» والصندوق
        (بيانه «مسترجع») يُقفل باقي فاقده الحالي. الآن الإقفال بزر الإقفال وحده،
        والمسترجع يذهب لحساب مسترجع المرحلة فقط — فتلك القيود تُستثنى من كل الأرصدة.
        لا تُحذف: تبقى محفوظة سطوراً معلوماتية (حالة MEMO، ومعها سبب الإلغاء في
        بيانها)، فيظهر فاقد تلك الفترات كاملاً ليُقفل بالزر.

        تُعرف بدقة: وارد باسم مسترجع، يليه مباشرةً طرفا قيد برقم «JE-(رقمه+١)»
        وبتاريخه نفسه، بيانهما «مسترجع»، بين «حساب الخسائر» وحساب صندوق.
        نسخة العميل تحفظ التعديل في قاعدتها (فيُرفع للسحابة)، ونسخة المدير في الذاكرة.
        """
        try:
            recovery_names = set(self.get_all_mustarja_names())
            box_names = {self.get_box_account_name(c) for c in self.get_khayas_box_categories()}
        except Exception:
            return 0
        found = []
        for inv_id, inv in list(self.invoices.items()):
            if inv.get("النوع") not in self.RECOVERY_IN_TYPES or inv.get("الاسم") not in recovery_names:
                continue
            if not isinstance(inv_id, int):
                continue
            legs = [self.invoices.get(inv_id + 1), self.invoices.get(inv_id + 2)]
            if not all(legs):
                continue
            ref = f"JE-{inv_id + 1}"
            if not all(leg.get("settled_status") == "ACTIVE" and leg.get("النوع") in self.JOURNAL_TYPES
                       and leg.get("set_number") == ref and (leg.get("البيان") or "") == "مسترجع"
                       and leg.get("التاريخ") == inv.get("التاريخ") for leg in legs):
                continue
            if {legs[0].get("النوع"), legs[1].get("النوع")} != set(self.JOURNAL_TYPES):
                continue
            names = {legs[0].get("الاسم"), legs[1].get("الاسم")}
            others = names - {self.LOSS_PARENT_ACCOUNT}
            if self.LOSS_PARENT_ACCOUNT not in names or len(others) != 1 or not others <= box_names:
                continue
            found.extend(legs)
        if not found:
            return 0
        for leg in found:
            leg["settled_status"] = MEMO_STATUS
            leg["البيان"] = self.AUTO_RECOVERY_CLOSE_NOTE
        self._inv_version = getattr(self, "_inv_version", 0) + 1
        if not IS_ADMIN_BUILD and getattr(self, "db_path", None):
            try:
                with sqlite3.connect(self.db_path) as conn:
                    conn.executemany(
                        "UPDATE invoices SET settled_status = ?, note = ? WHERE invoice_id = ?",
                        [(MEMO_STATUS, self.AUTO_RECOVERY_CLOSE_NOTE, leg["رقم الفاتورة"]) for leg in found])
                    conn.commit()
                self.mark_backup_dirty()
            except Exception as e:
                log_cloud_error("تعذّر حفظ إلغاء الإقفال التلقائي القديم للمسترجع", e)
        return len(found) // 2

    def migrate_casting_returns(self):
        """يصحّح حركات «المسترجع» التي سجّلتها شاشة الكاستنج باسم حساب «مسترجع كاستنج».

        هي رجوعٌ من الفاقد الحالي نفسه (مسترجع الأشجار، وقبض عملية «مسترجع») لا وارد
        لحساب المسترجع: تصير قبضاً للكاستنج (يُخصم من فاقده الحالي)، وصرف عملية
        «مسترجع» باسمها الجديد. تُعرف بدقة: شاشة الوارد تشترط رقم الفاتورة دائماً، وشاشة
        الكاستنج لا تضعه أبداً — فوارد باسم «مسترجع كاستنج» بلا رقم فاتورة جاء منها.
        نسخة العميل تحفظ التصحيح في قاعدتها (فيُرفع للسحابة)، ونسخة المدير في الذاكرة.
        """
        try:
            madin_type, qabd_type, rec_name = self.get_stage_config("الكاستنج")
        except Exception:
            return 0
        changed = []
        for inv in self.invoices.values():
            if inv.get("الاسم") != rec_name or (inv.get("set_number") or "").strip():
                continue
            row = (inv.get("row_number") or "").strip()
            t = inv.get("النوع")
            if t == "وارد ذهب (عيار 18)":
                if inv.get("trees_count") == 1.0 and inv.get("البيان") == "قيد افتتاحي":
                    continue           # قيد رصيد افتتاحي — ليس من الكاستنج
                inv["النوع"] = qabd_type
                inv["الاسم"] = self.TREE_RETURN_NAME if row else self.CAST_RETURN_NAME
                inv["قبل"] = inv["بعد"] = 0.0
                changed.append(inv)
            elif t == madin_type and not row:
                inv["الاسم"] = self.CAST_RETURN_NAME
                changed.append(inv)
        if not changed:
            return 0
        self._inv_version = getattr(self, "_inv_version", 0) + 1
        if not IS_ADMIN_BUILD and getattr(self, "db_path", None):
            try:
                with sqlite3.connect(self.db_path) as conn:
                    conn.executemany(
                        "UPDATE invoices SET op_type = ?, name = ?, before_w = ?, after_w = ? WHERE invoice_id = ?",
                        [(inv["النوع"], inv["الاسم"], inv.get("قبل", 0.0), inv.get("بعد", 0.0),
                          inv["رقم الفاتورة"]) for inv in changed])
                    conn.commit()
                self.mark_backup_dirty()
            except Exception as e:
                log_cloud_error("تعذّر حفظ تصحيح حركات مسترجع الكاستنج", e)
        return len(changed)

    def migrate_row_extras(self):
        """يطابق نوع «الحركة الثانية» لصفوف الأقسام مع تعريفها الحالي (stage_row_extra).

        الليزر في «بوليش 1» سُجّل قبضاً («قبض تلميع بف») في الإصدار 1.46.0، ثم صار صرفاً
        بطلب العميل: تُحوَّل حركاته القديمة إلى «صرف تلميع بف» فيُضاف الليزر إلى الفاقد
        الحالي بدل أن يُخصم منه. تُعرف بدقة: اسم «ليزر البوليش» لا يُسجَّل إلا من خانة الليزر.
        نسخة العميل تحفظ التصحيح في قاعدتها (فيُرفع للسحابة)، ونسخة المدير في الذاكرة.
        """
        changed = []
        try:
            madin_type, qabd_type, _rec = self.get_stage_config("التلميع/البف")
            extra = self.stage_row_extra(qabd_type)
        except Exception:
            return 0
        if not extra:
            return 0
        want, other = (madin_type, qabd_type) if extra[2] > 0 else (qabd_type, madin_type)
        for inv in self.invoices.values():
            if inv.get("الاسم") == extra[0] and inv.get("النوع") == other:
                inv["النوع"] = want
                changed.append(inv)
        if not changed:
            return 0
        self._inv_version = getattr(self, "_inv_version", 0) + 1
        if not IS_ADMIN_BUILD and getattr(self, "db_path", None):
            try:
                with sqlite3.connect(self.db_path) as conn:
                    conn.executemany("UPDATE invoices SET op_type = ? WHERE invoice_id = ?",
                                     [(inv["النوع"], inv["رقم الفاتورة"]) for inv in changed])
                    conn.commit()
                self.mark_backup_dirty()
            except Exception as e:
                log_cloud_error("تعذّر حفظ تصحيح حركات الليزر", e)
        return len(changed)

    def save_invoice_to_db(self, inv_id, inv_data):
        """يرجع True لو تم الحفظ فعلياً، أو False لو تم المنع (تعديل على فاتورة موجودة ومقفول عليها التعديل)"""
        with sqlite3.connect(self.db_path) as conn:
            cursor = conn.cursor()
            cursor.execute("""SELECT invoice_id, date_time, name, op_type, weight, before_w, after_w, note,
                               settled_status, trees_count, set_number, row_number, manual_no, period FROM invoices WHERE invoice_id = ?""", (inv_id,))
            existing_row = cursor.fetchone()
            existing_manual = (existing_row[12] if existing_row and len(existing_row) > 12 and existing_row[12] else "")
            existing_period = (existing_row[13] if existing_row and len(existing_row) > 13 and existing_row[13] else "")
            # داخل خطوة تراجع مفتوحة (حذف/إقفال): صورة الحركة قبل التغيير
            self._undo_note_row(inv_id, existing_row)

            # ختم الفترة المحاسبية مركزياً لكل الحركات:
            #   • حركة جديدة  → الفترة المعروضة وقت التسجيل
            #   • حركة قائمة  → تبقى فترتها الأصلية ما لم تُمرَّر صراحةً
            # المركزية مقصودة: مسارات إنشاء الحركات كثيرة (٢٧ موضعاً)، وختمها
            # هنا يضمن ألا يفلت أي مسار بلا فترة فتسقط حركته من كل الشاشات.
            if not inv_data.get("period"):
                inv_data["period"] = existing_period or self.current_display_month

            # فاتورة موجودة بالفعل بقاعدة البيانات (تعديل على عملية سابقة) ومقفول عليه التعديل؟
            if existing_row and not self.check_edit_permission():
                # نرجّع الذاكرة لنفس القيمة المخزّنة فعلياً بقاعدة البيانات (بدون أي تغيير وهمي)
                self.invoices[inv_id] = self.invoice_from_row(existing_row)
                # كائن حركة جديد مكان القديم: فهارس الأسماء والفترات تُبنى من جديد
                self._inv_version = getattr(self, "_inv_version", 0) + 1
                return False

            cursor.execute("""
                INSERT OR REPLACE INTO invoices (invoice_id, date_time, name, op_type, weight, before_w, after_w, note, settled_status, trees_count, set_number, row_number, manual_no, period)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """, (inv_id, inv_data["التاريخ"], inv_data["الاسم"], inv_data["النوع"], 
                  inv_data["الوزن"], inv_data.get("قبل", 0.0), inv_data.get("بعد", 0.0), 
                  inv_data["البيان"], inv_data.get("settled_status", "ACTIVE"), inv_data.get("trees_count", 0.0), inv_data.get("set_number", ""), inv_data.get("row_number", ""),
                  inv_data.get("رقم الفاتورة اليدوي", existing_manual),
                  inv_data.get("period") or existing_period or self.inv_period(inv_data)))
            conn.commit()
        self.mark_backup_dirty()
        return True

    def delete_invoice_from_db(self, inv_id):
        """يرجع True لو تم الحذف فعلياً، أو False لو تم المنع.
        الحذف مسموح دائماً حتى لو أقفل المدير التعديل (القفل يخص تعديل الحركات فقط)."""
        if not self.check_delete_permission():
            return False
        with sqlite3.connect(self.db_path) as conn:
            cursor = conn.cursor()
            row = cursor.execute(f"SELECT {self.INVOICE_COLUMNS} FROM invoices WHERE invoice_id = ?",
                                 (inv_id,)).fetchone()
            if row:
                # كل حذف قابل للتراجع: يفتح خطوة (أو ينضمّ لخطوة الضغطة نفسها)
                if getattr(self, "_undo_open", None) is None:
                    self.push_undo(f"حذف حركة ({row[2]} — {row[3]})", auto=True)
                self._undo_note_row(inv_id, row, deleted=True)
            cursor.execute("DELETE FROM invoices WHERE invoice_id = ?", (inv_id,))
            conn.commit()
        if inv_id in self.invoices:
            del self.invoices[inv_id]
        self.mark_backup_dirty()
        return True

    def delete_worker_from_db(self, worker_name, category, keep_transactions=True):
        """يحذف اسم العامل من شجرة الحسابات.

        keep_transactions=True (الافتراضي): **حركاته المحاسبية تبقى كما هي**.
        حذف حركات عامل يغيّر رصيد الخزينة وإجمالي الفواقد بأثر رجعي ويُفسد
        فترات مقفلة — والاسم مجرد تسمية، أما الحركات فقيود محاسبية.
        تمرير False يحذفها معه (يُستخدم عند حذف صندوق خياس بكامله بعد تأكيد
        المستخدم على عدد حركاته).
        """
        if not self.check_delete_permission():
            return False

        # خطوة تراجع قبل أي تغيير: الاسم وحركاته المحذوفة (إن حُذفت) تعود معاً
        self.push_undo(f"حذف الاسم ({worker_name})")
        self._undo_note_name(worker_name, category)

        with sqlite3.connect(self.db_path) as conn:
            cursor = conn.cursor()
            cursor.execute("DELETE FROM names WHERE name = ? AND category = ?", (worker_name, category))
            if not keep_transactions:
                for row in cursor.execute(f"SELECT {self.INVOICE_COLUMNS} FROM invoices "
                                          "WHERE name = ? AND settled_status = 'ACTIVE'", (worker_name,)).fetchall():
                    self._undo_note_row(row[0], row, deleted=True)
                cursor.execute("DELETE FROM invoices WHERE name = ? AND settled_status = 'ACTIVE'",
                               (worker_name,))
            conn.commit()

        if worker_name in self.categories.get(category, []):
            self.categories[category].remove(worker_name)
        if not keep_transactions:
            # الذاكرة كالقاعدة تماماً: تُحذف الحركات النشطة وحدها (كانت تُحذف من الذاكرة كل
            # حركات الاسم فتعود المؤرشفة والمعلوماتية بعد إعادة التشغيل)
            self.invoices = {k: v for k, v in self.invoices.items()
                             if not (v["الاسم"] == worker_name and v.get("settled_status") == "ACTIVE")}
        self.mark_backup_dirty()
        return True

    # =====================================================================
    # --- التراجع عن آخر خطوة (مثل Ctrl+Z) ---
    # =====================================================================
    # سجل خفيف لكل خطوة: الصورة السابقة **من القاعدة** لكل حركة تُحفظ أو تُحذف
    # داخل الخطوة، والأسماء المحذوفة — لا نسخة كاملة من البيانات (كانت اللقطة
    # الكاملة تتضخّم بعشرات الميغابايت مع آلاف الحركات).
    UNDO_LIMIT = 20
    INVOICE_COLUMNS = ("invoice_id, date_time, name, op_type, weight, before_w, after_w, note, "
                       "settled_status, trees_count, set_number, row_number, manual_no, period")

    @staticmethod
    def invoice_from_row(row):
        """صف جدول الحركات ← حركة في الذاكرة (المصدر الواحد للتحويل عند التحميل والتراجع)"""
        return {
            "رقم الفاتورة": row[0], "التاريخ": row[1], "الاسم": row[2],
            "النوع": row[3], "الوزن": row[4], "قبل": row[5], "بعد": row[6], "البيان": row[7],
            "settled_status": row[8], "trees_count": row[9] if len(row) > 9 and row[9] else 0.0,
            "رقم الفاتورة اليدوي": row[12] if len(row) > 12 and row[12] else "",
            "set_number": row[10] if len(row) > 10 and row[10] else "",
            "row_number": row[11] if len(row) > 11 and row[11] else "",
            # الفترة المحاسبية صراحةً؛ وتُشتق من التاريخ لو كانت فارغة
            "period": (row[13] if len(row) > 13 and row[13] else str(row[1] or "")[:7]),
        }

    def push_undo(self, label, auto=False):
        """يفتح خطوة تراجع باسمها. كل حركة تُحفظ أو تُحذف بعدها تُسجَّل صورتها
        السابقة، وتُغلق الخطوة تلقائياً بانتهاء الحدث الجاري (الضغطة نفسها) —
        فالترحيل العادي بعدها لا يدخل فيها.

        auto=True: خطوة فتحها الحذف نفسه (اسمها يُشتق مما سُجّل فيها).
        خطوة مفتوحة في الحدث نفسه تضمّ ما بعدها (حذف صندوق بعمّاله خطوة واحدة)،
        والاسم الصريح يحلّ محلّ الاسم التلقائي.
        """
        try:
            if not hasattr(self, "_undo_stack"):
                self._undo_stack = []
            step = getattr(self, "_undo_open", None)
            if step is not None and step in self._undo_stack:
                if step["auto"] and not auto:
                    step["label"], step["auto"] = label, False
                    self.update_undo_buttons()
                return step
            step = {"label": label, "auto": auto, "rows": {}, "names": [], "cats": [], "deleted": 0, "saved": 0}
            self._undo_stack.append(step)
            if len(self._undo_stack) > self.UNDO_LIMIT:
                self._undo_stack.pop(0)
            self._undo_open = step
            try:
                self.after_idle(lambda: self._close_undo_step(step))
            except Exception:
                pass
            self.update_undo_buttons()
            return step
        except Exception as e:
            log_cloud_error("تعذّر فتح خطوة التراجع", e)
            return None

    def _close_undo_step(self, step):
        if getattr(self, "_undo_open", None) is step:
            self._undo_open = None
        # خطوة لم يُسجَّل فيها شيء (مُنع الحذف مثلاً) لا تبقى في المكدس
        if not (step["rows"] or step["names"] or step["cats"]) and step in getattr(self, "_undo_stack", []):
            self._undo_stack.remove(step)
        self.update_undo_buttons()

    def _undo_note_row(self, inv_id, row, deleted=False):
        """يسجّل صورة الحركة قبل أول تغيير لها داخل الخطوة المفتوحة (None = حركة جديدة)"""
        step = getattr(self, "_undo_open", None)
        if step is None:
            return
        if inv_id not in step["rows"]:
            step["rows"][inv_id] = tuple(row) if row else None
        step["deleted" if deleted else "saved"] += 1

    def _undo_note_name(self, name, category):
        """اسم موجود فعلاً سيُحذف: يُسجَّل بموضعه ليعود في مكانه"""
        step = getattr(self, "_undo_open", None)
        names = self.categories.get(category, [])
        if step is not None and name in names:
            step["names"].append((name, category, names.index(name)))

    def undo_step_label(self, step):
        if not step.get("auto"):
            return step["label"]
        if step["saved"]:
            return f"تعديل/حذف {len(step['rows'])} حركة"
        n = step["deleted"]
        return step["label"] if n <= 1 else f"حذف {n} حركات"

    def can_undo(self):
        return bool(getattr(self, "_undo_stack", []))

    def update_undo_buttons(self):
        """يفعّل أو يعطّل أزرار التراجع حسب توفّر خطوة سابقة"""
        label = "↩️ تراجع"
        if self.can_undo():
            label = f"↩️ تراجع: {self.undo_step_label(self._undo_stack[-1])}"
        for btn, compact in getattr(self, "_undo_buttons", []):
            try:
                btn.configure(text="↩️ تراجع" if compact or len(label) >= 34 else label,
                              state="normal" if self.can_undo() else "disabled")
            except Exception:
                continue

    def register_undo_button(self, btn, compact=False):
        """compact: زر الشريط العلوي يبقى قصيراً (اسم الخطوة يظهر في تأكيد التراجع)"""
        if not hasattr(self, "_undo_buttons"):
            self._undo_buttons = []
        self._undo_buttons.append((btn, compact))
        self.update_undo_buttons()

    def _on_ctrl_z(self, event=None):
        """Ctrl+Z خارج خانات الكتابة = تراجع عن آخر حذف أو إقفال"""
        try:
            focus = self.focus_get()
        except Exception:
            focus = None
        if isinstance(focus, (tk.Entry, tk.Text)):
            return None
        self.undo_last_action()
        return "break"

    def undo_last_action(self):
        """يُرجع الحالة إلى ما قبل آخر خطوة قابلة للتراجع"""
        if not self.can_undo():
            messagebox.showinfo("لا يوجد", "لا توجد خطوة يمكن التراجع عنها.")
            return
        if not self.check_edit_permission():
            return

        step = self._undo_stack[-1]
        label = self.undo_step_label(step)
        if not messagebox.askyesno(
                "تأكيد التراجع",
                f"سيتم التراجع عن: {label}\n\n"
                f"وتعود {len(step['rows'])} حركة كما كانت قبل هذه الخطوة. هل تريد المتابعة؟"):
            return

        self._undo_stack.pop()
        self._undo_open = None
        try:
            self.apply_undo_step(step)
            self.recalculate_all()
            for fn in ("refresh_journal_entries_table", "refresh_losses_tab", "refresh_khayas_category_buttons",
                       "refresh_chart_of_accounts", "refresh_stage_buttons"):
                if hasattr(self, fn):
                    try:
                        getattr(self, fn)()
                    except Exception:
                        pass
            self.update_undo_buttons()
            self.toast(f"↩️ تم التراجع عن: {label}", "success")
        except Exception as e:
            log_cloud_error("تعذّر التراجع", e)
            messagebox.showerror("خطأ", f"تعذّر إتمام التراجع:\n{e}")

    def apply_undo_step(self, step):
        """يُعيد صور الحركات والأسماء المسجّلة في الخطوة.

        القاعدة أولاً في معاملة واحدة (إما كل شيء أو لا شيء)، ثم الذاكرة من
        الصور نفسها — فتطابق الذاكرة ما يُحمَّل عند إعادة التشغيل تماماً.
        """
        marks = ",".join("?" * 14)
        with sqlite3.connect(self.db_path) as conn:
            cur = conn.cursor()
            cur.execute("BEGIN")
            try:
                for inv_id, row in step["rows"].items():
                    if row is None:
                        cur.execute("DELETE FROM invoices WHERE invoice_id = ?", (inv_id,))
                    else:
                        cur.execute(f"INSERT OR REPLACE INTO invoices ({self.INVOICE_COLUMNS}) VALUES ({marks})",
                                    row)
                for name, cat, _idx in step["names"]:
                    cur.execute("INSERT OR IGNORE INTO names (name, category) VALUES (?, ?)", (name, cat))
                conn.commit()
            except Exception:
                conn.rollback()
                raise
        for inv_id, row in step["rows"].items():
            if row is None:
                self.invoices.pop(inv_id, None)
            else:
                self.invoices[inv_id] = self.invoice_from_row(row)
        for cat in step["cats"]:
            self.categories.setdefault(cat, [])
        for name, cat, idx in reversed(step["names"]):
            names = self.categories.setdefault(cat, [])
            if name not in names:
                names.insert(min(idx, len(names)), name)
        self._inv_version = getattr(self, "_inv_version", 0) + 1
        self.mark_backup_dirty()

    def save_name_to_db(self, name, category):
        # إضافة اسم/عامل/مورد جديد = عملية طبيعية يومية، مسموحة دائماً بدون الحاجة لإذن المدير
        with sqlite3.connect(self.db_path) as conn:
            cursor = conn.cursor()
            try:
                cursor.execute("INSERT INTO names (name, category) VALUES (?, ?)", (name, category))
                conn.commit()
            except sqlite3.IntegrityError:
                pass
        self.mark_backup_dirty()

    def get_setting(self, key, default=None):
        with sqlite3.connect(self.db_path) as conn:
            cursor = conn.cursor()
            cursor.execute("SELECT value FROM settings WHERE key = ?", (key,))
            row = cursor.fetchone()
            return row[0] if row else default

    def set_setting(self, key, value):
        # إعدادات عامة للنظام (مش "فاتورة أو رقم مُثبت") — مسموحة دائماً
        with sqlite3.connect(self.db_path) as conn:
            conn.execute("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", (key, str(value)))
            conn.commit()
        self.mark_backup_dirty()

    # =====================================================================
    # --- تلوين الأرقام السالبة: إعداد مستقل لكل قسم، محفوظ ويبقى بعد الإغلاق ---
    # =====================================================================
    def negative_color_enabled(self, section):
        """هل تلوين السالب مفعّل في هذا القسم؟ (الافتراضي: غير مفعّل)"""
        return self.get_setting(f"neg_color_{section}", "0") == "1"

    def toggle_negative_color(self, section, refresh_callback=None):
        """يبدّل حالة التلوين لهذا القسم ويعيد رسم جدوله فوراً"""
        new_value = "0" if self.negative_color_enabled(section) else "1"
        self.set_setting(f"neg_color_{section}", new_value)
        self.update_negative_color_button(section)
        if refresh_callback:
            try:
                refresh_callback()
            except Exception:
                pass

    def build_negative_color_button(self, parent, section, refresh_callback=None):
        """زر صغير يظهر في أعلى جدول كل قسم (بما فيها الأقسام المضافة لاحقاً)"""
        if not hasattr(self, "neg_color_buttons"):
            self.neg_color_buttons = {}

        btn = ctk.CTkButton(
            parent, text="", font=("Cairo", 12, "bold"), width=105, height=28,
            command=lambda s=section, cb=refresh_callback: self.toggle_negative_color(s, cb))
        btn.pack(side="left", padx=5)

        self.neg_color_buttons[section] = btn
        self.update_negative_color_button(section)
        return btn

    def update_negative_color_button(self, section):
        """يحدّث شكل الزر ليعكس حالته الحالية بوضوح"""
        btn = getattr(self, "neg_color_buttons", {}).get(section)
        if btn is None:
            return
        if self.negative_color_enabled(section):
            btn.configure(text="🔴 تلوين السالب", fg_color="#8b0000", hover_color="#a52a2a")
        else:
            btn.configure(text="⚪ لون واحد", fg_color="#555555", hover_color="#333333")

    def get_discount_percentages(self):
        """كل نسب الخصم المتاحة لخانة الأحجار بعد الخصم (كنص، بدون علامة %) - القيمة الافتراضية 30 دائماً متاحة"""
        pcts = [n.replace("نسبة%", "") for n in self.categories.get("نسب_خصم_احجار", [])]
        if not pcts:
            pcts = ["30"]
        return pcts

    def add_discount_percentage(self, pct_str):
        label = f"نسبة%{pct_str}"
        if label not in self.categories.get("نسب_خصم_احجار", []):
            self.categories.setdefault("نسب_خصم_احجار", []).append(label)
            self.save_name_to_db(label, "نسب_خصم_احجار")

    def get_last_discount_percentage(self):
        return self.get_setting("last_discount_pct", self.get_discount_percentages()[0])

    def set_last_discount_percentage(self, pct_str):
        self.set_setting("last_discount_pct", pct_str)

    def register_operation_period(self, date_val):
        """تُستدعى بعد أي ترحيل: تحدّث قائمة الفترات فقط.

        الحركة تُختم بالفترة المعروضة وقت تسجيلها (save_invoice_to_db) أياً كان
        تاريخها — فتظهر في جدول الفترة الحالية دائماً. كانت هنا رسالة تقول إن
        الحركة رُحّلت لفترة شهر تاريخها ولن تظهر في الفترة الحالية، وهذا عكس
        ما يحدث فعلاً، فأُزيلت.
        """
        self.update_period_selector()

    @staticmethod
    def inv_period(inv):
        """الفترة المحاسبية لحركة: العمود الصريح إن وُجد، وإلا تُشتق من تاريخها.

        الاشتقاق ضروري لتوافق بيانات العملاء المسجّلة قبل هذا التحديث، حيث
        كانت الفترة = شهر التاريخ دائماً.
        """
        period = (inv.get("period") or "").strip()
        if period:
            return period
        # الاشتقاق من التاريخ مباشرةً هنا فقط — لا عبر self.inv_period وإلا
        # استدعت الدالة نفسها بلا نهاية
        return str(inv.get("التاريخ", ""))[:7]

    @classmethod
    def inv_in_period(cls, inv, month):
        """هل تنتمي الحركة للفترة المطلوبة؟ (فترة فارغة = بلا تقييد)"""
        if not month:
            return True
        return cls.inv_period(inv) == month

    def get_treasury_type_sets(self):
        """أنواع صرف/قبض كل صناديق الخياس (الثابتة والمضافة) وأسماء مسترجعاتها."""
        sarf_types, qabd_types, mustarja_names = set(), set(), set()
        for cat in self.get_all_stage_categories():
            madin, qabd, mustarja = self.get_stage_config(cat)
            if madin:
                sarf_types.add(madin)
            if qabd:
                qabd_types.add(qabd)
            if mustarja:
                mustarja_names.add(mustarja)
        return sarf_types, qabd_types, mustarja_names

    def treasury_bucket(self, inv, type_sets=None):
        """يصنّف حركة واحدة في بند من بنود الخزينة ويرجع (البند، الأثر بإشارته).

        ══ المصدر الوحيد لتعريف ما يمسّ الخزينة ══
        يستخدمه شريط الخزينة، ورصيد أول المدة، والتقرير الشهري، وكشف حساب
        الخزينة — فيستحيل أن يختلف رقم شاشة عن رقم التقرير.

        البنود:
          opening  رصيد افتتاحي / قيد افتتاحي من شاشة الرصيد الافتتاحي   (+)
          inbound  وارد ذهب — بما فيه الوارد لحساب مسترجع مرحلة            (+)
          sales    مبيعات ذهب / صادر ذهب                                  (−)
          boxes    صرف صناديق الخياس (−) وقبضها (+)
          closed   صرف خياس مقفل (إقفال الأرشفة القديم)                   (−)
          journal  قيد يومي على «حساب الخزينة» (مدين + / دائن −)

        (خياس المصنعين والمركبين لا يأتي من حركة واحدة بل من معادلة القسم،
         فيُضاف في treasury_period_components.)
        """
        if inv.get("settled_status") not in COUNTED_STATUSES:
            return None, 0.0
        sarf_types, qabd_types, _mustarja_names = type_sets or self.get_treasury_type_sets()
        t = inv.get("النوع")
        w = inv.get("الوزن", 0.0) or 0.0

        if t == "رصيد افتتاحي":
            return "opening", w
        if t == "وارد ذهب (عيار 18)":
            if inv.get("trees_count") == 1.0 and inv.get("البيان") == "قيد افتتاحي":
                return "opening", w
            # كل وارد ذهب «وارد» — ومنه ما سُجّل من شاشة الوارد لحساب مسترجع مرحلة:
            # ذهبٌ دخلنا فعلاً، فيظهر في لوحة الوارد والتقرير الشهري. (مسترجع الكاستنج
            # من شاشته — الأشجار وعملية «مسترجع» — قبضٌ للكاستنج نفسه فيُحسب «صناديق»)
            return "inbound", w
        if t in ("مبيعات ذهب", "مبيعات ذهب مع الماس", "صادر ذهب"):
            return "sales", -w
        if t == "صرف خياس مقفل":
            return "closed", -w
        if t in sarf_types:
            return "boxes", -w
        if t in qabd_types:
            return "boxes", w
        if inv.get("الاسم") == "حساب الخزينة":
            if t == "قيد يومي مدين":
                return "journal", w
            if t == "قيد يومي دائن":
                return "journal", -w
        return None, 0.0

    def treasury_effect(self, inv):
        """أثر حركة واحدة على رصيد الخزينة (+ وارد، − صادر، 0 لا أثر)."""
        return self.treasury_bucket(inv)[1]

    def get_workers_khayas(self, month, invoices=None):
        """الخياس الفعلي للمصنعين والمركبين في فترة — يُخصم من الخزينة سواء أُقفل أم لا.

        الإقفال قيد مزدوج بين «حساب الخسائر» وحساب الصندوق فقط، ولا يمسّ الخزينة:
        هو إعادة تصنيف للفاقد لا ذهبٌ عاد. لذلك يبقى الخياس مخصوماً بعد الإقفال —
        في فترته، وفي رصيد أول المدة لكل ما بعدها.

        (كان رصيد أول المدة يخصم «غير المُقفل» فقط، فإقفال خياس فترة ٨ كان يرفع
        رصيد افتتاح فترة ٩ بقيمة المُقفل — فتختلف أرقام فترة ٩ عن نهاية فترة ٨.
        والإقفال القديم بالأرشفة يحوّل السطور إلى SETTLED ويسجّل «صرف خياس مقفل»،
        فيصير الخياس الحي صفراً ويُخصم عبر بند closed — لا يُخصم مرتين.)
        """
        return round(
            self.get_actual_section_khayas("المصنعين", target_month=month, invoices=invoices)
            + self.get_actual_section_khayas("المركبين", target_month=month, invoices=invoices), 2)

    def treasury_period_components(self, month, invoices=None, type_sets=None):
        """بنود حركة الخزينة داخل فترة واحدة (بإشاراتها) وصافيها.

        invoices: حركات الفترة إن كانت مجمّعة مسبقاً (تسريع)، وإلا تُقرأ هنا.
        """
        type_sets = type_sets or self.get_treasury_type_sets()
        if invoices is None:
            invoices = list(self.period_invoices(month))
        comp = {"opening": 0.0, "inbound": 0.0, "sales": 0.0,
                "boxes": 0.0, "closed": 0.0, "journal": 0.0}
        for inv in invoices:
            if not inv.get("التاريخ"):
                continue
            bucket, amount = self.treasury_bucket(inv, type_sets)
            if bucket:
                comp[bucket] += amount
        comp["workers"] = -self.get_workers_khayas(month, invoices=invoices)
        comp = {k: round(v, 2) for k, v in comp.items()}
        comp["net"] = round(sum(comp.values()), 2)
        return comp

    def get_treasury_ledger(self, before=None):
        """دفتر الخزينة لكل الفترات بالترتيب.

        لكل فترة: carry (رصيد أولها = نهاية سابقتها بالضبط)، وبنودها، و closing.
        كل حركة تنتمي لفترتها (عمود period) لا لشهر تاريخها، والفترة لا تتأثر
        بالفترة المعروضة حالياً — فالتقرير يعطي الأرقام نفسها من أي فترة فُتح.

        before: يقصر الحساب على الفترات السابقة لها (يكفي لرصيد أول المدة).
        """
        by_period = {}
        for inv in self.invoices.values():
            period = self.inv_period(inv)
            if period:
                by_period.setdefault(period, []).append(inv)
        periods = {p for p, invs in by_period.items()
                   if any(i.get("settled_status") in COUNTED_STATUSES for i in invs)}
        if getattr(self, "current_display_month", None):
            periods.add(self.current_display_month)

        type_sets = self.get_treasury_type_sets()
        ledger, carry = [], 0.0
        for period in sorted(periods):
            if before and period >= before:
                break
            comp = self.treasury_period_components(period, invoices=by_period.get(period, []),
                                                   type_sets=type_sets)
            row = dict(comp)
            row["period"] = period
            row["carry"] = round(carry, 2)
            row["closing"] = round(carry + comp["net"], 2)
            ledger.append(row)
            carry = row["closing"]
        return ledger

    def period_closing_datetime(self, month):
        """آخر لحظة في الفترة: تاريخ مناسب لقيود إقفالها.

        استخدام تاريخ اليوم كان يضع قيد إقفال شهر ٩ في أول شهر ١٠، فيبدو
        كأنه حركة الشهر الجديد.
        """
        try:
            year, mon = (int(x) for x in str(month).split("-")[:2])
            last_day = calendar.monthrange(year, mon)[1]
            return f"{year:04d}-{mon:02d}-{last_day:02d} 23:59:00"
        except (ValueError, IndexError):
            return f"{self.get_smart_default_date()} {datetime.datetime.now().strftime('%H:%M:%S')}"

    def get_opening_treasury_balance(self, month):
        """رصيد أول المدة = رصيد نهاية الفترة السابقة بالضبط.

        يُقرأ من دفتر الخزينة الموحّد (get_treasury_ledger)، الذي يبني شريط
        الخزينة والتقرير الشهري أيضاً — فرصيد افتتاح فترة ٩ = آخر رصيد في
        فترة ٨ دائماً، سواء أُقفل خياس فترة ٨ أم لا.
        """
        if not month:
            return 0.0
        ledger = self.get_treasury_ledger(before=month)
        return round(ledger[-1]["closing"], 2) if ledger else 0.0

    _DATE_DIGITS = str.maketrans("٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹", "01234567890123456789")

    def read_entry_date(self, text, parent=None):
        """تاريخ العملية من خانته بصيغة واحدة YYYY-MM-DD (والأرقام الهندية تُحوَّل)، أو None مع
        تنبيه. كانت أغلب شاشات الترحيل تقبل أي نص فيُحفظ تاريخ مكسور يخلّ بترتيب الحركات."""
        text = str(text or "").translate(self._DATE_DIGITS).strip().replace("/", "-")
        try:
            return datetime.datetime.strptime(text[:10], "%Y-%m-%d").strftime("%Y-%m-%d")
        except ValueError:
            kw = {"parent": parent} if parent is not None else {}
            messagebox.showwarning("التاريخ غير صحيح",
                                   "الرجاء إدخال التاريخ بالصيغة YYYY-MM-DD (مثل 2026-10-01).", **kw)
            return None

    def get_smart_default_date(self):
        """تاريخ العملية الافتراضي: **تاريخ اليوم الحقيقي** دائماً.

        العملية تُعرض وتُسجَّل بتاريخها الحيّ (مثلاً ٢٠٢٦-٠٩-٠١)، بينما تُثبَّت
        محاسبياً في الفترة المعروضة (مثلاً ٢٠٢٦-٠٨) عبر عمود (period) المستقل.
        فلا يُزوَّر التاريخ ليدخل الفترة، ولا تُحسب العملية في فترة غير فترتها.
        """
        # التاريخ هو تاريخ اليوم الحقيقي دائماً، مهما كانت الفترة المعروضة.
        # أما انتماء العملية للفترة فيحدّده عمود (period) لا التاريخ.
        return datetime.datetime.now().strftime("%Y-%m-%d")

    def get_operation_datetime(self):
        """تاريخ ووقت العملية الحقيقيان (الفترة تُحدَّد بعمود period لا بالتاريخ)"""
        return f"{self.get_smart_default_date()} {datetime.datetime.now().strftime('%H:%M:%S')}"

    def stamp_period(self, inv_data, date_value=None):
        """يختم الحركة بالفترة المحاسبية التي تنتمي إليها.

        الأساس: الفترة المعروضة وقت التسجيل. ولو كان تاريخ الحركة يقع داخل
        فترة معروضة أخرى (كتعديل حركة قديمة) تُترك فترتها كما هي.
        """
        if not inv_data.get("period"):
            inv_data["period"] = self.current_display_month
        return inv_data

    def refresh_live_date_fields(self):
        """يحدّث خانات التاريخ المعروضة عند تغيّر تاريخ الجهاز والبرنامج مفتوح.

        بدون هذا كانت الخانات تحتفظ بتاريخ لحظة فتح الشاشة، فيبقى النظام
        على تاريخ الأمس حتى يُعاد تشغيله.
        """
        try:
            expected = self.get_smart_default_date()
            last = getattr(self, "_last_live_date", None)
            if last != expected:
                for attr in ("date_entry", "sale_date", "in_date", "op_date",
                             "cast_date", "polish_date", "pbuff_date"):
                    widget = getattr(self, attr, None)
                    if widget is None:
                        continue
                    try:
                        current = widget.get().strip()
                        # لا نلمس تاريخاً عدّله المستخدم بنفسه
                        if current in ("", last):
                            widget.delete(0, "end")
                            widget.insert(0, expected)
                    except Exception:
                        continue

                for stage in getattr(self, "dynamic_stage_widgets", {}).values():
                    widget = stage.get("date")
                    if widget is None:
                        continue
                    try:
                        current = widget.get().strip()
                        if current in ("", last):
                            widget.delete(0, "end")
                            widget.insert(0, expected)
                    except Exception:
                        continue

                self._last_live_date = expected
        except Exception as e:
            log_cloud_error("تعذّر تحديث التاريخ الحيّ", e)
        finally:
            self.after(30000, self.refresh_live_date_fields)   # كل ٣٠ ثانية

    def update_period_warning(self):
        """مؤشر واضح بجوار مختار الفترة عندما تكون الفترة المعروضة ليست الشهر الحالي.

        الهدف: ألا يُسجّل المستخدم حركات في شهر خطأ وهو لا ينتبه.
        """
        if not hasattr(self, 'lbl_period_warning'):
            return
        curr = datetime.datetime.now().strftime("%Y-%m")
        if self.current_display_month == curr:
            self.lbl_period_warning.configure(text="")
        else:
            self.lbl_period_warning.configure(
                text=f"⚠️ أنت تعمل في فترة سابقة ({self.current_display_month}) — الشهر الحالي {curr}")

    def watch_system_month(self):
        """يراقب تغيّر شهر النظام والبرنامج مفتوح (يعمل ليلاً عند نهاية الشهر).

        بدون هذا يبقى البرنامج مفتوحاً من ٣١ يوليو إلى ١ أغسطس وهو ما زال
        يسجّل في يوليو، لأن الفترة تُحسب مرة واحدة عند التشغيل فقط.
        """
        try:
            curr = datetime.datetime.now().strftime("%Y-%m")
            last = getattr(self, "_last_seen_system_month", None)
            if last is None:
                self._last_seen_system_month = curr
            elif curr != last:
                self._last_seen_system_month = curr
                if messagebox.askyesno(
                        "بداية شهر جديد",
                        f"بدأ شهر جديد ({curr}).\n\n"
                        f"هل تريد الانتقال للفترة الجديدة الآن؟\n"
                        f"(إن اخترت لا، ستبقى في فترة {self.current_display_month} "
                        f"وستُسجَّل حركاتك فيها)"):
                    self.current_display_month = curr
                    self.update_period_selector()
                    self.on_period_changed(curr)
        except Exception:
            pass
        finally:
            self.after(300000, self.watch_system_month)   # كل ٥ دقائق

    def create_sticky_total_tree(self, parent, columns, height=18, col_widths=None):
        """جدول بصف إجمالي ثابت أسفله لا يتحرّك مع التمرير.

        Treeview لا يدعم "تجميد صف" أصلياً، فالحل القياسي هو استخدام شجرتين:
        الأولى قابلة للتمرير لصفوف البيانات، والثانية أسفلها مباشرة (خارج
        منطقة التمرير) لصف الإجمالي فقط، بنفس الأعمدة والعرض بالضبط حتى
        تصطف الأرقام رأسياً مع الجدول العلوي.

        يرجع: (شجرة البيانات القابلة للتمرير، شجرة الإجمالي الثابتة)
        """
        wrapper = ttk.Frame(parent)
        wrapper.pack(fill="both", expand=True)

        # ترتيب الرصف مقصود: صف الإجمالي يُرصف **أولاً** من الأسفل، ثم يأخذ
        # جدول البيانات ما تبقّى. لو عُكس الترتيب لالتهم الجدول المساحة كلها
        # ودُفع صف الإجمالي خارج الشاشة فلا يظهر إطلاقاً.
        # ارتفاع ثابت ومنع الانتشار: يضمن ظهور الشريط دائماً، فقد كان ينكمش
        # إلى صفر عندما يطلب جدول البيانات ارتفاعاً أكبر من المتاح
        self.ensure_totals_bar_style()
        total_holder = ttk.Frame(wrapper, height=getattr(self, "_totals_row_h", 34) + 6)
        total_holder.pack(side="bottom", fill="x")
        total_holder.pack_propagate(False)
        ttk.Separator(wrapper, orient="horizontal").pack(side="bottom", fill="x", pady=(2, 0))

        body_frame = ttk.Frame(wrapper)
        body_frame.pack(side="top", fill="both", expand=True)

        data_tree = ttk.Treeview(body_frame, columns=columns, show="headings", height=height)
        self.enable_row_hover(data_tree)
        for col in columns:
            data_tree.heading(col, text=col)
            data_tree.column(col, width=(col_widths or {}).get(col, 110), anchor="center", stretch=False)

        vsb = self.make_scrollbar(body_frame, "vertical", data_tree.yview)
        data_tree.configure(yscrollcommand=vsb.set)
        vsb.pack(side="right", fill="y")
        data_tree.pack(side="left", fill="both", expand=True)
        self.enable_table_tools(data_tree)

        # هامش بعرض شريط التمرير الرأسي نفسه (ويكبر معه بتكبير ويندوز)، حتى تصطف
        # أعمدة الشجرتين رأسياً رغم غياب الشريط في شجرة الإجمالي
        ctk.CTkFrame(total_holder, width=14, height=1, corner_radius=0,
                     fg_color=(self.DESIGN["light"]["bg"], self.DESIGN["dark"]["bg"])
                     ).pack(side="right", fill="y")

        # show="" يُخفي شريط العناوين الفارغ فوق صف الإجمالي، فيظهر الصف
        # ملاصقاً للجدول تماماً بلا فراغ يفصله عنه
        total_tree = ttk.Treeview(total_holder, columns=columns, show="", height=1,
                                  style="Totals.Treeview")
        for col in columns:
            total_tree.column(col, width=(col_widths or {}).get(col, 110), anchor="center", stretch=False)
        # شريط رصاصي غامق بأرقام بيضاء ليتميّز بوضوح عن صفوف الجدول
        self.ensure_totals_bar_style()
        total_tree.tag_configure("total_tag", foreground="#000000", font=("Cairo", 14, "bold"))
        total_tree.pack(side="left", fill="x", expand=True)

        # ربط الشجرتين ليُعاد ضبط عرض أعمدة الإجمالي كلما تغيّر عرض الجدول
        data_tree._total_tree = total_tree
        data_tree.bind("<Configure>",
                       lambda e, d=data_tree, t=total_tree: self.sync_total_tree_columns(d, t),
                       add="+")
        return data_tree, total_tree

    def ensure_totals_bar_style(self):
        """نمط شريط الإجمالي: خلفية رصاصية غامقة ثابتة في الوضعين الفاتح والداكن"""
        if getattr(self, "_totals_style_ready", False):
            return
        try:
            style = ttk.Style()
            d = getattr(self, "_design", None) or {}
            total_font = d.get("total_font", ("Cairo", 14, "bold"))
            # ارتفاعه من قياس خط الإجمالي نفسه (لا ٣٤ ثابتة تقصّ الخط على التكبير)
            self._totals_row_h = self.table_row_height(total_font, 34)
            # رصاصي فاتح بنص أسود عريض — أوضح للقراءة من الغامق
            style.configure("Totals.Treeview",
                            background="#c4c9ce", fieldbackground="#c4c9ce",
                            foreground="#000000", rowheight=self._totals_row_h, borderwidth=0,
                            font=total_font)
            # الصف يبقى بلونه حتى عند التحديد، فلا يتغيّر شكل الشريط بالنقر
            style.map("Totals.Treeview",
                      background=[("selected", "#c4c9ce")],
                      foreground=[("selected", "#000000")])
            self._totals_style_ready = True
        except Exception:
            pass

    def sync_total_tree_columns(self, data_tree, total_tree):
        """يطابق عرض أعمدة صف الإجمالي مع أعمدة جدول البيانات.

        ضروري لأن عرض أعمدة الجدول يُضبط لاحقاً حسب المحتوى، فلولا هذه
        المطابقة لظهر صف الإجمالي بأرقام مزاحة عن أعمدتها.
        """
        if data_tree is None or total_tree is None:
            return
        try:
            for col in data_tree["columns"]:
                total_tree.column(col, width=data_tree.column(col, "width"), stretch=False)
            total_font = (getattr(self, "_design", None) or {}).get("total_font")
            if total_font:
                total_tree.tag_configure("total_tag", font=total_font)
        except Exception:
            pass

    def view_treeview_fullscreen(self, tree, title, name_tree=None):
        """يقرأ محتوى Treeview ظاهر حالياً في الشاشة (بيانات + إجمالي إن وُجد)
        ويعرضه بملء الشاشة بنفس الآلية العامة، بدل إعادة حساب البيانات من
        الصفر — فما تراه بالضبط هو ما يُعرض بملء الشاشة، بلا احتمال تعارض."""
        if tree is None:
            messagebox.showinfo("تنبيه", "لا يوجد جدول لعرضه حالياً.")
            return

        columns = list(tree["columns"])
        children = tree.get_children()
        if not children:
            messagebox.showinfo("تنبيه", "الجدول فارغ حالياً — لا يوجد ما يُعرض.")
            return

        # صف الإجمالي هو آخر صف موسوم total_tag إن وُجد، وباقي الصفوف بيانات
        rows, tags, totals_values = [], [], None
        for iid in children:
            vals = tree.item(iid, "values")
            item_tags = tree.item(iid, "tags") or ()
            if "total_tag" in item_tags:
                totals_values = tuple(vals)
            else:
                rows.append(tuple(vals))
                tags.append("red_tag" if "red_tag" in item_tags else None)

        # الجداول ذات الإجمالي الثابت تحفظه على الجدول نفسه
        if totals_values is None:
            totals_values = getattr(tree, "_totals_values", None)

        # عمود الاسم (إن وُجد كجدول منفصل) يُدمَج كعمود أول في العرض الكامل
        if name_tree is not None:
            name_children = name_tree.get_children()
            merged_rows = []
            for i, r in enumerate(rows):
                nm = name_tree.item(name_children[i], "values")[0] if i < len(name_children) else ""
                merged_rows.append((nm,) + r)
            rows = merged_rows
            columns = ["الاسم"] + columns
            if totals_values is not None:
                totals_values = ("الإجمالي",) + totals_values[1:]

        self.open_fullscreen_table_view(title, tuple(columns), rows,
                                        totals_values=totals_values, row_tags=tags)

    def open_fullscreen_table_view(self, title, columns, rows, totals_values=None,
                                   col_widths=None, row_tags=None):
        """يفتح نافذة ملء الشاشة لعرض جدول كامل.

        صف الإجمالي يُدرَج **داخل الجدول نفسه** كآخر صف بعد البيانات، بترتيبه
        المحاسبي الطبيعي. استُبدل بذلك الشريط المنفصل أسفل الجدول لأنه كان
        ينكمش ويختفي حسب مساحة النافذة — والصف داخل الجدول لا يمكن أن يختفي
        ولا أن تنزاح أعمدته. وعند الفتح يُمرَّر الجدول إليه تلقائياً ليظهر فوراً.

        rows: قائمة صفوف، كل صف Tuple بنفس عدد الأعمدة
        totals_values: صف الإجمالي (Tuple)، أو None ليُحسب تلقائياً
        row_tags: قائمة موازية لـ rows فيها وسم اللون لكل صف (أو None)
        """
        win = ctk.CTkToplevel(self)
        win.title(title)
        win.transient(self)
        win.grab_set()
        win.focus_force()

        # حجم يناسب الشاشة مع هامش، ثم تكبير على ويندوز إن أمكن
        sw, sh = self.winfo_screenwidth(), self.winfo_screenheight()
        win.geometry(f"{max(900, sw - 80)}x{max(600, sh - 120)}+40+30")
        try:
            win.state("zoomed")
        except Exception:
            pass

        ctk.CTkLabel(win, text=title, font=("Cairo", 20, "bold"),
                     text_color="#d4af37").pack(pady=(14, 2))
        ctk.CTkLabel(win, text=f"عدد الصفوف: {len(rows)}   •   صف الإجمالي في آخر الجدول",
                     font=("Cairo", 12), text_color="#8b8f95").pack(pady=(0, 8))

        body = ctk.CTkFrame(win, fg_color="transparent")
        body.pack(fill="both", expand=True, padx=24, pady=(0, 6))

        table_frame = ttk.Frame(body)
        table_frame.pack(fill="both", expand=True)

        data_tree = ttk.Treeview(table_frame, columns=columns, show="headings")
        self.enable_row_hover(data_tree)
        self.enable_table_tools(data_tree)
        for col in columns:
            data_tree.heading(col, text=self.wrap_header(col))
            data_tree.column(col, width=(col_widths or {}).get(col, 110),
                             anchor="center", stretch=False)

        vsb = self.make_scrollbar(table_frame, "vertical", data_tree.yview)
        hsb = self.make_scrollbar(table_frame, "horizontal", data_tree.xview)
        data_tree.configure(yscrollcommand=vsb.set, xscrollcommand=hsb.set)
        hsb.pack(side="bottom", fill="x")
        vsb.pack(side="right", fill="y")
        data_tree.pack(side="left", fill="both", expand=True)

        # صف الإجمالي بارز: خلفية رصاصية غامقة وخط أبيض عريض، ليتميّز عن البيانات
        data_tree.tag_configure("total_tag", foreground="#000000", background="#c4c9ce",
                                font=("Cairo", 14, "bold"))
        data_tree.tag_configure("red_tag", foreground="#e74c3c", font=("Cairo", 13, "bold"))

        if totals_values is None:
            totals_values = self.compute_totals_row(columns, rows)

        for i, row in enumerate(rows):
            tag = (row_tags[i],) if row_tags and row_tags[i] else ()
            data_tree.insert("", "end", values=row, tags=tag)

        # صف الإجمالي في **آخر** الجدول، بترتيبه المحاسبي الطبيعي بعد البيانات
        if totals_values is not None:
            data_tree.insert("", "end", values=totals_values, tags=("total_tag",))

        def fit_and_reveal():
            self.fit_columns_to_content(data_tree, None, min_width=54, max_width=220)
            # ارتفاع الجدول يُضبط على عدد صفوفه ما دام يسع الشاشة، فيظهر صف
            # الإجمالي مباشرةً بلا تمرير؛ ولو زادت الصفوف عن سعة الشاشة نُمرّر
            # إليه تلقائياً ليكون أول ما تراه عند الفتح
            try:
                children = data_tree.get_children()
                if children:
                    data_tree.see(children[-1])
            except Exception:
                pass

        win.after(120, fit_and_reveal)
        win.after(420, fit_and_reveal)   # إعادة بعد اكتمال التكبير

        ctk.CTkButton(win, text="إغلاق", font=("Cairo", 14, "bold"), width=140, height=40,
                      command=win.destroy).pack(pady=12)

    @staticmethod
    def compute_totals_row(columns, rows):
        """يحسب صف إجمالي من الصفوف المعروضة عندما لا يوفّره الجدول المصدر.

        يجمع كل عمود قابل للتحويل لرقم، ويضع (-) في الأعمدة النصية،
        والكلمة (الإجمالي) في أول عمود.
        """
        if not rows:
            return None

        totals = []
        for idx, _col in enumerate(columns):
            if idx == 0:
                totals.append("الإجمالي")
                continue
            acc, numeric = 0.0, False
            for row in rows:
                try:
                    raw = str(row[idx]).replace(",", "").replace("\u200e", "").strip()
                except (IndexError, TypeError):
                    continue
                if raw in ("", "-"):
                    continue
                try:
                    acc += float(raw)
                    numeric = True
                except ValueError:
                    continue      # عمود نصي: لا يُجمع
            totals.append(f"{round(acc, 2):.2f}" if numeric else "-")
        return tuple(totals)

    def create_two_pane_ledger_tree(self, parent, main_cols, height=11,
                                    name_col_width=110, main_col_widths=None):
        """جدولان متلاصقان: عمود (الاسم) برتقالي بالكامل + الجدول الرئيسي بجانبه،
        يتحرّكان معاً عند التمرير أو عجلة الفأرة.

        السبب التقني: Treeview يُلوَّن على مستوى الصف كاملاً لا الخلية المفردة،
        فلا توجد طريقة لجعل عمود واحد برتقالياً بينما بقية أعمدة نفس الصف
        سوداء/حمراء حسب حالتها — حاولت ذلك بوسوم الصف فتعارضت الألوان.
        الحل: عمود الاسم في جدول منفصل ملاصق، بلا تعارض تلوين إطلاقاً.

        يرجع: (الجدول الرئيسي, جدول الاسم)
        """
        row = ttk.Frame(parent)
        row.pack(fill="both", expand=True)

        name_frame = ttk.Frame(row)
        name_frame.pack(side="right", fill="y")
        name_tree = ttk.Treeview(name_frame, columns=("الاسم",), show="headings", height=height)
        name_tree.heading("الاسم", text="الاسم")
        name_tree.column("الاسم", width=name_col_width, anchor="center", stretch=False)
        name_tree.tag_configure("orange_name", foreground="#e67e22", font=("Cairo", 13, "bold"))
        self.normalize_tree_tags(name_tree)       # ألوان الوسوم من اللوحة الهادئة في المظهرين
        name_tree.pack(fill="y")

        main_frame = ttk.Frame(row)
        main_frame.pack(side="right", fill="both", expand=True)
        main_tree = self.create_standard_treeview(main_frame, main_cols, height=height)
        main_tree._no_sort = True        # الترتيب يفصله عن عمود الاسم الملاصق — النسخ والتصدير متاحان
        if main_col_widths:
            for col, w in main_col_widths.items():
                main_tree.column(col, width=w, anchor="center", stretch=False)

        # تزامن التمرير في الاتجاهين: تحريك أي من الجدولين يحرّك الآخر بنفس القدر
        orig_cmd = main_tree.cget("yscrollcommand")

        def on_main_scroll(first, last):
            if orig_cmd:
                self.tk.call(orig_cmd, first, last)
            name_tree.yview_moveto(first)

        main_tree.configure(yscrollcommand=on_main_scroll)
        name_tree.bind("<MouseWheel>",
                       lambda e: (main_tree.yview_scroll(int(-1 * (e.delta / 120)), "units"), "break"))
        name_tree.bind("<Button-4>", lambda e: (main_tree.yview_scroll(-1, "units"), "break"))
        name_tree.bind("<Button-5>", lambda e: (main_tree.yview_scroll(1, "units"), "break"))

        return main_tree, name_tree

    # أسماء الأعمدة المعدّلة من المستخدم — تُحفظ لكل جدول على حدة
    COLUMN_LABEL_KEY = "col_labels"

    def get_column_label(self, table_key, column_id):
        """الاسم المعروض للعمود: المعدَّل من المستخدم إن وُجد، وإلا الاسم الأصلي"""
        try:
            import json as _json
            saved = _json.loads(self.get_setting(f"{self.COLUMN_LABEL_KEY}_{table_key}", "") or "{}")
            return saved.get(column_id, column_id)
        except Exception:
            return column_id

    def set_column_label(self, table_key, column_id, new_label):
        try:
            import json as _json
            key = f"{self.COLUMN_LABEL_KEY}_{table_key}"
            saved = _json.loads(self.get_setting(key, "") or "{}")
            if new_label and new_label != column_id:
                saved[column_id] = new_label
            else:
                saved.pop(column_id, None)   # إرجاع الاسم الأصلي
            self.set_setting(key, _json.dumps(saved, ensure_ascii=False))
        except Exception as e:
            log_cloud_error("تعذّر حفظ اسم العمود", e)

    @staticmethod
    def wrap_header(text, max_len=9):
        """عنوان العمود كما هو — بلا توزيع على سطرين.

        السبب: رؤوس أعمدة ttk.Treeview تعرض **السطر الأول فقط** من النص،
        فتوزيع العنوان على سطرين كان يقصّه فيظهر «خياس» بدل «خياس المركب».
        العرض يتكفّل به fit_columns_to_content الذي يقيس العنوان كاملاً.
        """
        return str(text or "")

    @staticmethod
    def _wrap_header_unused(text, max_len=9):
        text = str(text or "")
        if len(text) <= max_len:
            return text
        words = text.split()
        if len(words) == 1:
            return text
        # نقسم الكلمات على سطرين متوازنين قدر الإمكان
        best, best_diff = 1, None
        for i in range(1, len(words)):
            a = len(" ".join(words[:i]))
            b = len(" ".join(words[i:]))
            diff = abs(a - b)
            if best_diff is None or diff < best_diff:
                best, best_diff = i, diff
        return " ".join(words[:best]) + "\n" + " ".join(words[best:])

    def enable_column_rename(self, tree, table_key, on_renamed=None):
        """يسمح بتعديل اسم أي عمود بالضغط على رأسه، ويحفظ الاسم الجديد"""
        def on_header_click(event):
            if tree.identify_region(event.x, event.y) != "heading":
                return
            try:
                cols = list(tree["columns"])
                idx = int(tree.identify_column(event.x).replace("#", "")) - 1
                if not (0 <= idx < len(cols)):
                    return
                col_id = cols[idx]
            except (ValueError, IndexError):
                return
            if str(col_id).startswith("_"):
                return          # أعمدة داخلية بلا عنوان (مثل عمود أزرار التعديل والحذف)

            current = self.get_column_label(table_key, col_id)
            dialog = ctk.CTkInputDialog(
                title="تعديل اسم العمود",
                text=f"الاسم الجديد للعمود «{current}»\n(اتركه فارغاً لإرجاع الاسم الأصلي: {col_id})")
            new_name = dialog.get_input()
            if new_name is None:
                return

            self.set_column_label(table_key, col_id, new_name.strip())
            label = self.get_column_label(table_key, col_id)
            try:
                tree.heading(col_id, text=self.wrap_header(label))
            except Exception:
                pass
            if on_renamed:
                try:
                    on_renamed()
                except Exception:
                    pass

        # علم على الأداة نفسها لا على النافذة: كل جدول جديد يُربط مرة واحدة،
        # فلا تتراكم الروابط على الجدول نفسه ولا يُحرم الجدول الجديد من الربط
        if not getattr(tree, "_rename_bound", False):
            tree.bind("<Button-1>", on_header_click, add="+")
            tree._rename_bound = True

    def apply_column_labels(self, tree, table_key):
        """يطبّق الأسماء المعدّلة والعناوين ذات السطرين على كل أعمدة الجدول"""
        try:
            for col_id in list(tree["columns"]):
                tree.heading(col_id, text=self.wrap_header(self.get_column_label(table_key, col_id)))
        except Exception:
            pass

    def expected_table_width(self):
        """العرض المتوقّع للجدول قبل ظهوره على الشاشة.

        يُقدَّر من عرض النافذة بعد خصم الشريط الجانبي والهوامش، فتُضبط
        الأعمدة صحيحةً من أول مرة بلا انتظار الظهور.
        """
        try:
            w = self.winfo_width()
            if w <= 1:
                w = self.winfo_screenwidth()
        except Exception:
            w = 1366
        try:
            w -= self.sidebar_width()
        except Exception:
            w -= 300
        return max(600, w - 60)

    def fit_dialog_to_screen(self, win, width, height):
        """نافذة حوار بحجمها المطلوب ما دام يسع الشاشة، وإلا بحجم الشاشة ناقص هامش،
        في منتصفها. width/height بوحدات الواجهة (قبل تكبير ويندوز)، والشاشة بالبكسل."""
        try:
            s = float(ctk.ScalingTracker.get_window_scaling(win))
        except Exception:
            s = 1.0
        try:
            sw, sh = self.winfo_screenwidth(), self.winfo_screenheight()
        except Exception:
            sw, sh = 1366, 768
        w = min(int(width * s), sw - 40)
        h = min(int(height * s), sh - 90)
        x, y = max(0, (sw - w) // 2), max(0, (sh - h) // 3)
        try:
            win.geometry(f"{max(300, int(w / s))}x{max(240, int(h / s))}+{x}+{y}")
        except Exception:
            pass

    # عناوين مختصرة تُستعمل تلقائياً حين يضيق الجدول عن العناوين الكاملة (شاشات
    # اللابتوب الصغيرة)، وتعود الكاملة متى اتسعت الشاشة. الاسم الذي عدّله المستخدم
    # بنفسه لا يُختصر.
    COMPACT_HEADERS = {
        "رقم الفاتورة": "الفاتورة", "رقم التشغيل": "التشغيل", "رقم الصف": "الصف",
        "الأحجار بعد الخصم": "بعد الخصم", "خياس التلميع النهائي": "التلميع",
        "خياس التلميع": "التلميع", "خياس البوليش": "البوليش", "خياس المركب": "المركب",
        "الوزن القائم": "القائم", "الوزن المقيد": "المقيد", "عدد الأسطر": "الأسطر",
        "مسترجع الأشجار": "مسترجع", "عدد الأشجار": "الأشجار", "خياس كل شجرة": "لكل شجرة",
        "آخر تعديل": "التعديل",
    }
    # أعمدة نصية يجوز أن يُقصّ طرف محتواها حين تضيق الشاشة جداً — الأرقام لا تُقصّ
    SHRINKABLE_COLUMNS = ("البيان", "الاسم", "العملية", "النوع", "ملاحظات", "المصدر")

    @staticmethod
    def plan_column_widths(desired, floors, avail):
        """يوزّع عرض الجدول على أعمدته فيملؤه **تماماً** — لا فراغ على جانب ولا تجاوز:
          • المتاح أوسع من المطلوب ← الفائض يُوزَّع بنسبة عرض كل عمود.
          • أضيق ← ينكمش كل عمود من عرضه المطلوب نحو حدّه الأدنى بنسبة فائضه.
          • أضيق من الحدود الدنيا نفسها (شاشة ضيقة جداً) ← تُصغَّر كلها بنسبة واحدة.
        """
        desired = [max(1, int(d)) for d in desired]
        floors = [max(1, min(int(f), d)) for f, d in zip(floors, desired)]
        total = sum(desired)
        if avail <= 0 or total <= 0:
            return desired
        if total <= avail:
            widths = [d + int((avail - total) * d / total) for d in desired]
        else:
            floor_total = sum(floors)
            if floor_total <= avail:
                keep = (avail - floor_total) / float(total - floor_total or 1)
                widths = [f + int((d - f) * keep) for d, f in zip(desired, floors)]
            else:
                widths = [max(20, int(f * avail / floor_total)) for f in floors]
        # بقايا القسمة الصحيحة تُضاف لأعرض عمود فيساوي المجموع المتاح بالضبط
        diff = avail - sum(widths)
        if widths and diff:
            i = widths.index(max(widths))
            widths[i] = max(20, widths[i] + diff)
        return widths

    def fit_columns_to_content(self, tree, table_key=None, min_width=46, max_width=200, padding=16):
        """يضبط أعمدة الجدول على محتواها ثم يوزّع عرضه عليها فيملؤه تماماً.

        كل عمود يُقاس بعرض محتواه وعنوانه الفعليين (بخط الجدول الحقيقي على هذه
        الشاشة)، ثم plan_column_widths:
          • شاشة واسعة ← الفائض يُوزَّع بالتناسب، فلا فراغ على اليسار.
          • شاشة ضيقة (لابتوب) ← عناوين مختصرة أولاً، ثم تنكمش الأعمدة نحو
            حدّها الأدنى (نصوص البيان والاسم قبل الأرقام) — فلا يخرج عمود عن الجدول.
        الأعمدة قابلة للتمدّد (stretch): أي تغيّر صغير في الحجم يوزّعه الجدول نفسه
        فوراً، والتغيّر الكبير يُعاد له القياس بعد استقرار النافذة.
        """
        if tree is None:
            return
        try:
            import tkinter.font as tkfont
            cols = list(tree["columns"])
            if not cols:
                return

            # خط الجدول الحقيقي (يكبر ويصغر مع الشاشة — design_metrics)، لا حجم ثابت:
            # القياس بخط أصغر من المعروض كان يقصّ الأرقام على الشاشات الكبيرة
            design = getattr(self, "_design", None) or {}
            body_size = int(design.get("font", 11) or 11)
            head_size = int(design.get("head", body_size) or body_size)
            body_font = tkfont.Font(root=tree, font=design.get("body_font", ("Cairo", body_size)))
            head_font = tkfont.Font(root=tree, font=design.get("head_font", ("Cairo", head_size, "bold")))
            # خطوط الوسوم من نظام التصميم قبل القياس، فيُقاس الجدول بما سيُعرض فعلاً
            self.normalize_tree_tags(tree)

            # قياس **عيّنة** من الصفوف لا كلها:
            # القياس السابق كان يستدعي measure() لكل خلية — مع ٥٠٠ صف و١٦
            # عموداً = ٨٠٠٠ استدعاء في كل تحديث، وهو السبب الأكبر لبطء فتح
            # الشاشات. العيّنة تعطي نفس العرض عملياً لأن الأرقام متقاربة الطول.
            all_children = tree.get_children()
            if len(all_children) > FIT_SAMPLE_ROWS:
                step = max(1, len(all_children) // FIT_SAMPLE_ROWS)
                children = all_children[::step][:FIT_SAMPLE_ROWS]
                # آخر الصفوف مهم: صف الإجمالي عادةً أطول الأرقام
                children = list(children) + list(all_children[-3:])
            else:
                children = all_children
            # قيم الصف تُقرأ مرة واحدة (لا مرة لكل عمود)، وصف الإجمالي بخطه
            # الأعرض (الوسم total_tag) يُقاس به هو
            rows, total_rows = [], []
            for iid in children:
                try:
                    vals = tree.item(iid, "values") or ()
                    (total_rows if "total_tag" in (tree.item(iid, "tags") or ()) else rows).append(vals)
                except Exception:
                    pass
            total_font = None
            if total_rows:
                try:
                    spec = tree.tag_configure("total_tag", "font")
                    total_font = tkfont.Font(font=spec) if spec else None
                except Exception:
                    total_font = None
            # قياس النص بطيء (نصف ملّي ثانية للنص العربي): تُقاس **أطول** نصوص
            # العمود وحدها، ويُحفظ كل قياس — فالأرقام والأسماء نفسها تتكرّر
            # في كل تحديث. كان فتح مراحل التصنيع يقضي نصف ثانية في القياس وحده
            cache = getattr(self, "_measure_cache", None)
            if cache is None or len(cache) > 20000:
                cache = self._measure_cache = {}

            def measure(font, text):
                key = (str(font), text)
                w = cache.get(key)
                if w is None:
                    w = cache[key] = font.measure(text)
                return w

            def widest(values, font):
                texts = {str(v) for v in values}
                texts.discard("")
                return max([measure(font, t) for t in sorted(texts, key=len, reverse=True)[:6]] or [0])

            specs = []
            for i, col_id in enumerate(cols):
                label = self.get_column_label(table_key, col_id) if table_key else col_id
                # العنوان يُقاس كاملاً: هو سطر واحد في رأس العمود (+ هامش الرأس الداخلي)
                header_w = head_font.measure(str(label)) + 10 + 6
                short = self.COMPACT_HEADERS.get(col_id) if str(label) == str(col_id) else None
                short_w = (head_font.measure(short) + 10 + 6) if short else header_w
                content_w = widest([v[i] for v in rows if i < len(v)], body_font)
                if total_font is not None:
                    content_w = max(content_w, widest([v[i] for v in total_rows if i < len(v)], total_font))
                # العنوان لا يُقصّ أبداً: الحد الأقصى يقيّد المحتوى لا الرأس،
                # وإلا ظهرت كلمة واحدة من اسم العمود
                width = max(min_width, header_w, min(max_width, content_w + padding))
                specs.append({"id": col_id, "label": label, "short": short, "header_w": header_w,
                              "short_w": short_w, "content_w": content_w, "width": width,
                              # أعمدة داخلية (عمود أزرار التعديل والحذف) بعرضها المضبوط سلفاً
                              "fixed": str(col_id).startswith("_")})
            for s in specs:
                if s["fixed"]:
                    try:
                        s["width"] = int(tree.column(s["id"], "width")) or s["width"]
                    except Exception:
                        pass

            # العرض المتاح: من الجدول إن كان ظاهراً، وإلا **يُقدَّر** من عرض
            # النافذة. هذا هو جوهر إصلاح «اهتزاز» الشاشة عند الفتح:
            # كان الجدول يُبنى وهو مخفي (عرضه ١)، فيُؤجَّل الضبط إلى ما بعد
            # الظهور — فيرى المستخدم الأعمدة تقفز أمامه. التقدير المسبق يجعل
            # الأعمدة صحيحة **قبل** أول رسم، فتظهر الشاشة جاهزة دفعةً واحدة.
            avail = tree.winfo_width()
            if avail <= 1:
                avail = self.expected_table_width()
            avail -= 4                         # هامش يمنع شريطاً أفقياً زائداً

            # ضاق الجدول عن العناوين الكاملة ← يُختصر من العناوين **ما يلزم فقط**، الأكثر
            # توفيراً أولاً، حتى يتسع الجدول (والبقية تبقى كاملة)
            def want_of(s, short):
                head_w = s["short_w"] if short else s["header_w"]
                return max(min_width, head_w, min(max_width, s["content_w"] + padding))
            total_w = sum(s["width"] for s in specs)
            for s in sorted((s for s in specs if s["short"] and not s["fixed"]),
                            key=lambda s: want_of(s, False) - want_of(s, True), reverse=True):
                if total_w <= avail:
                    break
                s["use_short"] = True
                total_w -= want_of(s, False) - want_of(s, True)
            desired, floors = [], []
            for s in specs:
                head_w = s["short_w"] if s.get("use_short") else s["header_w"]
                if s["fixed"]:
                    want = floor = s["width"]
                else:
                    want = max(min_width, head_w, min(max_width, s["content_w"] + padding))
                    # الحد الأدنى: العنوان والرقم كاملين؛ ونصوص البيان/الاسم تنكمش أكثر
                    if s["id"] in self.SHRINKABLE_COLUMNS or s["label"] in self.SHRINKABLE_COLUMNS:
                        floor = max(head_w, min(s["content_w"] + 8, 90))
                    else:
                        floor = max(head_w, s["content_w"] + 8, 30)
                desired.append(want)
                floors.append(floor)
            widths = self.plan_column_widths(desired, floors, avail)

            for s, width in zip(specs, widths):
                tree.column(s["id"], width=width, minwidth=width if s["fixed"] else 20,
                            stretch=not s["fixed"])
                if s["fixed"] or not s["short"]:
                    continue
                # العنوان المختصر/الكامل حسب المساحة — ولا نمسّ عنواناً وضعه غيرنا
                full_txt, short_txt = self.wrap_header(s["label"]), self.wrap_header(s["short"])
                want_txt = short_txt if s.get("use_short") else full_txt
                try:
                    cur = str(tree.heading(s["id"], "text"))
                    if cur in (full_txt, short_txt) and cur != want_txt:
                        tree.heading(s["id"], text=want_txt)
                except Exception:
                    pass

            # صف الإجمالي الثابت (إن وُجد) يتبع نفس الأعرض فتصطف الأرقام معه
            self.sync_total_tree_columns(tree, getattr(tree, "_total_tree", None))

            # الصفوف المتناوبة: تُطبَّق هنا لأن الجدول يكون قد امتلأ فعلاً
            self.style_tree_rows(tree)

            # يُعاد الضبط عند تغيير حجم النافذة، لكن **بتأجيل**: حدث Configure
            # يتكرّر عشرات المرات أثناء السحب، وإعادة الضبط مع كل حدث كانت
            # تُجمّد الواجهة. التأجيل ينفّذها مرة واحدة بعد استقرار الحجم.
            if not getattr(tree, "_fit_bound", False):
                def on_resize(_e, t=tree, k=table_key):
                    # تجاهل التغيّر الطفيف: أول ظهور للجدول يُطلق Configure
                    # بعرضه الحقيقي، وإعادة الضبط حينها هي ما يُرى كاهتزاز.
                    new_w = t.winfo_width()
                    last = getattr(t, "_last_fit_w", 0)
                    if abs(new_w - last) < 40:
                        return
                    t._last_fit_w = new_w

                    job = getattr(t, "_fit_job", None)
                    if job:
                        try:
                            t.after_cancel(job)
                        except Exception:
                            pass
                    t._fit_job = t.after(200, lambda: self.fit_columns_to_content(
                        t, k, min_width, max_width, padding))

                tree.bind("<Configure>", on_resize, add="+")
                tree._fit_bound = True
            # العرض الذي قيس عليه: فرقٌ صغير عنه عند الظهور يوزّعه التمدّد بلا إعادة قياس
            tree._last_fit_w = avail + 4
        except Exception:
            pass   # التنسيق تحسين بصري: فشله يجب ألا يمنع عرض الجدول

    def autofit_tree_columns(self, tree, min_width=70, priority_wide=None):
        """يوزّع عرض الأعمدة على كامل عرض الجدول تلقائياً.

        المشكلة التي يحلّها: الأعمدة كانت بعرض ثابت، فتتكدّس في نصف الجدول
        ويبقى النصف الآخر فارغاً على الشاشات العريضة. الآن تُوزَّع المساحة
        كاملة بلا تدخّل، مع إعطاء أعمدة النصوص (كالبيان والاسم) وزناً أكبر
        لأنها تحتاج مساحة أكثر من الأعمدة الرقمية.
        """
        if tree is None:
            return
        try:
            cols = list(tree["columns"])
            if not cols:
                return

            wide = set(priority_wide or ("البيان", "الاسم", "التاريخ", "رقم التشغيل"))
            weights = {c: (1.7 if c in wide else 1.0) for c in cols}
            total_weight = sum(weights.values())

            avail = tree.winfo_width()
            if avail <= 1:
                # الجدول لم يُرسم بعد: نعيد المحاولة بعد اكتمال التخطيط
                tree.after(120, lambda: self.autofit_tree_columns(tree, min_width, priority_wide))
                return

            avail -= 4   # هامش بسيط يمنع ظهور شريط تمرير أفقي بلا داعٍ
            for c in cols:
                w = int(avail * (weights[c] / total_weight))
                tree.column(c, width=max(min_width, w), minwidth=min_width, stretch=True)
        except Exception:
            pass   # التنسيق تحسين بصري: فشله يجب ألا يمنع عرض الجدول

    # ══════════════════════════════════════════════════════════════════
    #  نظام التصميم المركزي
    #
    #  كل الجداول في النظام تُنشأ من create_standard_treeview، وكل الخطوط
    #  تُقاس من هنا — فتغيير هذه القيم يغيّر مظهر الشاشات الأربع عشرة معاً
    #  بلا لمس أي منطق محاسبي.
    # ══════════════════════════════════════════════════════════════════
    # ألوان الجداول — من لوحة «منتصف الليل والذهب» نفسها: رأس كحلي هادئ،
    # صفوف متناوبة خفيفة، والسطر المحدد بلون ذهبي ناعم يُقرأ بوضوح، وتظليل
    # أزرق خفيف للصف تحت المؤشر (hover)
    DESIGN = {
        "light": {
            "bg":          "#ffffff",
            "row_alt":     "#f4f7fb",
            "text":        "#1f2937",
            "head_bg":     "#1e3a5f",
            "head_hover":  "#27496f",
            "head_text":   "#ffffff",
            # التحديد بدرجة من اللون الرئيسي نفسه (كان أصفر ذهبياً): لون واحد في كل النظام
            "sel_bg":      "#d3dfef",
            "sel_text":    "#10213a",
            "grid":        "#d5dce6",
            "hover":       "#edf2f8",
        },
        "dark": {
            "bg":          "#151a21",
            "row_alt":     "#1b222b",
            "text":        "#e6edf3",
            "head_bg":     "#22364f",
            "head_hover":  "#2b4363",
            "head_text":   "#ffffff",
            "sel_bg":      "#2b4a75",
            "sel_text":    "#ffffff",
            "grid":        "#323b47",
            "hover":       "#223044",
        },
    }

    def design_metrics(self):
        """مقاييس تتناسب مع مساحة الشاشة **الفعلية** (بعد تكبير ويندوز).

        الشاشة تُقاس بعرضها المنطقي: ١٩٢٠ بكسل بتكبير ١٢٥٪ مساحتها ١٥٣٦ — فيُختار
        لها خط ١٢ لا ١٤ (كان يُختار بالبكسل الحقيقي فيكبر الخط مرتين: مرة بالحجم
        ومرة بتكبير ويندوز، فتضيق الجداول). الخطوط بالنقاط تكبر مع التكبير تلقائياً.
        """
        try:
            sw, sh = self.winfo_screenwidth(), self.winfo_screenheight()
        except Exception:
            sw, sh = 1366, 768
        try:
            scale = float(ctk.ScalingTracker.get_window_scaling(self)) or 1.0
        except Exception:
            scale = 1.0
        sw, sh = sw / scale, sh / scale

        if sw >= 2400:
            base, row_h, head = 15, 40, 15
        elif sw >= 1900:
            base, row_h, head = 14, 36, 14
        elif sw >= 1600:
            base, row_h, head = 13, 33, 13
        elif sw >= 1400:
            base, row_h, head = 12, 31, 12
        else:
            base, row_h, head = 11, 28, 11

        # الشاشات القصيرة تحتاج صفوفاً أقصر وإلا ظهر عدد قليل منها (والحد الأدنى
        # الحقيقي يأتي من قياس الخط — table_row_height — فلا يُقصّ حرف)
        if sh <= 800:
            row_h = max(24, row_h - 4)

        return {"font": base, "row_h": row_h, "head": head,
                "pad_x": max(6, base - 4), "pad_y": max(3, base // 3)}

    @staticmethod
    def row_height_for(ascent, descent, minimum=0, padding=2):
        """أقل ارتفاع صف يسع حروف الخط كاملة (نقاط الياء وذيول الحروف).

        الجدول يضع سطر النص (الصعود + النزول) في منتصف الصف ويقصّ ما يخرج عنه.
        في Cairo الصعود كبير (١٫٣١ من حجم الخط) والنزول ٠٫٥٧، وأعمق ذيل حرف
        ٠٫٤٦ ≈ ٨١٪ من النزول. فأدنى ارتفاع = الصعود − النزول + ٢ × ٠٫٨١ × النزول.
        كان الصف ٢٤ بكسل ثابتاً فتُقصّ نقاط «ي» على تكبير ١٢٥٪ («النهائي» ← «النهائى»).
        """
        need = ascent - descent + 2 * 0.81 * descent
        return max(int(minimum), int(need + 0.999) + padding)

    def table_row_height(self, font_spec, minimum=0):
        """ارتفاع صف الجدول من قياس الخط الحقيقي على هذه الشاشة (بتكبيرها)"""
        try:
            import tkinter.font as tkfont
            f = tkfont.Font(root=self, font=font_spec)
            return self.row_height_for(f.metrics("ascent"), f.metrics("descent"), minimum)
        except Exception:
            return int(minimum) or 28

    def apply_design_system(self):
        """يطبّق التنسيق الموحّد على كل جداول النظام دفعةً واحدة"""
        try:
            m = self.design_metrics()
            mode = "dark" if ctk.get_appearance_mode() == "Dark" else "light"
            c = self.DESIGN[mode]
            body = (table_font_family(), m["font"])
            head = ("Cairo", m["head"], "bold")
            total = ("Cairo", m["font"] + 1, "bold")
            row_h = self.table_row_height(body, m["row_h"])
            self._design = dict(c, **m, mode=mode, body_font=body, head_font=head, total_font=total,
                                row_height=row_h)

            style = ttk.Style()
            try:
                style.theme_use("clam")   # أكثر سمة تقبل التخصيص الكامل
            except Exception:
                pass

            # حدود الجدول رفيعة بلون الشبكة، بلا حواف ثلاثية الأبعاد قديمة
            style.configure(
                "Treeview",
                background=c["bg"], fieldbackground=c["bg"], foreground=c["text"],
                rowheight=row_h, borderwidth=1, relief="flat", font=body,
                bordercolor=c["grid"], lightcolor=c["bg"], darkcolor=c["bg"])

            style.configure(
                "Treeview.Heading",
                background=c["head_bg"], foreground=c["head_text"],
                # هامش رأسي معتدل: سطر Cairo طويل أصلاً (١٫٨٨ من حجم الخط)
                relief="flat", borderwidth=0, padding=(6, max(2, m["pad_y"])), font=head,
                bordercolor=c["head_bg"], lightcolor=c["head_bg"], darkcolor=c["head_bg"])

            style.map("Treeview.Heading",
                      background=[("active", c["head_hover"])],
                      foreground=[("active", c["head_text"])])

            style.map("Treeview",
                      background=[("selected", c["sel_bg"])],
                      foreground=[("selected", c["sel_text"])])

            # جدول شجرة الحسابات: خط أكبر قليلاً (هرمي يُقرأ كقائمة)
            style.configure("Accounts.Treeview", font=(table_font_family(), m["font"] + 2),
                            rowheight=self.table_row_height((table_font_family(), m["font"] + 2), 30))

            # حاويات الجداول بلون الجدول نفسه (يظهر خلف شريط التمرير الحديث)
            style.configure("TFrame", background=c["bg"])

            # أشرطة التمرير القديمة المتبقية بنفس لغة الألوان
            style.configure("Vertical.TScrollbar", background=c["grid"],
                            troughcolor=c["bg"], borderwidth=0, arrowsize=14)
            style.configure("Horizontal.TScrollbar", background=c["grid"],
                            troughcolor=c["bg"], borderwidth=0, arrowsize=14)

            # شريط الإجمالي يتبع النظام أيضاً
            self._totals_style_ready = False
            self.ensure_totals_bar_style()

            # الجداول القائمة: ألوان الوسوم (التظليل، الإجمالي…) تتبع المظهر الجديد فوراً
            for tree in list(getattr(self, "_styled_trees", ())):
                try:
                    if tree.winfo_exists():
                        self.style_tree_rows(tree)
                except Exception:
                    pass
        except Exception as e:
            log_cloud_error("تعذّر تطبيق نظام التصميم", e)

    def make_scrollbar(self, parent, orientation, command):
        """شريط تمرير حديث (رفيع مستدير يتضح عند المرور) لكل جداول النظام"""
        c_light, c_dark = self.DESIGN["light"], self.DESIGN["dark"]
        kw = {"width": 14} if orientation == "vertical" else {"height": 14}
        return ctk.CTkScrollbar(parent, orientation=orientation, command=command,
                                bg_color=(c_light["bg"], c_dark["bg"]),
                                fg_color=(c_light["bg"], c_dark["bg"]), **kw)

    # وسوم ألوان قديمة داخل الجداول ← لون مقروء في كل مظهر (كما في ThemedLabel):
    # الذهبي والبرتقالي الفاتحان كانا بتباين ٢:١ على الأبيض، والأسود يختفي على الداكن
    _LEGACY_TREE_COLORS = {"#000000": ("#1f2937", "#e6edf3"), "black": ("#1f2937", "#e6edf3")}

    def normalize_tree_tags(self, tree):
        """خطوط الوسوم وألوانها من نظام التصميم لا بأحجام ثابتة متفرّقة.

        كانت الجداول تضع لوسومها خطوطاً ثابتة (Cairo 13 أو 14 عريض) فيختلف حجم
        النص من جدول لآخر ولا يتبع حجم الشاشة، وصفوف العمال كلها عريضة. الآن:
        العريض يبقى عريضاً بحجم خط الجدول (والإجمالي أكبر بدرجة)، والعادي عادي،
        والألوان القديمة الباهتة أو السوداء تُترجَم للون مقروء في المظهر الحالي.
        """
        d = getattr(self, "_design", None)
        if not d:
            return
        try:
            names = tree.tk.splitlist(tree.tk.call(tree._w, "tag", "names"))
        except Exception:
            names = ()
        orig = getattr(tree, "_tag_orig", None)
        if orig is None:
            orig = tree._tag_orig = {}
        dark = d.get("mode") == "dark"
        for tag in names:
            if tag in ("odd_row", "even_row", "hover_row"):
                continue
            try:
                if tag not in orig:
                    orig[tag] = (str(tree.tag_configure(tag, "font") or ""),
                                 str(tree.tag_configure(tag, "foreground") or ""),
                                 str(tree.tag_configure(tag, "background") or ""))
                font_spec, fg, bg = orig[tag]
                if font_spec:
                    bold = "bold" in font_spec.lower()
                    if tag == "total_tag":
                        tree.tag_configure(tag, font=d["total_font"])
                    else:
                        # العريض بوجه Cairo Bold الحقيقي (لا تعريض مصطنع لـ SemiBold)
                        tree.tag_configure(tag, font=("Cairo", d["font"], "bold") if bold
                                           else d["body_font"])
                # وسم بخلفية خاصة (شريط الإجمالي الرمادي) يبقى بلونَيه كما صُمّما معاً
                pair = None if bg else (_LEGACY_TEXT_COLORS.get(fg.lower())
                                        or self._LEGACY_TREE_COLORS.get(fg.lower()))
                if pair:
                    tree.tag_configure(tag, foreground=pair[1] if dark else pair[0])
            except Exception:
                continue

    def enable_row_hover(self, tree):
        """تظليل خفيف للصف تحت المؤشر: يسهّل تتبّع السطر عبر الجداول العريضة.

        يُستدعى فور إنشاء الجدول قبل أي وسم آخر: في ttk الوسم الأسبق إنشاءً أعلى
        أولوية، فيغلب التظليلُ لونَ الصفوف المتناوبة ولا يغيّر لون النص.
        """
        if getattr(tree, "_hover_bound", False):
            return
        c = getattr(self, "_design", None) or self.DESIGN["light"]
        try:
            tree.tag_configure("hover_row", background=c["hover"])
        except Exception:
            return
        state = {"iid": None}

        def clear(_e=None):
            iid, state["iid"] = state["iid"], None
            try:
                if iid and tree.exists(iid):
                    tree.item(iid, tags=tuple(t for t in (tree.item(iid, "tags") or ()) if t != "hover_row"))
            except Exception:
                pass

        def on_motion(e):
            try:
                iid = tree.identify_row(e.y)
            except Exception:
                return
            if iid == state["iid"]:
                return
            clear()
            if iid:
                try:
                    tags = tuple(tree.item(iid, "tags") or ())
                    tree.item(iid, tags=tags + ("hover_row",))
                    state["iid"] = iid
                except Exception:
                    pass

        tree.bind("<Motion>", on_motion, add="+")
        tree.bind("<Leave>", clear, add="+")
        tree._hover_bound = True
        registry = getattr(self, "_styled_trees", None)
        if registry is None:
            import weakref
            registry = self._styled_trees = weakref.WeakSet()
        try:
            registry.add(tree)
        except Exception:
            pass

    def style_tree_rows(self, tree):
        """صفوف متناوبة اللون: تسهّل تتبّع السطر الواحد عبر جدول عريض"""
        try:
            c = getattr(self, "_design", self.DESIGN["light"])
            if getattr(tree, "_hover_bound", False):
                tree.tag_configure("hover_row", background=c["hover"])
            self.normalize_tree_tags(tree)
            tree.tag_configure("odd_row", background=c["bg"])
            tree.tag_configure("even_row", background=c["row_alt"])
            for i, iid in enumerate(tree.get_children()):
                tags = list(tree.item(iid, "tags") or ())
                # لا نلمس الصفوف ذات الوسوم الخاصة (الإجمالي، السالب…)
                if any(t in tags for t in ("total_tag", "red_tag", "orange_name")):
                    continue
                tags = [t for t in tags if t not in ("odd_row", "even_row")]
                tags.append("even_row" if i % 2 else "odd_row")
                tree.item(iid, tags=tuple(tags))
        except Exception:
            pass

    def reuse_or_create_tree(self, parent, columns, height=15, sticky_total=False):
        """يُعيد استخدام جدول الإطار إن كانت أعمدته نفسها، وإلا يبنيه من جديد.

        السبب: كانت كل عملية تحديث تُدمّر أدوات الجدول كلها وتُعيد بناءها —
        إنشاء Treeview وشريط تمرير وعشرات الإعدادات في كل مرة. هذا ما يظهر
        للمستخدم كأن الشاشة «تتكوّن» أمامه. إعادة الاستخدام تُبقي الأدوات
        وتكتفي بمسح الصفوف وإعادة ملئها — وهو أسرع بمراتب.

        يرجع: (الجدول، شجرة الإجمالي أو None، هل أُعيد استخدامه؟)
        """
        cached = getattr(parent, "_cached_tree", None)
        cached_cols = getattr(parent, "_cached_cols", None)

        if cached is not None and cached_cols == tuple(columns):
            try:
                if cached.winfo_exists():
                    cached.delete(*cached.get_children())
                    total = getattr(parent, "_cached_total_tree", None)
                    if total is not None and total.winfo_exists():
                        total.delete(*total.get_children())
                    else:
                        total = None
                    return cached, total, True
            except Exception:
                pass   # الجدول تالف لأي سبب: نبنيه من جديد

        for widget in parent.winfo_children():
            widget.destroy()

        if sticky_total:
            tree, total = self.create_sticky_total_tree(parent, columns, height=height)
        else:
            tree, total = self.create_standard_treeview(parent, columns, height=height), None

        parent._cached_tree = tree
        parent._cached_cols = tuple(columns)
        parent._cached_total_tree = total
        return tree, total, False

    # ═══ أدوات كل جدول: الترتيب بالنقر على العنوان، وبزر الفأرة الأيمن: نسخ، تصدير Excel، بحث ═══
    _NUM_CLEAN = re.compile(r"[,\u200e\u200f\s]|جم|ر\.س|‰|%")
    SORT_ARROWS = (" ▲", " ▼")

    @classmethod
    def cell_number(cls, value):
        """قيمة خلية رقماً إن كانت رقمية (تُزال الفواصل والوحدات وعلامات الاتجاه)، وإلا None"""
        text = cls._NUM_CLEAN.sub("", str(value if value is not None else ""))
        if not text or text in ("-", "—"):
            return None
        try:
            return float(text)
        except ValueError:
            return None

    def enable_table_tools(self, tree):
        if getattr(tree, "_tools_bound", False):
            return
        tree._tools_bound = True
        tree.bind("<Button-3>", lambda e: self.show_table_menu(tree, e), add="+")
        for seq in ("<Control-c>", "<Control-C>"):
            tree.bind(seq, lambda e: (self.copy_tree_rows(tree, selected=True), "break")[1], add="+")
        # ButtonRelease: الجداول التي يُعدَّل اسم عمودها بالنقر (Button-1) تُرتَّب من القائمة
        tree.bind("<ButtonRelease-1>", lambda e: self._on_tree_header_click(tree, e), add="+")

    def table_headers(self, tree):
        cols = [c for c in tree["columns"] if not str(c).startswith("_")]
        heads = []
        for c in cols:
            text = str(tree.heading(c).get("text", c)).replace("\n", " ")
            for arrow in self.SORT_ARROWS:
                text = text.replace(arrow, "")
            heads.append(text.strip() or str(c))
        return cols, heads

    def _on_tree_header_click(self, tree, event):
        if getattr(tree, "_rename_bound", False) or getattr(tree, "_no_sort", False):
            return
        if tree.identify_region(event.x, event.y) != "heading":
            return
        try:
            col = tree["columns"][int(tree.identify_column(event.x).replace("#", "")) - 1]
        except (ValueError, IndexError):
            return
        last = getattr(tree, "_sort_state", None)
        self.sort_tree_by(tree, col, descending=bool(last and last[0] == col and not last[1]))

    def sort_tree_by(self, tree, col, descending=False):
        """يرتّب صفوف الجدول بعمود (الأرقام رقمياً، والنص والتاريخ أبجدياً)؛ صف الإجمالي يبقى آخراً"""
        items = list(tree.get_children(""))
        pinned = [i for i in items if "total_tag" in (tree.item(i, "tags") or ())]
        rest = [i for i in items if i not in pinned]

        def key(i):
            raw = tree.set(i, col)
            num = self.cell_number(raw)
            return (0, num, "") if num is not None else (1, 0.0, str(raw))
        numbers = sorted((i for i in rest if key(i)[0] == 0), key=key, reverse=descending)
        texts = sorted((i for i in rest if key(i)[0] == 1), key=key, reverse=descending)
        for idx, i in enumerate(numbers + texts + pinned):
            tree.move(i, "", idx)
        tree._sort_state = (col, descending)
        cols, heads = self.table_headers(tree)
        for c, h in zip(cols, heads):
            try:
                tree.heading(c, text=self.wrap_header(h) + (self.SORT_ARROWS[1 if descending else 0] if c == col else ""))
            except Exception:
                pass

    def tree_rows(self, tree, selected=False):
        """(العناوين، الصفوف) كما تُعرض — ومعها صف الإجمالي الملاصق إن وُجد"""
        cols, heads = self.table_headers(tree)
        items = tree.selection() if selected else tree.get_children("")
        rows = [[str(tree.set(i, c)) for c in cols] for i in items]
        total = getattr(tree, "_total_tree", None)
        if total is not None and not selected:
            try:
                rows += [[str(total.set(i, c)) for c in cols] for i in total.get_children("")]
            except Exception:
                pass
        return heads, rows

    def copy_tree_rows(self, tree, selected=False):
        heads, rows = self.tree_rows(tree, selected=selected)
        if not rows:
            self.toast("حدّد صفاً أولاً" if selected else "الجدول فارغ", "warn", parent=tree)
            return 0
        text = "\n".join("\t".join(r) for r in [heads] + rows)
        self.clipboard_clear()
        self.clipboard_append(text)
        self.toast(f"📋 نُسخ {len(rows)} صف — الصقه في Excel أو أي برنامج", "success", parent=tree)
        return len(rows)

    @staticmethod
    def write_table_csv(path, heads, rows):
        """CSV بترميز UTF-8 مع BOM: يفتحه Excel بالعربية سليمة مباشرة"""
        import csv
        with open(path, "w", encoding="utf-8-sig", newline="") as f:
            w = csv.writer(f)
            w.writerow(heads)
            w.writerows(rows)
        return path

    def export_tree_csv(self, tree, path=None):
        heads, rows = self.tree_rows(tree)
        if not rows:
            self.toast("الجدول فارغ", "warn", parent=tree)
            return None
        if path is None:
            path = filedialog.asksaveasfilename(
                parent=tree.winfo_toplevel(), initialdir=EXPORTS_DIR, defaultextension=".csv",
                initialfile=f"jadeite_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}.csv",
                filetypes=[("Excel (CSV)", "*.csv")], title="تصدير الجدول إلى Excel")
            if not path:
                return None
        self.write_table_csv(path, heads, rows)
        self.toast(f"📤 صُدِّر {len(rows)} صف إلى Excel", "success", parent=tree)
        try:
            self._open_file(path)
        except Exception:
            pass
        return path

    def table_title(self, tree):
        """عنوان الجدول للطباعة: عنوان نافذته، أو اسم الشاشة المعروضة في النافذة الرئيسية"""
        explicit = getattr(tree, "_print_title", None)
        if explicit:
            return explicit
        try:
            top = tree.winfo_toplevel()
            if top is not self:
                return top.title() or "جدول"
        except Exception:
            pass
        return getattr(getattr(self, "tabview", None), "current_screen", None) or "جدول"

    def print_tree(self, tree):
        """أي جدول PDF بقالب الطباعة الموحّد للنظام (كما يظهر: الترتيب نفسه والإجمالي آخراً)"""
        heads, rows = self.tree_rows(tree)
        if not rows:
            self.toast("الجدول فارغ", "warn", parent=tree)
            return None
        ratios = [1.4 if any(k in h for k in ("الاسم", "البيان", "التاريخ", "العامل", "الحساب")) else 1.0
                  for h in heads]
        title = self.table_title(tree)
        self.print_generic_table_screen(f"📋 {title}", tuple(heads), ratios, [tuple(r) for r in rows], "table_print",
                                        subtitle=f"{len(rows)} صف — {datetime.datetime.now().strftime('%Y-%m-%d %H:%M')}")
        return title

    def find_in_tree(self, tree, text=None):
        """يحدّد كل صف يحتوي النص ويعرض أولها"""
        if text is None:
            text = ctk.CTkInputDialog(title="بحث في الجدول", text="اكتب ما تبحث عنه (اسم، رقم، تاريخ…):").get_input()
        text = (text or "").strip()
        if not text:
            return []
        hits = [i for i in tree.get_children("") if any(text in str(v) for v in tree.item(i, "values"))]
        tree.selection_set(hits)
        if hits:
            tree.see(hits[0])
            tree.focus(hits[0])
        self.toast(f"🔍 {len(hits)} صف يحتوي «{text}»" if hits else f"لا يوجد «{text}» في الجدول",
                   "success" if hits else "warn", parent=tree)
        return hits

    def show_table_menu(self, tree, event):
        menu = tk.Menu(tree, tearoff=0, font=("Cairo", 12))
        region = tree.identify_region(event.x, event.y)
        row = tree.identify_row(event.y)
        if row and row not in tree.selection():
            tree.selection_set(row)
        if region == "heading" and not getattr(tree, "_no_sort", False):
            try:
                col = tree["columns"][int(tree.identify_column(event.x).replace("#", "")) - 1]
                label = dict(zip(*self.table_headers(tree))).get(col, col)
                menu.add_command(label=f"▲ ترتيب تصاعدي حسب «{label}»",
                                 command=lambda: self.sort_tree_by(tree, col, False))
                menu.add_command(label=f"▼ ترتيب تنازلي حسب «{label}»",
                                 command=lambda: self.sort_tree_by(tree, col, True))
                menu.add_separator()
            except (ValueError, IndexError):
                pass
        menu.add_command(label="📋 نسخ الصفوف المحددة   Ctrl+C", command=lambda: self.copy_tree_rows(tree, True))
        menu.add_command(label="📋 نسخ الجدول كاملاً", command=lambda: self.copy_tree_rows(tree, False))
        menu.add_command(label="📤 تصدير إلى Excel", command=lambda: self.export_tree_csv(tree))
        menu.add_command(label="🖨️ طباعة الجدول (PDF)", command=lambda: self.print_tree(tree))
        menu.add_separator()
        menu.add_command(label="🔍 بحث في الجدول…", command=lambda: self.find_in_tree(tree))
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()
        return "break"

    def create_standard_treeview(self, parent, columns, height=15):
        # كل جداول النظام تمرّ من هنا، فالتنسيق الموحّد يصلها جميعاً
        if not getattr(self, "_design", None):
            self.apply_design_system()

        tree = ttk.Treeview(parent, columns=columns, show="headings", height=height)
        # التظليل تحت المؤشر أولاً: أول وسم يُنشأ هو الأعلى أولوية في ttk
        self.enable_row_hover(tree)
        for col in columns:
            tree.heading(col, text=self.wrap_header(col))
            tree.column(col, anchor="center")

        vsb = self.make_scrollbar(parent, "vertical", tree.yview)
        tree.configure(yscrollcommand=vsb.set)

        vsb.pack(side="right", fill="y")
        tree.pack(side="left", fill="both", expand=True)
        self.enable_table_tools(tree)

        return tree

    @staticmethod
    def row_sort_key(row_num):
        """مفتاح ترتيب تدريجي لأرقام الصفوف: رقمياً أولاً، ثم نصياً، والصفوف بدون ترقيم في النهاية"""
        s = str(row_num or "").strip()
        if not s:
            return (2, 0.0, "")
        try:
            return (0, float(s), "")
        except ValueError:
            return (1, 0.0, s)

    INBOUND_TYPES = ("وارد ذهب (عيار 18)", "وارد فصوص وأحجار", "وارد الماس")

    # «المسترجع» في شاشة الكاستنج رجوعٌ من الفاقد الحالي نفسه — لا صلة له بحساب
    # «مسترجع كاستنج» (ذاك لما يُستلم من شاشة الوارد إلى حسابه). تُسجَّل حركاته صرفاً
    # وقبضاً للكاستنج نفسه بهذين الاسمين، فيزيد صرفها الفاقد الحالي ويُخصم قبضها منه:
    CAST_RETURN_NAME = "مسترجع الفاقد"      # عملية «مسترجع» (بلا صف): صرفها وقبضها
    TREE_RETURN_NAME = "مسترجع الأشجار"     # مسترجع أشجار الصف: قبض من فاقد صفه
    # الليزر في «بوليش 1»: مثل الصرف تماماً (صرف تلميع بف) يُضاف إلى فاقد صفه، ويُسجَّل
    # بهذا الاسم ليظهر في عموده الخاص (كان قبضاً في 1.46.0 — migrate_row_extras يصحّحه)
    LASER_NAME = "ليزر البوليش"

    def stage_row_extra(self, qabd_type, recover_name=None):
        """الحركة الثانية المرتبطة بصفوف قسم: (اسم حركتها، عنوان خانتها وعمودها، أثرها) أو None.
          • الكاستنج ← «مسترجع الأشجار» (في الشاشة التي تعرض المسترجع): قبضٌ، أثره −1
          • بوليش 1  ← «الليزر»: صرفٌ، أثره +1
        الأثر على الخياس والفاقد الحالي للقسم: الخياس = الصرف − القبض + الأثر × قيمتها."""
        if qabd_type == "قبض كاستنج":
            return (self.TREE_RETURN_NAME, "مسترجع الأشجار", -1) if recover_name else None
        if qabd_type == "قبض تلميع بف":
            return (self.LASER_NAME, "الليزر", 1)
        return None

    def is_row_recovery(self, inv, recover_name):
        """«مسترجع الأشجار» لصف: قبض من الفاقد الحالي على رقم الصف نفسه.
        recover_name: غير فارغ في الشاشات التي تعرض المسترجع (الكاستنج)"""
        return bool(recover_name and inv.get("الاسم") == self.TREE_RETURN_NAME
                    and (inv.get("row_number", "") or ""))

    def is_recovery_op(self, inv, madin_type, recover_name):
        """عملية «مسترجع» بلا صف (الكاستنج): صرفها يزيد الفاقد الحالي وقبضها يُخصم منه"""
        return bool(recover_name and inv.get("الاسم") == self.CAST_RETURN_NAME
                    and not (inv.get("row_number", "") or ""))

    def collect_stage_ops_rows(self, madin_type, qabd_type, recover_name=None):
        """يجمع حركات أي شاشة عمليات للشهر المعروض في صفوف مرتبة تصاعدياً برقم الصف.

        لكل صف (g["op"]):
          • «فاقد»   — صرف وقبض القسم بصفوفها (رقم الصف)، ومعها «مسترجع الأشجار» لصفها.
          • «مسترجع» — عمليات المسترجع بلا صف، كل عملية صف مستقل بعد صفوف الفاقد:
                       صرفها تحت الصرف، وقبضها تحت القبض.
        الخياس = الصرف − القبض − مسترجع الأشجار: كلها من الفاقد الحالي نفسه، ولا صلة لأيٍّ
        منها بحساب «مسترجع» المرحلة. والليزر في «بوليش 1» مثل مسترجع الأشجار تماماً
        (الحركة الثانية للصف — stage_row_extra) تُجمع في الخانة نفسها g["مسترجع"]، لكنه صرفٌ
        يُضاف إلى الخياس (أثره +1) لا قبضٌ يُخصم منه.
        """
        recs = [inv for inv in self.period_invoices(self.current_display_month)
                if inv.get("settled_status") == "ACTIVE" and inv.get("النوع") in (madin_type, qabd_type)]
        recs.sort(key=lambda x: (x.get("التاريخ", ""), x.get("رقم الفاتورة", 0)))
        extra = self.stage_row_extra(qabd_type, recover_name)
        extra_name = extra[0] if extra else None

        def is_extra(inv):
            return bool(extra_name and inv.get("الاسم") == extra_name
                        and (inv.get("row_number", "") or ""))

        # حركات الصرف والقبض أولاً ثم القبض الثاني، ليُلحق بصف قائم إن وُجد
        recs.sort(key=lambda x: 1 if is_extra(x) else 0)

        grouped = {}
        for inv in recs:
            rec_op = self.is_recovery_op(inv, madin_type, recover_name)
            tree = is_extra(inv)
            key = ((inv.get("row_number", "") or ""), inv["الاسم"])
            if rec_op:
                key = ("", inv["الاسم"], inv["رقم الفاتورة"])      # كل عملية مسترجع صف مستقل
            elif tree:
                key = next((k for k in grouped if len(k) == 2 and k[0] == key[0]), key)
            if key not in grouped:
                grouped[key] = {"ids": [], "مدين": 0.0, "دائن": 0.0, "مسترجع": 0.0,
                                "dt": inv["التاريخ"], "البيان": "", "أشجار": 0.0,
                                "op": "مسترجع" if rec_op else "فاقد"}
            g = grouped[key]
            g["ids"].append(inv["رقم الفاتورة"])
            note = (inv.get("البيان") or "").strip()
            # الجمع (وليس الاستبدال) حتى لا تُهمل أي حركة مسجّلة فعلياً بنفس رقم الصف
            if tree:
                g["مسترجع"] = round(g["مسترجع"] + inv["الوزن"], 2)
                # اسم الحركة («مسترجع الأشجار»/«ليزر البوليش») وحده لا يُكرَّر في عمود
                # البيان، أما ما كتبه المستخدم بعده فيظهر («مسترجع الأشجار — بيانه»)
                note = note.split(" — ", 1)[1].strip() if " — " in note else (
                    "" if note == extra_name else note)
            elif inv["النوع"] == madin_type:
                g["مدين"] = round(g["مدين"] + inv["الوزن"], 2)
            else:
                g["دائن"] = round(g["دائن"] + inv["الوزن"], 2)
            if note and note not in g["البيان"]:
                g["البيان"] = note if not g["البيان"] else g["البيان"] + " | " + note
            trees = inv.get("trees_count", 0.0) or 0.0
            if trees > g["أشجار"]:
                g["أشجار"] = trees

        order = sorted(grouped.keys(), key=lambda k: (grouped[k]["op"] == "مسترجع",
                                                      self.row_sort_key(k[0]), grouped[k]["dt"], k[1]))
        return [(k[0], k[1], grouped[k]) for k in order]

    def render_stage_ops_table(self, table_frame, madin_type, qabd_type, height=11,
                               with_trees=False, on_edit=None, totals_label=None,
                               section=None, show_name=False, on_detail=None, on_refresh=None,
                               recover_name=None, op_filter=None):
        """محرك موحّد لجداول شاشات العمليات:
        (الصف / [العملية] / صرف / قبض / [مسترجع الأشجار] / الخياس [+ الأشجار] / البيان)
        مع سطر إجماليات أسفل الجدول وشريط إجماليات ثابت تحته.

        recover_name (الكاستنج): عمود «العملية» (فاقد/مسترجع) و«مسترجع الأشجار».
        الخياس = الصرف − القبض − مسترجع الأشجار (كلها من الفاقد الحالي نفسه).
        وفي «بوليش 1» عمود «الليزر» مكانه: الخياس = الصرف − القبض − الليزر.
        op_filter: «مسترجع» ← عمليات المسترجع وحدها؛ غير ذلك ← كل العمليات.
        """
        # عمود الاسم يظهر فقط حيث يكون له معنى؛ وفي الكاستنج مكانه «العملية»
        name_col = ("الاسم",) if (show_name and not recover_name) else ()
        op_col = ("العملية",) if recover_name else ()
        extra = self.stage_row_extra(qabd_type, recover_name)
        rec_col = (extra[1],) if extra else ()
        if with_trees:
            cols = (("الصف",) + op_col + name_col + ("صرف", "قبض") + rec_col + ("الخياس",)
                    + ("عدد الأشجار", "خياس كل شجرة", "البيان"))
        else:
            cols = ("الصف",) + op_col + name_col + ("صرف", "قبض") + rec_col + ("الخياس", "البيان")

        tree, total_tree, _reused = self.reuse_or_create_tree(
            table_frame, cols, height=height, sticky_total=True)
        tree.tag_configure("total_tag", foreground="#e67e22", font=("Cairo", 13, "bold"))
        tree.tag_configure("red_tag", foreground="#e74c3c", font=("Cairo", 13, "bold"))
        for c in cols:
            w = 230 if c == "البيان" else 165 if c == "الاسم" else 120 if c == "الصف" else 110
            tree.column(c, width=w, anchor="center")

        color_negative = self.negative_color_enabled(section) if section else False

        # الإجمالي في شجرة ثابتة أسفل الجدول: يبقى أمام المستخدم أثناء التمرير
        # بدل الاضطرار للنزول لآخر الصفوف لرؤيته
        rows_map = {}
        tot_madin = tot_daen = tot_trees = tot_rec = 0.0
        rows = self.collect_stage_ops_rows(madin_type, qabd_type, recover_name)
        if op_filter == "مسترجع":
            # عمليات المسترجع وحدها، والإجماليات لها وحدها
            rows = [r for r in rows if r[2].get("op") == "مسترجع"]
        # أثر الحركة الثانية: مسترجع الأشجار قبضٌ (−1)، والليزر صرفٌ (+1)
        extra_sign = extra[2] if extra else -1
        for row_num, name, g in rows:
            # الخياس = الفاقد الحالي للصف: صرف − قبض − مسترجع الأشجار (أو + الليزر)
            khayas = round(g["مدين"] - g["دائن"] + extra_sign * g["مسترجع"], 2)
            tot_madin = round(tot_madin + g["مدين"], 2)
            tot_daen = round(tot_daen + g["دائن"], 2)
            tot_rec = round(tot_rec + g["مسترجع"], 2)
            tot_trees += g["أشجار"]
            is_rec_row = g.get("op") == "مسترجع"
            row_label = row_num if row_num else ("-" if is_rec_row else "بدون ترقيم")
            # التلوين حسب إعداد القسم نفسه: الأحمر فقط لو كان الخياس سالباً
            # (أي أن القبض أكبر من الصرف) والزر مفعّل في هذا القسم.
            tags = ("red_tag",) if (color_negative and khayas < 0) else ()
            vals = [row_label]
            if recover_name:
                op_label = g.get("op", "فاقد")
                # حركات قديمة سُجّلت بأسماء (قبل خانة العملية) تُذكر أسماؤها
                if op_label == "فاقد" and name and name not in ("كاستنج", recover_name, self.TREE_RETURN_NAME):
                    op_label = f"فاقد ({name})"
                vals.append(op_label)
            elif show_name:
                vals.append(name)
            vals += [f"{g['مدين']:.2f}" if g["مدين"] else "-",
                     f"{g['دائن']:.2f}" if g["دائن"] else "-"]
            if extra:
                vals.append(f"{g['مسترجع']:.2f}" if g["مسترجع"] else "-")
            vals.append(f"{khayas:.2f}")
            if with_trees:
                trees = g["أشجار"]
                vals += [f"{trees:g}" if trees else "-",
                         f"{round(khayas / trees, 2):.2f}" if trees > 0 else "-"]
            vals.append(g["البيان"])
            item_id = tree.insert("", "end", values=tuple(vals), tags=tags)
            rows_map[item_id] = g["ids"]

        tot_khayas = round(tot_madin - tot_daen + extra_sign * tot_rec, 2)
        if rows_map:
            tvals = ["إجمالي الشهر"] + (["-"] if (recover_name or show_name) else []) + [
                     f"{tot_madin:.2f}", f"{tot_daen:.2f}"] + (
                     [f"{tot_rec:.2f}"] if extra else []) + [f"{tot_khayas:.2f}"]
            if with_trees:
                tvals += [f"{tot_trees:g}" if tot_trees else "-",
                          f"{round(tot_khayas / tot_trees, 2):.2f}" if tot_trees > 0 else "-"]
            tvals.append("-")
            # الإجمالي في الشريط الثابت **وداخل الجدول** معاً: الشريط يبقى أمام
            # المستخدم بلا تمرير، والصف داخل الجدول ضمانة لا يمكن أن تختفي
            total_tree.insert("", "end", values=tuple(tvals), tags=("total_tag",))
            tree.insert("", "end", values=tuple(tvals), tags=("total_tag",))
            tree._totals_values = tuple(tvals)
            tree._total_tree = total_tree

        if totals_label is not None:
            txt = f"الإجماليات — صرف: {tot_madin:.2f}  |  قبض: {tot_daen:.2f}"
            if extra:
                txt += f"  |  {extra[1]}: {tot_rec:.2f}"
            txt += f"  |  الخياس: {tot_khayas:.2f} جم"
            if with_trees:
                per_tree = round(tot_khayas / tot_trees, 2) if tot_trees > 0 else 0.0
                txt += f"  |  عدد الأشجار: {tot_trees:g}  |  خياس كل شجرة: {per_tree:.2f}"
            totals_label.configure(text=txt)

        # الضغط المزدوج يعرض تفاصيل العملية. التعديل يبقى متاحاً من زره المخصّص،
        # حتى لا يفتح المستخدم نافذة تعديل بالخطأ وهو يريد الاطّلاع فقط.
        if on_detail:
            tree.bind("<Double-1>", lambda e: on_detail())
        elif on_edit:
            tree.bind("<Double-1>", lambda e: on_edit())

        # عناوين بسطرين + عرض محكوم بالمحتوى، فتظهر كل الأعمدة بلا سحب أفقي
        # الانتقال لآخر صف: نريد أن نرى أين وصلنا، لا أول الصفوف
        try:
            rows_now = tree.get_children()
            if rows_now:
                tree.see(rows_now[-1])
        except Exception:
            pass

        table_key = f"stage_{section or madin_type}"
        self.apply_column_labels(tree, table_key)
        self.fit_columns_to_content(tree, table_key, min_width=44, max_width=170)
        # تعديل اسم أي عمود بالضغط على رأسه (يُحفظ ويُطبَّق في كل مرة)
        self.enable_column_rename(tree, table_key, on_renamed=on_refresh)
        return tree, rows_map

    def show_selected_stage_details(self, tree, rows_map, title):
        """يفتح تفاصيل الصف المحدد في أي جدول من جداول الأقسام"""
        if not tree:
            return
        sel = tree.selection()
        if not sel:
            return
        ids = (rows_map or {}).get(sel[0])
        if ids:
            self.show_stage_row_details(ids, title)

    def show_stage_row_details(self, ids, title):
        """نافذة عرض تفاصيل حركات الصف: التاريخ والوقت والنوع والوزن والبيان.

        للاطّلاع فقط — لا تعديل هنا، فالتعديل له زره المخصّص أعلى الجدول.
        """
        invs = [self.invoices[i] for i in ids if i in self.invoices]
        if not invs:
            messagebox.showwarning("تنبيه", "لم يعد لهذا الصف حركات مسجّلة.")
            return
        invs.sort(key=lambda x: (x.get("التاريخ", ""), x.get("رقم الفاتورة", 0)))

        win = ctk.CTkToplevel(self)
        win.title(title)
        win.geometry("760x480")
        win.transient(self)
        win.grab_set()
        win.focus_force()

        ref = invs[0]
        ctk.CTkLabel(win, text=f"📋 تفاصيل الصف ({ref.get('row_number') or 'بدون ترقيم'})",
                     font=("Cairo", 18, "bold"), text_color="#d4af37").pack(pady=(14, 2))
        ctk.CTkLabel(win, text=f"{ref.get('الاسم', '')}   |   عدد الحركات: {len(invs)}",
                     font=("Cairo", 12), text_color="#8b8f95").pack(pady=(0, 10))

        frame = ttk.Frame(win)
        frame.pack(fill="both", expand=True, padx=16, pady=6)

        cols = ("رقم الحركة", "التاريخ", "الوقت", "النوع", "الوزن", "عدد الأشجار", "البيان")
        tree = self.create_standard_treeview(frame, cols, height=11)
        tree.tag_configure("total_tag", foreground="#e67e22", font=("Cairo", 13, "bold"))
        for c in cols:
            tree.column(c, width=180 if c == "البيان" else 130 if c == "النوع" else 100, anchor="center")

        total_w = 0.0
        for inv in invs:
            dt = str(inv.get("التاريخ", ""))
            total_w = round(total_w + inv.get("الوزن", 0.0), 2)
            tree.insert("", "end", values=(
                inv.get("رقم الفاتورة", "-"),
                dt[:10] or "-",
                dt[11:19] or "-",
                inv.get("النوع", "-"),
                f"{inv.get('الوزن', 0.0):.2f}",
                f"{inv.get('trees_count', 0) or 0:g}" if inv.get("trees_count") else "-",
                inv.get("البيان", "") or "-",
            ))

        tree.insert("", "end", values=("الإجمالي", "-", "-", "-", f"{total_w:.2f}", "-", "-"),
                    tags=("total_tag",))

        ctk.CTkButton(win, text="إغلاق", font=("Cairo", 14, "bold"), width=140, height=38,
                      command=win.destroy).pack(pady=12)

    def open_stage_op_edit_dialog(self, ids, madin_type, qabd_type, title, with_trees=False, status_text="",
                                  recover_name=None):
        """نافذة تعديل موحّدة لأي حركة في شاشات العمليات (صرف/قبض/مسترجع الأشجار/عدد الأشجار/البيان)"""
        if not self.check_edit_permission():
            return
        invs = [self.invoices[i] for i in ids if i in self.invoices]
        if not invs:
            messagebox.showwarning("تنبيه", "الحركة المحددة لم تعد موجودة. حدّث الشاشة وحاول مجدداً.")
            return
        # القبض الثاني للصف: مسترجع الأشجار (الكاستنج) أو الليزر (بوليش 1)
        row_extra = self.stage_row_extra(qabd_type, recover_name)
        rec_inv = next((i for i in invs if row_extra and i.get("الاسم") == row_extra[0]
                        and (i.get("row_number", "") or "")), None)
        # بيانات الصف من حركة الصرف/القبض لا من القبض الثاني (له اسمه الخاص)
        ref = next((i for i in invs if i is not rec_inv), invs[0])
        ref_dt = ref["التاريخ"]
        ref_name = ref["الاسم"]
        ref_row = ref.get("row_number", "") or ""
        # أي حركة جديدة تُضاف للصف بالتعديل تبقى في فترة الصف نفسها، لا الفترة المعروضة
        ref_period = self.inv_period(ref)
        # الليزر صرفٌ أيضاً: لا يُخلط بصرف الصف نفسه
        sarf_inv = next((i for i in invs if i["النوع"] == madin_type and i is not rec_inv), None)
        # مسترجع الأشجار قبضٌ أيضاً: لا يُخلط بقبض الصف نفسه
        qabd_inv = next((i for i in invs if i["النوع"] == qabd_type and i is not rec_inv), None)
        base_inv = sarf_inv or qabd_inv
        common_note = (base_inv.get("البيان") or "") if base_inv else ""
        cur_trees = max([(i.get("trees_count", 0.0) or 0.0) for i in invs] or [0.0])

        win = ctk.CTkToplevel(self)
        win.title(title)
        win.geometry("540x660" if (with_trees and row_extra) else "540x610" if (with_trees or row_extra) else "540x545")
        win.transient(self)
        win.grab_set()
        win.focus_force()

        ctk.CTkLabel(win, text=f"تعديل حركة الصف ({ref_row or 'بدون ترقيم'}) — {ref_name}",
                     font=("Cairo", 17, "bold"), text_color="#d4af37").pack(pady=10)

        frm = ctk.CTkFrame(win)
        frm.pack(fill="x", padx=20, pady=10)

        ctk.CTkLabel(frm, text="الصرف (مدين):", font=("Cairo", 15, "bold")).grid(row=0, column=1, padx=10, pady=8)
        ent_sarf = ctk.CTkEntry(frm, justify="center", width=130)
        ent_sarf.insert(0, f"{sarf_inv['الوزن']:g}" if sarf_inv else "0")
        ent_sarf.grid(row=0, column=0, padx=10, pady=8)

        ctk.CTkLabel(frm, text="القبض (دائن):", font=("Cairo", 15, "bold")).grid(row=1, column=1, padx=10, pady=8)
        ent_qabd = ctk.CTkEntry(frm, justify="center", width=130)
        ent_qabd.insert(0, f"{qabd_inv['الوزن']:g}" if qabd_inv else "0")
        ent_qabd.grid(row=1, column=0, padx=10, pady=8)

        ent_trees = None
        if with_trees:
            ctk.CTkLabel(frm, text="عدد الأشجار:", font=("Cairo", 15, "bold")).grid(row=3, column=1, padx=10, pady=8)
            ent_trees = ctk.CTkEntry(frm, justify="center", width=130)
            ent_trees.insert(0, f"{cur_trees:g}" if cur_trees else "")
            ent_trees.grid(row=3, column=0, padx=10, pady=8)

        ent_rec = None
        if row_extra:
            ctk.CTkLabel(frm, text=f"{row_extra[1]}:", font=("Cairo", 15, "bold")).grid(row=2, column=1, padx=10, pady=8)
            ent_rec = ctk.CTkEntry(frm, justify="center", width=130)
            ent_rec.insert(0, f"{rec_inv['الوزن']:g}" if rec_inv else "0")
            ent_rec.grid(row=2, column=0, padx=10, pady=8)

        # حقول تعريف الحركة: قابلة للتعديل لتصحيح أي خطأ في الترقيم أو التاريخ
        ref_set = (base_inv.get("set_number", "") or "") if base_inv else ""

        ctk.CTkLabel(frm, text="رقم الصف:", font=("Cairo", 15, "bold")).grid(row=4, column=1, padx=10, pady=8)
        ent_row_no = ctk.CTkEntry(frm, justify="center", width=130)
        ent_row_no.insert(0, ref_row)
        ent_row_no.grid(row=4, column=0, padx=10, pady=8)

        ctk.CTkLabel(frm, text="رقم التشغيل:", font=("Cairo", 15, "bold")).grid(row=5, column=1, padx=10, pady=8)
        ent_set_no = ctk.CTkEntry(frm, justify="center", width=130)
        ent_set_no.insert(0, ref_set)
        ent_set_no.grid(row=5, column=0, padx=10, pady=8)

        ctk.CTkLabel(frm, text="التاريخ:", font=("Cairo", 15, "bold")).grid(row=6, column=1, padx=10, pady=8)
        ent_date = ctk.CTkEntry(frm, justify="center", width=130)
        ent_date.insert(0, str(ref_dt)[:10])
        ent_date.grid(row=6, column=0, padx=10, pady=8)

        ctk.CTkLabel(win, text="البيان:", font=("Cairo", 15, "bold")).pack(pady=(8, 0))
        ent_note = ctk.CTkEntry(win, justify="right", width=380)
        ent_note.insert(0, common_note)
        ent_note.pack(pady=5)

        def save_edit():
            try:
                new_sarf = round(float(ent_sarf.get().strip() or 0), 2)
                new_qabd = round(float(ent_qabd.get().strip() or 0), 2)
                new_trees = round(float(ent_trees.get().strip() or 0), 2) if ent_trees is not None else cur_trees
                new_rec = round(float(ent_rec.get().strip() or 0), 2) if ent_rec is not None else 0.0
            except ValueError:
                messagebox.showerror("خطأ", "الرجاء إدخال أرقام صحيحة.", parent=win)
                return
            if new_sarf < 0 or new_qabd < 0 or new_trees < 0 or new_rec < 0:
                messagebox.showerror("خطأ", "لا يمكن إدخال قيم بالسالب.", parent=win)
                return
            if new_sarf <= 0 and new_qabd <= 0 and new_rec <= 0:
                if not messagebox.askyesno("تأكيد", "الصرف والقبض كلاهما صفر — سيتم حذف هذه الحركة بالكامل.\nهل تريد المتابعة؟", parent=win):
                    return
            new_note = ent_note.get().strip()
            new_row_no = ent_row_no.get().strip()
            new_set_no = ent_set_no.get().strip()

            new_date = ent_date.get().strip()
            if len(new_date) < 10 or new_date[4] != "-":
                messagebox.showerror("خطأ", "الرجاء إدخال التاريخ بالصيغة YYYY-MM-DD.", parent=win)
                return
            # نُبقي وقت الحركة كما هو ما دام اليوم لم يتغيّر، فلا يتبدّل ترتيبها
            # المحاسبي بلا داعٍ داخل اليوم نفسه
            old_time = str(ref_dt)[11:] or datetime.datetime.now().strftime("%H:%M:%S")
            new_dt = f"{new_date} {old_time}"

            any_blocked = False

            def upsert(existing, value, op_type):
                nonlocal any_blocked
                if value > 0:
                    if existing:
                        existing["الوزن"] = value
                        existing["البيان"] = new_note
                        existing["trees_count"] = new_trees
                        existing["row_number"] = new_row_no
                        existing["set_number"] = new_set_no
                        existing["التاريخ"] = new_dt
                        if not self.save_invoice_to_db(existing["رقم الفاتورة"], existing):
                            any_blocked = True
                    else:
                        self.invoice_counter += 1
                        inv_data = {"رقم الفاتورة": self.invoice_counter, "التاريخ": new_dt, "الاسم": ref_name,
                                    "النوع": op_type, "الوزن": value, "البيان": new_note, "settled_status": "ACTIVE",
                                    "trees_count": new_trees, "قبل": 0.0, "بعد": 0.0,
                                    "set_number": new_set_no, "row_number": new_row_no, "period": ref_period}
                        self.invoices[self.invoice_counter] = inv_data
                        if not self.save_invoice_to_db(self.invoice_counter, inv_data):
                            any_blocked = True
                elif existing:
                    if not self.delete_invoice_from_db(existing["رقم الفاتورة"]):
                        any_blocked = True

            upsert(sarf_inv, new_sarf, madin_type)
            upsert(qabd_inv, new_qabd, qabd_type)

            if row_extra:
                # مسترجع الأشجار/الليزر: قبض من فاقد الصف نفسه (لا صلة له بحساب المسترجع)
                extra_type = madin_type if row_extra[2] > 0 else qabd_type
                if new_rec > 0:
                    if rec_inv:
                        rec_inv.update({"الوزن": new_rec, "النوع": extra_type,
                                        "row_number": new_row_no, "التاريخ": new_dt})
                        if not self.save_invoice_to_db(rec_inv["رقم الفاتورة"], rec_inv):
                            any_blocked = True
                    else:
                        self.invoice_counter += 1
                        inv_data = {"رقم الفاتورة": self.invoice_counter, "التاريخ": new_dt,
                                    "الاسم": row_extra[0], "النوع": extra_type, "الوزن": new_rec,
                                    "البيان": row_extra[0], "settled_status": "ACTIVE", "trees_count": 0.0,
                                    "قبل": 0.0, "بعد": 0.0, "set_number": "", "row_number": new_row_no,
                                    "period": ref_period}
                        self.invoices[self.invoice_counter] = inv_data
                        if not self.save_invoice_to_db(self.invoice_counter, inv_data):
                            any_blocked = True
                elif rec_inv:
                    if not self.delete_invoice_from_db(rec_inv["رقم الفاتورة"]):
                        any_blocked = True

            # أي حركة أخرى في نفس الصف (غير الصرف والقبض) تتبع الترقيم الجديد
            # أيضاً، وإلا انفصلت عن صفها وظهرت كصف مستقل بعد التعديل
            for extra in invs:
                if extra is sarf_inv or extra is qabd_inv or extra is rec_inv:
                    continue
                extra["row_number"] = new_row_no
                extra["set_number"] = new_set_no
                extra["التاريخ"] = new_dt
                if not self.save_invoice_to_db(extra["رقم الفاتورة"], extra):
                    any_blocked = True

            if any_blocked:
                return  # تم منع بعض التعديلات (رسالة "غير مسموح" ظهرت بالفعل)
            self.recalculate_all()
            win.destroy()
            if status_text and hasattr(self, 'lbl_op_status'):
                self.lbl_op_status.configure(text=status_text)
                self.after(2500, lambda: self.lbl_op_status.configure(text=""))
            messagebox.showinfo("تم", "تم تحديث الحركة بنجاح.")

        # التنقّل بين الخانات: Enter و↑ ↓، وEnter في آخر خانة يحفظ مباشرة
        _nav = [e for e in (ent_sarf, ent_qabd, ent_rec,
                            ent_trees if with_trees else None,
                            ent_row_no, ent_set_no, ent_date, ent_note) if e is not None]
        self.bind_vertical_navigation(_nav, on_last=lambda: save_edit(), window=win)
        try:
            _nav[0].focus_set()
        except Exception:
            pass

        ctk.CTkButton(win, text="حفظ التعديلات 💾", font=("Cairo", 16, "bold"), fg_color="#2ecc71",
                      hover_color="#27ae60", height=42, command=save_edit).pack(pady=15)

    # ترتيب الشاشات في الشريط الجانبي كما طلبه المستخدم
    SIDEBAR_PRIMARY = [
        ("المبيعات",        "🧾", "المبيعات / الصادر"),
        ("مراحل التصنيع",   "⚙️", "مراحل التصنيع"),
        ("صناديق الخياس",   "⚖️", "صناديق الخياس"),
        ("الوارد",          "📥", "الوارد / قبض"),
        ("شاشة الخسائر",    "📉", "شاشة الخسائر"),
        ("صناديق المصنع",   "🏭", "صناديق المصنع"),
    ]
    SIDEBAR_SECONDARY = [
        ("لوحة المؤشرات",   "🧭", "لوحة المؤشرات"),
        ("ربح/خسارة الطقم", "📈", "ربح / خسارة الطقم"),
        ("كشف حساب",        "📑", "كشف حساب"),
        ("التقرير الشهري",  "📊", "التقرير الشهري"),
        ("أرشيف الفواتير",  "🗂️", "أرشيف الفواتير"),
        ("القيود اليومية",  "📝", "القيود اليومية"),
        ("الحسابات",        "🌳", "شجرة الحسابات"),
        ("الموردين",        "🚚", "الموردين"),
        ("الرصيد الافتتاحي", "🔢", "الرصيد الافتتاحي"),
    ]

    # وصف قصير يظهر تحت عنوان كل شاشة: ماذا تفعل هنا بجملة واحدة
    SCREEN_SUBTITLES = {
        "المبيعات": "فواتير المبيعات والصادر: إدخال السطور ثم الترحيل",
        "مراحل التصنيع": "صرف وقبض الكاستنج والمصنعين والمركبين والتلميع",
        "صناديق الخياس": "أرصدة العمال والخياس الفعلي لكل قسم وإقفاله",
        "الوارد": "استلام الذهب والفصوص والألماس من الموردين والمصنع",
        "شاشة الخسائر": "لكل مرحلة: الفاقد الحالي، وحسابا فاقدها ومسترجعها، والصافي — والإقفال لحساب فاقدها",
        "صناديق المصنع": "المبيعات والوارد لكل مادة ونسب الإنتاج",
        "ربح/خسارة الطقم": "خياسات كل طقم ومسترجعها وربحه أو خسارته",
        "لوحة المؤشرات": "مؤشرات الإدارة: الخزينة والفاقد والمبيعات والوارد عبر الفترات",
        "كشف حساب": "حركة أي حساب مع رصيد أول المدة المُرحَّل",
        "التقرير الشهري": "رصيد الخزينة لكل الفترات — كل فترة تبدأ بنهاية سابقتها",
        "أرشيف الفواتير": "كل الفواتير المرحّلة: معاينة وطباعة وتعديل",
        "القيود اليومية": "قيود مدين ودائن بين الحسابات",
        "الحسابات": "شجرة الحسابات: الأقسام والعمال والموردون والصناديق",
        "الموردين": "أرصدة الموردين والمسترجعات",
        "الرصيد الافتتاحي": "القيود الافتتاحية لبداية التشغيل",
    }

    def screen_meta_map(self):
        """أيقونة وعنوان ووصف كل شاشة — لرأسها الموحّد (ScreenRouter)"""
        meta = {}
        for name, icon, label in self.SIDEBAR_PRIMARY + self.SIDEBAR_SECONDARY:
            meta[name] = (icon, self.get_screen_label(name, label), self.SCREEN_SUBTITLES.get(name, ""))
        return meta

    def logical_screen_width(self):
        """عرض الشاشة بوحدات الواجهة: البكسل الفعلي ÷ تكبير ويندوز للعرض.

        شاشة ١٩٢٠ بتكبير ١٢٥٪ تتسع فعلياً لما تتسع له شاشة ١٥٣٦ — والقياس
        بالبكسل الفعلي كان يعطي الشريط الجانبي عرض الشاشات الكبيرة على حاسوب
        محمول فيضيق ما تبقى للشاشات.
        """
        try:
            sw = self.winfo_screenwidth()
        except Exception:
            sw = 1366
        try:
            # مقياس العناصر: تكبير العرض × تصغير الشاشات الصغيرة (apply_screen_fit)
            scale = float(ctk.ScalingTracker.get_widget_scaling(self)) or 1.0
        except Exception:
            scale = 1.0
        return sw / scale

    def sidebar_width(self):
        """عرض الشريط حسب حجم الشاشة: لا يبتلع المساحة على الشاشات الصغيرة"""
        sw = self.logical_screen_width()
        # عريض بما يكفي ليظهر اسم كل شاشة كاملاً بخط واضح
        if sw >= 1920:
            return 330
        if sw >= 1440:
            return 300
        if sw >= 1280:
            return 268
        return 232

    def ui_scale(self):
        """معامل تكبير موحّد يجعل النظام مريحاً على كل مقاسات الشاشات"""
        sw = self.logical_screen_width()
        if sw >= 1920:
            return 1.0
        if sw >= 1440:
            return 0.94
        if sw >= 1280:
            return 0.86
        return 0.8

    def safe_minsize(self, width, height):
        """حدّ أدنى لحجم النافذة لا يتجاوز الشاشة نفسها أبداً.

        customtkinter يضرب الحد الأدنى في تكبير ويندوز للعرض: ١١٠٠×٦٢٠ على
        شاشة ١٣٦٦×٧٦٨ بتكبير ١٢٥٪ تصير ١٣٧٥×٧٧٥ بكسلاً — أكبر من الشاشة، فكان
        جزء من النافذة يخرج عنها ولا يظهر النظام كاملاً على هذه الأجهزة.
        """
        self._min_request = (width, height)     # يُعاد حسابه إن تغيّر تكبير العرض لاحقاً
        try:
            scale = float(ctk.ScalingTracker.get_window_scaling(self)) or 1.0
        except Exception:
            scale = 1.0
        try:
            max_w = self.winfo_screenwidth() / scale * 0.8
            max_h = self.winfo_screenheight() / scale * 0.7
        except Exception:
            max_w, max_h = width, height
        self.minsize(int(min(width, max_w)), int(min(height, max_h)))

    def get_screen_label(self, name, default_label):
        """اسم الشاشة المعروض في الشريط: المعدَّل من المستخدم إن وُجد"""
        try:
            saved = json.loads(self.get_setting("sidebar_labels", "") or "{}")
            return saved.get(name) or default_label
        except Exception:
            return default_label

    def rename_screen_dialog(self, name, default_label):
        """تعديل اسم شاشة في الشريط الجانبي (بالزر الأيمن)"""
        current = self.get_screen_label(name, default_label)
        new_label = ctk.CTkInputDialog(
            title="تعديل اسم الشاشة",
            text=f"الاسم الجديد للشاشة «{current}»\n(اتركه فارغاً لإرجاع الاسم الأصلي)"
        ).get_input()
        if new_label is None:
            return
        try:
            saved = json.loads(self.get_setting("sidebar_labels", "") or "{}")
            new_label = new_label.strip()
            if new_label and new_label != default_label:
                saved[name] = new_label
            else:
                saved.pop(name, None)
            self.set_setting("sidebar_labels", json.dumps(saved, ensure_ascii=False))
        except Exception as e:
            log_cloud_error("تعذّر حفظ اسم الشاشة", e)
        self.build_sidebar()
        if hasattr(self, "tabview"):
            self.tabview.set_title(name, self.get_screen_label(name, default_label))

    def promote_screen_to_main(self, name):
        """ينقل شاشة من (أخرى) إلى القائمة الرئيسية في الشريط"""
        order = self.sidebar_order()
        if name not in order:
            order.append(name)
            self.save_sidebar_order(order)
        self.build_sidebar()

    def demote_screen_to_more(self, name):
        """يُرجع شاشة من القائمة الرئيسية إلى (أخرى)"""
        order = [n for n in self.sidebar_order() if n != name]
        self.save_sidebar_order(order)
        self.build_sidebar()

    def show_screen_context_menu(self, event, name, default_label, in_main):
        """قائمة الزر الأيمن: تعديل الاسم، ونقل الشاشة بين القائمتين"""
        menu = tk.Menu(self, tearoff=0)
        menu.add_command(label="✏️ تعديل الاسم",
                         command=lambda: self.rename_screen_dialog(name, default_label))
        menu.add_separator()
        if in_main:
            menu.add_command(label="⤵️ نقل إلى (أخرى)",
                             command=lambda: self.demote_screen_to_more(name))
        else:
            menu.add_command(label="⤴️ نقل إلى القائمة الرئيسية",
                             command=lambda: self.promote_screen_to_main(name))
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()

    def sidebar_order(self):
        """ترتيب الشاشات في الشريط: المحفوظ إن وُجد، وإلا الافتراضي.

        يُصلَح تلقائياً لو أُضيفت أو حُذفت شاشة في نسخة أحدث.
        """
        default = [n for n, _i, _l in self.SIDEBAR_PRIMARY]
        try:
            saved = json.loads(self.get_setting("sidebar_order", "") or "[]")
        except Exception:
            saved = []
        known = {n for n, _i, _l in self.SIDEBAR_PRIMARY + self.SIDEBAR_SECONDARY}
        order = [n for n in saved if n in known]
        order += [n for n in default if n not in order]
        return order

    def save_sidebar_order(self, order):
        try:
            self.set_setting("sidebar_order", json.dumps(order, ensure_ascii=False))
        except Exception as e:
            log_cloud_error("تعذّر حفظ ترتيب الشريط الجانبي", e)

    def move_sidebar_item(self, name, direction):
        """يحرّك شاشة لأعلى أو لأسفل في الشريط الجانبي"""
        order = self.sidebar_order()
        if name not in order:
            order.insert(0, name)
        i = order.index(name)
        j = i + direction
        if 0 <= j < len(order):
            order[i], order[j] = order[j], order[i]
            self.save_sidebar_order(order)
            self.build_sidebar()

    def toggle_sidebar_arrange(self):
        """تشغيل/إيقاف وضع ترتيب الشريط: تظهر أسهم التحريك بجانب كل شاشة"""
        self._sidebar_arrange = not getattr(self, "_sidebar_arrange", False)
        self.build_sidebar()

    def build_sidebar(self):
        """يبني أزرار التنقّل: بطاقات بيضاء زجاجية بحواف زرقاء لامعة"""
        for w in self.sidebar.winfo_children():
            w.destroy()

        scale = self.ui_scale()
        btn_h = int(58 * scale)
        font_size = max(17, int(20 * scale))         # خط بارز يُقرأ من بعيد

        # رأس الشريط: شعار مصغّر واسم النظام
        head = ctk.CTkFrame(self.sidebar, fg_color="transparent")
        head.pack(fill="x", padx=10, pady=(14, 8))
        try:
            logo_img = Image.open(io.BytesIO(base64.b64decode(APP_LOGO_B64)))
            w0, h0 = logo_img.size
            dw = int(200 * scale)
            mini = crisp_ctk_image(logo_img, logo_img, (dw, max(1, round(dw * h0 / w0))), self)
            ctk.CTkLabel(head, image=mini, text="").pack()
        except Exception:
            ctk.CTkLabel(head, text="جاديت", font=("Cairo", 20, "bold"),
                         text_color="#d4af37").pack()

        ttk.Separator(self.sidebar, orient="horizontal").pack(fill="x", padx=12, pady=(4, 6))

        ctk.CTkLabel(self.sidebar, text="الشاشات الرئيسية", anchor="e", height=22,
                     font=ctk.CTkFont(family="Cairo", size=max(12, int(13 * scale)), weight="bold"),
                     text_color=UI["muted"]).pack(fill="x", padx=18, pady=(0, 2))

        nav = ctk.CTkScrollableFrame(self.sidebar, fg_color=("#ffffff", "#ffffff"))
        nav.pack(fill="both", expand=True, padx=6, pady=(0, 8))

        # حافة زرقاء ناعمة تلمع بالأزرق الكامل عند المرور، وخلفية زرقاء فاتحة
        edge = "#9DB9E6"
        edge_more = "#C3CAD4"
        shortcut_no = [0]
        self._sidebar_cards = []          # (البطاقة، لون حافتها) — للمعان عند الدخول

        def fitted_size(text, with_hint):
            """أكبر خط (حتى font_size) يُظهر اسم الشاشة كاملاً في عرض الشريط الحالي"""
            # المحجوز: الهوامش وشريط التمرير وحافة البطاقة وحشو الزر، وعمود الاختصار إن وُجد
            avail = self.sidebar_width() - 64 - (58 if with_hint else 0)
            try:
                import tkinter.font as tkfont
                for size in range(font_size, 12, -1):
                    if tkfont.Font(family="Cairo", size=-size, weight="bold").measure(text) <= avail:
                        return size
                return 13
            except Exception:
                return font_size

        def make_button(parent, name, icon, label, primary=True, in_main=True):
            label = self.get_screen_label(name, label)
            """بطاقة زجاجية: خلفية بيضاء وحافة زرقاء تلمع عند المرور"""
            card = ctk.CTkFrame(
                parent, corner_radius=12, border_width=1,
                border_color=edge if primary else edge_more,
                fg_color=("#ffffff", "#ffffff"), height=btn_h)
            card.pack(fill="x", pady=4, padx=2)
            card.pack_propagate(False)
            self._sidebar_cards.append((card, edge if primary else edge_more))

            widgets = [card]
            # اختصار لوحة المفاتيح لأول ست شاشات في الشريط (Ctrl+1 … Ctrl+6) —
            # في عمود مستقل يسار البطاقة فلا يغطي اسم الشاشة أبداً
            if in_main and shortcut_no[0] < 6:
                shortcut_no[0] += 1
                hint = ctk.CTkLabel(card, text=f"Ctrl+{shortcut_no[0]}", width=50, height=22,
                                    corner_radius=6, font=("Cairo", 11, "bold"),
                                    fg_color=(UI["surface_alt"], UI["surface_alt"]),
                                    text_color=(UI["muted"], UI["muted"]))
                hint.pack(side="left", padx=(8, 0))
                hint.bind("<Button-1>", lambda e, n=name: self.navigate_to_screen(n))
                widgets.append(hint)

            btn = ctk.CTkButton(
                card, text=f"{icon}  {label}", anchor="e",
                font=ctk.CTkFont(family="Cairo", size=fitted_size(f"{icon}  {label}", len(widgets) > 1),
                                 weight="bold"),
                fg_color="transparent", hover_color=(UI["primary_soft"], UI["primary_soft"]),
                text_color=(UI["ink"], UI["ink"]),
                corner_radius=10, height=btn_h - 6,
                command=lambda n=name: self.navigate_to_screen(n))
            btn.pack(side="right", fill="both", expand=True, padx=3, pady=3)
            widgets.append(btn)

            # لمعان الحافة عند المرور بالفأرة
            def glow(_e=None):
                card.configure(border_color=UI["primary"], fg_color=(UI["primary_soft"], UI["primary_soft"]))

            def unglow(_e=None):
                card.configure(border_color=edge if primary else edge_more,
                               fg_color=("#ffffff", "#ffffff"))

            for widget in widgets:
                widget.bind("<Enter>", glow, add="+")
                widget.bind("<Leave>", unglow, add="+")
                # الزر الأيمن: تعديل الاسم أو نقل الشاشة بين القائمتين
                widget.bind("<Button-3>",
                            lambda e, n=name, l=label, m=in_main:
                            self.show_screen_context_menu(e, n, l, m), add="+")
            return card

        registered = set(getattr(self.tabview, "_contents", {}).keys())
        meta = {n: (i, l) for n, i, l in self.SIDEBAR_PRIMARY + self.SIDEBAR_SECONDARY}
        arranging = getattr(self, "_sidebar_arrange", False)

        for name in self.sidebar_order():
            if name not in registered:
                continue
            icon, label = meta.get(name, ("📄", name))
            card = make_button(nav, name, icon, label, primary=True, in_main=True)
            if arranging:
                # أسهم التحريك تظهر في وضع الترتيب فقط، فلا تزحم الواجهة عادةً
                arrows = ctk.CTkFrame(card, fg_color="transparent")
                arrows.place(relx=0.02, rely=0.5, anchor="w")
                for txt_a, delta in (("▲", -1), ("▼", 1)):
                    ctk.CTkButton(arrows, text=txt_a, width=24, height=22,
                                  font=("Cairo", 11, "bold"), fg_color="#2e86de",
                                  hover_color="#1b5e91", corner_radius=6,
                                  command=lambda n=name, d=delta: self.move_sidebar_item(n, d)
                                  ).pack(side="left", padx=1)

        # زر (أخرى) يفتح باقي الشاشات أسفله
        self._sidebar_more_open = False
        more_holder = ctk.CTkFrame(nav, fg_color="transparent")

        def toggle_more():
            self._sidebar_more_open = not self._sidebar_more_open
            if self._sidebar_more_open:
                more_holder.pack(fill="x", pady=(2, 0))
                btn_more.configure(text="▴  أخرى")
            else:
                more_holder.pack_forget()
                btn_more.configure(text="▾  أخرى")

        more_card = ctk.CTkFrame(nav, corner_radius=12, border_width=1,
                                 border_color=UI["line"],
                                 fg_color=(UI["surface_alt"], UI["surface_alt"]), height=btn_h)
        more_card.pack(fill="x", pady=(10, 4), padx=2)
        more_card.pack_propagate(False)
        btn_more = ctk.CTkButton(
            more_card, text="▾  أخرى", anchor="e",
            font=ctk.CTkFont(family="Cairo", size=font_size, weight="bold"),
            fg_color="transparent", hover_color=(UI["secondary"], UI["secondary"]),
            text_color=(UI["ink"], UI["ink"]), corner_radius=10, height=btn_h - 6,
            command=toggle_more)
        btn_more.pack(fill="both", expand=True, padx=3, pady=3)

        more_holder.pack_forget()
        primary_names = set(self.sidebar_order())
        for name, icon, label in self.SIDEBAR_SECONDARY:
            if name in registered and name not in primary_names:
                make_button(more_holder, name, icon, label, primary=False, in_main=False)

        # زر ترتيب الشريط أسفله
        ctk.CTkButton(
            self.sidebar,
            text="✅ إنهاء الترتيب" if arranging else "↔️ ترتيب الشاشات",
            font=ctk.CTkFont(family="Cairo", size=max(12, int(13 * scale)), weight="bold"),
            fg_color=UI["success"] if arranging else "transparent",
            hover_color=UI["success_hover"] if arranging else UI["surface_alt"],
            text_color="#ffffff" if arranging else UI["ink"],
            border_width=0 if arranging else 1, border_color=UI["line"],
            height=int(38 * scale), corner_radius=10,
            command=self.toggle_sidebar_arrange).pack(fill="x", padx=10, pady=(0, 4))

        ctk.CTkLabel(self.sidebar, text="يمين الفأرة: تعديل/نقل  ·  Esc: الرئيسية  ·  F1: الاختصارات",
                     font=("Cairo", 10), text_color=UI["muted"], wraplength=max(120, self.sidebar_width() - 24),
                     justify="center").pack(pady=(0, 10))

    def create_layout(self):
        # الشريط الجانبي أولاً وبكامل ارتفاع النافذة (من أعلاها لأسفلها)،
        # ثم منطقة المحتوى يساره تضمّ الشريط العلوي والشاشات معاً.
        self.sidebar = ctk.CTkFrame(
            self, width=self.sidebar_width(), corner_radius=0,
            border_width=0, fg_color=("#ffffff", "#ffffff"))
        self.sidebar.pack(side="right", fill="y")
        self.sidebar.pack_propagate(False)

        self.content_area = ctk.CTkFrame(self, fg_color="transparent")
        self.content_area.pack(side="right", fill="both", expand=True)

        top_frame = ctk.CTkFrame(self.content_area, height=62, corner_radius=14, border_width=1,
                                 fg_color=(UI["surface"], "#171C23"), border_color=(UI["line"], "#2A313B"))
        top_frame.pack(fill="x", padx=10, pady=(8, 6))
        self.top_frame = top_frame

        treasury_display_frame = ctk.CTkFrame(top_frame, fg_color="transparent")
        treasury_display_frame.pack(side="right", padx=14, pady=4)

        # ====== شريط رصيد الخزينة ======
        treasury_bar = ctk.CTkFrame(treasury_display_frame, corner_radius=12,
                                     fg_color=(UI["gold_soft"], "#2a2318"), border_width=1,
                                     border_color=(UI["gold_line"], "#6B5A22"))
        treasury_bar.pack(fill="x", pady=(0, 4))

        self.lbl_live_treasury = ctk.CTkLabel(treasury_bar, text="رصيد الخزينة الحالي: 0.00 جم", font=ctk.CTkFont(family="Cairo", size=19, weight="bold"), text_color=TREASURY_BAR_TEXT)
        self.lbl_live_treasury.pack(padx=14, pady=3)

        # ====== شريط الرصيد الحالي (الخزينة + كل صناديق الخياس) ======
        # بلون هادئ محايد: الذهبي لشريط الخزينة وحده (لون الشعار)
        total_bar = ctk.CTkFrame(treasury_display_frame, corner_radius=12,
                                  fg_color=(UI["surface_alt"], "#1D232B"), border_width=1,
                                  border_color=(UI["line"], "#323B47"))
        total_bar.pack(fill="x", pady=(0, 6))

        self.lbl_total_gold = ctk.CTkLabel(total_bar, text="الرصيد الحالي: 0.00 جم", font=ctk.CTkFont(family="Cairo", size=19, weight="bold"), text_color=(UI["title"], "#C9D6E8"), cursor="hand2")
        self.lbl_total_gold.pack(padx=14, pady=3)
        self.lbl_total_gold.bind("<Button-1>", lambda e: self.show_gold_balance_breakdown())

        # أرصدة الفصوص والألماس تبقى محسوبة لكنها لا تُرصف: الشريط العلوي
        # يعرض الرصيدين الأساسيين فقط ليبقى منخفضاً ومريحاً للعين.
        # تفصيلها متاح بالضغط على (الرصيد الحالي).
        self.lbl_gems_stones_balance = ctk.CTkLabel(treasury_display_frame, text="", font=("Cairo", 11))
        self.lbl_diamond_balance = ctk.CTkLabel(treasury_display_frame, text="", font=("Cairo", 11))

        self.btn_theme = ctk.CTkButton(top_frame, text=self.THEME_LABELS.get(self.current_theme, "🎨 المظهر"), width=108, height=36, corner_radius=10, font=ctk.CTkFont(family="Cairo", size=12, weight="bold"), fg_color="transparent", border_width=1, border_color=(UI["line"], "#3A434F"), text_color=(UI["ink"], "#E6EDF3"), hover_color=(UI["surface_alt"], "#232A33"), command=self.toggle_theme)
        self.btn_theme.pack(side="right", padx=8, pady=6)

        btn_search_all = ctk.CTkButton(
            top_frame, text="🔍 بحث", width=86, height=36, corner_radius=10,
            font=ctk.CTkFont(family="Cairo", size=12, weight="bold"), fg_color="transparent",
            border_width=1, border_color=(UI["line"], "#3A434F"), text_color=(UI["ink"], "#E6EDF3"),
            hover_color=(UI["surface_alt"], "#232A33"), command=self.open_global_search)
        btn_search_all.pack(side="right", padx=4, pady=6)
        HoverTip(btn_search_all, "بحث شامل (Ctrl+F): حساب، رقم تشغيل، فاتورة مبيعات، رقم حركة")

        # تراجع عام عن آخر حذف أو إقفال (وCtrl+Z) — نسخة العميل وحدها تعدّل البيانات
        if not IS_ADMIN_BUILD:
            btn_global_undo = ctk.CTkButton(
                top_frame, text="↩️ تراجع", width=96, height=36, corner_radius=10,
                font=ctk.CTkFont(family="Cairo", size=12, weight="bold"), fg_color="transparent",
                border_width=1, border_color=(UI["line"], "#3A434F"), text_color=(UI["ink"], "#E6EDF3"),
                hover_color=(UI["surface_alt"], "#232A33"), command=self.undo_last_action)
            btn_global_undo.pack(side="right", padx=4, pady=6)
            self.register_undo_button(btn_global_undo, compact=True)
            HoverTip(btn_global_undo, "تراجع عن آخر حذف أو إقفال (Ctrl+Z) — آخر ٢٠ خطوة")

        # صف أدوات واحد: كل الأزرار جنباً إلى جنب أفقياً بلا تبعثر رأسي
        period_column = ctk.CTkFrame(top_frame, fg_color="transparent")
        period_column.pack(side="right", padx=8, pady=4)
        self.period_column = period_column

        period_frame = ctk.CTkFrame(period_column, fg_color="transparent")
        period_frame.pack(side="right")
        
        ctk.CTkLabel(period_frame, text="الفترة:", font=ctk.CTkFont(family="Cairo", size=16, weight="bold"), text_color=(UI["primary"], "#9CC0F5")).pack(side="right", padx=5)
        self.combo_active_period = ctk.CTkComboBox(period_frame, width=125, font=("Cairo", 16), command=self.on_period_changed)
        self.combo_active_period.pack(side="right", padx=5)
        
        btn_add_period = ctk.CTkButton(period_frame, text="➕ شهر جديد", width=110, height=40, font=ctk.CTkFont(family="Cairo", size=14, weight="bold"), fg_color="#1f77b4", hover_color="#144d75", command=self.add_new_period_ui)
        # نسخة المدير تتصفّح فترات العميل كما هي: فترة جديدة عندها لا تصل العميل ولا معنى لها
        if not IS_ADMIN_BUILD:
            btn_add_period.pack(side="right", padx=5)

        # قسم البحث المزدوج الجديد (بحث فاتورة + بحث رقم التشغيل)
        # أزرار البحث لا تُرصف: الشريط العلوي يعرض الرصيدين والفترة والمظهر
        # وتصفير البيانات فقط. البحث متاح من داخل الشاشات نفسها.
        search_container = ctk.CTkFrame(top_frame, fg_color="transparent")

        # صف 1: البحث وتعديل الفاتورة
        row1 = ctk.CTkFrame(search_container, fg_color="transparent")
        row1.pack(fill="x", pady=3)
        btn_search = ctk.CTkButton(row1, text="بحث عن فاتورة", font=ctk.CTkFont(family="Cairo", size=12, weight="bold"), width=112, height=30, corner_radius=8, command=self.search_invoice_window)
        btn_search.pack(side="left", padx=5)
        self.entry_search_inv = ctk.CTkEntry(row1, placeholder_text="رقم الفاتورة...", font=("Cairo", 14), justify="center", width=125, height=35)
        self.entry_search_inv.pack(side="left", padx=5)
        self.entry_search_inv.bind("<Return>", lambda e: self.search_invoice_window())
        # تحديد الشاشة التي تمت فيها الفاتورة (الأرقام قد تتكرر بين الشاشات)
        self.combo_search_source = ctk.CTkComboBox(row1, values=self.SEARCH_SOURCES, font=("Cairo", 13),
                                                    justify="right", width=145, height=35, state="readonly")
        self.combo_search_source.set("المبيعات/الصادر")
        self.combo_search_source.pack(side="left", padx=5)

        # صف 2: البحث برقم التشغيل الجديد
        row2 = ctk.CTkFrame(search_container, fg_color="transparent")
        row2.pack(fill="x", pady=3)
        btn_search_op = ctk.CTkButton(row2, text="بحث برقم التشغيل", font=ctk.CTkFont(family="Cairo", size=12, weight="bold"), width=124, height=30, corner_radius=8, fg_color="#b8860b", hover_color="#daa520", command=self.search_op_number_window)
        btn_search_op.pack(side="left", padx=5)
        self.entry_search_op = ctk.CTkEntry(row2, placeholder_text="رقم التشغيل...", font=("Cairo", 14), justify="center", width=140, height=35)
        self.entry_search_op.pack(side="left", padx=5)

        # زر التصفير يُنشأ داخل عمود الفترة مباشرة فيظهر فوق شريط الشهر
        # زر خطير: إطار أحمر فقط (لا زر ممتلئ بارز) حتى لا يُضغط سهواً
        btn_clear_system = ctk.CTkButton(self.period_column, text="⚠️ تصفير البيانات", font=ctk.CTkFont(family="Cairo", size=12, weight="bold"), width=132, height=34, corner_radius=10, fg_color="transparent", border_width=1, border_color=UI["danger"], text_color=UI["danger"], hover_color=(UI["danger_soft"], "#3A1C1E"), command=self.reset_system_data_action)
        # نسخة المدير مرآة لجهاز العميل: التصفير لا يمسّ إلا نسختها المؤقتة ويُربك، فلا يُعرض
        if not IS_ADMIN_BUILD:
            btn_clear_system.pack(side="right", padx=(6, 0))

        # ====== خانة حالة التعديل والمزامنة: في طرف الشريط العلوي داخل إطار مستقل واضح ======
        status_box = ctk.CTkFrame(top_frame, corner_radius=12, border_width=1,
                                  fg_color=(UI["surface_alt"], "#1D232B"), border_color=(UI["line"], "#2A313B"))
        # في نسخة المدير يأخذ مكانه أولاً: حالة نسخة العميل وزر «تحديث من العميل» يجب
        # أن يظهرا دائماً (كان يُزاح خارج الشريط على شاشة ١٣٦٦)
        status_box.pack(side="left", padx=12, pady=8,
                        **({"before": treasury_display_frame} if IS_ADMIN_BUILD else {}))

        self.lbl_edit_status = ctk.CTkLabel(status_box, text="", font=ctk.CTkFont(family="Cairo", size=13, weight="bold"), text_color="#2ecc71")
        self.lbl_edit_status.pack(padx=10, pady=(7, 0))

        self.lbl_cloud_sync = ctk.CTkLabel(status_box, text="☁️ المزامنة: —", font=ctk.CTkFont(family="Cairo", size=11), text_color=UI["muted"])
        self.lbl_cloud_sync.pack(padx=10)

        # تنبيه واضح لو كانت الفترة المعروضة ليست الشهر الحالي
        self.lbl_period_warning = ctk.CTkLabel(status_box, text="", font=ctk.CTkFont(family="Cairo", size=11, weight="bold"), text_color="#e67e22")
        self.lbl_period_warning.pack(padx=10)

        status_btns = ctk.CTkFrame(status_box, fg_color="transparent")
        status_btns.pack(padx=8, pady=(3, 7))
        if IS_ADMIN_BUILD and self.client_id:
            # المدير: تنزيل آخر نسخة من جهاز العميل فوراً (والتحديث التلقائي كل دقيقة)
            ctk.CTkButton(status_btns, text="📥 تحديث من العميل", font=("Cairo", 12, "bold"), width=125, height=28,
                          fg_color="#1e8449", hover_color="#145a32",
                          command=lambda: self.refresh_admin_mirror(manual=True)).pack(side="left", padx=3)
        else:
            ctk.CTkButton(status_btns, text="🔄 تحديث الصلاحية", font=("Cairo", 12, "bold"), width=125, height=28,
                          fg_color="#1f77b4", hover_color="#144d75", command=self.refresh_edit_permission_now).pack(side="left", padx=3)
        if not (IS_ADMIN_BUILD and self.client_id):
            # المدير يستبدله بـ«تحديث من العميل» (نسخه الاحتياطية نسخ لمرآة مؤقتة لا أكثر)
            ctk.CTkButton(status_btns, text="☁️ النسخ الاحتياطي", font=("Cairo", 12, "bold"), width=125, height=28,
                          fg_color="#555555", hover_color="#333333", command=self.open_backup_manager).pack(side="left", padx=3)

        self.main_shell = ctk.CTkFrame(self.content_area, fg_color="transparent")
        self.main_shell.pack(fill="both", expand=True, padx=10, pady=(0, 6))

        self.tabview = ScreenRouter(self.main_shell, go_home_callback=self.show_home_screen,
                                    meta=self.screen_meta_map())

        self.tabview.add("الحسابات")
        self.tabview.add("الرصيد الافتتاحي")
        self.tabview.add("الوارد")
        self.tabview.add("المبيعات")
        self.tabview.add("الموردين")
        self.tabview.add("مراحل التصنيع")
        self.tabview.add("صناديق الخياس")
        self.tabview.add("صناديق المصنع")
        self.tabview.add("كشف حساب")
        self.tabview.add("التقرير الشهري")
        self.tabview.add("أرشيف الفواتير")
        self.tabview.add("القيود اليومية")
        self.tabview.add("شاشة الخسائر")
        self.tabview.add("ربح/خسارة الطقم")
        self.tabview.add("لوحة المؤشرات")

        # ═══════════════════════════════════════════════════════════════
        #  بناء كسول للشاشات
        #
        #  كانت الشاشات الأربع عشرة تُبنى كلها عند التشغيل: آلاف الأدوات
        #  تُنشأ وتُرسم قبل ظهور النظام، فيبطؤ الفتح وتظهر الشاشات وهي
        #  «تتكوّن» أمام المستخدم.
        #
        #  الآن تُبنى كل شاشة **عند أول فتح لها فقط**، ثم تبقى جاهزة.
        #  فالتشغيل فوري، وفتح الشاشة أول مرة يستغرق جزءاً من الثانية.
        # ═══════════════════════════════════════════════════════════════
        self._screen_builders = {
            "الرصيد الافتتاحي": self.build_opening_tab,
            "الوارد":           self.build_inout_tab,
            "المبيعات":         self.build_sales_tab,
            "الموردين":         self.build_suppliers_tab,
            "مراحل التصنيع":    self.build_operations_tab,
            "صناديق الخياس":    self.build_inquiries_tab,
            "صناديق المصنع":    self.build_factory_boxes_tab,
            "كشف حساب":         self.build_account_statement_tab,
            "التقرير الشهري":   self.build_monthly_report_tab,
            "أرشيف الفواتير":   self.build_invoice_archive_tab,
            "القيود اليومية":   self.build_journal_entries_tab,
            "شاشة الخسائر":     self.build_losses_tab,
            "الحسابات":         self.build_chart_of_accounts_tab,
            "ربح/خسارة الطقم":  self.build_sets_profit_tab,
            "لوحة المؤشرات":    self.build_dashboard_tab,
        }
        self._built_screens = set()

        self.bind("<Escape>", self._on_escape_key, add="+")
        self.bind("<Control-KeyPress>", self._on_ctrl_number_key, add="+")
        self.bind_all("<F1>", lambda e: self.open_shortcuts_help(), add="+")

        self.ensure_default_khayas_boxes()
        self.remove_legacy_casting_box()
        self.build_gold_price_bar()
        if not IS_ADMIN_BUILD:
            self.build_scale_indicator()
        self.build_home_screen()
        self.show_home_screen()
        self.update_edit_status_ui()
        self.update_period_warning()
        self.watch_system_month()
        self.refresh_live_date_fields()

    # أرقام الصف العلوي للوحة المفاتيح: الإنجليزية والعربية الهندية معاً (أي تخطيط)
    _SHORTCUT_DIGITS = {"1": 0, "2": 1, "3": 2, "4": 3, "5": 4, "6": 5,
                        "١": 0, "٢": 1, "٣": 2, "٤": 3, "٥": 4, "٦": 5}

    def _on_escape_key(self, event=None):
        """Esc داخل أي شاشة يعود للقائمة الرئيسية (لا يمسّ النوافذ المنبثقة)"""
        tv = getattr(self, "tabview", None)
        if tv is not None and tv.winfo_ismapped():
            tv._go_home()

    def _on_ctrl_number_key(self, event):
        """Ctrl + رقم (١–٦) يفتح شاشة الشريط الرئيسية بنفس ترتيبها، وCtrl+Z للتراجع، وCtrl+B لتتبّع رقم تشغيل"""
        if (getattr(event, "keysym", "") in ("z", "Z")
                or (sys.platform.startswith("win") and getattr(event, "keycode", 0) == 90)):
            if not IS_ADMIN_BUILD:
                return self._on_ctrl_z(event)    # بأي لغة كتابة (المفتاح نفسه)
            return
        if (getattr(event, "keysym", "") in ("b", "B")
                or (sys.platform.startswith("win") and getattr(event, "keycode", 0) == 66)):
            self.open_set_number_trace()         # Ctrl+B: امسح باركود التذكرة لتتبّع رقمها
            return "break"
        if (getattr(event, "keysym", "") in ("f", "F")
                or (sys.platform.startswith("win") and getattr(event, "keycode", 0) == 70)):
            self.open_global_search()            # Ctrl+F: بحث شامل
            return "break"
        idx = self._SHORTCUT_DIGITS.get(getattr(event, "char", "") or "")
        if idx is None:
            idx = self._SHORTCUT_DIGITS.get(getattr(event, "keysym", ""))
        if idx is None and sys.platform.startswith("win") and 49 <= getattr(event, "keycode", 0) <= 54:
            idx = event.keycode - 49      # مفاتيح الأرقام نفسها في أي لغة كتابة
        if idx is None:
            return
        registered = set(getattr(self.tabview, "_contents", {}).keys())
        order = [n for n in self.sidebar_order() if n in registered]
        if idx < len(order):
            self.navigate_to_screen(order[idx])
            return "break"

    def build_gold_price_bar(self):
        """شريط سعر الذهب العالمي أسفل الشاشة — يتحدّث تلقائياً كل ١٠ ثوانٍ"""
        self.gold_watcher = None

        # شريط كحلي ليلي بأرقام فاتحة: أعلى تباين ممكن، وبلون هوية البرنامج
        self.gold_bar = ctk.CTkFrame(self, height=44, corner_radius=0,
                                      fg_color=(UI["midnight_2"], UI["midnight_2"]),
                                      border_width=0)
        # يُرصف قبل الشريط الجانبي ليمتدّ بعرض النافذة كاملاً أسفل الكل،
        # وإلا اقتصر على المنطقة اليسرى فقط
        if hasattr(self, "sidebar"):
            self.gold_bar.pack(side="bottom", fill="x", before=self.sidebar)
        else:
            self.gold_bar.pack(side="bottom", fill="x")

        self.lbl_gold_price = ctk.CTkLabel(
            self.gold_bar, text="🥇 جارٍ جلب سعر الذهب العالمي…",
            font=ctk.CTkFont(family="Cairo", size=16, weight="bold"),
            text_color="#F5F1E3")
        self.lbl_gold_price.pack(side="right", padx=16, pady=7)

        ctk.CTkButton(self.gold_bar, text="🔄 تحديث", width=80, height=28,
                      font=ctk.CTkFont(family="Cairo", size=13, weight="bold"),
                      fg_color="transparent", border_width=1, border_color="#3A4A66",
                      hover_color="#22304A", text_color="#E9C75C",
                      command=lambda: self.gold_watcher and self.gold_watcher.refresh_now()
                      ).pack(side="left", padx=10)

        if not GOLD_PRICE_AVAILABLE:
            self.lbl_gold_price.configure(text="🥇 سعر الذهب غير متاح (وحدة الأسعار غير موجودة)",
                                          text_color="#F5A35C")
            return

        try:
            self.gold_watcher = GoldPriceWatcher(on_update=self._on_gold_price)
            self.gold_watcher.start()
        except Exception as e:
            log_cloud_error("تعذّر تشغيل مراقب سعر الذهب", e)

    # ═══ إشعار عابر (toast): رسالة نجاح/تنبيه قصيرة لا توقف العمل ولا تحتاج «موافق» ═══
    TOAST_COLORS = {"info": ("#1E3A5F", "#FFFFFF"), "success": ("#1F6E4A", "#FFFFFF"),
                    "warn": ("#8A5A00", "#FFFFFF"), "error": ("#B4343C", "#FFFFFF")}

    def toast(self, text, kind="info", ms=2600, parent=None):
        """يعرض رسالة قصيرة أسفل النافذة (النشطة أو parent) ثم تختفي وحدها"""
        try:
            host = parent.winfo_toplevel() if parent is not None else self
            old = getattr(host, "_jade_toast", None)
            if old is not None:
                try:
                    old.destroy()
                except Exception:
                    pass
            bg, fg = self.TOAST_COLORS.get(kind, self.TOAST_COLORS["info"])
            frame = ctk.CTkFrame(host, fg_color=bg, corner_radius=12)
            ctk.CTkLabel(frame, text=text, text_color=fg, font=ctk.CTkFont(family="Cairo", size=14, weight="bold"),
                         wraplength=520).pack(padx=18, pady=8)
            frame.place(relx=0.5, rely=1.0, y=-64, anchor="s")
            frame.lift()
            host._jade_toast = frame
            host.after(ms, lambda: frame.winfo_exists() and frame.destroy())
            return frame
        except Exception:
            return None

    # ═══ الميزان الإلكتروني: F2 داخل خانة الوزن يكتب القراءة المستقرة ═══
    SCALE_PREF_KEYS = ("scale_enabled", "scale_port", "scale_baud", "scale_preset")

    def scale_settings(self):
        prefs = load_ui_prefs()
        preset = prefs.get("scale_preset")
        presets = scale_reader.PRESETS if SCALE_MODULE_AVAILABLE else {}
        return {"enabled": bool(prefs.get("scale_enabled", False)),
                "port": str(prefs.get("scale_port") or ""),
                "baud": int(prefs.get("scale_baud") or (scale_reader.DEFAULT_BAUD if SCALE_MODULE_AVAILABLE else 9600)),
                "preset": preset if preset in presets else (scale_reader.DEFAULT_PRESET if SCALE_MODULE_AVAILABLE else "")}

    def start_scale_reader(self):
        """يشغّل قارئ الميزان حسب إعداد هذا الجهاز (أو يوقفه إن عُطّل)"""
        old = getattr(self, "scale_reader", None)
        if old is not None:
            try:
                old.stop(timeout=0.5)
            except Exception:
                pass
        self.scale_reader = None
        conf = self.scale_settings()
        if not (SCALE_MODULE_AVAILABLE and conf["enabled"] and conf["port"]):
            return None
        self.scale_reader = scale_reader.ScaleReader(conf["port"], conf["baud"],
                                                     scale_reader.PRESETS.get(conf["preset"]))
        self.scale_reader.start()
        return self.scale_reader

    def build_scale_indicator(self):
        """مؤشر الميزان في الشريط السفلي (الضغط عليه يفتح الإعداد) و F2 في أي نافذة"""
        bar = getattr(self, "gold_bar", None)
        if bar is None:
            return
        self.lbl_scale = ctk.CTkLabel(bar, text="⚖️ الميزان", cursor="hand2",
                                      font=ctk.CTkFont(family="Cairo", size=13, weight="bold"),
                                      text_color="#C9D6E8")
        self.lbl_scale.pack(side="left", padx=(6, 8))
        self.lbl_scale.bind("<Button-1>", lambda e: self.open_scale_settings())
        HoverTip(self.lbl_scale, "الميزان الإلكتروني: اضغط للإعداد — وF2 داخل أي خانة وزن يكتب القراءة المستقرة")
        self.bind_all("<F2>", self._on_scale_key, add="+")
        self.start_scale_reader()
        self._scale_tick()

    def _scale_tick(self):
        """يحدّث مؤشر الميزان كل نصف ثانية من خيط الواجهة (القارئ لا يلمس الواجهة)"""
        lbl = getattr(self, "lbl_scale", None)
        try:
            if lbl is None or not lbl.winfo_exists():
                return
            reader = getattr(self, "scale_reader", None)
            lbl.configure(text=reader.status_text() if reader is not None else "⚖️ الميزان: غير مضبوط")
            self.after(500, self._scale_tick)
        except Exception:
            pass

    def _on_scale_key(self, event=None):
        widget = getattr(event, "widget", None) if event is not None else None
        try:
            focus = self.focus_get()
        except Exception:
            focus = None
        self.insert_scale_weight(focus if isinstance(focus, tk.Entry) else widget)
        return "break"

    def insert_scale_weight(self, entry=None, attempts=0):
        """يكتب وزن الميزان المستقر في الخانة؛ ينتظر الثبات حتى ٣ ثوانٍ ثم ينبّه"""
        reader = getattr(self, "scale_reader", None)
        if reader is None:
            self.toast("⚖️ الميزان غير مضبوط — اضغط مؤشر الميزان أسفل الشاشة لإعداده", "warn", parent=entry)
            return False
        if not isinstance(entry, tk.Entry):
            self.toast("ضع المؤشر في خانة الوزن ثم اضغط F2", "warn", parent=entry)
            return False
        r = reader.current()
        if r is None:
            self.toast("⚖️ لا توجد قراءة من الميزان — تأكد من توصيله وتشغيله", "error", parent=entry)
            return False
        if not r["stable"]:
            if attempts < 12:
                self.after(250, lambda: self.insert_scale_weight(entry, attempts + 1))
                return None
            self.toast("⚖️ القراءة غير مستقرة — انتظر ثبات الميزان ثم أعد F2", "warn", parent=entry)
            return False
        if r["grams"] < 0:
            self.toast("⚖️ الوزن سالب — أعد تصفير الميزان", "warn", parent=entry)
            return False
        entry.delete(0, "end")
        entry.insert(0, f"{r['grams']:.2f}")
        self.toast(f"⚖️ {r['grams']:.2f} جم من الميزان", "success", ms=1600, parent=entry)
        return True

    def open_scale_settings(self):
        """إعداد الميزان لهذا الجهاز: المنفذ، السرعة، نوع الميزان — مع قراءة حيّة للتجربة"""
        win = ctk.CTkToplevel(self)
        win.title("إعداد الميزان الإلكتروني")
        win.geometry("560x450")
        win.transient(self)
        win.focus_force()
        ctk.CTkLabel(win, text="⚖️ الميزان الإلكتروني", font=("Cairo", 19, "bold"), text_color=UI_TITLE).pack(pady=(14, 2))
        ctk.CTkLabel(win, text="وصّل الميزان بكابل RS-232 أو USB، واختر منفذه ونوعه.\n"
                               "بعدها: ضع المؤشر في أي خانة وزن واضغط F2 فيُكتب الوزن المستقر.",
                     font=("Cairo", 12), text_color=UI["muted"], justify="center").pack(pady=(0, 8))
        if not SCALE_MODULE_AVAILABLE or not scale_reader.SERIAL_AVAILABLE:
            ctk.CTkLabel(win, text="مكتبة الاتصال بالمنافذ (pyserial) غير مثبّتة في هذه النسخة.",
                         font=("Cairo", 13, "bold"), text_color=UI["danger"]).pack(pady=20)
            ctk.CTkButton(win, text="إغلاق", command=win.destroy, **BUTTON_STYLES["secondary"]).pack()
            return win
        conf = self.scale_settings()
        form = ctk.CTkFrame(win, fg_color="transparent")
        form.pack(pady=4)

        def row(label, widget_factory):
            r = ctk.CTkFrame(form, fg_color="transparent")
            r.pack(fill="x", pady=4)
            ctk.CTkLabel(r, text=label, font=("Cairo", 13, "bold"), width=120, anchor="e").pack(side="right", padx=6)
            w = widget_factory(r)
            w.pack(side="right", padx=6)
            return w

        ports = [p for p, _d in scale_reader.list_ports()]
        port_box = row("المنفذ:", lambda r: ctk.CTkComboBox(r, values=ports or [""], width=260, font=("Cairo", 13)))
        port_box.set(conf["port"] or (ports[0] if ports else ""))
        baud_box = row("السرعة:", lambda r: ctk.CTkOptionMenu(r, values=[str(b) for b in scale_reader.BAUD_RATES],
                                                              width=260, font=("Cairo", 13)))
        baud_box.set(str(conf["baud"]))
        preset_box = row("نوع الميزان:", lambda r: ctk.CTkOptionMenu(r, values=list(scale_reader.PRESETS),
                                                                     width=260, font=("Cairo", 13)))
        preset_box.set(conf["preset"])
        enabled = ctk.BooleanVar(value=conf["enabled"])
        ctk.CTkCheckBox(win, text="تفعيل الميزان على هذا الجهاز", variable=enabled,
                        font=("Cairo", 13, "bold")).pack(pady=6)
        live = ctk.CTkLabel(win, text="", font=("Cairo", 15, "bold"), corner_radius=10, height=44,
                            fg_color=(UI["surface_alt"], "#1D232B"))
        live.pack(fill="x", padx=24, pady=8)
        raw = ctk.CTkLabel(win, text="", font=("Cairo", 11), text_color=UI["muted"])
        raw.pack()

        def save():
            save_ui_pref("scale_enabled", bool(enabled.get()))
            save_ui_pref("scale_port", port_box.get().strip())
            save_ui_pref("scale_baud", int(baud_box.get()))
            save_ui_pref("scale_preset", preset_box.get())
            self.start_scale_reader()
            self.toast("✅ حُفظ إعداد الميزان" if enabled.get() else "أُوقف الميزان على هذا الجهاز", "success",
                       parent=win)

        def tick():
            if not win.winfo_exists():
                return
            reader = getattr(self, "scale_reader", None)
            if reader is None:
                live.configure(text="الميزان غير مفعّل — اختر المنفذ وفعّله ثم «حفظ وتشغيل»")
            else:
                r = reader.current()
                live.configure(text=(f"{r['grams']:.3f} جم  " + ("✓ مستقر" if r["stable"] else "… يتحرّك"))
                               if r else ("غير متصل: " + reader.error if reader.error else "بانتظار قراءة…"))
                raw.configure(text=f"آخر سطر من الميزان: {reader.last_raw}" if reader.last_raw else "")
            win.after(400, tick)

        btns = ctk.CTkFrame(win, fg_color="transparent")
        btns.pack(pady=10)
        ctk.CTkButton(btns, text="💾 حفظ وتشغيل", width=150, height=40, font=("Cairo", 14, "bold"),
                      command=save, **BUTTON_STYLES["primary"]).pack(side="left", padx=6)
        ctk.CTkButton(btns, text="إغلاق", width=110, height=40, font=("Cairo", 14, "bold"),
                      command=win.destroy, **BUTTON_STYLES["secondary"]).pack(side="left", padx=6)
        tick()
        return win

    # ═══ البحث الشامل (Ctrl+F): اسم حساب، رقم تشغيل، رقم فاتورة مبيعات، أو رقم حركة — ثم فتح ما وُجد ═══
    SEARCH_LIMIT = 60

    def global_search(self, query):
        """[(النوع، القيمة، التفاصيل، الإجراء)] — الأقرب أولاً في كل نوع"""
        q = (query or "").strip()
        if "|" in q or self._SCANNED_WEIGHT.match(q.rsplit(" ", 1)[-1] if " " in q else ""):
            q = self.scanned_set_number(q)  # مسح تذكرة المبيعات (QR أو الباركود بالوزن): رقم التشغيل وحده
        if len(q) < 1:
            return []
        out = []
        qn = self.normalize_set_number(q)
        # ١) الحسابات والأسماء
        for name in self.get_account_statement_options():
            if q in name:
                out.append(("حساب", name, "فتح كشف الحساب", lambda n=name: self.open_account_statement_for(n)))
        # ٢) أرقام التشغيل (بأي صيغة أرقام) — بلا القيود (JE-n)
        seen_sets, seen_sales = set(), set()
        for inv in self.invoices.values():
            if inv.get("settled_status") not in self.TRACE_STATUSES or inv.get("النوع") in self.JOURNAL_TYPES:
                continue
            sn = self.normalize_set_number(inv.get("set_number"))
            if sn and qn and qn in sn and sn not in seen_sets:
                seen_sets.add(sn)
                out.append(("رقم تشغيل", sn, f"{inv.get('الاسم', '')} — {self.inv_period(inv)}",
                            lambda x=sn: self.open_set_number_trace(x)))
            manual = (inv.get("رقم الفاتورة اليدوي") or "").strip()
            if manual and q in manual and inv.get("النوع") in self.SALE_TYPES:
                key = (manual, inv.get("التاريخ"), inv.get("الاسم"))
                if key not in seen_sales:
                    seen_sales.add(key)
                    out.append(("فاتورة مبيعات", manual, f"{inv.get('الاسم', '')} — {str(inv.get('التاريخ', ''))[:10]}",
                                lambda k=key: self.preview_invoice_groups(self.sale_invoice_groups(k))))
        # ٣) رقم حركة بعينه
        if q.isdigit() and int(q) in self.invoices:
            inv = self.invoices[int(q)]
            out.append(("حركة", q, f"{inv.get('الاسم', '')} — {inv.get('النوع', '')} — {float(inv.get('الوزن') or 0):.2f}",
                        lambda i=int(q): self.open_edit_invoice_ui(i)))
        # المطابق تماماً أولاً؛ وعند التساوي رقم التشغيل (مسح باركود التذكرة ثم Enter يفتح تتبّعه)
        rank = {"رقم تشغيل": 0, "فاتورة مبيعات": 1, "حركة": 2, "حساب": 3}
        out.sort(key=lambda r: (r[1] not in (q, qn), rank.get(r[0], 9), len(str(r[1])), str(r[1])))
        return out[:self.SEARCH_LIMIT]

    def open_account_statement_for(self, name):
        self.navigate_to_screen("كشف حساب")
        if hasattr(self, "kh_account_name"):
            self.kh_account_name.set(name)
            self.refresh_account_statement()

    def open_global_search(self, initial=""):
        win = getattr(self, "_search_win", None)
        if win is not None and win.winfo_exists():
            win.lift()
            win.focus_force()
            return win
        win = ctk.CTkToplevel(self)
        self._search_win = win
        win.title("بحث شامل")
        win.geometry("760x520")
        win.transient(self)
        ctk.CTkLabel(win, text="🔍 بحث شامل", font=("Cairo", 19, "bold"), text_color=UI_TITLE).pack(pady=(14, 2))
        ctk.CTkLabel(win, text="اسم حساب أو عامل أو مورد · رقم تشغيل (أو امسح باركوده) · رقم فاتورة مبيعات · رقم حركة",
                     font=("Cairo", 12), text_color=UI["muted"]).pack(pady=(0, 6))
        entry = ctk.CTkEntry(win, font=("Cairo", 16), height=42, justify="right", placeholder_text="اكتب للبحث…")
        entry.pack(fill="x", padx=18, pady=4)
        status = ctk.CTkLabel(win, text="", font=("Cairo", 12), text_color=UI["muted"])
        status.pack()
        frame = ttk.Frame(win)
        frame.pack(fill="both", expand=True, padx=18, pady=(4, 6))
        cols = ("النوع", "القيمة", "التفاصيل")
        tree = self.create_standard_treeview(frame, cols, height=12)
        for c, w in zip(cols, (130, 200, 360)):
            tree.column(c, width=w, anchor="center")
        state = {"rows": [], "job": None}

        def run():
            state["job"] = None
            rows = self.global_search(entry.get())
            state["rows"] = rows
            for i in tree.get_children():
                tree.delete(i)
            for n, (kind, value, detail, _a) in enumerate(rows):
                tree.insert("", "end", iid=str(n), values=(kind, value, detail))
            if rows:
                tree.selection_set("0")
            status.configure(text=(f"{len(rows)} نتيجة — Enter أو النقر المزدوج يفتح المحدد" if rows
                                   else ("لا نتائج" if entry.get().strip() else "")))

        def schedule(_e=None):
            if state["job"] is not None:
                win.after_cancel(state["job"])
            state["job"] = win.after(220, run)

        def activate(_e=None):
            sel = tree.selection()
            if state["job"] is not None:            # Enter مباشرة بعد المسح/الكتابة
                win.after_cancel(state["job"])
                run()
                sel = tree.selection()
            if sel and state["rows"]:
                action = state["rows"][int(sel[0])][3]
                win.destroy()
                action()
            return "break"

        entry.bind("<KeyRelease>", lambda e: None if e.keysym in ("Return", "Down", "Up") else schedule())
        entry.bind("<Return>", activate)
        entry.bind("<Down>", lambda e: (tree.focus_set(), tree.focus(tree.selection()[0] if tree.selection() else ""), "break")[2])
        tree.bind("<Double-1>", activate)
        tree.bind("<Return>", activate)
        win.bind("<Escape>", lambda e: win.destroy())
        if initial:
            entry.insert(0, initial)
            run()
        entry.focus_set()
        win.after(120, entry.focus_force)
        win._run_search, win._activate = run, activate       # للاختبار
        win._entry, win._tree = entry, tree
        return win

