    def refresh_sales_ops_table(self):
        if not hasattr(self, 'sales_ops_table_frame') or not self.sales_ops_table_frame:
            return

        # البيان بعد الاسم (بيان الفاتورة كما سُجّل في شاشة المبيعات)
        cols = ("رقم الفاتورة", "التاريخ", "الاسم", "البيان", "الذهب", "الفصوص", "الأحجار بعد الخصم",
                "الماس", "خياس", "عدد الأسطر")
        self.sales_ops_tree, _t, reused = self.reuse_or_create_tree(self.sales_ops_table_frame, cols, height=13)
        tree = self.sales_ops_tree
        tree.tag_configure("total_tag", foreground="#d4af37", font=("Cairo", 13, "bold"))
        if not reused:
            tree.bind("<Double-1>", lambda e: self.edit_selected_sale_invoice())

        self.sales_ops_map = {}
        tot = {k: 0.0 for k in ("ذهب", "فصوص", "أحجار بعد الخصم", "الماس", "خياس")}
        groups = self.get_sale_invoice_groups(self.current_display_month)

        for g in groups:
            for k in tot:
                tot[k] = round(tot[k] + g[k], 2)
            item = tree.insert("", "end", values=(
                g["manual_no"] or g["first_id"], g["date"], g["name"], g.get("البيان", "") or "-",
                f"{g['ذهب']:.2f}" if g["ذهب"] else "-",
                f"{g['فصوص']:.2f}" if g["فصوص"] else "-",
                f"{g['أحجار بعد الخصم']:.2f}" if g["أحجار بعد الخصم"] else "-",
                f"{g['الماس']:.2f}" if g["الماس"] else "-",
                f"{g['خياس']:.2f}" if g["خياس"] else "-",
                len(g["sets"]) or 1,
            ))
            self.sales_ops_map[item] = (g["manual_no"], g["date"], g["name"])

        if groups:
            tree.insert("", "end", values=(
                "إجمالي الشهر", "-", "-", "-", f"{tot['ذهب']:.2f}", f"{tot['فصوص']:.2f}",
                f"{tot['أحجار بعد الخصم']:.2f}", f"{tot['الماس']:.2f}", f"{tot['خياس']:.2f}", len(groups)
            ), tags=("total_tag",))

        # الأعمدة بعرض الجدول تماماً على أي شاشة (لا تجاوز ولا فراغ)
        self.apply_column_labels(tree, "sales_ops")
        self.fit_columns_to_content(tree, "sales_ops", min_width=50, max_width=220)
        self.enable_column_rename(tree, "sales_ops", on_renamed=self.refresh_sales_ops_table)

        if hasattr(self, 'lbl_sales_ops_totals'):
            self.lbl_sales_ops_totals.configure(
                text=(f"إجماليات الفترة ({self.current_display_month}) — الذهب: {tot['ذهب']:.2f}  |  "
                      f"الفصوص: {tot['فصوص']:.2f}  |  الأحجار بعد الخصم: {tot['أحجار بعد الخصم']:.2f}  |  "
                      f"الماس: {tot['الماس']:.2f}  |  الخياس: {tot['خياس']:.2f} جم"))

    def get_selected_sale_invoice_key(self, action="تعديل"):
        if not (hasattr(self, 'sales_ops_tree') and self.sales_ops_tree):
            return None
        sel = self.sales_ops_tree.selection()
        if not sel:
            messagebox.showwarning("تنبيه", f"الرجاء تحديد الفاتورة المراد {action}ها من الجدول أولاً.")
            return None
        key = self.sales_ops_map.get(sel[0])
        if not key:
            messagebox.showinfo("تنبيه", "هذا السطر إجمالي وليس فاتورة مستقلة.")
            return None
        return key

    def get_sale_invoice_records(self, key):
        """كل حركات فاتورة مبيعات واحدة حسب مفتاحها (رقم يدوي + تاريخ + اسم).

        تشمل السطور المعلوماتية ليُعاد بناؤها عند التعديل، ولتُحذف مع الفاتورة
        فلا تبقى سطور يتيمة بلا فاتورة."""
        manual_no, date_str, name = key
        recs = []
        for inv in self.invoices.values():
            if inv.get("settled_status") not in SALE_READ_STATUSES:
                continue
            t = inv.get("النوع")
            if t not in self.SALE_TYPES and t != "خياس طقوم":
                continue
            if (inv.get("رقم الفاتورة اليدوي", "") or "") != manual_no:
                continue
            if inv.get("التاريخ") != date_str or inv.get("الاسم") != name:
                continue
            recs.append(inv)
        return recs

    def sale_records_to_rows(self, recs):
        """يعيد بناء سطور الفاتورة (نفس شكل السطور المعلّقة) من الحركات المسجّلة"""
        rows = {}
        order = []
        for inv in sorted(recs, key=lambda x: x.get("رقم الفاتورة", 0)):
            set_num = inv.get("set_number", "") or ""
            if set_num not in rows:
                rows[set_num] = {"set_number": set_num, "row_number": inv.get("row_number", "") or "",
                                 "ذهب": 0.0, "فصوص": 0.0, "أحجار": 0.0, "أحجار بعد الخصم": 0.0,
                                 "الماس": 0.0, "خياس": 0.0, "خياس البوليش": 0.0,
                                 "خياس المركب": 0.0}
                order.append(set_num)
            r = rows[set_num]
            if not r["row_number"] and inv.get("row_number"):
                r["row_number"] = inv.get("row_number")
            t = inv.get("النوع")
            w = inv.get("الوزن", 0.0)
            if t in ("مبيعات ذهب", "مبيعات ذهب مع الماس"):
                r["ذهب"] = round(r["ذهب"] + w, 2)
            elif t == "مبيعات فصوص وأحجار":
                if inv.get("trees_count") == 3.0:
                    r["أحجار"] = round(r["أحجار"] + inv.get("قبل", 0.0), 2)
                    r["أحجار بعد الخصم"] = round(r["أحجار بعد الخصم"] + w, 2)
                else:
                    r["فصوص"] = round(r["فصوص"] + w, 2)
            elif t == "مبيعات الماس":
                r["الماس"] = round(r["الماس"] + w, 2)
            elif t == "خياس طقوم":
                mark = inv.get("trees_count", 0.0) or 0.0
                if mark == KHAYAS_MARK_NET:
                    continue      # سطر الصافي معلوماتي ويُعاد حسابه، فلا يُعاد تحميله
                if mark == KHAYAS_MARK_POLISH:
                    r["خياس البوليش"] = round(r["خياس البوليش"] + w, 2)
                elif mark == KHAYAS_MARK_ASSEMBLER:
                    r["خياس المركب"] = round(r["خياس المركب"] + w, 2)
                else:
                    r["خياس"] = round(r["خياس"] + w, 2)
        return [rows[s] for s in order]

    def post_sale_rows(self, rows, name, full_dt, manual_no, note="", period=None):
        """يسجّل سطور فاتورة مبيعات كحركات محاسبية (نفس منطق الترحيل الأصلي، مصدر واحد موحّد
        يستخدمه الترحيل الجديد وتعديل الفاتورة المرحّلة معاً). يرجع قائمة (رقم التشغيل، التاريخ، الاسم).

        note: بيان الفاتورة — يُلحق ببيان كل حركة بعد دورها (sale_bayan).
        period: فترة الفاتورة الأصلية عند تعديلها — تبقى فيها ولا تنتقل للفترة المعروضة
        (الترحيل الجديد بلا فترة يُختم بالفترة المعروضة كأي حركة)."""
        committed_groups = []

        def store(record):
            if period:
                record["period"] = period
            self.invoices[record["رقم الفاتورة"]] = record
            self.save_invoice_to_db(record["رقم الفاتورة"], record)
        for row in rows:
            gold_v = row.get("ذهب", 0.0)
            diamond_v = row.get("الماس", 0.0)
            gems_v = row.get("فصوص", 0.0)
            stones_raw_v = row.get("أحجار", 0.0)
            stones_discount_v = row.get("أحجار بعد الخصم", 0.0)
            set_num = row.get("set_number", "")
            row_num = row.get("row_number", "")
            khayas_v = row.get("خياس", 0.0)
            khayas_polish_v = row.get("خياس البوليش", 0.0)
            khayas_assembler_v = row.get("خياس المركب", 0.0)
            net_v = sale_net_weight(row)

            # إذا كان السطر يجمع ذهب وماس معاً، الذهب المرافق للماس يُسجَّل بنوع خاص
            gold_type = "مبيعات ذهب مع الماس" if (gold_v > 0 and diamond_v > 0) else "مبيعات ذهب"

            # "الأحجار" الخام لا تُعتمد كمبيعات؛ المعتمد محاسبياً هو "الأحجار بعد الخصم" فقط
            line_items = [
                (gold_v, gold_type, "مبيعات", 0.0, 0.0),
                (gems_v, "مبيعات فصوص وأحجار", "مبيعات", 0.0, 0.0),
                (stones_discount_v, "مبيعات فصوص وأحجار", "مبيعات", 3.0, stones_raw_v),
                (diamond_v, "مبيعات الماس", "مبيعات", 0.0, 0.0),
            ]
            for val, op_type, bayan, marker, raw_ref in line_items:
                if val > 0:
                    self.invoice_counter += 1
                    inv_data = {
                        "رقم الفاتورة": self.invoice_counter, "التاريخ": full_dt, "الاسم": name, "النوع": op_type,
                        "الوزن": val, "البيان": self.sale_bayan(bayan, note), "settled_status": "ACTIVE", "trees_count": marker,
                        "قبل": raw_ref, "بعد": 0.0, "set_number": set_num, "row_number": row_num,
                        "رقم الفاتورة اليدوي": manual_no
                    }
                    store(inv_data)

            # خياس البوليش: حالته MEMO فيُستثنى من الخزينة وكشفها ومن صندوق
            # خياس التلميع النهائي، ويبقى محفوظاً للعرض وإعادة البناء والقالب.
            if khayas_polish_v > 0:
                self.invoice_counter += 1
                polish_data = {
                    "رقم الفاتورة": self.invoice_counter, "التاريخ": full_dt, "الاسم": name,
                    "النوع": "خياس طقوم", "الوزن": khayas_polish_v, "البيان": self.sale_bayan("خياس بوليش", note),
                    "settled_status": MEMO_STATUS, "trees_count": KHAYAS_MARK_POLISH, "قبل": 0.0, "بعد": 0.0,
                    "set_number": set_num, "row_number": row_num, "رقم الفاتورة اليدوي": manual_no
                }
                store(polish_data)

            # خياس المركب: مصدره حركات المركبين في مراحل التصنيع وهو محمّل هناك
            # أصلاً على صندوق المركبين. يُسجَّل هنا بحالة MEMO لحفظه مع الفاتورة
            # وحساب الصافي — تحميله ثانيةً يعني احتساب الفاقد مرتين.
            if abs(khayas_assembler_v) > 0.0001:
                self.invoice_counter += 1
                asm_data = {
                    "رقم الفاتورة": self.invoice_counter, "التاريخ": full_dt, "الاسم": name,
                    "النوع": "خياس طقوم", "الوزن": khayas_assembler_v, "البيان": self.sale_bayan("خياس المركب", note),
                    "settled_status": MEMO_STATUS, "trees_count": KHAYAS_MARK_ASSEMBLER,
                    "قبل": 0.0, "بعد": 0.0,
                    "set_number": set_num, "row_number": row_num, "رقم الفاتورة اليدوي": manual_no
                }
                store(asm_data)

            # سطر الصافي: معلوماتي بحت بحالة MEMO — خارج كل حسابات الخزينة
            # والفواقد، ووظيفته الوحيدة عرض الصافي بلا إعادة حسابه من حركات متفرقة
            if abs(net_v) > 0.0001:
                self.invoice_counter += 1
                net_data = {
                    "رقم الفاتورة": self.invoice_counter, "التاريخ": full_dt, "الاسم": name,
                    "النوع": "خياس طقوم", "الوزن": net_v, "البيان": self.sale_bayan("صافي الطقم", note),
                    "settled_status": MEMO_STATUS, "trees_count": KHAYAS_MARK_NET, "قبل": 0.0, "بعد": 0.0,
                    "set_number": set_num, "row_number": row_num, "رقم الفاتورة اليدوي": manual_no
                }
                store(net_data)

            # خياس الطقم: لا يدخل ضمن أوزان الطقم المباعة، بل يُرحّل لصندوق (خياس الطقوم)
            if khayas_v > 0:
                self.invoice_counter += 1
                khayas_data = {
                    "رقم الفاتورة": self.invoice_counter, "التاريخ": full_dt, "الاسم": name,
                    # البيان يطابق اسم الصندوق ليظهر واضحاً في كشف حساب الخزينة
                    "النوع": "خياس طقوم", "الوزن": khayas_v,
                    "البيان": self.sale_bayan("خياس التلميع النهائي", note),
                    "settled_status": "ACTIVE", "trees_count": KHAYAS_MARK_FINAL, "قبل": 0.0, "بعد": 0.0,
                    "set_number": set_num, "row_number": row_num, "رقم الفاتورة اليدوي": manual_no
                }
                store(khayas_data)

            committed_groups.append((set_num, full_dt, name))
        return committed_groups

    def preview_selected_sale_invoice(self):
        key = self.get_selected_sale_invoice_key("معاينة")
        if not key:
            return
        recs = self.get_sale_invoice_records(key)
        if not recs:
            messagebox.showwarning("تنبيه", "لم يتم العثور على حركات هذه الفاتورة.")
            return
        self.preview_invoice_groups(self.sale_invoice_groups(key, recs))

    def sale_invoice_groups(self, key, recs=None):
        """مجموعات فاتورة مبيعات للطباعة: (رقم التشغيل، التاريخ، الاسم) لكل سطر بترتيب إدخاله"""
        _manual_no, date_str, name = key
        recs = self.get_sale_invoice_records(key) if recs is None else recs
        sets = []
        for r in sorted(recs, key=lambda x: x.get("رقم الفاتورة", 0)):
            sn = r.get("set_number", "") or ""
            if sn not in [g[0] for g in sets]:
                sets.append((sn, date_str, name))
        return sets

    def print_selected_sale_tickets(self):
        """تذاكر أرقام التشغيل وحدها لفاتورة محددة في «العمليات» (للطباعة على ورق الملصقات)"""
        key = self.get_selected_sale_invoice_key("طباعة تذاكر")
        if not key:
            return None
        return self.print_sale_tickets(self.sale_invoice_groups(key))

    def delete_selected_sale_invoice(self):
        """حذف فاتورة مبيعات مرحّلة بالكامل (كل سطورها وخياسها) مع إعادة حساب الخزينة وكل الحسابات"""
        key = self.get_selected_sale_invoice_key("حذف")
        if not key:
            return
        recs = self.get_sale_invoice_records(key)
        if not recs:
            return
        manual_no, date_str, name = key
        tot_w = round(sum(r.get("الوزن", 0.0) for r in recs), 2)
        if not messagebox.askyesno(
                "تأكيد حذف الفاتورة",
                f"سيتم حذف فاتورة المبيعات رقم ({manual_no or '-'}) للعميل ({name})\n"
                f"بتاريخ {date_str}، وعدد حركاتها {len(recs)} بإجمالي {tot_w:.2f} جم.\n\n"
                "سيتم إعادة حساب الخزينة وكل الحسابات المرتبطة تلقائياً. هل تريد المتابعة؟"):
            return

        blocked = False
        for r in list(recs):
            if not self.delete_invoice_from_db(r["رقم الفاتورة"]):
                blocked = True
        if blocked:
            return
        self.recalculate_all()
        self.refresh_sales_ops_table()
        messagebox.showinfo("تم الحذف", "تم حذف الفاتورة بالكامل وتحديث كل الأرصدة والحسابات.")

    def edit_selected_sale_invoice(self):
        key = self.get_selected_sale_invoice_key("تعديل")
        if key:
            self.open_sale_invoice_editor(key)

    def open_sale_invoice_editor(self, key):
        """نافذة تعديل فاتورة مبيعات مرحّلة: نفس خانات العمليات + جدول سطورها مع تعديل/حذف/إضافة سطر،
        وعند الحفظ تُعاد كتابة حركات الفاتورة بالكامل فتتحدث الخزينة وكل الحسابات محاسبياً."""
        if not self.check_edit_permission():
            return
        recs = self.get_sale_invoice_records(key)
        if not recs:
            messagebox.showwarning("تنبيه", "لم يتم العثور على حركات هذه الفاتورة.")
            return
        old_manual_no, old_date, old_name = key
        # الفاتورة تبقى في فترتها الأصلية بعد الحفظ، حتى لو فُتحت من البحث أو التدقيق
        # وأنت على فترة أخرى (كانت تُعاد كتابتها بالفترة المعروضة فتنتقل إليها)
        old_period = self.inv_period(min(recs, key=lambda x: x.get("رقم الفاتورة", 0)))
        edit_rows = self.sale_records_to_rows(recs)
        old_note = next((n for n in (self.sale_note_of(r.get("البيان")) for r in
                                     sorted(recs, key=lambda x: x.get("رقم الفاتورة", 0))) if n), "")

        win = ctk.CTkToplevel(self)
        win.title("تعديل فاتورة مبيعات مرحّلة")
        # بحجمها المريح ما دام يسع الشاشة، وإلا بحجم الشاشة (اللابتوب الصغير)
        self.fit_dialog_to_screen(win, 1180, 720)
        win.transient(self)
        win.grab_set()
        win.focus_force()

        ctk.CTkLabel(win, text="✏️ تعديل فاتورة مبيعات مرحّلة", font=("Cairo", 18, "bold"), text_color="#d4af37").pack(pady=(12, 6))

        head = ctk.CTkFrame(win)
        head.pack(fill="x", padx=18, pady=6)

        ctk.CTkLabel(head, text="رقم الفاتورة:", font=("Cairo", 14, "bold"), text_color="#1f77b4").pack(side="right", padx=(10, 4), pady=10)
        ent_manual = ctk.CTkEntry(head, justify="center", width=110, height=34)
        ent_manual.insert(0, old_manual_no)
        ent_manual.pack(side="right", padx=4, pady=10)

        ctk.CTkLabel(head, text="التاريخ:", font=("Cairo", 14, "bold"), text_color="#1f77b4").pack(side="right", padx=(10, 4), pady=10)
        ent_date = ctk.CTkEntry(head, justify="center", width=120, height=34)
        ent_date.insert(0, old_date[:10])
        ent_date.pack(side="right", padx=4, pady=10)

        ctk.CTkLabel(head, text="الاسم:", font=("Cairo", 14, "bold"), text_color="#1f77b4").pack(side="right", padx=(10, 4), pady=10)
        cmb_name = ctk.CTkComboBox(head, values=self.get_supplier_name_values_no_mustarja(), justify="right", width=190, height=34)
        cmb_name.set(old_name)
        cmb_name.pack(side="right", padx=4, pady=10)

        # البيان بعد الاسم — كما في شاشة المبيعات
        ctk.CTkLabel(head, text="البيان:", font=("Cairo", 14, "bold"), text_color="#1f77b4").pack(side="right", padx=(10, 4), pady=10)
        ent_note = ctk.CTkEntry(head, justify="right", height=34, placeholder_text="بيان الفاتورة...")
        if old_note:
            ent_note.insert(0, old_note)
        ent_note.pack(side="right", padx=(4, 10), pady=10, fill="x", expand=True)

        # خانات السطر بترتيب خانات شاشة المبيعات نفسه (الماس بعد الأحجار)، في شبكة
        # أعمدة متساوية تتمدّد وتنكمش مع عرض النافذة فلا تُقصّ على الشاشة الصغيرة
        fields_row = ctk.CTkFrame(win, corner_radius=10)
        fields_row.pack(fill="x", padx=18, pady=6)

        entries = {}
        field_defs = [("رقم الصف", "row_number"), ("رقم التشغيل", "set_number"), ("الذهب", "ذهب"),
                      ("الفصوص", "فصوص"), ("الأحجار", "أحجار"), ("الماس", "الماس"),
                      ("الأحجار بعد الخصم", "أحجار بعد الخصم"), ("خياس التلميع النهائي", "خياس"),
                      ("خياس البوليش", "خياس البوليش"), ("خياس المركب", "خياس المركب")]
        n_fields = len(field_defs)
        for c in range(n_fields):
            fields_row.grid_columnconfigure(c, weight=1, uniform="inv_edit_fields")
        for i, (label_text, key_name) in enumerate(field_defs):
            col = n_fields - 1 - i                  # من اليمين لليسار
            ctk.CTkLabel(fields_row, text=label_text, font=("Cairo", 13, "bold"), wraplength=110).grid(
                row=0, column=col, padx=4, pady=(8, 3), sticky="s")
            ent = ctk.CTkEntry(fields_row, justify="center", font=("Cairo", 14), width=60, height=32)
            ent.grid(row=1, column=col, padx=4, pady=(0, 10), sticky="ew")
            entries[key_name] = ent

        lbl_state = ctk.CTkLabel(win, text="", font=("Cairo", 13, "bold"), text_color="#f1c40f")
        lbl_state.pack(pady=(0, 2))
        # مصدر خياس المركب للسطر المحمّل، وتنبيه إن خالف المسجّلُ كشفَ المركبين
        lbl_asm = ctk.CTkLabel(win, text="", font=("Cairo", 12), text_color=(UI["muted"], "#9AA4B2"),
                               wraplength=1000, justify="right")
        lbl_asm.pack(padx=18, pady=(0, 2))
        asm_state = {"set": ""}       # آخر رقم تشغيل جُلب له خياس المركب في هذه النافذة

        def fetch_assembler(event=None):
            """رقم تشغيل جديد/معدَّل ← خياس المركب من كشف المركبين (كما في شاشة المبيعات)"""
            set_no = self.normalize_set_number(entries["set_number"].get())
            if set_no == asm_state["set"]:
                return
            asm_state["set"] = set_no
            try:
                details = self.get_assembler_khayas_details(set_no)
                entries["خياس المركب"].delete(0, "end")
                if abs(details[0]) > 0.0001:
                    entries["خياس المركب"].insert(0, f"{details[0]:g}")
                lbl_asm.configure(text=self.describe_assembler_khayas(set_no, details),
                                  text_color=(UI["muted"], "#9AA4B2"))
            except Exception as e:
                log_cloud_error("تعذّر جلب خياس المركب في نافذة تعديل الفاتورة", e)

        def check_loaded_assembler(r):
            """سطر محمّل للتعديل: يقارن خياس المركب المسجّل بقيمته الصحيحة الآن"""
            set_no = self.normalize_set_number(r.get("set_number"))
            asm_state["set"] = set_no
            if not set_no:
                lbl_asm.configure(text="")
                return
            details = self.get_assembler_khayas_details(set_no)
            correct, stored = details[0], round(r.get("خياس المركب", 0.0) or 0.0, 2)
            source = self.describe_assembler_khayas(set_no, details)
            # المطابق بلون هادئ، والمخالف بالأحمر (اللون المحجوز للأخطاء) ليُرى فوراً
            calm, alert = (UI["muted"], "#9AA4B2"), (UI["danger"], "#F08A8F")
            if abs(stored - correct) <= 0.005:
                lbl_asm.configure(text="✔ " + source, text_color=calm)
            elif correct > 0:
                entries["خياس المركب"].delete(0, "end")
                entries["خياس المركب"].insert(0, f"{correct:g}")
                lbl_asm.configure(text=(f"⚠️ خياس المركب المسجّل {stored:.2f} والصحيح من كشف المركبين {correct:.2f} — "
                                        f"وُضع الصحيح في الخانة: اضغط (حفظ السطر) ثم (حفظ تعديلات الفاتورة)\n{source}"),
                                  text_color=alert)
            else:
                lbl_asm.configure(text=(f"⚠️ خياس المركب المسجّل {stored:.2f} لكن {source} — راجع الرقم "
                                        "قبل الحفظ"), text_color=alert)

        entries["set_number"].bind("<FocusOut>", fetch_assembler, add="+")

        btns_row = ctk.CTkFrame(win, fg_color="transparent")
        btns_row.pack(fill="x", padx=18, pady=(2, 4))

        table_frame = ttk.Frame(win)
        table_frame.pack(fill="both", expand=True, padx=18, pady=(4, 4))

        cols = ("رقم الصف", "رقم التشغيل", "الذهب", "الفصوص", "الأحجار", "الأحجار بعد الخصم",
                "الماس", "خياس التلميع النهائي", "خياس البوليش", "الصافي")
        rows_tree = self.create_standard_treeview(table_frame, cols, height=9)
        rows_tree.tag_configure("total_tag", foreground="#d4af37", font=("Cairo", 13, "bold"))

        selected_idx = {"i": None}

        def read_fields():
            vals = {"set_number": entries["set_number"].get().strip(),
                    "row_number": entries["row_number"].get().strip()}
            for k in ("ذهب", "فصوص", "أحجار", "أحجار بعد الخصم", "الماس", "خياس",
                      "خياس البوليش", "خياس المركب"):
                txt = entries[k].get().strip()
                try:
                    v = round(float(txt), 2) if txt else 0.0
                except ValueError:
                    messagebox.showerror("خطأ", f"القيمة المدخلة في خانة ({k}) ليست رقماً صحيحاً.", parent=win)
                    return None
                if v < 0:
                    messagebox.showerror("خطأ", "لا يمكن إدخال أوزان بالسالب.", parent=win)
                    return None
                vals[k] = v
            if (vals["ذهب"] <= 0 and vals["فصوص"] <= 0 and vals["أحجار بعد الخصم"] <= 0
                    and vals["الماس"] <= 0 and vals["خياس"] <= 0 and vals["خياس البوليش"] <= 0):
                messagebox.showwarning("تنبيه", "لا بد من قيمة واحدة على الأقل (ذهب/فصوص/أحجار/ماس/خياس).", parent=win)
                return None
            return vals

        def clear_fields():
            for ent in entries.values():
                ent.delete(0, 'end')
            selected_idx["i"] = None
            lbl_state.configure(text="")
            lbl_asm.configure(text="")
            asm_state["set"] = ""

        def refresh_rows_tree():
            for item in rows_tree.get_children():
                rows_tree.delete(item)
            tot = {k: 0.0 for k in ("ذهب", "فصوص", "أحجار", "أحجار بعد الخصم", "الماس",
                                    "خياس", "خياس البوليش")}
            tot_net = 0.0
            for r in edit_rows:
                for k in tot:
                    tot[k] = round(tot[k] + r.get(k, 0.0), 2)
                net_r = sale_net_weight(r)
                tot_net = round(tot_net + net_r, 2)
                rows_tree.insert("", "end", values=(
                    r.get("row_number", "") or "-", r.get("set_number", "") or "-",
                    f"{r.get('ذهب', 0):.2f}" if r.get("ذهب") else "-",
                    f"{r.get('فصوص', 0):.2f}" if r.get("فصوص") else "-",
                    f"{r.get('أحجار', 0):.2f}" if r.get("أحجار") else "-",
                    f"{r.get('أحجار بعد الخصم', 0):.2f}" if r.get("أحجار بعد الخصم") else "-",
                    f"{r.get('الماس', 0):.2f}" if r.get("الماس") else "-",
                    f"{r.get('خياس', 0):.2f}" if r.get("خياس") else "-",
                    f"{r.get('خياس البوليش', 0):.2f}" if r.get("خياس البوليش") else "-",
                    f"{net_r:.2f}",
                ))
            if edit_rows:
                rows_tree.insert("", "end", values=(
                    "الإجمالي", "-", f"{tot['ذهب']:.2f}", f"{tot['فصوص']:.2f}", f"{tot['أحجار']:.2f}",
                    f"{tot['أحجار بعد الخصم']:.2f}", f"{tot['الماس']:.2f}", f"{tot['خياس']:.2f}",
                    f"{tot['خياس البوليش']:.2f}", f"{tot_net:.2f}"), tags=("total_tag",))
            # أعمدة الجدول بعرض النافذة تماماً (لا تجاوز ولا فراغ)
            self.fit_columns_to_content(rows_tree, "sale_invoice_editor", min_width=50, max_width=170)

        def get_sel_index():
            sel = rows_tree.selection()
            if not sel:
                messagebox.showwarning("تنبيه", "الرجاء تحديد السطر من الجدول أولاً.", parent=win)
                return None
            idx = rows_tree.get_children().index(sel[0])
            if not (0 <= idx < len(edit_rows)):
                messagebox.showinfo("تنبيه", "هذا السطر إجمالي وليس سطر فاتورة.", parent=win)
                return None
            return idx

        def load_row_to_fields():
            idx = get_sel_index()
            if idx is None:
                return
            r = edit_rows[idx]
            for k, ent in entries.items():
                ent.delete(0, 'end')
                val = r.get(k, "")
                ent.insert(0, str(val) if k in ("set_number", "row_number") else (f"{val:g}" if val else ""))
            selected_idx["i"] = idx
            lbl_state.configure(text=f"✏️ يتم الآن تعديل السطر رقم ({idx + 1}) — اضغط (حفظ السطر) بعد التعديل")
            check_loaded_assembler(r)

        def save_row():
            vals = read_fields()
            if vals is None:
                return
            if self.check_sale_row_duplicate(edit_rows, vals["row_number"], vals["set_number"],
                                             skip_index=selected_idx["i"], parent=win):
                return
            if selected_idx["i"] is None:
                edit_rows.append(vals)
            else:
                edit_rows[selected_idx["i"]] = vals
            clear_fields()
            refresh_rows_tree()
            return True

        def delete_row():
            idx = get_sel_index()
            if idx is None:
                return
            if not messagebox.askyesno("تأكيد", "هل تريد حذف هذا السطر من الفاتورة؟", parent=win):
                return
            del edit_rows[idx]
            clear_fields()
            refresh_rows_tree()

        ctk.CTkButton(btns_row, text="💾 حفظ السطر (إضافة/تعديل)", font=("Cairo", 13, "bold"), width=205, height=34,
                      fg_color="#1e8449", hover_color="#145a32", command=save_row).pack(side="right", padx=5)
        ctk.CTkButton(btns_row, text="✏️ تحميل السطر المحدد للتعديل", font=("Cairo", 13, "bold"), width=215, height=34,
                      fg_color="#b8860b", hover_color="#daa520", command=load_row_to_fields).pack(side="right", padx=5)
        ctk.CTkButton(btns_row, text="🗑️ حذف السطر المحدد", font=("Cairo", 13, "bold"), width=175, height=34,
                      fg_color="#8b0000", hover_color="#a52a2a", command=delete_row).pack(side="right", padx=5)
        ctk.CTkButton(btns_row, text="🧹 تفريغ الخانات", font=("Cairo", 13, "bold"), width=140, height=34,
                      fg_color="#555555", hover_color="#333333", command=clear_fields).pack(side="right", padx=5)

        rows_tree.bind("<Double-1>", lambda e: load_row_to_fields())
        refresh_rows_tree()

        # التنقل: Enter للخانة التالية (وفي آخر خانة يُحفظ السطر ويعود التركيز لأول
        # خانة لسطر جديد)، والأسهم يمين/يسار بين الخانات — من رقم الفاتورة حتى آخر خانة
        def save_row_and_continue():
            if save_row():
                try:
                    entries["row_number"].focus_set()
                except Exception:
                    pass

        nav = [ent_manual, ent_date, cmb_name, ent_note] + [entries[k] for _l, k in field_defs]
        self.bind_enter_navigation(nav, on_last=save_row_and_continue)
        self.bind_arrow_navigation(nav)
        win.bind("<Escape>", lambda e: win.destroy())
        win.after(120, lambda: entries["row_number"].focus_set())

        def save_invoice_changes():
            new_manual = ent_manual.get().strip()
            new_date = ent_date.get().strip()
            new_name = cmb_name.get().strip()
            if not new_manual:
                messagebox.showwarning("تنبيه", "رقم الفاتورة مطلوب.", parent=win)
                return
            if len(new_date) < 10 or new_date[4] != '-':
                messagebox.showerror("خطأ", "الرجاء إدخال التاريخ بالصيغة الصحيحة YYYY-MM-DD.", parent=win)
                return
            if not new_name or new_name not in self.get_supplier_name_values_no_mustarja():
                messagebox.showwarning("تنبيه", "الرجاء اختيار اسم من الموردين المسجلين.", parent=win)
                return
            if not edit_rows:
                messagebox.showwarning("تنبيه", "لا توجد سطور في الفاتورة.\nلحذف الفاتورة بالكامل استخدم زر (حذف الفاتورة) من جدول العمليات.", parent=win)
                return
            if not messagebox.askyesno(
                    "تأكيد الحفظ",
                    f"سيتم إعادة تسجيل الفاتورة بـ {len(edit_rows)} سطر/أسطر،\n"
                    "وسيتم تحديث الخزينة وصندوق خياس الطقوم وكل الحسابات المرتبطة تلقائياً.\n\nهل تريد المتابعة؟", parent=win):
                return

            # وقت الفاتورة يبقى كما هو ما دام اليوم لم يتغيّر، حتى لا يتغيّر ترتيبها المحاسبي بلا داعٍ
            old_time = old_date[11:] if len(old_date) > 11 else datetime.datetime.now().strftime('%H:%M:%S')
            new_full_dt = f"{new_date} {old_time}" if new_date == old_date[:10] else f"{new_date} {datetime.datetime.now().strftime('%H:%M:%S')}"

            # حذف الحركات القديمة ثم إعادة كتابتها بالكامل — يضمن تطابق الحسابات مع الفاتورة بعد التعديل
            for r in list(self.get_sale_invoice_records(key)):
                if not self.delete_invoice_from_db(r["رقم الفاتورة"]):
                    messagebox.showerror("تعذّر الحفظ", "تم منع حذف إحدى الحركات القديمة، وأُلغي التعديل حفاظاً على سلامة الحسابات.", parent=win)
                    self.recalculate_all()
                    return

            self.post_sale_rows(edit_rows, new_name, new_full_dt, new_manual, ent_note.get().strip(),
                                period=old_period)

            self.register_operation_period(new_date)
            self.recalculate_all()
            self.refresh_sales_ops_table()
            win.destroy()
            messagebox.showinfo("تم", "تم حفظ تعديلات الفاتورة وتحديث الخزينة وكل الحسابات المرتبطة.")

        btn_save_inv = ctk.CTkButton(win, text="✅ حفظ تعديلات الفاتورة", font=("Cairo", 16, "bold"), height=44,
                                     width=280, fg_color="#144d75", hover_color="#0d3350", command=save_invoice_changes)
        # يُحجز مكانه أسفل النافذة قبل الجدول، فلا يدفعه الجدول خارجها على الشاشة القصيرة
        btn_save_inv.pack(side="bottom", pady=10, before=table_frame)
        self.apply_edit_lock_to_button(btn_save_inv, win)

    def remember_discount_pct(self):
        """يحفظ النسبة الظاهرة في خانة نسبة الخصم إن كانت رقماً صحيحاً (مكتوبة أو مختارة)"""
        if not hasattr(self, "sale_discount_pct"):
            return
        text = self.sale_discount_pct.get().strip().replace("%", "").strip()
        try:
            value = float(text)
        except ValueError:
            return
        if not (0 <= value <= 100):
            return
        text = f"{value:g}"
        if text != str(self.get_last_discount_percentage()):
            self.set_last_discount_percentage(text)
        if hasattr(self, '_auto_compute_stones_discount'):
            self._auto_compute_stones_discount()

    def on_discount_pct_change(self):
        """عند تغيير نسبة الخصم المختارة: يُعاد حساب الأحجار بعد الخصم فوراً، وتُحفظ النسبة كآخر نسبة مستخدمة"""
        pct_text = self.sale_discount_pct.get().strip().replace("%", "")
        self.set_last_discount_percentage(pct_text)
        if hasattr(self, '_auto_compute_stones_discount'):
            self._auto_compute_stones_discount()

    def open_add_discount_pct_dialog(self):
        win = ctk.CTkToplevel(self)
        win.title("إضافة نسبة خصم جديدة")
        win.geometry("360x200")
        win.transient(self)
        win.grab_set()
        win.focus_force()

        ctk.CTkLabel(win, text="➕ إضافة نسبة خصم جديدة", font=("Cairo", 15, "bold"), text_color="#d4af37").pack(pady=(20, 10))
        ctk.CTkLabel(win, text="النسبة (%):", font=("Cairo", 13, "bold"), text_color="#1f77b4").pack(pady=(5, 3))
        entry = ctk.CTkEntry(win, font=("Cairo", 14), justify="center", width=140, height=38)
        entry.pack(pady=5)
        entry.focus_set()

        lbl_status = ctk.CTkLabel(win, text="", font=("Cairo", 12, "bold"), text_color="#e74c3c")
        lbl_status.pack(pady=3)

        def do_add():
            val = entry.get().strip()
            try:
                pct_num = float(val)
                if pct_num <= 0 or pct_num > 100:
                    raise ValueError
            except ValueError:
                lbl_status.configure(text="الرجاء إدخال نسبة صحيحة بين 0 و100.")
                return
            pct_str = str(pct_num) if pct_num % 1 else str(int(pct_num))
            self.add_discount_percentage(pct_str)
            self.sale_discount_pct.configure(values=[f"{p}%" for p in self.get_discount_percentages()])
            self.sale_discount_pct.set(f"{pct_str}%")
            self.on_discount_pct_change()
            win.destroy()

        entry.bind("<Return>", lambda e: do_add())
        ctk.CTkButton(win, text="✅ إضافة", font=("Cairo", 14, "bold"), fg_color="#1e8449", hover_color="#145a32", width=140, height=38, command=do_add).pack(pady=15)

    # أرقام هندية/فارسية ← أرقام لاتينية: «٧٠٠٣» و«7003» رقم تشغيل واحد
    _SET_DIGITS = str.maketrans("٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹", "01234567890123456789")
    # حالات قبوض المركبين التي يُقرأ منها خياس المركب: ما يُحتسب في الأرصدة، وما
    # أُقفل بالأرشفة القديمة (SETTLED) — الإقفال لا يُلغي ذهباً قُبض فعلاً على رقم
    # التشغيل. السطور المعلوماتية (MEMO) مستثناة
    ASSEMBLER_KHAYAS_STATUSES = ("ACTIVE", "SETTLED_INOUT", "SETTLED")

    @classmethod
    def normalize_set_number(cls, text):
        """رقم التشغيل بصيغة واحدة للمقارنة: بلا فراغات زائدة وبأرقام لاتينية."""
        return " ".join(str(text or "").translate(cls._SET_DIGITS).split())

    _SCANNED_WEIGHT = re.compile(r"^-?\d+\.\d{2}$")      # الوزن المقيد في الباركود: رقمان عشريان

    @classmethod
    def scanned_set_number(cls, text):
        """رقم التشغيل من نص المسح:
          • باركود تذكرة التشغيل: الرقم وحده.
          • الباركود الخطي لتذكرة المبيعات: «الرقم الوزن» أو «الرقم⇥الوزن» — يُحذف الوزن المقيد.
          • رمز QR تذكرة المبيعات: «رقم التشغيل: … | الوزن المقيد: …» فيؤخذ الرقم من أوله — ولو ضاعت
            الحروف العربية في قارئ يكتب بلوحة مفاتيح إنجليزية يبقى الرقم بعد النقطتين (أو آخر كلمة قبل |)."""
        text = str(text or "")
        if "|" in text:
            head = text.split("|", 1)[0]
            text = head.rsplit(":", 1)[-1] if ":" in head else (head.split() or [""])[-1]
        elif "\t" in text:                  # الباركود الخطي بخانتين: الرقم ثم Tab ثم الوزن
            text = text.split("\t", 1)[0]
        else:                                # الباركود الخطي بخانة واحدة: «الرقم الوزن»
            parts = cls.normalize_set_number(text).rsplit(" ", 1)
            if len(parts) == 2 and cls._SCANNED_WEIGHT.match(parts[1]):
                text = parts[0]
        return cls.normalize_set_number(text)

    def get_assembler_khayas_for_set(self, set_number, month=None):
        """قيمة عمود (مسموح/٨) لرقم تشغيل معيّن، من قسم **المركبين** حصراً.

        تُحاكي هذه الدالة كشف مراحل التصنيع خطوةً بخطوة حتى يتطابق الرقم معه
        حرفياً:
          ١) تُجمَّع حركات كل عامل مركّب في صفوف حسب (الفترة، رقم الصف) — نفس
             تجميع الكشف، فالكشف يعرض فترة واحدة ورقم الصف يتكرّر بين الفترات.
          ٢) رقم تشغيل الصف = **أول رقم غير فارغ** في حركاته بترتيب التاريخ، وهو
             بالضبط ما يعرضه الكشف في عمود رقم التشغيل.
          ٣) الصفوف التي رقم تشغيلها = المطلوب فقط تدخل الحساب.
          ٤) مسموح/٨ لكل صف = قبض الذهب × ٨ بالألف مقرّباً كما يظهر في عموده،
             والنتيجة مجموع قيم العمود للصفوف المطابقة.

        أسباب الأرقام الخاطئة سابقاً:
          • قسم المصنعين كان يدخل الحساب، وحركات الصف بأرقام تشغيل أخرى.
          • التجميع كان بـ(العامل، رقم الصف) عبر **كل** الفترات: الصف ١ في أغسطس
            والصف ١ في سبتمبر صارا صفاً واحداً — فرقم أحدهما يجلب مجموع الشهرين،
            ورقم الآخر لا يُجلب إطلاقاً (صفر).
          • «٧٠٠٣» بأرقام هندية لم تطابق «7003»، وصفوف الإقفال القديم كانت تُهمَل.

        البحث يشمل كل الفترات (رقم التشغيل فريد عبر الزمن)، ما لم يُمرَّر شهر.
        """
        return self.get_assembler_khayas_details(set_number, month)[0]

    def get_assembler_khayas_details(self, set_number, month=None):
        """(خياس المركب، الصفوف التي جاء منها) — كل صف: العامل والفترة ورقم الصف
        والقبض ومسموح/٨ كما في كشف المركبين، ليرى المستخدم مصدر الرقم بعينه."""
        set_number = self.normalize_set_number(set_number)
        if not set_number:
            return 0.0, []
        return self.assembler_khayas_index(month).get(set_number, (0.0, []))

    def assembler_khayas_index(self, month=None):
        """كل أرقام التشغيل في كشف المركبين ← (خياس المركب، صفوفه) بمسحٍ واحد للحركات.
        يستخدمه البحث عن رقم واحد، وتدقيق كل فواتير المبيعات دفعةً واحدة."""
        assemblers = set(self.categories.get("المركبين", []))
        if not assemblers:
            return {}

        # (١) تجميع حركات المركبين في صفوف: (العامل، الفترة، رقم الصف) بترتيب التاريخ
        rows = [inv for inv in self.invoices.values()
                if inv.get("settled_status") in self.ASSEMBLER_KHAYAS_STATUSES
                and inv.get("الاسم") in assemblers
                and (not month or self.inv_in_period(inv, month))]
        rows.sort(key=lambda x: (str(x.get("التاريخ", "")), x.get("رقم الفاتورة", 0) or 0))
        groups = {}
        for inv in rows:
            key = (inv.get("الاسم"), self.inv_period(inv), (inv.get("row_number", "") or "").strip())
            g = groups.setdefault(key, {"set_number": "", "قبض": 0.0})

            # (٢) أول رقم تشغيل غير فارغ هو رقم الصف — كما في الكشف تماماً
            if not g["set_number"]:
                g["set_number"] = self.normalize_set_number(inv.get("set_number", ""))

            if inv.get("النوع") == "قبض ذهب":
                g["قبض"] += inv.get("الوزن", 0.0) or 0.0

        # (٣) و(٤) كل رقم تشغيل ← صفوفه، ومسموح/٨ لكل صف كما يظهر في عموده
        index = {}
        for (name, period, row), g in groups.items():
            if not g["set_number"]:
                continue
            m = {"name": name, "period": period, "row": row, "qabd": round(g["قبض"], 2),
                 "allow8": round(g["قبض"] * ALLOWANCE_8, 2)}
            total, matches = index.get(g["set_number"], (0.0, []))
            index[g["set_number"]] = (round(total + m["allow8"], 2), matches + [m])
        return index

    def audit_sale_assembler_khayas(self, month=None):
        """سطور فواتير المبيعات المرحّلة التي يختلف «خياس المركب» المسجّل فيها عن
        قيمته الصحيحة الآن في كشف المركبين (مسموح/٨ لرقم التشغيل).

        للقراءة فقط: لا يغيّر شيئاً؛ التصحيح من نافذة تعديل الفاتورة نفسها."""
        index = self.assembler_khayas_index()
        by_key = {}
        for inv in self.invoices.values():
            if inv.get("settled_status") not in SALE_READ_STATUSES:
                continue
            t = inv.get("النوع")
            if t not in self.SALE_TYPES and t != "خياس طقوم":
                continue
            if not self.inv_in_period(inv, month):
                continue
            key = (inv.get("رقم الفاتورة اليدوي", "") or "", inv.get("التاريخ", ""), inv.get("الاسم", ""))
            by_key.setdefault(key, []).append(inv)
        found, checked = [], 0
        for key, recs in by_key.items():
            for r in self.sale_records_to_rows(recs):
                set_no = self.normalize_set_number(r.get("set_number"))
                if not set_no:
                    continue
                checked += 1
                correct, matches = index.get(set_no, (0.0, []))
                stored = round(r.get("خياس المركب", 0.0) or 0.0, 2)
                if abs(stored - correct) > 0.005:
                    found.append({"key": key, "set_number": set_no, "row_number": r.get("row_number", ""),
                                  "stored": stored, "correct": correct, "matches": matches,
                                  "invoice_no": key[0] or min(i.get("رقم الفاتورة", 0) for i in recs)})
        found.sort(key=lambda d: (d["key"][1], str(d["invoice_no"]), d["set_number"]))
        return found, checked

    def open_assembler_khayas_audit(self):
        """نافذة تدقيق خياس المركب في كل فواتير المبيعات المرحّلة (كل الفترات)."""
        win = ctk.CTkToplevel(self)
        win.title("تدقيق خياس المركب")
        self.fit_dialog_to_screen(win, 1150, 620)
        win.transient(self)

        ctk.CTkLabel(win, text="🔍 تدقيق خياس المركب في فواتير المبيعات المرحّلة",
                     font=("Cairo", 17, "bold"), text_color=(UI["ink"], "#E6EDF3")).pack(pady=(12, 2))
        ctk.CTkLabel(win, text=("يقارن «خياس المركب» المسجّل في كل سطر برقم تشغيل بقيمته الصحيحة الآن في كشف "
                                "المركبين (مسموح/٨ لصفوف رقم التشغيل). لا يغيّر شيئاً — التصحيح من نافذة تعديل الفاتورة."),
                     font=("Cairo", 12), text_color=(UI["muted"], "#9AA4B2"), wraplength=1000).pack(padx=18)
        lbl_result = ctk.CTkLabel(win, text="", font=("Cairo", 14, "bold"))
        lbl_result.pack(pady=(6, 4))

        table_frame = ttk.Frame(win)
        table_frame.pack(fill="both", expand=True, padx=18, pady=4)
        cols = ("رقم الفاتورة", "التاريخ", "الاسم", "رقم التشغيل", "المسجّل", "الصحيح", "الفرق", "المصدر")
        tree = self.create_standard_treeview(table_frame, cols, height=12)
        rows_map = {}

        def run():
            for item in tree.get_children():
                tree.delete(item)
            rows_map.clear()
            found, checked = self.audit_sale_assembler_khayas()
            for d in found:
                rows = [m for m in d["matches"] if m["allow8"]] or d["matches"]
                src = "  +  ".join(f"{m['name']} — الصف {m['row'] or '-'} — {m['period']}: {m['allow8']:.2f}"
                                   for m in rows) or "غير موجود في كشف المركبين"
                item = tree.insert("", "end", values=(
                    d["invoice_no"], d["key"][1], d["key"][2], d["set_number"], f"{d['stored']:.2f}",
                    f"{d['correct']:.2f}", f"{d['correct'] - d['stored']:+.2f}", src))
                rows_map[item] = d["key"]
            if found:
                lbl_result.configure(text=f"⚠️ {len(found)} سطراً يختلف خياس المركب فيها — من {checked} سطراً برقم تشغيل",
                                     text_color=(UI["danger"], "#F28B82"))
            else:
                lbl_result.configure(text=f"✔ كل السطور مطابقة لكشف المركبين ({checked} سطراً برقم تشغيل)",
                                     text_color=(UI["success"], "#7EE2B8"))
            self.fit_columns_to_content(tree, None, min_width=60, max_width=420)

        def open_selected(event=None):
            sel = tree.selection()
            key = rows_map.get(sel[0]) if sel else None
            if not key:
                messagebox.showwarning("تنبيه", "حدّد سطراً من الجدول أولاً.", parent=win)
                return
            self.open_sale_invoice_editor(key)

        tree.bind("<Double-1>", open_selected)
        btns = ctk.CTkFrame(win, fg_color="transparent")
        btns.pack(pady=(4, 12))
        ctk.CTkButton(btns, text="✏️ فتح الفاتورة للتعديل", font=("Cairo", 14, "bold"), width=200, height=36,
                      fg_color=UI["primary"], hover_color=UI["primary_hover"],
                      command=open_selected).pack(side="right", padx=6)
        ctk.CTkButton(btns, text="↻ إعادة التدقيق", font=("Cairo", 14, "bold"), width=160, height=36,
                      fg_color=UI["neutral"], hover_color=UI["neutral_hover"],
                      command=run).pack(side="right", padx=6)
        run()

    def describe_assembler_khayas(self, set_number, details=None):
        """سطر قصير تحت الخانات: من أين جاء خياس المركب (أو أنه غير موجود).
        details: ناتج get_assembler_khayas_details إن حُسب للتو (لا يُعاد البحث)."""
        set_number = self.normalize_set_number(set_number)
        if not set_number:
            return ""
        total, matches = details or self.get_assembler_khayas_details(set_number)
        if not matches:
            return f"رقم التشغيل {set_number} غير موجود في قسم المركبين بمراحل التصنيع — خياس المركب فارغ"
        # الصفوف ذات القيمة فقط (صف بلا قبض بعدُ يُذكر حين لا يوجد غيره ليُفهم سبب الصفر)
        shown = [m for m in matches if m["allow8"]] or matches
        parts = [f"{m['name']} — الصف {m['row'] or 'بدون ترقيم'} — فترة {m['period']}: "
                 f"قبض {m['qabd']:.2f} × ٨ بالألف = {m['allow8']:.2f}" for m in shown]
        return f"خياس المركب للتشغيل {set_number} = {total:.2f}  ←  من المركبين: " + "  +  ".join(parts)

    def autofill_assembler_khayas(self, event=None):
        """يملأ خانة (خياس المركب) تلقائياً حسب رقم التشغيل المكتوب.

        الأخطاء تُسجَّل ولا تُكتم: كتمها سابقاً جعل فشل الجلب يبدو كأن الرقم
        غير موجود، فيصعب تشخيص السبب.
        """
        if not hasattr(self, "sale_khayas_assembler"):
            return
        job = getattr(self, "_assembler_job", None)
        if job is not None:
            self._assembler_job = None
            try:
                self.after_cancel(job)
            except Exception:
                pass
        try:
            key = self.normalize_set_number(self.sale_set_number.get())
            # الرقم نفسه ما زال مكتوباً والخانة ممتلئة ← لا يُعاد الجلب: المرور على
            # الخانة بالأسهم أو Enter لا يمسح خياساً عدّله المستخدم بيده
            if (key == getattr(self, "_assembler_set_fetched", None)
                    and self.sale_khayas_assembler.get().strip()):
                return
            details = self.get_assembler_khayas_details(key)
            self._assembler_set_fetched = key
            value = details[0]
            self.sale_khayas_assembler.delete(0, 'end')
            if abs(value) > 0.0001:
                self.sale_khayas_assembler.insert(0, f"{value:g}")
            self.show_assembler_source(self.describe_assembler_khayas(key, details))
            if hasattr(self, "_recompute_sale_totals"):
                self._recompute_sale_totals()
        except Exception as e:
            log_cloud_error("تعذّر جلب خياس المركب تلقائياً", e)

    def schedule_assembler_autofill(self, event=None):
        """الجلب بعد توقّف الكتابة ١٨٠ ملّي ثانية — لا مع كل حرف (البحث يمسح كل الحركات)"""
        job = getattr(self, "_assembler_job", None)
        if job is not None:
            try:
                self.after_cancel(job)
            except Exception:
                pass
        self._assembler_job = self.after(180, self.autofill_assembler_khayas)

    def show_assembler_source(self, text):
        """سطر المصدر تحت خانات المبيعات: يظهر بنصه ويختفي حين يفرغ."""
        lbl = getattr(self, "lbl_assembler_source", None)
        if lbl is None:
            return
        try:
            lbl.configure(text=text or "")
            if text:
                lbl.grid()
            else:
                lbl.grid_remove()
        except Exception:
            pass

    def bind_vertical_navigation(self, fields, on_last=None, window=None):
        """تنقّل بين خانات نافذة التعديل بـ Enter و↑ ↓.

        الربط يتم على **النافذة نفسها** لا على كل خانة:
        CTkEntry غلافٌ حول خانة داخلية، والربط على الغلاف قد لا يصل لها في
        بعض إصدارات المكتبة — فلا يستجيب المفتاح. الربط على النافذة يلتقط
        المفتاح دائماً، ثم نحدّد الخانة الحالية من موضع التركيز.

        on_last: يُستدعى عند Enter في آخر خانة (الحفظ عادةً).
        """
        widgets = [f for f in fields if f is not None]
        if not widgets:
            return

        win = window
        if win is None:
            try:
                win = widgets[0].winfo_toplevel()
            except Exception:
                return

        def inner(w):
            """الخانة الداخلية الحقيقية لـ CTkEntry (أو الأداة نفسها)"""
            return getattr(w, "_entry", w)

        def current_index():
            """موضع الخانة التي فيها التركيز الآن"""
            try:
                focused = win.focus_get()
            except Exception:
                return None
            for i, w in enumerate(widgets):
                if focused is w or focused is inner(w):
                    return i
            return None

        def go(step, wrap_to_save=False):
            i = current_index()
            if i is None:
                return None          # التركيز خارج الخانات: لا نتدخّل
            j = i + step
            if j >= len(widgets):
                if wrap_to_save and on_last is not None:
                    on_last()
                return "break"
            if j < 0:
                return "break"
            target = widgets[j]
            try:
                target.focus_set()
                inner(target).select_range(0, "end")
            except Exception:
                pass
            return "break"

        win.bind("<Down>", lambda e: go(1), add="+")
        win.bind("<Up>", lambda e: go(-1), add="+")
        win.bind("<Return>", lambda e: go(1, wrap_to_save=True), add="+")
        win.bind("<KP_Enter>", lambda e: go(1, wrap_to_save=True), add="+")


    def bind_enter_navigation(self, fields, on_last=None):
        """Enter (ومفتاح Enter في لوحة الأرقام) ينقل للخانة التالية ويحدّد نصها فيُكتب
        فوقه مباشرة، وعند آخر خانة يستدعي on_last (إضافة السطر أو حفظه).

        الربط على كل خانة: CTkEntry وCTkComboBox يمرّران الربط لخانتهما الداخلية.
        """
        widgets = [f for f in fields if f is not None]

        def go(i):
            if i + 1 < len(widgets):
                target = widgets[i + 1]
                try:
                    target.focus_set()
                    getattr(target, "_entry", target).select_range(0, "end")
                except Exception:
                    pass
            elif on_last is not None:
                on_last()
            return "break"

        for i, field in enumerate(widgets):
            for seq in ("<Return>", "<KP_Enter>"):
                try:
                    field.bind(seq, lambda e, i=i: go(i))
                except Exception:
                    pass

    def bind_arrow_navigation(self, fields):
        """تنقّل بالأسهم يمين/يسار بين خانات الإدخال المرصوفة من اليمين لليسار.

        لا يتدخّل عندما يكون المؤشر داخل النص: السهم الأيسر ينتقل للخانة
        التالية فقط إذا كان المؤشر في نهاية النص، والأيمن فقط إذا كان في
        بدايته — حتى يبقى تحريك المؤشر داخل الرقم ممكناً كالمعتاد.
        """
        widgets = [f for f in fields if f is not None]

        def go(idx, event):
            if 0 <= idx < len(widgets):
                widgets[idx].focus_set()
                return "break"
            return None

        # الأسهم تنتقل بين الخانات دائماً (لا تحرّك المؤشر داخل الرقم).
        # الشرط السابق كان يمنع الانتقال يميناً كلما كان المؤشر بعد أول حرف،
        # فبدا وكأن التنقل يعمل في اتجاه واحد فقط.
        # لتحريك المؤشر داخل النص: Home و End.
        for i, field in enumerate(widgets):
            def on_left(e, i=i):
                return go(i + 1, e)

            def on_right(e, i=i):
                return go(i - 1, e)

            try:
                field.bind("<Left>", on_left)
                field.bind("<Right>", on_right)
            except Exception:
                pass

    def stage_sale_row(self):
        """إضافة سطر إلى الفاتورة الحالية (تجهيز فقط، بدون ترحيل فعلي بعد)"""
        self.remember_discount_pct()        # النسبة المستخدمة في السطر هي «آخر نسبة»
        name = self.sale_name.get().strip()
        if not name or name not in self.get_supplier_name_values_no_mustarja():
            messagebox.showwarning("تنبيه", "لا يمكن إضافة سطر إلا بعد اختيار اسم من الموردين المسجلين.")
            return

        def safe_val(entry):
            try:
                return round(float(entry.get().strip()), 2) if entry.get().strip() else 0.0
            except ValueError:
                return 0.0

        gold_v = safe_val(self.sale_gold)
        gems_v = safe_val(self.sale_gems)
        stones_v = safe_val(self.sale_stones)
        stones_discount_v = safe_val(self.sale_stones_discount)
        diamond_v = safe_val(self.sale_diamond)
        khayas_v = safe_val(self.sale_khayas)
        khayas_polish_v = safe_val(self.sale_khayas_polish)
        khayas_assembler_v = safe_val(self.sale_khayas_assembler)
        set_num = self.sale_set_number.get().strip()
        # الترقيم التلقائي: أكبر رقم موجود + ١، فلا يتكرر رقم حتى لو حُذف
        # سطر من وسط الفاتورة (الترقيم يُعاد ضبطه بعد الحذف على كل حال)
        row_num = str(self.next_sale_row_number())

        if (gold_v <= 0 and gems_v <= 0 and stones_v <= 0 and diamond_v <= 0
                and khayas_v <= 0 and khayas_polish_v <= 0 and khayas_assembler_v == 0):
            messagebox.showwarning("تنبيه", "الرجاء إدخال قيمة واحدة على الأقل (ذهب/فصوص/أحجار/ماس/خياس).")
            return
        if khayas_v < 0 or khayas_polish_v < 0:
            messagebox.showwarning("تنبيه", "لا يمكن إدخال خياس بالسالب.")
            return
        if self.check_sale_row_duplicate(self.pending_sale_rows, row_num, set_num):
            return

        self.pending_sale_rows.append({
            "row_number": row_num, "set_number": set_num, "ذهب": gold_v, "فصوص": gems_v, "أحجار": stones_v,
            "أحجار بعد الخصم": stones_discount_v, "الماس": diamond_v, "خياس": khayas_v,
            "خياس البوليش": khayas_polish_v, "خياس المركب": khayas_assembler_v
        })

        self.sale_row_number.delete(0, 'end')
        self.sale_khayas.delete(0, 'end')
        self.sale_khayas_polish.delete(0, 'end')
        self.sale_khayas_assembler.delete(0, 'end')
        self.sale_set_number.delete(0, 'end')
        self.sale_gold.delete(0, 'end')
        self.sale_gems.delete(0, 'end')
        self.sale_stones.delete(0, 'end')
        self.sale_stones_discount.delete(0, 'end')
        self.sale_diamond.delete(0, 'end')
        self.sale_weight_standing.delete(0, 'end')
        self.sale_weight_bound.delete(0, 'end')
        self._assembler_set_fetched = None
        self.show_assembler_source("")
        self.sale_set_number.focus_set()

        self.refresh_pending_sales_table()

    def toggle_pending_sales_order(self):
        """يعكس ترتيب عرض سطور الفاتورة (تصاعدي/تنازلي).

        الترتيب عرضٌ فقط ولا يمسّ ترتيب السطور المحفوظ ولا أرقامها — الغرض
        رؤية آخر سطر سُجِّل بلا نزول إلى آخر الجدول.
        """
        self.pending_sales_desc = not getattr(self, "pending_sales_desc", False)
        if hasattr(self, "btn_sales_sort"):
            self.btn_sales_sort.configure(
                text="⬆️ تصاعدي" if self.pending_sales_desc else "⬇️ تنازلي")
        self.refresh_pending_sales_table()

    # عمود الإجراءات: أول عمود بلا عنوان، نصفه الأيسر ✏️ (تعديل) والأيمن 🗑️ (حذف)
    SALE_ACTION_COL = "_act"
    SALE_ACTION_TEXT = "✏️        🗑️"

    def refresh_pending_sales_table(self):
        if not hasattr(self, 'pending_sales_table_frame') or not self.pending_sales_table_frame:
            return
        # أسماء مختصرة واضحة: العمود الأول (خياس) هو التلميع النهائي،
        # ثم (بوليش) ثم (مركب) — بدل تكرار كلمة خياس في ثلاثة عناوين.
        # لا عمود «الصافي» هنا: يُحسب عند الترحيل ويظهر في شاشة ربح/خسارة الطقم.
        act = self.SALE_ACTION_COL
        cols = (act, "رقم الصف", "رقم التشغيل", "الذهب", "الفصوص", "الأحجار", "الماس",
                "الأحجار بعد الخصم", "خياس التلميع", "بوليش", "مركب", "الوزن القائم", "الوزن المقيد")
        self.pending_sales_tree, _t, reused = self.reuse_or_create_tree(
            self.pending_sales_table_frame, cols, height=16)
        tree = self.pending_sales_tree
        tree.tag_configure("total_tag", foreground="#e67e22", font=("Cairo", 13, "bold"))
        for c in cols:
            tree.column(c, width=70, anchor="center", stretch=False)

        tot = dict.fromkeys(["ذهب", "فصوص", "أحجار", "أحجار بعد الخصم", "الماس",
                             "خياس", "خياس البوليش", "خياس المركب", "القائم", "المقيد"], 0.0)

        def num(row, key):
            try:
                return float(row.get(key, 0.0) or 0.0)
            except (TypeError, ValueError):
                return 0.0

        def cell(row, key):
            return f"{num(row, key):.2f}" if num(row, key) else "-"

        # الترتيب عرضٌ فقط: معرّف كل صف في الجدول = موضعه في self.pending_sale_rows،
        # فالتعديل والحذف يصيبان السطر الصحيح حتى مع العرض التنازلي
        order = list(enumerate(self.pending_sale_rows))
        if getattr(self, "pending_sales_desc", False):
            order.reverse()

        for idx, row in order:
            # الوزن القائم يحسب الأحجار الخام، والمقيد يحسبها بعد الخصم
            standing = round(num(row, "ذهب") + num(row, "فصوص") + num(row, "أحجار") + num(row, "الماس"), 2)
            bound = round(num(row, "ذهب") + num(row, "فصوص") + num(row, "أحجار بعد الخصم") + num(row, "الماس"), 2)
            for k in ("ذهب", "فصوص", "أحجار", "أحجار بعد الخصم", "الماس", "خياس",
                      "خياس البوليش", "خياس المركب"):
                tot[k] = round(tot[k] + num(row, k), 2)
            tot["القائم"] = round(tot["القائم"] + standing, 2)
            tot["المقيد"] = round(tot["المقيد"] + bound, 2)

            tree.insert("", "end", iid=f"row{idx}", values=(
                self.SALE_ACTION_TEXT,
                row.get("row_number", "") or "-",
                row.get("set_number", "") or "-",
                cell(row, "ذهب"), cell(row, "فصوص"), cell(row, "أحجار"), cell(row, "الماس"),
                cell(row, "أحجار بعد الخصم"), cell(row, "خياس"), cell(row, "خياس البوليش"), cell(row, "خياس المركب"),
                f"{standing:.2f}" if standing else "-",
                f"{bound:.2f}" if bound else "-",
            ))

        if self.pending_sale_rows:
            tree.insert("", "end", iid="total", values=(
                "", "الإجمالي", "-", f"{tot['ذهب']:.2f}", f"{tot['فصوص']:.2f}", f"{tot['أحجار']:.2f}",
                f"{tot['الماس']:.2f}", f"{tot['أحجار بعد الخصم']:.2f}", f"{tot['خياس']:.2f}",
                f"{tot['خياس البوليش']:.2f}", f"{tot['خياس المركب']:.2f}",
                f"{tot['القائم']:.2f}", f"{tot['المقيد']:.2f}"), tags=("total_tag",))

        self.apply_column_labels(tree, "pending_sales")
        # عمود الإجراءات بلا عنوان وبعرض ثابت يكفي الزرّين — يُضبط **قبل** توزيع
        # العرض، فتتقاسم بقية الأعمدة ما يتبقّى ويمتلئ الجدول بلا تجاوز
        tree.heading(act, text="")
        tree.column(act, width=96, minwidth=96, stretch=False, anchor="center")
        self.fit_columns_to_content(tree, "pending_sales", min_width=44, max_width=150)
        self.enable_column_rename(tree, "pending_sales", on_renamed=self.refresh_pending_sales_table)

        if not getattr(tree, "_sale_actions_bound", False):
            tree.bind("<ButtonRelease-1>", self._on_pending_sales_click, add="+")
            tree.bind("<Double-1>", self._on_pending_sales_double_click, add="+")
            tree.bind("<Delete>", lambda e: self.delete_pending_sale_row(), add="+")
            tree.bind("<Motion>", self._on_pending_sales_motion, add="+")
            tree._sale_actions_bound = True

    def _pending_row_index(self, iid):
        """موضع السطر في self.pending_sale_rows من معرّف صفه في الجدول (None لصف الإجمالي)"""
        if not iid or not str(iid).startswith("row"):
            return None
        try:
            idx = int(str(iid)[3:])
        except ValueError:
            return None
        return idx if 0 <= idx < len(getattr(self, "pending_sale_rows", [])) else None

    def _pending_action_at(self, event):
        """أي زر تحت المؤشر في عمود الإجراءات: ('edit'|'delete', معرّف الصف) أو (None, None)"""
        tree = self.pending_sales_tree
        try:
            if tree.identify_region(event.x, event.y) != "cell" or tree.identify_column(event.x) != "#1":
                return None, None
            iid = tree.identify_row(event.y)
            if self._pending_row_index(iid) is None:
                return None, None
            x0, _y0, w, _h = tree.bbox(iid, "#1")
            return ("edit" if event.x < x0 + w / 2 else "delete"), iid
        except Exception:
            return None, None

    def _on_pending_sales_motion(self, event):
        action, _iid = self._pending_action_at(event)
        try:
            self.pending_sales_tree.configure(cursor="hand2" if action else "")
        except Exception:
            pass

    def _on_pending_sales_click(self, event):
        action, iid = self._pending_action_at(event)
        if not action:
            return
        self.pending_sales_tree.selection_set(iid)
        if action == "edit":
            self.edit_pending_sale_row()
        else:
            self.delete_pending_sale_row()

    def _on_pending_sales_double_click(self, event):
        iid = self.pending_sales_tree.identify_row(event.y)
        if self._pending_row_index(iid) is not None and self.pending_sales_tree.identify_column(event.x) != "#1":
            self.pending_sales_tree.selection_set(iid)
            self.edit_pending_sale_row()

    def _selected_pending_index(self, action_word):
        if not (hasattr(self, 'pending_sales_tree') and self.pending_sales_tree):
            return None
        sel = self.pending_sales_tree.selection()
        if not sel:
            messagebox.showwarning("تنبيه", f"الرجاء تحديد السطر المراد {action_word} أولاً.")
            return None
        idx = self._pending_row_index(sel[0])
        if idx is None:
            messagebox.showinfo("تنبيه", f"صف الإجمالي لا يُمكن {action_word}ه — اختر سطراً من سطور الفاتورة.")
        return idx

    def delete_pending_sale_row(self):
        idx = self._selected_pending_index("حذف")
        if idx is None:
            return
        row = self.pending_sale_rows[idx]
        label = f"السطر رقم ({row.get('row_number') or idx + 1})"
        if row.get("set_number"):
            label += f" — رقم التشغيل ({row.get('set_number')})"
        if not messagebox.askyesno("تأكيد الحذف", f"حذف {label} من الفاتورة الحالية؟"):
            return
        del self.pending_sale_rows[idx]
        # إعادة الترقيم بعد الحذف: تبقى الأرقام ١..ن بلا فجوات
        self.renumber_pending_sale_rows()
        self.refresh_pending_sales_table()

    # خانات نافذة التعديل بترتيب خانات الإدخال نفسها (من اليمين)
    SALE_EDIT_FIELDS = (("رقم التشغيل", "set_number"), ("الذهب", "ذهب"), ("الفصوص", "فصوص"),
                        ("الأحجار", "أحجار"), ("الماس", "الماس"), ("الأحجار بعد الخصم", "أحجار بعد الخصم"),
                        ("خياس التلميع النهائي", "خياس"), ("خياس البوليش", "خياس البوليش"),
                        ("خياس المركب", "خياس المركب"))

    def edit_pending_sale_row(self):
        """تعديل كل خانات سطر من الفاتورة الحالية في نافذة أفقية (مثل صف الإدخال نفسه).

        كانت النافذة السابقة عمودية وتُسقط خياس البوليش وخياس المركب من السطر
        عند الحفظ — الآن تعرض كل الخانات وتحفظها كلها.
        """
        idx = self._selected_pending_index("تعديل")
        if idx is None:
            return
        row = dict(self.pending_sale_rows[idx])

        win = ctk.CTkToplevel(self)
        win.title(f"تعديل السطر رقم {row.get('row_number') or idx + 1}")
        win.resizable(True, False)
        win.transient(self)
        win.configure(fg_color=(UI["canvas"], "#10141A"))

        head = ctk.CTkFrame(win, fg_color="transparent")
        head.pack(fill="x", padx=18, pady=(14, 4))
        ctk.CTkLabel(head, text=f"✏️ تعديل السطر رقم {row.get('row_number') or idx + 1}",
                     font=("Cairo", 18, "bold"), text_color=UI_TITLE).pack(side="right")
        lbl_live = ctk.CTkLabel(head, text="", font=("Cairo", 13, "bold"),
                                fg_color=(UI["primary_soft"], "#1B2A44"), text_color=(UI["primary"], "#9CC0F5"),
                                corner_radius=8, height=30)
        lbl_live.pack(side="left", ipadx=10)

        card = ctk.CTkFrame(win, corner_radius=12, fg_color=(UI["surface"], "#171C23"),
                            border_width=1, border_color=(UI["line"], "#2A313B"))
        card.pack(fill="x", padx=18, pady=6)
        fields = self.SALE_EDIT_FIELDS
        n = len(fields)
        for c in range(n):
            card.grid_columnconfigure(c, weight=1, uniform="edit_fields")
        entries = {}
        for i, (label, key) in enumerate(fields):
            col = n - 1 - i                    # من اليمين لليسار
            ctk.CTkLabel(card, text=label, font=("Cairo", 13, "bold"), wraplength=120,
                         text_color=(UI["ink"], "#E5E7EB")).grid(row=0, column=col, padx=5, pady=(10, 3), sticky="s")
            ent = ctk.CTkEntry(card, justify="center", font=("Cairo", 15), width=88, height=38)
            val = row.get(key, "")
            if key == "set_number":
                ent.insert(0, str(val or ""))
            else:
                try:
                    v = float(val or 0)
                except (TypeError, ValueError):
                    v = 0.0
                if v:
                    ent.insert(0, f"{v:g}")
            ent.grid(row=1, column=col, padx=5, pady=(0, 12), sticky="ew")
            entries[key] = ent

        # نسبة خصم هذا السطر كما سُجّل (الأحجار بعد الخصم ÷ الأحجار)، وإلا النسبة الحالية
        def read(key):
            try:
                return float(entries[key].get().strip() or 0)
            except ValueError:
                return 0.0
        try:
            pct = float(row.get("أحجار بعد الخصم", 0) or 0) / float(row.get("أحجار", 0) or 0)
        except (TypeError, ValueError, ZeroDivisionError):
            try:
                pct = float(self.sale_discount_pct.get().replace("%", "")) / 100.0
            except Exception:
                pct = 0.30

        def update_live(event=None):
            standing = read("ذهب") + read("فصوص") + read("أحجار") + read("الماس")
            bound = read("ذهب") + read("فصوص") + read("أحجار بعد الخصم") + read("الماس")
            lbl_live.configure(text=f"الوزن القائم: {standing:.2f}   ·   الوزن المقيد: {bound:.2f}")

        def on_stones(event=None):
            entries["أحجار بعد الخصم"].delete(0, "end")
            if read("أحجار") > 0:
                entries["أحجار بعد الخصم"].insert(0, f"{round(read('أحجار') * pct, 2):g}")
            update_live()

        def on_set_number(event=None):
            """رقم تشغيل جديد ← خياس المركب الخاص به من مراحل التصنيع (مثل خانات الإدخال)"""
            if entries["set_number"].get().strip() == str(row.get("set_number") or "").strip():
                return
            try:
                v = self.get_assembler_khayas_for_set(entries["set_number"].get())
                entries["خياس المركب"].delete(0, "end")
                if abs(v) > 0.0001:
                    entries["خياس المركب"].insert(0, f"{v:g}")
            except Exception as e:
                log_cloud_error("تعذّر جلب خياس المركب في نافذة التعديل", e)

        entries["أحجار"].bind("<KeyRelease>", on_stones, add="+")
        entries["set_number"].bind("<FocusOut>", on_set_number, add="+")
        for key in ("ذهب", "فصوص", "أحجار بعد الخصم", "الماس"):
            entries[key].bind("<KeyRelease>", update_live, add="+")
        update_live()

        def save_row(event=None):
            new_row = dict(row)
            new_row["set_number"] = entries["set_number"].get().strip()
            for _label, key in fields:
                if key == "set_number":
                    continue
                try:
                    v = round(float(entries[key].get().strip() or 0), 2)
                except ValueError:
                    messagebox.showerror("خطأ", f"الرجاء إدخال رقم صحيح في خانة ({_label}).", parent=win)
                    entries[key].focus_set()
                    return "break"
                # خياس المركب وحده قد يكون سالباً (يأتي من معادلة القسم)
                if v < 0 and key != "خياس المركب":
                    messagebox.showerror("خطأ", f"لا يمكن إدخال ({_label}) بالسالب.", parent=win)
                    entries[key].focus_set()
                    return "break"
                new_row[key] = v
            if (new_row["ذهب"] <= 0 and new_row["فصوص"] <= 0 and new_row["أحجار"] <= 0
                    and new_row["الماس"] <= 0 and new_row["خياس"] <= 0 and new_row["خياس البوليش"] <= 0
                    and new_row["خياس المركب"] == 0):
                messagebox.showwarning("تنبيه", "لا بد من قيمة واحدة على الأقل (ذهب/فصوص/أحجار/ماس/خياس).",
                                       parent=win)
                return "break"
            if self.check_sale_row_duplicate(self.pending_sale_rows, new_row.get("row_number", ""),
                                             new_row["set_number"], skip_index=idx, parent=win):
                return "break"
            self.pending_sale_rows[idx] = new_row
            self.refresh_pending_sales_table()
            try:
                self.pending_sales_tree.selection_set(f"row{idx}")
                self.pending_sales_tree.see(f"row{idx}")
            except Exception:
                pass
            win.destroy()
            return "break"

        btns = ctk.CTkFrame(win, fg_color="transparent")
        btns.pack(fill="x", padx=18, pady=(4, 14))
        ctk.CTkButton(btns, text="💾 حفظ التعديل", font=("Cairo", 15, "bold"), height=40, width=180,
                      fg_color=UI["success"], hover_color=UI["success_hover"], command=save_row).pack(side="right")
        ctk.CTkButton(btns, text="إلغاء", font=("Cairo", 14, "bold"), height=40, width=110,
                      fg_color=UI["neutral"], hover_color=UI["neutral_hover"],
                      command=win.destroy).pack(side="right", padx=8)
        ctk.CTkLabel(btns, text="Enter: التالي ثم الحفظ   ·   Esc: إلغاء", font=("Cairo", 12),
                     text_color=(UI["muted"], "#9AA3AF")).pack(side="left")

        order = [entries[key] for _l, key in fields]
        self.bind_arrow_navigation(order)
        for i, ent in enumerate(order[:-1]):
            ent.bind("<Return>", lambda e, nxt=order[i + 1]: nxt.focus_set() or "break")
        order[-1].bind("<Return>", save_row)
        win.bind("<Escape>", lambda e: win.destroy())

        # نافذة أفقية بعرض يتسع للخانات كلها، في منتصف النظام
        win.update_idletasks()
        try:
            s = float(ctk.ScalingTracker.get_window_scaling(self))
        except Exception:
            s = 1.0
        w = min(int(1180 * s), self.winfo_width() - 40) if self.winfo_width() > 400 else int(1180 * s)
        h = win.winfo_reqheight()
        x = self.winfo_rootx() + max(0, (self.winfo_width() - w) // 2)
        y = self.winfo_rooty() + max(0, (self.winfo_height() - h) // 3)
        win.geometry(f"{int(w / s)}x{int(h / s)}+{x}+{y}")
        try:
            win.grab_set()
            win.focus_force()
        except Exception:
            pass
        order[1].focus_set()

    def commit_sale_invoice(self):
        """اعتماد وترحيل كل السطور المعلّقة، كل سطر يصبح فاتورة طباعة مستقلة، ثم فتح معاينة الفواتير دفعة واحدة"""
        name = self.sale_name.get().strip()
        if not name or name not in self.get_supplier_name_values_no_mustarja():
            messagebox.showwarning("تنبيه", "الرجاء اختيار اسم من الموردين المسجلين قبل الترحيل.")
            return
        if not self.pending_sale_rows:
            messagebox.showwarning("تنبيه", "لا توجد سطور معلّقة لترحيلها. الرجاء إضافة سطر واحد على الأقل أولاً.")
            return

        manual_no = self.sale_invoice_num.get().strip()
        if not manual_no:
            messagebox.showwarning("رقم الفاتورة مطلوب", "لازم تسجل رقم الفاتورة يدوياً قبل اعتماد الفاتورة.")
            self.sale_invoice_num.focus_set()
            return
        sale_types_chk = ("مبيعات ذهب", "مبيعات ذهب مع الماس", "مبيعات فصوص وأحجار", "مبيعات الماس")
        if any(inv.get("رقم الفاتورة اليدوي", "") == manual_no and inv.get("settled_status") == "ACTIVE"
               and inv.get("النوع") in sale_types_chk for inv in self.invoices.values()):
            if not messagebox.askyesno("رقم فاتورة مكرر", f"رقم الفاتورة ({manual_no}) مسجل من قبل بفاتورة مبيعات أخرى.\nهل تريد المتابعة برغم ذلك؟"):
                return

        if not messagebox.askyesno("تأكيد الاعتماد", f"هل أنت متأكد من اعتماد وترحيل هذه الفاتورة لـ ({name})؟\nسيتم تسجيل {len(self.pending_sale_rows)} سطر/أسطر ولا يمكن التراجع إلا بالتعديل أو الحذف لاحقاً."):
            return

        date_val = self.read_entry_date(self.sale_date.get().strip() or self.get_smart_default_date())
        if not date_val:
            return
        full_dt = f"{date_val} {datetime.datetime.now().strftime('%H:%M:%S')}"
        note_widget = getattr(self, "sale_note", None)
        note = note_widget.get().strip() if note_widget is not None else ""

        # الترحيل يمر عبر الدالة الموحّدة نفسها المستخدمة في تعديل الفاتورة، لضمان تطابق المعالجة المحاسبية
        committed_groups = self.post_sale_rows(self.pending_sale_rows, name, full_dt, manual_no, note)

        # فاتورة كانت معلّقة ثم رُحّلت: أُثبتت في «العمليات» فتختفي من «المعلقات»
        suspended_id = getattr(self, "current_suspended_id", None)
        if suspended_id:
            self.delete_suspended_sale(suspended_id)
        self.set_current_suspended(None)

        self.pending_sale_rows = []
        self.sale_name.set("المصنع")
        self.sale_invoice_num.delete(0, 'end')
        if note_widget is not None:
            note_widget.delete(0, 'end')

        self.register_operation_period(date_val)
        self.recalculate_all()

        self.lbl_sales_status.configure(text=f"✅ تم اعتماد وترحيل الفاتورة لـ ({name})")
        self.after(2500, lambda: self.lbl_sales_status.configure(text=""))
        self.refresh_pending_sales_table()
        self.refresh_sales_table()
        self.refresh_sales_ops_table()
        self.update_suspended_count()

        # نسأل المستخدم قبل فتح معاينة الطباعة (بدل فتحها تلقائياً بدون تأكيد)
        with_tickets = self.sale_tickets_with_invoice() and any(
            self.normalize_set_number(g[0]) for g in committed_groups)
        if messagebox.askyesno("معاينة الطباعة", "تم ترحيل الفاتورة بنجاح.\nهل تريد معاينة الطباعة؟"
                               + ("\n(تُرفق صفحة تذاكر: تذكرة لكل رقم تشغيل جاهزة للمسح)" if with_tickets else "")):
            self.preview_invoice_groups(committed_groups)

    # =====================================================================
    # ------- «المعلقات»: فواتير مبيعات عُلّقت قبل ترحيلها لاستكمالها لاحقاً -------
    #
    #  التعليق لا يُنشئ أي حركة محاسبية: تُحفظ الفاتورة كما هي في الشاشة (رأسها،
    #  سطورها، وما كُتب في خانات السطر ولم يُضف) في جدول مستقل. «فتح» يعيدها إلى
    #  قسم المبيعات كما كانت تماماً، وترحيلها يُثبتها في «العمليات» ويحذفها من هنا.
    # =====================================================================
    SUSPENDED_TABLE_SQL = """CREATE TABLE IF NOT EXISTS suspended_sales (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    sale_date TEXT DEFAULT '', manual_no TEXT DEFAULT '', name TEXT DEFAULT '',
                    note TEXT DEFAULT '', discount_pct TEXT DEFAULT '',
                    rows_json TEXT DEFAULT '[]', draft_json TEXT DEFAULT '{}',
                    created_at TEXT DEFAULT '', updated_at TEXT DEFAULT '')"""

    # خانات السطر التي تُحفظ مع التعليق إن كُتب فيها ولم يُضف السطر بعد
    SALE_DRAFT_FIELDS = (("set_number", "sale_set_number"), ("ذهب", "sale_gold"), ("فصوص", "sale_gems"),
                         ("أحجار", "sale_stones"), ("الماس", "sale_diamond"),
                         ("أحجار بعد الخصم", "sale_stones_discount"), ("خياس", "sale_khayas"),
                         ("خياس البوليش", "sale_khayas_polish"), ("خياس المركب", "sale_khayas_assembler"))

    def list_suspended_sales(self):
        """الفواتير المعلّقة، الأحدث تعديلاً أولاً.

        جدولها قد يغيب عن قاعدة أقدم (مرآة المدير لجهاز عميل لم يُحدَّث بعد)،
        فتُرجع قائمة فارغة بلا خطأ."""
        try:
            with sqlite3.connect(self.db_path) as conn:
                raw = conn.execute(
                    "SELECT id, sale_date, manual_no, name, note, discount_pct, rows_json, draft_json, "
                    "created_at, updated_at FROM suspended_sales ORDER BY updated_at DESC, id DESC").fetchall()
        except sqlite3.Error:
            return []
        out = []
        for r in raw:
            try:
                rows = json.loads(r[6] or "[]")
            except ValueError:
                rows = []
            try:
                draft = json.loads(r[7] or "{}")
            except ValueError:
                draft = {}
            out.append({"id": r[0], "date": r[1] or "", "manual_no": r[2] or "", "name": r[3] or "",
                        "note": r[4] or "", "discount_pct": r[5] or "",
                        "rows": [x for x in rows if isinstance(x, dict)] if isinstance(rows, list) else [],
                        "draft": draft if isinstance(draft, dict) else {},
                        "created_at": r[8] or "", "updated_at": r[9] or ""})
        return out

    def get_suspended_sale(self, rec_id):
        return next((r for r in self.list_suspended_sales() if r["id"] == rec_id), None)

    def save_suspended_sale(self, data, rec_id=None):
        """يحفظ فاتورة معلّقة: تحديث المعلّقة نفسها إن كانت هي المفتوحة، وإلا جديدة. يرجع رقمها"""
        now = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        vals = (data.get("date", ""), data.get("manual_no", ""), data.get("name", ""), data.get("note", ""),
                data.get("discount_pct", ""), json.dumps(data.get("rows", []), ensure_ascii=False),
                json.dumps(data.get("draft", {}), ensure_ascii=False))
        with sqlite3.connect(self.db_path) as conn:
            conn.execute(self.SUSPENDED_TABLE_SQL)
            if rec_id and conn.execute("SELECT 1 FROM suspended_sales WHERE id = ?", (rec_id,)).fetchone():
                conn.execute("UPDATE suspended_sales SET sale_date = ?, manual_no = ?, name = ?, note = ?, "
                             "discount_pct = ?, rows_json = ?, draft_json = ?, updated_at = ? WHERE id = ?",
                             vals + (now, rec_id))
            else:
                cur = conn.execute("INSERT INTO suspended_sales (sale_date, manual_no, name, note, discount_pct, "
                                   "rows_json, draft_json, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                                   vals + (now, now))
                rec_id = cur.lastrowid
            conn.commit()
        self.mark_backup_dirty()          # تصل مرآة المدير مع النسخة التالية
        return rec_id

    def delete_suspended_sale(self, rec_id):
        try:
            with sqlite3.connect(self.db_path) as conn:
                conn.execute("DELETE FROM suspended_sales WHERE id = ?", (rec_id,))
                conn.commit()
        except sqlite3.Error as e:
            log_cloud_error("تعذّر حذف الفاتورة المعلّقة", e)
            return False
        self.mark_backup_dirty()
        return True

    @staticmethod
    def suspended_totals(rec):
        """إجماليات فاتورة معلّقة من سطورها (كأعمدة «العمليات»)"""
        tot = dict.fromkeys(("ذهب", "فصوص", "أحجار بعد الخصم", "الماس", "خياس"), 0.0)
        for row in rec.get("rows", []):
            for k in tot:
                try:
                    tot[k] = round(tot[k] + float(row.get(k, 0.0) or 0.0), 2)
                except (TypeError, ValueError):
                    pass
        return tot

    def collect_sale_form(self):
        """الفاتورة الحالية كما هي في الشاشة: رأسها، وسطورها، وما كُتب في خانات السطر ولم يُضف"""
        def text(attr):
            w = getattr(self, attr, None)
            try:
                return w.get().strip() if w is not None else ""
            except Exception:
                return ""
        draft = {k: text(attr) for k, attr in self.SALE_DRAFT_FIELDS}
        return {"date": text("sale_date"), "manual_no": text("sale_invoice_num"), "name": text("sale_name"),
                "note": text("sale_note"), "discount_pct": text("sale_discount_pct"),
                "rows": [dict(r) for r in getattr(self, "pending_sale_rows", [])],
                "draft": {k: v for k, v in draft.items() if v}}

    def fill_sale_form(self, data):
        """يضع فاتورة في شاشة المبيعات كما حُفظت تماماً (رأسها وسطورها وخانات السطر)"""
        def put(attr, value):
            w = getattr(self, attr, None)
            if w is None:
                return
            try:
                w.delete(0, "end")
                if value:
                    w.insert(0, str(value))
            except Exception:
                pass
        put("sale_date", data.get("date") or self.get_smart_default_date())
        put("sale_invoice_num", data.get("manual_no", ""))
        put("sale_note", data.get("note", ""))
        try:
            self.sale_name.set(data.get("name") or "المصنع")
        except Exception:
            pass
        if data.get("discount_pct"):
            try:
                self.sale_discount_pct.set(data["discount_pct"])
            except Exception:
                pass
        self.pending_sale_rows = [dict(r) for r in data.get("rows", []) if isinstance(r, dict)]
        draft = data.get("draft") or {}
        for key, attr in self.SALE_DRAFT_FIELDS:
            put(attr, draft.get(key, ""))
        # خياس المركب المحفوظ مع المسودة يبقى كما هو حتى يتغيّر رقم التشغيل
        self._assembler_set_fetched = self.normalize_set_number(draft.get("set_number", "")) or None
        self.show_assembler_source("")
        if hasattr(self, "_recompute_sale_totals"):
            self._recompute_sale_totals()

    def clear_sale_form(self):
        """فاتورة جديدة فارغة (التاريخ ونسبة الخصم يبقيان كما هما)"""
        self.fill_sale_form({"date": self.sale_date.get().strip(), "name": "المصنع"})

    def set_current_suspended(self, rec_id, rec=None):
        """الفاتورة المعلّقة المفتوحة الآن في قسم المبيعات (None: لا شيء)، مع تذكير ثابت بها"""
        self.current_suspended_id = rec_id
        lbl = getattr(self, "lbl_suspended_open", None)
        if lbl is None:
            return
        try:
            if rec_id:
                no = (rec or {}).get("manual_no") or f"#{rec_id}"
                lbl.configure(text=f"📂 فاتورة معلّقة مفتوحة: {no}")
            else:
                lbl.configure(text="")
        except Exception:
            pass

    def suspend_sale_invoice(self, silent=False):
        """«تعليق الفاتورة»: تُحفظ الفاتورة الحالية كما هي في «المعلقات» وتُفرَّغ الشاشة لفاتورة
        جديدة. لا حركة محاسبية ولا أثر على أي رصيد — تُفتح لاحقاً لاستكمالها ثم ترحيلها."""
        data = self.collect_sale_form()
        if not data["rows"] and not data["draft"]:
            if not silent:
                messagebox.showwarning("لا شيء لتعليقه",
                                       "أضف سطراً واحداً على الأقل إلى الفاتورة قبل تعليقها.")
            return None
        try:
            rec_id = self.save_suspended_sale(data, getattr(self, "current_suspended_id", None))
        except sqlite3.Error as e:
            log_cloud_error("تعذّر تعليق الفاتورة", e)
            messagebox.showerror("تعذّر التعليق", f"لم تُحفظ الفاتورة المعلّقة:\n{e}")
            return None
        self.set_current_suspended(None)
        self.clear_sale_form()
        self.refresh_pending_sales_table()
        self.update_suspended_count()
        if getattr(self, "current_sales_subtab", "") == "المعلقات":
            self.refresh_suspended_sales_table()
        if not silent:
            self.lbl_sales_status.configure(text="⏸️ عُلّقت الفاتورة — تجدها في «المعلقات»")
            self.after(3000, lambda: self.lbl_sales_status.configure(text=""))
            try:
                self.sale_set_number.focus_set()
            except Exception:
                pass
        return rec_id

    def get_selected_suspended_id(self, action="فتح"):
        tree = getattr(self, "suspended_tree", None)
        if not tree:
            return None
        sel = tree.selection()
        if not sel:
            messagebox.showwarning("تنبيه", f"الرجاء تحديد الفاتورة المراد {action}ها من الجدول أولاً.")
            return None
        rec_id = self.suspended_map.get(sel[0])
        if not rec_id:
            messagebox.showinfo("تنبيه", "هذا السطر إجمالي وليس فاتورة معلّقة.")
        return rec_id

    def open_suspended_sale(self, rec_id=None):
        """يفتح فاتورة معلّقة في قسم المبيعات ببياناتها كلها لاستكمالها من حيث توقفت"""
        if rec_id is None:
            rec_id = self.get_selected_suspended_id("فتح")
        if not rec_id:
            return
        rec = self.get_suspended_sale(rec_id)
        if rec is None:
            messagebox.showwarning("تنبيه", "هذه الفاتورة لم تعد في المعلقات (رُحّلت أو حُذفت).")
            self.refresh_suspended_sales_table()
            return
        if rec_id != getattr(self, "current_suspended_id", None):
            current = self.collect_sale_form()
            if current["rows"] or current["draft"]:
                # لا تضيع فاتورة الشاشة الحالية: تُعلَّق هي أولاً
                if not messagebox.askyesno(
                        "فاتورة غير مرحّلة في الشاشة",
                        f"في قسم المبيعات فاتورة فيها {len(current['rows'])} سطر لم تُرحَّل.\n\n"
                        "ستُعلَّق أولاً (تجدها في المعلقات)، ثم تُفتح الفاتورة المختارة.\nهل تريد المتابعة؟"):
                    return
                self.suspend_sale_invoice(silent=True)
            self.fill_sale_form(rec)
            self.set_current_suspended(rec_id, rec)
        self.switch_sales_subtab("المبيعات")
        self.refresh_pending_sales_table()
        self.lbl_sales_status.configure(text="📂 فُتحت الفاتورة المعلّقة — أكمل من حيث توقفت")
        self.after(3000, lambda: self.lbl_sales_status.configure(text=""))
        self.after(80, lambda: self.sale_set_number.focus_set())

    def delete_selected_suspended_sale(self):
        rec_id = self.get_selected_suspended_id("حذف")
        if not rec_id:
            return
        rec = self.get_suspended_sale(rec_id) or {}
        if not messagebox.askyesno(
                "حذف فاتورة معلّقة",
                f"حذف الفاتورة المعلّقة ({rec.get('manual_no') or '-'}) لـ ({rec.get('name') or '-'}) "
                f"وسطورها ({len(rec.get('rows', []))}) نهائياً؟\n\nلم تُرحَّل، فلا أثر لحذفها على أي رصيد."):
            return
        if not self.delete_suspended_sale(rec_id):
            return
        if rec_id == getattr(self, "current_suspended_id", None):
            # ما في الشاشة يبقى كما هو، لكنه لم يعد مرتبطاً بفاتورة معلّقة
            self.set_current_suspended(None)
        self.refresh_suspended_sales_table()
        self.update_suspended_count()

    def update_suspended_count(self):
        """عدد المعلقات على زر القسم، فتُرى بنظرة دون فتحه"""
        btn = getattr(self, "sales_subtab_buttons", {}).get("المعلقات")
        if btn is None:
            return
        n = len(self.list_suspended_sales())
        try:
            btn.configure(text=f"⏸️ المعلقات ({n})" if n else "⏸️ المعلقات")
        except Exception:
            pass

    def build_sales_suspended_ui(self, parent):
        head = ctk.CTkFrame(parent, fg_color="transparent")
        head.pack(fill="x", padx=20, pady=(12, 4))
        ctk.CTkLabel(head, text="⏸️ الفواتير المعلّقة (لم تُرحَّل — بلا أثر على الأرصدة)",
                     font=ctk.CTkFont(family="Cairo", size=18, weight="bold"),
                     text_color="#d4af37").pack(side="right", padx=10)
        ctk.CTkButton(head, text="حذف 🗑️", font=("Cairo", 14, "bold"), width=120, height=34,
                      fg_color=UI["danger"], hover_color=UI["danger_hover"],
                      command=self.delete_selected_suspended_sale).pack(side="left", padx=5)
        ctk.CTkButton(head, text="📂 فتح الفاتورة", font=("Cairo", 14, "bold"), width=170, height=34,
                      fg_color=UI["success"], hover_color=UI["success_hover"],
                      command=lambda: self.open_suspended_sale()).pack(side="left", padx=5)

        self.suspended_table_frame = ttk.Frame(parent)
        self.suspended_table_frame.pack(fill="both", expand=True, padx=20, pady=(4, 4))
        self.suspended_tree = None
        self.suspended_map = {}

        self.lbl_suspended_totals = ctk.CTkLabel(parent, text="", font=("Cairo", 15, "bold"), text_color="#d4af37")
        self.lbl_suspended_totals.pack(fill="x", padx=20, pady=(0, 6))
        ctk.CTkLabel(parent, text="اضغط مرتين على أي فاتورة (أو Enter) لفتحها في قسم المبيعات "
                                  "واستكمالها من حيث توقفت — وعند ترحيلها تنتقل إلى «العمليات»",
                     font=("Cairo", 11), text_color="#aaaaaa").pack(pady=(0, 8))

    def refresh_suspended_sales_table(self):
        if not getattr(self, "suspended_table_frame", None):
            return
        cols = ("رقم الفاتورة", "التاريخ", "الاسم", "البيان", "الذهب", "الفصوص", "الأحجار بعد الخصم",
                "الماس", "خياس", "عدد الأسطر", "آخر تعديل")
        tree, _t, reused = self.reuse_or_create_tree(self.suspended_table_frame, cols, height=13)
        self.suspended_tree = tree
        tree.tag_configure("total_tag", foreground="#d4af37", font=("Cairo", 13, "bold"))
        if not reused:
            tree.bind("<Double-1>", lambda e: self.open_suspended_sale()
                      if self.suspended_map.get(tree.identify_row(e.y)) else None)
            tree.bind("<Return>", lambda e: self.open_suspended_sale())

        def fmt(v):
            return f"{v:.2f}" if v else "-"

        self.suspended_map = {}
        grand = dict.fromkeys(("ذهب", "فصوص", "أحجار بعد الخصم", "الماس", "خياس"), 0.0)
        recs = self.list_suspended_sales()
        current = getattr(self, "current_suspended_id", None)
        for rec in recs:
            t = self.suspended_totals(rec)
            for k in grand:
                grand[k] = round(grand[k] + t[k], 2)
            mark = "📂 " if rec["id"] == current else ""
            iid = tree.insert("", "end", values=(
                mark + (rec["manual_no"] or "-"), rec["date"] or "-", rec["name"] or "-", rec["note"] or "-",
                fmt(t["ذهب"]), fmt(t["فصوص"]), fmt(t["أحجار بعد الخصم"]), fmt(t["الماس"]), fmt(t["خياس"]),
                len(rec["rows"]), rec["updated_at"][:16] or "-"))
            self.suspended_map[iid] = rec["id"]
        if recs:
            tree.insert("", "end", values=(
                "إجمالي المعلقات", "-", "-", "-", f"{grand['ذهب']:.2f}", f"{grand['فصوص']:.2f}",
                f"{grand['أحجار بعد الخصم']:.2f}", f"{grand['الماس']:.2f}", f"{grand['خياس']:.2f}",
                sum(len(r["rows"]) for r in recs), "-"), tags=("total_tag",))

        self.apply_column_labels(tree, "sales_suspended")
        self.fit_columns_to_content(tree, "sales_suspended", min_width=50, max_width=220)
        self.enable_column_rename(tree, "sales_suspended", on_renamed=self.refresh_suspended_sales_table)
        if hasattr(self, "lbl_suspended_totals"):
            self.lbl_suspended_totals.configure(
                text=(f"عدد الفواتير المعلّقة: {len(recs)}  |  الذهب: {grand['ذهب']:.2f}  |  "
                      f"الفصوص: {grand['فصوص']:.2f}  |  الأحجار بعد الخصم: {grand['أحجار بعد الخصم']:.2f}  |  "
                      f"الماس: {grand['الماس']:.2f}  |  الخياس: {grand['خياس']:.2f} جم") if recs
                else "لا توجد فواتير معلّقة — «⏸️ تعليق الفاتورة» في قسم المبيعات يحفظها هنا")
        self.update_suspended_count()

    def refresh_sales_table(self):
        if hasattr(self, 'lbl_sales_balance'):
            bal_gold = self.get_material_balance("ذهب")
            bal_gems_stones = self.get_material_balance("فصوص وأحجار")
            bal_diamond = self.get_material_balance("الماس")
            self.lbl_sales_balance.configure(text=f"رصيد الذهب: {bal_gold:.2f} جم   |   رصيد فصوص وأحجار: {bal_gems_stones:.2f}   |   رصيد الماس: {bal_diamond:.2f}")

    # =========================================================================
    # --- محرك طباعة الفواتير: تجميع بيانات السطر + رسم القالب + معاينة/طباعة ---
    # =========================================================================
    SALE_READ_STATUSES_FOR_PRINT = SALE_READ_STATUSES

    def get_invoice_group_data(self, set_number, date_str, name):
        """يجمع كل فواتير سطر مبيعات واحد (بنفس رقم التشغيل والتاريخ والاسم) في قاموس بيانات فاتورة مستقلة"""
        data = {
            "set_number": set_number, "date": date_str, "name": name,
            "gold": 0.0, "gems": 0.0, "stones": 0.0, "stones_discount": "",
            "diamond": 0.0, "khayas": 0.0, "khayas_polish": 0.0, "khayas_assembler": 0.0, "net": 0.0,
            "row_number": "", "invoice_no": None, "voucher": ""
        }
        for inv in self.invoices.values():
            if inv.get("set_number") != set_number: continue
            if inv.get("التاريخ") != date_str: continue
            if inv.get("الاسم") != name: continue
            t = inv.get("النوع")
            if t in ("مبيعات ذهب", "مبيعات ذهب مع الماس"):
                data["gold"] += inv["الوزن"]
                data["voucher"] = data["voucher"] or inv.get("البيان", "")
            elif t == "مبيعات فصوص وأحجار":
                if inv.get("trees_count") == 3.0:
                    data["stones"] += inv.get("قبل", 0.0)  # الوزن الخام قبل الخصم (للعرض على الفاتورة)
                    data["stones_discount"] = f"{inv['الوزن']:.2f}"  # القيمة بعد الخصم (٣٠٪) وهي المعتمدة محاسبياً
                    data["voucher"] = data["voucher"] or inv.get("البيان", "")
                else:
                    data["gems"] += inv["الوزن"]
                    data["voucher"] = data["voucher"] or inv.get("البيان", "")
            elif t == "مبيعات الماس":
                data["diamond"] += inv["الوزن"]
                data["voucher"] = data["voucher"] or inv.get("البيان", "")
            elif t == "خياس طقوم":
                mark = inv.get("trees_count", 0.0) or 0.0
                if mark == KHAYAS_MARK_POLISH:
                    data["khayas_polish"] += inv["الوزن"]
                elif mark == KHAYAS_MARK_ASSEMBLER:
                    data["khayas_assembler"] += inv["الوزن"]
                elif mark == KHAYAS_MARK_NET:
                    data["net"] += inv["الوزن"]
                else:
                    data["khayas"] += inv["الوزن"]
            if not data["row_number"] and inv.get("row_number"):
                data["row_number"] = inv.get("row_number")
            if data["invoice_no"] is None:
                data["invoice_no"] = inv.get("رقم الفاتورة")
        return data

    def get_sale_batch_set_numbers(self, date_str, name):
        """يرجع كل أرقام التشغيل التي رُحّلت ضمن نفس دفعة المبيعات (نفس التاريخ والاسم)، بترتيب إدخالها الأصلي"""
        sale_types = ["مبيعات ذهب", "مبيعات ذهب مع الماس", "مبيعات فصوص وأحجار", "مبيعات الماس"]
        seen = {}
        for inv in self.invoices.values():
            if inv.get("settled_status") not in ("ACTIVE", "SETTLED_INOUT"): continue
            if inv.get("النوع") not in sale_types: continue
            if inv.get("التاريخ") != date_str or inv.get("الاسم") != name: continue
            sn = inv.get("set_number", "")
            inv_no = inv.get("رقم الفاتورة", 0)
            if sn not in seen or inv_no < seen[sn]:
                seen[sn] = inv_no
        return [sn for sn, _ in sorted(seen.items(), key=lambda kv: kv[1])]

    # ═══ سند رقم التشغيل: قالب المصنع الورقي نفسه (صورته ١٤٥٠×٢٠٤٨ = صفحة A4) ═══
    VOUCHER_PX_W = 1450.0

    def set_voucher_values(self, data):
        """قيم «الوزن النهائي» في سند رقم التشغيل — كما في النموذج الورقي:
        الوزن النهائي = الوزن القائم، ناقص فصوص = الفصوص، ناقص احجار = الأحجار،
        ناقص الماس = الماس، الوزن الصافي = الذهب"""
        gold, gems = data.get("gold", 0.0) or 0.0, data.get("gems", 0.0) or 0.0
        stones, diamond = data.get("stones", 0.0) or 0.0, data.get("diamond", 0.0) or 0.0
        return [("الوزن النهائي", round(gold + gems + stones + diamond, 2)), ("ناقص فصوص", round(gems, 2)),
                ("ناقص احجار", round(stones, 2)), ("ناقص الماس", round(diamond, 2)),
                ("الوزن الصافي", round(gold, 2))]

    def draw_set_voucher_page(self, c, data):
        """سند رقم التشغيل بقالب المصنع الورقي حرفياً (التصنيع، البوليش، التركيب، التلميع النهائي،
        جدول القطع ١–١٨، الإجماليات، التوقيعات). لا يُعبّأ منه إلا رقم التشغيل في خانة NO
        وجدول «الوزن النهائي»؛ وبقية الخانات فارغة للتعبئة اليدوية."""
        from reportlab.lib.colors import Color
        PW, PH = A4
        k = PW / self.VOUCHER_PX_W
        HEAD, LABEL = Color(0.80, 0.80, 0.80), Color(0.86, 0.86, 0.86)

        def X(px):
            return px * k

        def Y(py):
            return PH - py * k

        def box(x0, y0, x1, y1, fill=None, lw=0.9):
            c.setLineWidth(lw)
            if fill is not None:
                c.setFillColor(fill)
            c.rect(X(x0), Y(y1), (x1 - x0) * k, (y1 - y0) * k, fill=1 if fill is not None else 0, stroke=1)
            c.setFillColorRGB(0, 0, 0)

        def text(px, py, s, size=11, bold=True, align="center"):
            c.setFont(_ARABIC_FONT_BOLD_NAME if bold else _ARABIC_FONT_NAME, size)
            s = str(s)
            s = ar(s) if re.search("[\u0600-\u06FF]", s) else s
            base = Y(py) - size * 0.36
            {"center": c.drawCentredString, "right": c.drawRightString, "left": c.drawString}[align](X(px), base, s)

        def cell(x0, y0, x1, y1, label="", fill=None, size=11.5, align="center", bold=True):
            box(x0, y0, x1, y1, fill)
            if label != "":
                px = {"center": (x0 + x1) / 2, "right": x1 - 14, "left": x0 + 14}[align]
                fit = fit_font_size(label, (x1 - x0) * k - 8, size, bold=bold, min_size=7)   # النص داخل خانته دائماً
                text(px, (y0 + y1) / 2, label, fit, bold, align)

        # ── الرأس: مصنع جاديت + NO ──
        box(193, 95, 1315, 248, HEAD, lw=1.2)
        text(755, 148, "مصنع جاديت", 21)
        text(212, 195, "NO:", 14, align="left")
        cell(290, 172, 460, 218, str(data.get("set_number") or ""), Color(1, 1, 1), size=15)
        # ── بيانات السند ──
        for x0, x1, label, fill in ((193, 338, "/      /", None), (338, 437, ":DATE", LABEL), (437, 607, "", None),
                                    (607, 755, ":NAME", LABEL), (755, 852, "", None),
                                    (852, 998, "رقم الموديل:", LABEL), (998, 1170, "", None),
                                    (1170, 1315, "اسم العميل:", LABEL)):
            cell(x0, 248, x1, 295, label, fill, size=9)
        for x0, x1, label, fill in ((778, 875, "", None), (875, 998, "النوع:", LABEL), (998, 1170, "", None),
                                    (1170, 1315, "اسم المركب:", LABEL)):
            cell(x0, 295, x1, 348, label, fill, size=9)

        # ── العمود الأيسر: أقسام المراحل ──
        three = ((558, 728), (387, 558), (240, 387))

        def stage(top, title, heads):
            cell(240, top, 728, top + 47, title, HEAD, size=12.5)
            for (x0, x1), h in zip(three, heads):
                cell(x0, top + 47, x1, top + 95, h, LABEL, size=11.5)
                cell(x0, top + 95, x1, top + 143)
            return top + 143

        stage(297, "التصنيع", ("0.08%", "0.04%", "خياس"))
        stage(465, "البوليش", ("قبل", "بعد", "خياس"))
        y = stage(637, "التركيب", ("قبل", "بعد", "خياس"))
        for label, value_fill in (("فصوص", None), ("احجار", None), ("الماس", None)):
            cell(481, y, 728, y + 48, label, LABEL)
            cell(240, y, 481, y + 48, "%" if label == "احجار" else "", value_fill, align="right")
            y += 48
        c.setLineWidth(1.4)
        c.line(X(240), Y(y + 3), X(728), Y(y + 3))
        y += 6
        for label, value_fill in (("الوزن بعد", LABEL), ("السلسال", None), ("الوزن الأجمالي:", None)):
            cell(481, y, 728, y + 48, label, LABEL)
            cell(240, y, 481, y + 48, "", value_fill)
            y += 48
        stage(1135, "التلميع النهائي", ("قبل", "بعد", "خياس"))

        # الوزن النهائي — الجدول الوحيد المعبّأ
        cell(235, 1305, 724, 1355, "الوزن النهائي", HEAD, size=12.5)
        y = 1355
        for label, value in self.set_voucher_values(data):
            cell(478, y, 724, y + 48, label, LABEL)
            cell(235, y, 478, y + 48, f"{value:.2f}", None, size=12.5)
            y += 48

        # ── العمود الأيمن: جدول القطع ١–١٨ ──
        cols = ((1265, 1313, ""), (1143, 1265, "العدد"), (1046, 1143, "المقاس"), (972, 1046, "النوع"),
                (850, 972, "الوزن"), (778, 850, "البيان"))
        for x0, x1, h in cols:
            cell(x0, 348, x1, 397, h, LABEL, size=9)
        row_h = (1283 - 397) / 18
        for i in range(18):
            y0 = 397 + i * row_h
            for x0, x1, _h in cols:
                cell(x0, y0, x1, y0 + row_h, str(i + 1) if x0 == 1265 else "", size=9.5)
        cell(772, 1283, 1310, 1333, "الاجمالي", HEAD, size=12.5)
        for x0, x1, label, fill in ((1188, 1310, "فصوص:", LABEL), (1040, 1188, "", None),
                                    (918, 1040, "احجار:", LABEL), (772, 918, "", None)):
            cell(x0, 1333, x1, 1383, label, fill, size=11.5)
        cell(797, 1408, 1285, 1457, "الأجمالي", HEAD, size=12.5)
        y = 1457
        for label in ("الوزن الصافي", "فصوص", "الاحجار %", "الوزن المقيد"):
            if label == "الاحجار %":
                cell(1138, y, 1285, y + 48, label, LABEL)
                cell(1040, y, 1138, y + 48, "", LABEL)
            else:
                cell(1040, y, 1285, y + 48, label, LABEL)
            cell(797, y, 1040, y + 48)
            y += 48

        # ── التوقيعات ──
        c.setLineWidth(0.9)
        for x0, x1, label in ((992, 1212, "توقيع المدير"), (650, 870, "توقيع المحاسب"),
                              (285, 505, "توقيع مدير الانتاج")):
            c.line(X(x0), Y(1697), X(x1), Y(1697))
            text((x0 + x1) / 2, 1722, label, 10.5)

    def draw_sales_summary_pages(self, c, rows_data, name, date_str):
        """يرسم صفحة (أو أكثر عند كثرة الأسطر) لفاتورة المبيعات الإجمالية: جدول مرقّم بكل الأسطر + صف الإجمالي، بنفس تصميم قالب فاتورة المبيعات (الأزرق)، قبل صفحات أرقام التشغيل التفصيلية"""
        from reportlab.lib.colors import Color
        PW, PH = A4
        M = 10 * mm
        header_fill = Color(0.78, 0.80, 0.93)   # لافندر فاتح مطابق لقالب فاتورة المبيعات
        border_color = Color(0.15, 0.15, 0.55)  # كحلي غامق للحدود والنصوص

        def txt(x, y, s, size=9, bold=False, align="right", color=None):
            c.setFont(_ARABIC_FONT_BOLD_NAME if bold else _ARABIC_FONT_NAME, size)
            if color:
                c.setFillColor(color)
            s = ar(s)
            if align == "right":
                c.drawRightString(x, y, s)
            elif align == "left":
                c.drawString(x, y, s)
            else:
                c.drawCentredString(x, y, s)
            if color:
                c.setFillColorRGB(0, 0, 0)

        def rect(x, y, w, h, fill=None, stroke_color=None):
            c.saveState()
            if stroke_color:
                c.setStrokeColor(stroke_color)
            if fill:
                c.setFillColor(fill)
                c.rect(x, y - h, w, h, fill=1, stroke=1)
            else:
                c.rect(x, y - h, w, h, fill=0, stroke=1)
            c.restoreState()

        # الأعمدة من اليمين لليسار: التسلسل، رقم التشغيل، الذهب، الفصوص، الأحجار، الأحجار بعد الخصم، الماس، الوزن القائم، الوزن المقيد
        cols = ["#", "رقم التشغيل", "الذهب", "الفصوص", "الأحجار", "الأحجار بعد الخصم", "الماس", "خياس", "الوزن القائم", "الوزن المقيد"]
        col_ratios = [0.45, 0.95, 0.85, 0.85, 0.85, 1.05, 0.85, 0.8, 0.95, 0.95]
        n_cols = len(cols)
        table_w = PW - 2 * M
        ratio_sum = sum(col_ratios)
        col_ws = [table_w * r / ratio_sum for r in col_ratios]
        col_x_starts = []
        acc = 0.0
        for w in col_ws:
            col_x_starts.append(acc)
            acc += w

        row_h = 8.5 * mm
        header_h = 11 * mm
        max_rows_per_page = 24

        total_rows = len(rows_data)
        idx = 0
        page_num = 1

        while idx < total_rows or (idx == 0 and total_rows == 0):
            y = PH - M

            # رأس الصفحة: نفس شعار وبيانات الشركة المعتمدة بباقي صفحات الفاتورة
            txt(M, y - 6, "Jadeite Factory", size=12, bold=True, align="left")
            txt(M, y - 13, "Saudi Arabia, Riyadh", size=8, align="left")
            txt(PW - M, y - 6, "مصنع جاديت للتصنيع", size=12, bold=True, align="right")
            txt(PW - M, y - 13, "المملكة العربية السعودية", size=8, align="right")
            logo_bottom = y - 13  # قيمة احتياطية إن تعذّر تحميل الشعار
            try:
                logo_bytes = base64.b64decode(APP_LOGO_B64)
                logo_img = ImageReader(io.BytesIO(logo_bytes))
                lw, lh = 45 * mm, 10 * mm
                logo_top = y - 4
                logo_bottom = logo_top - lh
                c.drawImage(logo_img, (PW - lw) / 2, logo_bottom, width=lw, height=lh, mask='auto', preserveAspectRatio=True)
            except Exception:
                pass
            y = min(y - 13, logo_bottom) - 9 * mm  # مسافة أمان واضحة أسفل أعمق عنصر بالرأس (الشعار أو نص الشركة)

            txt(PW / 2, y, "فاتورة مبيعات", size=16, bold=True, align="center", color=border_color)
            y -= 8 * mm
            name_line = f"العميل: {name}"
            name_size = fit_font_size(name_line, (PW - 2 * M) * 0.62, 11, bold=True, min_size=8)
            txt(PW - M, y, name_line, size=name_size, bold=True, align="right")
            txt(M, y, f"عدد الأسطر: {total_rows}", size=10, align="left")
            y -= 6.5 * mm
            txt(PW - M, y, f"التاريخ: {date_str}", size=11, align="right")
            if page_num > 1:
                txt(M, y, f"(تابع - صفحة {page_num})", size=10, align="left")
            y -= 8 * mm

            table_top = y
            rect(M, table_top, table_w, header_h, fill=header_fill, stroke_color=border_color)
            for i, lbl in enumerate(cols):
                cx = M + table_w - col_x_starts[i] - col_ws[i] / 2
                hdr_size = fit_font_size(lbl, col_ws[i] - 3 * mm, 10, bold=True, min_size=6.5)
                txt(cx, vcenter_baseline(table_top, header_h, hdr_size), lbl, size=hdr_size, bold=True, align="center", color=border_color)
                if i > 0:
                    c.setStrokeColor(border_color)
                    c.line(M + table_w - col_x_starts[i], table_top - header_h, M + table_w - col_x_starts[i], table_top)

            y = table_top - header_h
            page_rows = rows_data[idx: idx + max_rows_per_page]

            for row_i, data in enumerate(page_rows):
                rect(M, y, table_w, row_h, stroke_color=border_color)
                for i in range(1, n_cols):
                    c.setStrokeColor(border_color)
                    c.line(M + table_w - col_x_starts[i], y - row_h, M + table_w - col_x_starts[i], y)
                gold_v = data.get('gold', 0) or 0.0
                gems_v = data.get('gems', 0) or 0.0
                stones_v = data.get('stones', 0) or 0.0
                diamond_v = data.get('diamond', 0) or 0.0
                try:
                    stones_disc_v = float(data.get("stones_discount") or 0)
                except (ValueError, TypeError):
                    stones_disc_v = 0.0
                row_weight_standing = round(gold_v + gems_v + stones_v + diamond_v, 2)
                row_weight_bound = round(gold_v + gems_v + stones_disc_v + diamond_v, 2)
                khayas_v = data.get("khayas", 0) or 0.0
                values = [
                    str(idx + row_i + 1),
                    str(data.get("set_number") or "-"),
                    f"{gold_v:.2f}" if gold_v else "-",
                    f"{gems_v:.2f}" if gems_v else "-",
                    f"{stones_v:.2f}" if stones_v else "-",
                    str(data.get("stones_discount") or "-"),
                    f"{diamond_v:.2f}" if diamond_v else "-",
                    f"{khayas_v:.2f}" if khayas_v else "-",
                    f"{row_weight_standing:.2f}" if row_weight_standing else "-",
                    f"{row_weight_bound:.2f}" if row_weight_bound else "-",
                ]
                for i, val in enumerate(values):
                    cx = M + table_w - col_x_starts[i] - col_ws[i] / 2
                    val_size = fit_font_size(val, col_ws[i] - 3 * mm, 9.5, min_size=6.5)
                    txt(cx, vcenter_baseline(y, row_h, val_size), val, size=val_size, align="center")
                y -= row_h

            idx += len(page_rows)

            # صف الإجمالي والتوقيعات تظهر فقط في آخر صفحة من الجدول
            if idx >= total_rows:
                tot_gold = sum(d.get("gold", 0.0) for d in rows_data)
                tot_gems = sum(d.get("gems", 0.0) for d in rows_data)
                tot_stones = sum(d.get("stones", 0.0) for d in rows_data)
                tot_stones_discount = 0.0
                for d in rows_data:
                    try:
                        tot_stones_discount += float(d.get("stones_discount") or 0)
                    except ValueError:
                        pass
                tot_diamond = sum(d.get("diamond", 0.0) for d in rows_data)
                tot_khayas = sum(d.get("khayas", 0.0) or 0.0 for d in rows_data)
                tot_weight_standing = round(tot_gold + tot_gems + tot_stones + tot_diamond, 2)
                tot_weight_bound = round(tot_gold + tot_gems + tot_stones_discount + tot_diamond, 2)

                rect(M, y, table_w, row_h, fill=header_fill, stroke_color=border_color)
                # "الإجمالي" تمتد على عمودي التسلسل ورقم التشغيل، والقيم تحت كل عمود مادة
                total_lbl_w = col_ws[0] + col_ws[1]
                total_lbl_size = fit_font_size("الإجمالي", total_lbl_w - 3 * mm, 11, bold=True)
                txt(M + table_w - (col_x_starts[0] + col_ws[0] + col_ws[1]) / 2 - col_ws[0] / 2, vcenter_baseline(y, row_h, total_lbl_size), "الإجمالي", size=total_lbl_size, bold=True, align="center", color=border_color)
                totals_by_col = {2: tot_gold, 3: tot_gems, 4: tot_stones, 5: tot_stones_discount, 6: tot_diamond,
                                 7: tot_khayas, 8: tot_weight_standing, 9: tot_weight_bound}
                for i, val in totals_by_col.items():
                    cx = M + table_w - col_x_starts[i] - col_ws[i] / 2
                    val_txt = f"{val:.2f}"
                    tot_val_size = fit_font_size(val_txt, col_ws[i] - 3 * mm, 10.5, bold=True, min_size=7)
                    txt(cx, vcenter_baseline(y, row_h, tot_val_size), val_txt, size=tot_val_size, bold=True, align="center", color=border_color)
                for i in range(1, n_cols):
                    c.setStrokeColor(border_color)
                    c.line(M + table_w - col_x_starts[i], y - row_h, M + table_w - col_x_starts[i], y)
                y -= row_h

                sig_y = 20 * mm
                sig_w = table_w / 3
                for i, label in enumerate(["توقيع المدير", "توقيع المحاسب", "توقيع مسؤول الصالة"]):
                    cx = M + sig_w * i + sig_w / 2
                    c.line(M + sig_w * i + 10, sig_y, M + sig_w * (i + 1) - 10, sig_y)
                    txt(cx, sig_y - 6, label, size=9, bold=True, align="center")

            c.showPage()
            page_num += 1

            if total_rows == 0:
                break

    def generate_invoice_pdf(self, groups, output_path):
        """ملف الترحيل والطباعة بالترتيب: تذاكر أرقام التشغيل أولاً (إن كانت مفعّلة)، ثم فاتورة
        المبيعات الإجمالية (إن كانت كل الأسطر بنفس التاريخ والاسم)، ثم سند لكل رقم تشغيل
        بقالب المصنع الورقي"""
        if not REPORTLAB_AVAILABLE:
            messagebox.showerror("غير متاح", "ميزة طباعة الفواتير تحتاج تثبيت مكتبة reportlab أولاً:\npip install reportlab arabic-reshaper python-bidi")
            return False
        c = pdf_canvas.Canvas(output_path, pagesize=A4)

        # ١) تذاكر أرقام التشغيل (جاهزة للقص والمسح)
        if self.sale_tickets_with_invoice():
            tickets = self.sale_ticket_data(groups)
            if tickets:
                self.draw_sale_tickets(c, tickets)

        # ٢) فاتورة المبيعات
        if groups:
            dates = set(g[1] for g in groups)
            names = set(g[2] for g in groups)
            if len(dates) == 1 and len(names) == 1:
                batch_date, batch_name = groups[0][1], groups[0][2]
                rows_data = [self.get_invoice_group_data(sn, batch_date, batch_name) for sn, _, _ in groups]
                self.draw_sales_summary_pages(c, rows_data, batch_name, batch_date)

        # ٣) سندات أرقام التشغيل بالقالب الورقي
        for (set_number, date_str, name) in groups:
            data = self.get_invoice_group_data(set_number, date_str, name)
            self.draw_set_voucher_page(c, data)
            c.showPage()
        c.save()
        return True

    # ═══ تذاكر أرقام التشغيل في المبيعات: تذكرة لكل طقم مباع ببيانات بيعه، جاهزة للمسح ═══
    TICKETS_PER_ROW, TICKET_ROWS = 2, 4

    def sale_tickets_with_invoice(self):
        return bool(load_ui_prefs().get("sale_tickets_with_invoice", True))

    def sale_ticket_data(self, groups):
        """بيانات تذكرة لكل رقم تشغيل في فاتورة مبيعات — من بيانات الفاتورة نفسها
        (get_invoice_group_data). السطر بلا رقم تشغيل لا تذكرة له."""
        out = []
        for set_number, date_str, name in groups:
            sn = self.normalize_set_number(set_number)
            if not sn:
                continue
            d = self.get_invoice_group_data(set_number, date_str, name)
            manual = next((inv.get("رقم الفاتورة اليدوي") for inv in self.invoices.values()
                           if inv.get("set_number") == set_number and inv.get("التاريخ") == date_str
                           and inv.get("الاسم") == name and inv.get("رقم الفاتورة اليدوي")), "")
            try:
                stones_after = float(d.get("stones_discount") or 0.0)
            except (TypeError, ValueError):
                stones_after = 0.0
            gold, gems, stones, diamond = d["gold"], d["gems"], d["stones"], d["diamond"]
            bound = round(gold + gems + stones_after + diamond, 2)
            out.append({
                "set_number": sn, "invoice": manual or "", "date": str(date_str)[:10],
                "gold": round(gold, 2), "gems": round(gems, 2), "stones": round(stones, 2),
                "stones_after": round(stones_after, 2), "diamond": round(diamond, 2),
                "standing": round(gold + gems + stones + diamond, 2), "bound": bound,
                "qr": self.sale_ticket_qr(sn, bound), "barcode": self.sale_ticket_barcode(sn, bound),
            })
        return out

    # محتوى الباركود الخطي في تذكرة المبيعات (يُختار لهذا الجهاز من «العمليات»):
    #   one    → «88001 40.25»   رقم التشغيل والوزن المقيد في خانة واحدة بمسافة بينهما
    #   tab    → «88001⇥40.25»   خانتان: القارئ يكتب الرقم ثم Tab ينقل للخانة التالية ثم الوزن
    #   number → «88001»         رقم التشغيل وحده
    SALE_BARCODE_MODES = {"one": "الرقم والوزن في خانة واحدة", "tab": "الرقم ثم الوزن في خانتين (Tab)",
                          "number": "رقم التشغيل وحده"}
    DEFAULT_SALE_BARCODE_MODE = "one"

    def sale_barcode_mode(self):
        mode = load_ui_prefs().get("sale_barcode_mode", self.DEFAULT_SALE_BARCODE_MODE)
        return mode if mode in self.SALE_BARCODE_MODES else self.DEFAULT_SALE_BARCODE_MODE

    def sale_ticket_barcode(self, set_number, bound, mode=None):
        """نص الباركود الخطي (Code128): أي قارئ خطي يكتبه في البرنامج الآخر كما هو عند المسح"""
        mode = mode or self.sale_barcode_mode()
        if mode == "number":
            return set_number
        return f"{set_number}{chr(9) if mode == 'tab' else ' '}{bound:.2f}"

    @staticmethod
    def sale_ticket_qr(set_number, bound):
        """نص رمز QR التذكرة: أي تطبيق مسح (جوال أو جهاز) يعرض رقم التشغيل ووزنه المقيد
        مباشرة بلا إنترنت؛ والبرنامج يأخذ منه رقم التشغيل وحده (scanned_set_number)."""
        return f"رقم التشغيل: {set_number} | الوزن المقيد: {bound:.2f} جم"

    def draw_sale_tickets(self, c, tickets):
        """صفحات A4 بثماني تذاكر (٢×٤) بحدود قصّ منقّطة. كل تذكرة: رقم التشغيل بخط كبير،
        باركود Code128 برقم التشغيل ووزنه المقيد (أو بالرقم وحده — حسب اختيار الجهاز)، ورمز QR
        برقم التشغيل والوزن المقيد، والفاتورة والتاريخ، وأوزان البيع: الذهب، الفصوص، الأحجار، بعد الخصم،
        الماس، الوزن القائم، والوزن المقيد."""
        from reportlab.graphics.barcode import code128, qr
        from reportlab.graphics.shapes import Drawing
        from reportlab.graphics import renderPDF
        PW, PH = A4
        TW, TH = 96 * mm, 68 * mm
        mx = (PW - self.TICKETS_PER_ROW * TW) / 2
        my = (PH - self.TICKET_ROWS * TH) / 2
        per_page = self.TICKETS_PER_ROW * self.TICKET_ROWS

        def text(x, y, s, size=8, bold=False, align="right"):
            c.setFont(_ARABIC_FONT_BOLD_NAME if bold else _ARABIC_FONT_NAME, size)
            s = str(s)
            s = ar(s) if re.search("[\u0600-\u06FF]", s) else s
            {"right": c.drawRightString, "left": c.drawString, "center": c.drawCentredString}[align](x, y, s)

        def pair(x, y, label, value, size=9):
            """العنوان بالعربية ثم قيمته يساره كما هي (لا تنقلب التواريخ والأرقام داخل الجملة)"""
            c.setFont(_ARABIC_FONT_NAME, size)
            lab = ar(label + ": ")
            c.drawRightString(x, y, lab)
            value = str(value)
            c.setFont(_ARABIC_FONT_BOLD_NAME, size)
            c.drawRightString(x - c.stringWidth(lab, _ARABIC_FONT_NAME, size), y,
                              ar(value) if re.search("[\u0600-\u06FF]", value) else value)

        for n, t in enumerate(tickets):
            slot = n % per_page
            if n and slot == 0:
                c.showPage()
            col, row = slot % self.TICKETS_PER_ROW, slot // self.TICKETS_PER_ROW
            x0 = PW - mx - (col + 1) * TW          # من اليمين لليسار
            y0 = PH - my - (row + 1) * TH
            c.setDash(3, 2)
            c.setLineWidth(0.5)
            c.setStrokeColorRGB(0.55, 0.6, 0.66)
            c.rect(x0, y0, TW, TH)
            c.setDash()
            c.setStrokeColorRGB(0, 0, 0)
            p = 3 * mm
            right, left, top = x0 + TW - p, x0 + p, y0 + TH - p
            text(right, top - 3 * mm, "مصنع جاديت للتصنيع", 8.5, True)
            text(left, top - 3 * mm, "تذكرة طقم — مبيعات", 8.5, True, "left")
            c.setLineWidth(0.6)
            c.line(left, top - 4.8 * mm, right, top - 4.8 * mm)

            # رمز QR يساراً (رقم التشغيل + الوزن المقيد)، والرقم والباركود يمينه
            qs = 24 * mm
            widget = qr.QrCodeWidget(t["qr"])
            bx0, by0, bx1, by1 = widget.getBounds()
            dq = Drawing(qs, qs, transform=[qs / (bx1 - bx0), 0, 0, qs / (by1 - by0), 0, 0])
            dq.add(widget)
            renderPDF.draw(dq, c, left - 1.5 * mm, top - 5.5 * mm - qs)
            text(right, top - 11.5 * mm, f"رقم التشغيل: {t['set_number']}", 14, True)
            code = t.get("barcode") or t["set_number"]
            bar = code128.Code128(code, barHeight=10 * mm, barWidth=1.0, quiet=False)
            room = right - left - 26 * mm               # المساحة يمين رمز QR
            if bar.width > room:                        # يُضغط ليتسع دون أن يرقّ عن حدّ القراءة
                bar = code128.Code128(code, barHeight=10 * mm, barWidth=max(0.6, room / bar.width), quiet=False)
            bar.drawOn(c, right - bar.width, top - 24 * mm)
            pair(right, top - 29 * mm, "الفاتورة", t["invoice"] or "—")
            pair(right - 30 * mm, top - 29 * mm, "التاريخ", t["date"])

            # الأوزان: الصف الأول أربع خانات، والثاني الماس والقائم ثم المقيد عريضاً
            rows = ([("الذهب", t["gold"], 1), ("الفصوص", t["gems"], 1), ("الأحجار", t["stones"], 1),
                     ("بعد الخصم", t["stones_after"], 1)],
                    [("الماس", t["diamond"], 1), ("الوزن القائم", t["standing"], 1), ("الوزن المقيد", t["bound"], 2)])
            gw = (right - left) / 4
            gh = 11 * mm
            c.setLineWidth(0.4)
            for r_i, cells in enumerate(rows):
                cy0 = y0 + p + (1 - r_i) * gh
                cx1 = right
                for label, value, span in cells:
                    w = gw * span
                    strong = label == "الوزن المقيد"
                    if strong:
                        c.setFillColorRGB(0.92, 0.94, 0.97)
                        c.rect(cx1 - w, cy0, w, gh, fill=1, stroke=0)
                        c.setFillColorRGB(0, 0, 0)
                    c.rect(cx1 - w, cy0, w, gh)
                    text(cx1 - w / 2, cy0 + gh - 3.8 * mm, label, 7.5, strong, "center")
                    text(cx1 - w / 2, cy0 + 1.9 * mm, f"{value:.2f}", 11.5 if strong else 10, True, "center")
                    cx1 -= w
        c.showPage()

    def print_sale_tickets(self, groups):
        """ملف PDF بتذاكر أرقام التشغيل وحدها، يُفتح للمعاينة والطباعة"""
        if not REPORTLAB_AVAILABLE:
            messagebox.showerror("غير متاح", "ميزة الطباعة تحتاج تثبيت مكتبة reportlab أولاً.")
            return None
        tickets = self.sale_ticket_data(groups)
        if not tickets:
            self.toast("لا توجد أرقام تشغيل في هذه الفاتورة لطباعة تذاكرها", "warn")
            return None
        out_path = os.path.join(INVOICES_DIR, f"sale_tickets_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}.pdf")
        c = pdf_canvas.Canvas(out_path, pagesize=A4)
        self.draw_sale_tickets(c, tickets)
        c.save()
        self._open_file(out_path)
        return out_path

    def preview_invoice_groups(self, groups):
        """يولّد PDF للفواتير المحدّدة (صفحة لكل سطر) ويفتحه للمعاينة بعارض PDF الافتراضي"""
        if not groups:
            return
        if not REPORTLAB_AVAILABLE:
            messagebox.showwarning("تنبيه", "ميزة معاينة الفواتير تحتاج تثبيت مكتبة reportlab أولاً:\npip install reportlab arabic-reshaper python-bidi\n\nتم ترحيل المبيعات بنجاح رغم ذلك.")
            return
        out_dir = INVOICES_DIR
        fname = f"invoice_preview_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}.pdf"
        out_path = os.path.join(out_dir, fname)
        try:
            ok = self.generate_invoice_pdf(groups, out_path)
            if not ok:
                return
            self.last_generated_invoice_pdf = out_path
            self._open_file(out_path)
        except Exception as e:
            messagebox.showerror("خطأ", f"تعذّر إنشاء/فتح ملف الفاتورة:\n{e}")

    def print_invoice_groups(self, groups):
        """يولّد PDF للفواتير المحدّدة ويرسلها مباشرة للطابعة الافتراضية"""
        if not groups:
            messagebox.showwarning("تنبيه", "لا توجد فواتير لطباعتها.")
            return
        if not REPORTLAB_AVAILABLE:
            messagebox.showwarning("تنبيه", "ميزة طباعة الفواتير تحتاج تثبيت مكتبة reportlab أولاً:\npip install reportlab arabic-reshaper python-bidi")
            return
        out_dir = INVOICES_DIR
        fname = f"invoice_print_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}.pdf"
        out_path = os.path.join(out_dir, fname)
        try:
            ok = self.generate_invoice_pdf(groups, out_path)
            if not ok:
                return
            self.last_generated_invoice_pdf = out_path
            self._print_file(out_path)
            messagebox.showinfo("تم", f"تم إرسال {len(groups)} فاتورة إلى الطابعة الافتراضية.")
        except Exception as e:
            messagebox.showerror("خطأ", f"تعذّر طباعة الفاتورة:\n{e}")

    def _open_file(self, path):
        """يفتح ملفاً بالبرنامج الافتراضي لنظام التشغيل (لمعاينة PDF مثلاً)"""
        try:
            if sys.platform.startswith("win"):
                os.startfile(path)
            elif sys.platform == "darwin":
                subprocess.Popen(["open", path])
            else:
                subprocess.Popen(["xdg-open", path])
        except Exception as e:
            messagebox.showerror("خطأ", f"تعذّر فتح الملف تلقائياً، يمكنك فتحه يدوياً من:\n{path}\n\n{e}")

    def _print_file(self, path):
        """يرسل ملفاً للطباعة على الطابعة الافتراضية لنظام التشغيل"""
        try:
            if sys.platform.startswith("win"):
                os.startfile(path, "print")
            elif sys.platform == "darwin":
                subprocess.Popen(["lp", path])
            else:
                subprocess.Popen(["lp", path])
        except Exception as e:
            messagebox.showerror("خطأ", f"تعذّرت الطباعة المباشرة، تم فتح الملف بدلاً من ذلك لتطبعه يدوياً.\n{e}")
            self._open_file(path)

    # =========================================================================
    # --- رقم التشغيل: تتبّع رحلته كاملة، وتذكرة تشغيل بباركود ورمز QR ---
    # =========================================================================
    WORKER_SECTIONS = ("المصنعين", "المركبين")
    TRACE_STATUSES = ("ACTIVE", "SETTLED", "SETTLED_INOUT")

    def set_number_trace(self, set_no):
        """كل حركات رقم تشغيل في كل الفترات بترتيب التاريخ: الحركات التي تحمل الرقم نفسه
        (أياً كانت صيغة أرقامه)، ومعها بقية حركات صفّه عند المصنّع/المركّب (القبض والسلك
        والعيار تُسجَّل غالباً على الصف بلا رقم التشغيل). القيود اليومية مستثناة (أرقامها JE-n)."""
        key = self.normalize_set_number(set_no)
        if not key:
            return []
        workers = {n for sec in self.WORKER_SECTIONS for n in self.categories.get(sec, [])}
        direct, rows = [], set()
        for inv in self.invoices.values():
            if (inv.get("settled_status") not in self.TRACE_STATUSES or inv.get("النوع") in self.JOURNAL_TYPES
                    or self.normalize_set_number(inv.get("set_number")) != key):
                continue
            direct.append(inv)
            row = (inv.get("row_number") or "").strip()
            if row and inv.get("الاسم") in workers:
                rows.add((inv.get("الاسم"), self.inv_period(inv), row))
        seen = {id(i) for i in direct}
        same_row = [inv for inv in self.invoices.values()
                    if id(inv) not in seen and inv.get("settled_status") in self.TRACE_STATUSES
                    and (inv.get("الاسم"), self.inv_period(inv), (inv.get("row_number") or "").strip()) in rows]
        return sorted(direct + same_row, key=lambda i: (str(i.get("التاريخ", "")), i.get("رقم الفاتورة", 0)))

    def set_sale_move(self, moves):
        """آخر حركة بيع (ذهب/فصوص/ماس) في رحلة رقم التشغيل، أو None إن لم يُبع"""
        sales = [m for m in moves if m.get("النوع") in self.SALE_TYPES]
        return sales[-1] if sales else None

    def trace_section(self, inv):
        """القسم الذي تظهر فيه الحركة (لعمود «القسم» في التتبّع)"""
        for sec in self.WORKER_SECTIONS:
            if inv.get("الاسم") in self.categories.get(sec, []):
                return sec
        if inv.get("النوع") in self.SALE_TYPES or inv.get("النوع") in ("خياس طقوم", "صادر ذهب"):
            return "المبيعات"
        return inv.get("النوع", "")

    def job_ticket_info(self, set_no):
        """بيانات تذكرة التشغيل: أول صرف ذهب للرقم عند المصنّع/المركّب (وإلا أول حركة له)"""
        moves = self.set_number_trace(set_no)
        if not moves:
            return None
        worker_moves = [m for m in moves if self.trace_section(m) in self.WORKER_SECTIONS]
        first = next((m for m in worker_moves if m.get("النوع") == "صرف ذهب"), None) or \
            (worker_moves[0] if worker_moves else moves[0])
        # صرف العامل نفسه وحده: الذهب نفسه يُصرف للمصنّع ثم للمركّب فلا يُجمع مرتين
        issued = round(sum(m.get("الوزن", 0.0) or 0.0 for m in worker_moves
                           if m.get("النوع") == "صرف ذهب" and m.get("الاسم") == first.get("الاسم")), 2)
        return {"set_number": self.normalize_set_number(set_no), "worker": first.get("الاسم", ""),
                "section": self.trace_section(first), "row": (first.get("row_number") or "").strip(),
                "date": str(first.get("التاريخ", ""))[:10], "period": self.inv_period(first),
                "issued": issued, "moves": len(moves)}

    def print_job_ticket(self, set_no):
        """تذكرة تشغيل صغيرة (١٠٠×٧٠ مم): الرقم بخط كبير، باركود Code128 يقرؤه أي قارئ
        كأنه كُتب بلوحة المفاتيح، ورمز QR بالرقم نفسه، وبيانات الصرف الأول."""
        if not REPORTLAB_AVAILABLE:
            messagebox.showerror("غير متاح", "ميزة الطباعة تحتاج تثبيت مكتبة reportlab أولاً.")
            return None
        info = self.job_ticket_info(set_no)
        if not info:
            messagebox.showwarning("غير موجود", f"لا توجد حركات برقم التشغيل ({set_no}).")
            return None
        from reportlab.graphics.barcode import code128, qr
        from reportlab.graphics.shapes import Drawing
        from reportlab.graphics import renderPDF

        W, H = 100 * mm, 70 * mm
        code = info["set_number"]
        safe = re.sub(r"[^0-9A-Za-z_-]+", "_", code)
        out_path = os.path.join(INVOICES_DIR, f"job_ticket_{safe}_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}.pdf")
        c = pdf_canvas.Canvas(out_path, pagesize=(W, H))
        M = 4 * mm

        def txt(x, y, s, size=9, bold=False, align="right"):
            c.setFont(_ARABIC_FONT_BOLD_NAME if bold else _ARABIC_FONT_NAME, size)
            s = ar(s)
            if align == "right":
                c.drawRightString(x, y, s)
            elif align == "left":
                c.drawString(x, y, s)
            else:
                c.drawCentredString(x, y, s)

        c.setLineWidth(0.8)
        c.roundRect(2 * mm, 2 * mm, W - 4 * mm, H - 4 * mm, 3 * mm)
        txt(W - M, H - M - 4 * mm, "مصنع جاديت للتصنيع", size=10, bold=True)
        txt(M, H - M - 4 * mm, "تذكرة تشغيل", size=10, bold=True, align="left")
        c.line(M, H - M - 6.5 * mm, W - M, H - M - 6.5 * mm)

        # الرقم بخط كبير ثم الباركود بعرض مناسب لأي قارئ
        txt(W / 2, H - M - 15 * mm, f"رقم التشغيل: {code}", size=15, bold=True, align="center")
        bar = code128.Code128(code, barHeight=13 * mm, barWidth=max(0.6, min(1.4, 62 * mm / max(1, 11 * len(code) + 35))))
        bar.drawOn(c, M, H - M - 32 * mm)

        # QR بالرقم نفسه (يمسحه الجوال أو القارئ ثنائي الأبعاد)
        size = 24 * mm
        widget = qr.QrCodeWidget(code)
        x0, y0, x1, y1 = widget.getBounds()
        d = Drawing(size, size, transform=[size / (x1 - x0), 0, 0, size / (y1 - y0), 0, 0])
        d.add(widget)
        renderPDF.draw(d, c, W - M - size, 5 * mm)

        def pair(x, y, label, value, size=8.5):
            """العنوان بالعربية ثم قيمته يساره كما هي: التاريخ والفترة داخل جملة عربية
            كانت تنقلب (٢٠٢٦-٠٩ ← ٠٩-٢٠٢٦) بإعادة الترتيب ثنائي الاتجاه"""
            c.setFont(_ARABIC_FONT_NAME, size)
            label_s = ar(label + ": ")
            c.drawRightString(x, y, label_s)
            value = str(value)
            c.drawRightString(x - c.stringWidth(label_s, _ARABIC_FONT_NAME, size), y,
                              ar(value) if re.search("[\u0600-\u06FF]", value) else value)

        x = W - M - size - 3 * mm
        pair(x, 23 * mm, "العامل", f"{info['worker']} ({info['section']})")
        pair(x, 18.4 * mm, "الصف", info["row"] or "-")
        pair(x, 13.8 * mm, "الفترة", info["period"])
        pair(x, 9.2 * mm, "تاريخ الصرف", info["date"])
        pair(x, 4.6 * mm + 0.6 * mm, "صرف ذهب (جم)", f"{info['issued']:.2f}")
        c.showPage()
        c.save()
        self._open_file(out_path)
        return out_path

    def open_set_number_trace(self, set_no=None):
        """«تتبّع رقم التشغيل»: امسح الباركود أو اكتب الرقم ← رحلته كاملة بكل الأقسام والفترات"""
        if set_no is None:
            dlg = ctk.CTkInputDialog(title="تتبّع رقم التشغيل", text="امسح باركود التذكرة أو اكتب رقم التشغيل:")
            set_no = dlg.get_input()
        key = self.scanned_set_number(set_no)
        if not key:
            return None
        moves = self.set_number_trace(key)
        if not moves:
            messagebox.showinfo("لا توجد نتائج", f"لا توجد حركات برقم التشغيل ({key}) في أي فترة.")
            return None

        win = ctk.CTkToplevel(self)
        win.title(f"تتبّع رقم التشغيل {key}")
        win.geometry("1100x620")
        win.transient(self)
        win.focus_force()
        ctk.CTkLabel(win, text=f"🔎 رحلة رقم التشغيل ({key})", font=("Cairo", 19, "bold"),
                     text_color=UI_TITLE).pack(pady=(14, 2))
        info = self.job_ticket_info(key)
        sold = sorted({(m.get("رقم الفاتورة اليدوي") or "").strip() for m in moves
                       if self.trace_section(m) == "المبيعات" and (m.get("رقم الفاتورة اليدوي") or "").strip()})
        summary = (f"العامل: {info['worker']} ({info['section']}) — الصف {info['row'] or '-'} — "
                   f"صرف ذهب {info['issued']:.2f} جم — {len(moves)} حركة")
        if sold:
            summary += f" — بيع في الفاتورة: {'، '.join(sold)}"
        ctk.CTkLabel(win, text=summary, font=("Cairo", 13, "bold"), text_color=UI["muted"]).pack(pady=(0, 2))
        asm = self.describe_assembler_khayas(key)
        if asm:
            ctk.CTkLabel(win, text=asm, font=("Cairo", 12), text_color=UI["muted"]).pack(pady=(0, 6))

        btns = ctk.CTkFrame(win, fg_color="transparent")
        btns.pack(side="bottom", pady=(4, 12))
        frame = ttk.Frame(win)
        frame.pack(fill="both", expand=True, padx=18, pady=6)
        cols = ("التاريخ", "القسم", "الاسم", "الصف", "النوع", "الوزن", "الفترة", "البيان")
        tree = self.create_standard_treeview(frame, cols, height=14)
        for col, w in zip(cols, (150, 100, 150, 60, 150, 90, 80, 220)):
            tree.column(col, width=w, anchor="center")
        for m in moves:
            tree.insert("", "end", values=(
                str(m.get("التاريخ", ""))[:16], self.trace_section(m), m.get("الاسم", ""),
                (m.get("row_number") or "").strip() or "-", m.get("النوع", ""),
                f"{m.get('الوزن', 0.0) or 0.0:.2f}", self.inv_period(m), m.get("البيان") or ""))
        ctk.CTkButton(btns, text="🏷️ طباعة تذكرة التشغيل", width=200, height=40, font=("Cairo", 14, "bold"),
                      command=lambda: self.print_job_ticket(key), **BUTTON_STYLES["primary"]).pack(side="left", padx=6)
        # مُسح الطقم بعد بيعه: فاتورة بيعه وتذكرة البيع مباشرة من هنا
        sale = self.set_sale_move(moves)
        if sale is not None:
            sale_key = (sale.get("رقم الفاتورة اليدوي") or "", sale.get("التاريخ"), sale.get("الاسم"))
            ctk.CTkButton(btns, text="🧾 فاتورة البيع", width=150, height=40, font=("Cairo", 14, "bold"),
                          command=lambda: self.preview_invoice_groups(self.sale_invoice_groups(sale_key)),
                          **BUTTON_STYLES["secondary"]).pack(side="left", padx=6)
            ctk.CTkButton(btns, text="🏷️ تذكرة البيع", width=140, height=40, font=("Cairo", 14, "bold"),
                          command=lambda: self.print_sale_tickets(
                              [(sale.get("set_number") or "", sale.get("التاريخ"), sale.get("الاسم"))]),
                          **BUTTON_STYLES["secondary"]).pack(side="left", padx=6)
        ctk.CTkButton(btns, text="إغلاق", width=120, height=40, font=("Cairo", 14, "bold"),
                      command=win.destroy, **BUTTON_STYLES["secondary"]).pack(side="left", padx=6)
        return win

    def stage_selected_set_number(self):
        """رقم التشغيل من الصف المحدد في كشف العامل، وإلا من خانة رقم التشغيل في النموذج"""
        tree = getattr(self, "op_ledger_tree", None)
        try:
            sel = tree.selection() if tree is not None else ()
            if sel:
                cols = list(tree["columns"])
                if "رقم التشغيل" in cols:
                    value = str(tree.item(sel[0], "values")[cols.index("رقم التشغيل")]).strip()
                    if value and value != "-":
                        return self.normalize_set_number(value)
        except Exception:
            pass
        ent = getattr(self, "current_win_entries", {}).get("رقم التشغيل")
        return self.normalize_set_number(ent.get()) if ent is not None else ""

    def print_stage_job_ticket(self):
        set_no = self.stage_selected_set_number()
        if not set_no:
            messagebox.showwarning("تنبيه", "حدّد صفاً في كشف العامل أو اكتب رقم التشغيل في خانته أولاً.")
            return None
        return self.print_job_ticket(set_no)

    def on_stage_set_number_entered(self, event=None):
        """بعد مسح الباركود أو كتابة رقم التشغيل في المصنعين/المركبين: يوحّد أرقامه، ولو كان
        الرقم مسجّلاً لصفٍّ عند العامل نفسه تُملأ خانة «رقم الصف» تلقائياً (فيُكمل القبض على صفه)."""
        entries = getattr(self, "current_win_entries", {})
        set_ent, row_ent = entries.get("رقم التشغيل"), entries.get("رقم الصف")
        if set_ent is None:
            return
        typed = set_ent.get()
        clean = self.scanned_set_number(typed)
        if clean != typed:
            set_ent.delete(0, "end")
            set_ent.insert(0, clean)
        if not clean or row_ent is None or row_ent.get().strip():
            return
        owner, owner_row = self.find_row_by_set_number(self.current_op_cat, clean)
        if owner and owner_row and owner == self.clean_name(self.combo_op_name.get()):
            row_ent.insert(0, owner_row)

    # =========================================================================
    # --- تقرير أداء العمال: نسبة الفاقد إلى الإنتاج بالألف لكل عامل وفترة ---
    # =========================================================================
    TREND_STEP = 0.05          # فرق النسبة بالألف الذي يُعدّ تغيّراً لا ثباتاً

    def worker_performance_rows(self, cat, periods, open_period=None):
        """أداء عمال المصنعين أو المركبين عبر فترات، من دفتر العامل نفسه (calculate_single_ledger):

          • الإنتاج = «حجم الإنتاج» (المصنعون: المفنش ٨ + ٤، والمركبون: القبض).
          • الفاقد  = ذهب/صافي − المرجع ٧٥٠ = −الخياس: ما نقص عند العامل بعد المسموح ٨/٤
                      والراجع؛ سالبه زيادة لصالحه.
          • النسبة  = الفاقد ÷ الإنتاج × ١٠٠٠ (بالألف)، والاتجاه من آخر فترتين لهما نسبة.
        open_period: الفترة الجارية — قد يكون فيها ذهب صُرف ولم يُقبض بعد، فلا تدخل الاتجاه
        (كانت ستُظهر كل عامل «يزداد» في أول الشهر).
        يرجع الصفوف مرتبة من الأعلى نسبةً، وإجمالي القسم.
        """
        rows = []
        sec_prod = sec_loss = 0.0
        for name in self.categories.get(cat, []):
            cells, prod_sum, loss_sum = {}, 0.0, 0.0
            for p in periods:
                led = self.calculate_single_ledger(name, cat, target_month=p)
                prod, loss = round(led["حجم الإنتاج"], 2), round(-led["الخياس"], 2)
                if abs(prod) < 0.005 and abs(loss) < 0.005:
                    continue
                cells[p] = (prod, loss, round(loss / prod * 1000, 2) if prod > 0 else None)
                prod_sum += prod
                loss_sum += loss
            if not cells:
                continue
            ratios = [cells[p][2] for p in periods
                      if p in cells and cells[p][2] is not None and p != open_period]
            trend = "—"
            if len(ratios) >= 2:
                diff = ratios[-1] - ratios[-2]
                trend = ("⬆️ يزداد" if diff > self.TREND_STEP else "⬇️ يتحسّن" if diff < -self.TREND_STEP
                         else "➖ ثابت")
            rows.append({"name": name, "cells": cells, "production": round(prod_sum, 2),
                         "loss": round(loss_sum, 2), "trend": trend,
                         "ratio": round(loss_sum / prod_sum * 1000, 2) if prod_sum > 0 else None})
            sec_prod += prod_sum
            sec_loss += loss_sum
        rows.sort(key=lambda r: (r["ratio"] is None, -(r["ratio"] or 0.0), r["name"]))
        section = {"production": round(sec_prod, 2), "loss": round(sec_loss, 2),
                   "ratio": round(sec_loss / sec_prod * 1000, 2) if sec_prod > 0 else None}
        return rows, section

    def open_worker_performance_report(self, cat="المصنعين"):
        """نافذة «أداء العمال»: عمود لكل فترة بنسبة الفاقد بالألف، ثم الإجمالي والاتجاه.
        الصف الذي نسبته أعلى من متوسط القسم يظهر بلون التنبيه."""
        win = ctk.CTkToplevel(self)
        win.title("أداء العمال")
        win.geometry("1220x800")
        win.transient(self)
        win.focus_force()
        ctk.CTkLabel(win, text="📊 أداء العمال — نسبة الفاقد إلى الإنتاج (بالألف)", font=("Cairo", 19, "bold"),
                     text_color=UI_TITLE).pack(pady=(14, 2))
        ctk.CTkLabel(win, text="الفاقد = ذهب/صافي − المرجع ٧٥٠ (بعد المسموح ٨/٤)  ·  النسبة = الفاقد ÷ الإنتاج × ١٠٠٠  "
                               "·  الاتجاه من آخر فترتين منتهيتين  ·  السالب زيادة لصالح العامل",
                     font=("Cairo", 12), text_color=UI["muted"]).pack(pady=(0, 6))
        bar = ctk.CTkFrame(win, fg_color="transparent")
        bar.pack(pady=4)
        section_var = ctk.StringVar(value=cat)
        span_var = ctk.StringVar(value="آخر ٦ فترات")
        spans = {"آخر ٣ فترات": 3, "آخر ٦ فترات": 6, "آخر ١٢ فترة": 12, "كل الفترات": None}
        summary = ctk.CTkLabel(win, text="", font=("Cairo", 14, "bold"))
        summary.pack(pady=(2, 4))
        btns = ctk.CTkFrame(win, fg_color="transparent")
        btns.pack(side="bottom", pady=(4, 12))
        # اتجاه العامل المحدد مقابل متوسط قسمه عبر الفترات
        trend_box = ctk.CTkFrame(win, corner_radius=12, border_width=1, fg_color=(UI["surface"], "#171C23"),
                                 border_color=(UI["line"], "#2A313B"))
        trend_box.pack(side="bottom", fill="x", padx=18, pady=(2, 4))
        trend_head = ctk.CTkFrame(trend_box, fg_color="transparent")
        trend_head.pack(fill="x", padx=12, pady=(6, 0))
        trend_title = ctk.CTkLabel(trend_head, text="حدّد عاملاً لرؤية اتجاهه مقابل متوسط القسم",
                                   font=("Cairo", 13, "bold"), text_color=UI_TITLE)
        trend_title.pack(side="right")
        for si, name in enumerate(("العامل", "متوسط القسم")):
            item = ctk.CTkFrame(trend_head, fg_color="transparent")      # العلامة ملاصقة لاسمها، وبين البندين فراغ
            item.pack(side="left", padx=(0, 18))
            ctk.CTkLabel(item, text=name, font=("Cairo", 12),
                         text_color=(UI["ink"], "#E6EDF3")).pack(side="left", padx=(0, 5))
            ctk.CTkFrame(item, width=16, height=4, corner_radius=2,
                         fg_color=(CHART_SERIES["light"][si], CHART_SERIES["dark"][si])).pack(side="left")
        trend_chart = MiniChart(trend_box, kind="line", unit="‰", decimals=2, height=170)
        trend_chart.pack(fill="x", padx=10, pady=(0, 6))
        frame = ttk.Frame(win)
        frame.pack(fill="both", expand=True, padx=18, pady=6)
        state = {"tree": None, "cols": (), "rows": [], "title": "", "data": [], "periods": [], "avg": []}

        def show_trend(_e=None):
            tree = state["tree"]
            sel = tree.selection() if tree is not None else ()
            if not sel or not sel[0].startswith("w"):
                return
            r = state["data"][int(sel[0][1:])]
            P = state["periods"]
            trend_chart.set_data(P, [(r["name"], [(r["cells"].get(p) or (0, 0, None))[2] for p in P]),
                                     ("متوسط القسم", state["avg"])])
            trend_title.configure(text=f"اتجاه {r['name']} مقابل متوسط القسم (بالألف)")

        def build():
            sec = section_var.get()
            n = spans.get(span_var.get())
            recorded = sorted(p for p in self.get_recorded_periods() if p)
            periods = recorded[-n:] if n else recorded
            open_period = datetime.datetime.now().strftime("%Y-%m")
            rows, total = self.worker_performance_rows(sec, periods, open_period=open_period)
            for w in frame.winfo_children():
                w.destroy()
            cols = (("العامل",) + tuple(f"{p} جارية" if p == open_period else f"{p} ‰" for p in periods)
                    + ("الإنتاج", "الفاقد", "النسبة ‰", "الاتجاه"))
            tree = self.create_standard_treeview(frame, cols, height=14)
            for c in cols:
                tree.column(c, width=160 if c == "العامل" else 112 if "جارية" in c else 95, anchor="center")
            tree.tag_configure("warn", foreground=UI["danger"])
            avg = total["ratio"]
            table = []
            state["data"], state["periods"] = rows, periods
            state["avg"] = [self.worker_performance_rows(sec, [p])[1]["ratio"] for p in periods]
            for r in rows:
                vals = [r["name"]]
                for p in periods:
                    cell = r["cells"].get(p)
                    vals.append("—" if not cell else (f"{cell[2]:.2f}" if cell[2] is not None else f"فاقد {cell[1]:.2f}"))
                vals += [f"{r['production']:.2f}", f"{r['loss']:.2f}",
                         f"{r['ratio']:.2f}" if r["ratio"] is not None else "—", r["trend"]]
                warn = avg is not None and r["ratio"] is not None and r["ratio"] > avg + self.TREND_STEP
                tree.insert("", "end", iid=f"w{len(table)}", values=vals, tags=("warn",) if warn else ())
                table.append(tuple(vals))
            summary.configure(text=(
                f"{self.get_display_label(sec)}: {len(rows)} عامل — الإنتاج {total['production']:.2f} جم — "
                f"الفاقد {total['loss']:.2f} جم — متوسط القسم "
                + (f"{avg:.2f} ‰" if avg is not None else "—")))
            tree.bind("<<TreeviewSelect>>", show_trend)
            if table:
                tree.selection_set("w0")
                show_trend()
            state.update(tree=tree, cols=cols, rows=table,
                         title=f"📊 أداء العمال — {self.get_display_label(sec)} ({periods[0] if periods else ''} … "
                               f"{periods[-1] if periods else ''})")

        for value in self.WORKER_SECTIONS:
            ctk.CTkRadioButton(bar, text=self.get_display_label(value), value=value, variable=section_var,
                               command=build, font=("Cairo", 13, "bold")).pack(side="right", padx=8)
        ctk.CTkOptionMenu(bar, values=list(spans), variable=span_var, command=lambda _v: build(),
                          font=("Cairo", 13), width=140).pack(side="right", padx=12)

        def print_report():
            if state["rows"]:
                ratios = [1.4] + [0.8] * (len(state["cols"]) - 1)
                self.print_generic_table_screen(state["title"], state["cols"], ratios, state["rows"],
                                                "worker_performance", subtitle=summary.cget("text"))

        ctk.CTkButton(btns, text="🖨️ طباعة التقرير", width=170, height=40, font=("Cairo", 14, "bold"),
                      command=print_report, **BUTTON_STYLES["primary"]).pack(side="left", padx=6)
        ctk.CTkButton(btns, text="إغلاق", width=120, height=40, font=("Cairo", 14, "bold"),
                      command=win.destroy, **BUTTON_STYLES["secondary"]).pack(side="left", padx=6)
        build()
        return win

    # =========================================================================
    # --- لوحة المؤشرات: الأرقام التي تتابعها الإدارة، ورسومها عبر الفترات ---
    # =========================================================================
    DASH_SPANS = {"آخر ٦ فترات": 6, "آخر ١٢ فترة": 12, "كل الفترات": None}

    def dashboard_data(self, n_periods=12):
        """أرقام اللوحة من المصادر نفسها التي تبني الشاشات: دفتر الخزينة ومكوّنات الفترة،
        ودفاتر العمال (نسبة الفاقد)، وشاشة الخسائر (الفاقد الحالي)"""
        ledger = self.get_treasury_ledger()
        periods = [r["period"] for r in ledger]
        if n_periods:
            periods = periods[-n_periods:]
        closing = {r["period"]: round(r["closing"], 2) for r in ledger}
        comps = {p: self.treasury_period_components(p) for p in periods}
        month = self.current_display_month
        ratios = {}
        for sec in self.WORKER_SECTIONS:
            ratios[sec] = [self.worker_performance_rows(sec, [p])[1]["ratio"] for p in periods]
        boxes = []
        for cat in self.get_khayas_box_categories():
            cur = self.get_box_loss_summary(cat, month=month)["current"]
            if abs(cur) >= 0.005:
                boxes.append((self.get_display_label(cat), round(cur, 2)))
        boxes.sort(key=lambda b: -abs(b[1]))
        cur_comp = self.treasury_period_components(month)
        prev = [p for p in (r["period"] for r in ledger) if p < month]
        prev_comp = self.treasury_period_components(prev[-1]) if prev else None
        return {
            "periods": periods,
            "treasury": [closing[p] for p in periods],
            "sales": [round(-comps[p]["sales"], 2) for p in periods],
            "inbound": [round(comps[p]["inbound"], 2) for p in periods],
            "khayas": [round(-(comps[p]["boxes"] + comps[p]["workers"] + comps[p]["closed"]), 2) for p in periods],
            "ratios": ratios,
            "boxes": boxes,
            "month": month,
            "kpi": {
                "treasury": round(getattr(self, "current_treasury_balance", closing.get(month, 0.0)), 2),
                "total": round(getattr(self, "current_total_gold", 0.0), 2),
                "sales": round(-cur_comp["sales"], 2),
                "inbound": round(cur_comp["inbound"], 2),
                "khayas": round(-(cur_comp["boxes"] + cur_comp["workers"] + cur_comp["closed"]), 2),
                "prev_sales": round(-prev_comp["sales"], 2) if prev_comp else None,
                "prev_treasury": closing.get(prev[-1]) if prev else None,
                "ratio": {sec: self.worker_performance_rows(sec, [month])[1]["ratio"]
                          for sec in self.WORKER_SECTIONS},
            },
        }

    def build_dashboard_tab(self):
        tab = self.tabview.tab("لوحة المؤشرات")
        try:
            tab.configure(fg_color=(UI["canvas"], "#10141A"))
        except Exception:
            pass
        bar = ctk.CTkFrame(tab, corner_radius=12, fg_color=(UI["surface"], "#171C23"),
                           border_width=1, border_color=(UI["line"], "#2A313B"))
        bar.pack(fill="x", padx=16, pady=(8, 6))
        ctk.CTkLabel(bar, text="المدى:", font=("Cairo", 13, "bold"),
                     text_color=(UI["primary"], "#9CC0F5")).pack(side="right", padx=(12, 4), pady=8)
        self.dash_span = ctk.CTkOptionMenu(bar, values=list(self.DASH_SPANS), width=140, font=("Cairo", 13),
                                           command=lambda _v: self.refresh_dashboard())
        self.dash_span.set("آخر ١٢ فترة")
        self.dash_span.pack(side="right", padx=4, pady=8)
        ctk.CTkButton(bar, text="🔄 تحديث", width=100, height=32, font=("Cairo", 13, "bold"),
                      command=self.refresh_dashboard, **BUTTON_STYLES["secondary"]).pack(side="left", padx=6)
        ctk.CTkButton(bar, text="🩺 فحص السلامة", width=130, height=32, font=("Cairo", 13, "bold"),
                      command=self.open_integrity_check_window, **BUTTON_STYLES["secondary"]).pack(side="left", padx=6)
        self.lbl_dash_note = ctk.CTkLabel(bar, text="", font=("Cairo", 12), text_color=UI["muted"])
        self.lbl_dash_note.pack(side="right", padx=10)

        body = ctk.CTkScrollableFrame(tab, fg_color="transparent")
        body.pack(fill="both", expand=True, padx=10, pady=(0, 6))
        tiles = ctk.CTkFrame(body, fg_color="transparent")
        tiles.pack(fill="x", padx=4, pady=(2, 8))
        self.dash_tiles = {}
        specs = (("treasury", "رصيد الخزينة"), ("total", "الرصيد الحالي (الذهب كله)"),
                 ("khayas", "خياس الفترة"), ("ratio", "نسبة الفاقد إلى الإنتاج"),
                 ("sales", "مبيعات الفترة"))
        for i, (key, caption) in enumerate(specs):
            card = ctk.CTkFrame(tiles, corner_radius=14, border_width=1, fg_color=(UI["surface"], "#171C23"),
                                border_color=(UI["line"], "#2A313B"))
            card.grid(row=0, column=len(specs) - 1 - i, padx=5, sticky="nsew")
            tiles.grid_columnconfigure(len(specs) - 1 - i, weight=1, uniform="tile")
            ctk.CTkLabel(card, text=caption, font=("Cairo", 12), text_color=(UI["muted"], "#9AA4B2"),
                         anchor="e").pack(fill="x", padx=14, pady=(10, 0))
            value = ctk.CTkLabel(card, text="—", anchor="e",
                                 font=ctk.CTkFont(family="Cairo", size=30 if key == "treasury" else 22, weight="bold"),
                                 text_color=(UI["ink"], "#F2F4F7"))
            value.pack(fill="x", padx=14)
            sub = ctk.CTkLabel(card, text="", font=("Cairo", 11), anchor="e", text_color=(UI["muted"], "#9AA4B2"))
            sub.pack(fill="x", padx=14, pady=(0, 10))
            self.dash_tiles[key] = (value, sub)

        grid = ctk.CTkFrame(body, fg_color="transparent")
        grid.pack(fill="both", expand=True, padx=4)
        grid.grid_columnconfigure((0, 1), weight=1, uniform="chart")
        self.dash_charts = {}
        charts = (("treasury", "رصيد الخزينة آخر كل فترة (جم)", "line", "جم", None),
                  ("ratio", "نسبة الفاقد إلى الإنتاج (بالألف)", "line", "‰", ("المصنعين", "المركبين")),
                  ("flow", "المبيعات والوارد لكل فترة (جم)", "bars", "جم", ("المبيعات", "الوارد")),
                  ("boxes", "الفاقد الحالي في كل صندوق — الفترة المعروضة (جم)", "hbars", "جم", None))
        for i, (key, title, kind, unit, legend) in enumerate(charts):
            card = ctk.CTkFrame(grid, corner_radius=14, border_width=1, fg_color=(UI["surface"], "#171C23"),
                                border_color=(UI["line"], "#2A313B"))
            card.grid(row=i // 2, column=1 - i % 2, padx=5, pady=5, sticky="nsew")
            head = ctk.CTkFrame(card, fg_color="transparent")
            head.pack(fill="x", padx=12, pady=(10, 2))
            ctk.CTkLabel(head, text=title, font=("Cairo", 14, "bold"), text_color=UI_TITLE).pack(side="right")
            if legend:
                for si, name in enumerate(legend):
                    item = ctk.CTkFrame(head, fg_color="transparent")    # العلامة ملاصقة لاسمها، وبين البندين فراغ
                    item.pack(side="left", padx=(0, 16))
                    ctk.CTkLabel(item, text=self.get_display_label(name) if name in self.WORKER_SECTIONS else name,
                                 font=("Cairo", 12), text_color=(UI["ink"], "#E6EDF3")).pack(side="left", padx=(0, 5))
                    ctk.CTkFrame(item, width=16, height=4, corner_radius=2,
                                 fg_color=(CHART_SERIES["light"][si], CHART_SERIES["dark"][si])).pack(side="left")
            chart = MiniChart(card, kind=kind, unit=unit, decimals=2, height=230)
            chart.pack(fill="both", expand=True, padx=10, pady=(0, 4))
            ctk.CTkButton(card, text="📋 الأرقام", width=90, height=26, font=("Cairo", 11, "bold"),
                          command=lambda k=key, t=title: self.show_dashboard_table(k, t),
                          **BUTTON_STYLES["secondary"]).pack(anchor="w", padx=12, pady=(0, 8))
            self.dash_charts[key] = chart
        self.refresh_dashboard()

    def refresh_dashboard(self):
        tiles = getattr(self, "dash_tiles", None)
        if not tiles:
            return
        span = self.DASH_SPANS.get(self.dash_span.get(), 12) if hasattr(self, "dash_span") else 12
        try:
            data = self.dashboard_data(span)
        except Exception as e:
            log_cloud_error("تعذّر تحديث لوحة المؤشرات", e)
            return
        self._dash_data = data
        k = data["kpi"]

        def delta(cur, prev):
            if prev is None:
                return ""
            d = round(cur - prev, 2)
            arrow = "▲" if d > 0 else "▼" if d < 0 else "■"
            return f"{arrow} {en(abs(d))} عن الفترة السابقة"

        tiles["treasury"][0].configure(text=f"{en(k['treasury'])} جم")
        tiles["treasury"][1].configure(text=delta(k["treasury"], k["prev_treasury"]))
        tiles["total"][0].configure(text=f"{en(k['total'])} جم")
        tiles["total"][1].configure(text="الخزينة + ما في الصناديق")
        tiles["khayas"][0].configure(text=f"{en(k['khayas'])} جم")
        tiles["khayas"][1].configure(text=f"فترة {data['month']} — كل الصناديق والعمال")
        rs = k["ratio"]
        tiles["ratio"][0].configure(text="\n".join(
            f"{self.get_display_label(sec)}: " + (f"{rs[sec]:,.2f} ‰" if rs[sec] is not None else "—")
            for sec in self.WORKER_SECTIONS), font=ctk.CTkFont(family="Cairo", size=15, weight="bold"))
        tiles["ratio"][1].configure(text="الفاقد ÷ الإنتاج × ١٠٠٠ — الفترة المعروضة")
        tiles["sales"][0].configure(text=f"{en(k['sales'])} جم")
        tiles["sales"][1].configure(text=delta(k["sales"], k["prev_sales"]) or f"الوارد {en(k['inbound'])} جم")
        P = data["periods"]
        self.dash_charts["treasury"].set_data(P, [("رصيد الخزينة", data["treasury"])])
        self.dash_charts["ratio"].set_data(P, [(self.get_display_label(sec), data["ratios"][sec])
                                               for sec in self.WORKER_SECTIONS])
        self.dash_charts["flow"].set_data(P, [("المبيعات", data["sales"]), ("الوارد", data["inbound"])])
        self.dash_charts["boxes"].set_data([b[0] for b in data["boxes"]], [("الفاقد الحالي", [b[1] for b in data["boxes"]])])
        if hasattr(self, "lbl_dash_note"):
            self.lbl_dash_note.configure(text=f"{len(P)} فترة · حتى {P[-1] if P else '—'}")

    def show_dashboard_table(self, key, title):
        """عرض أرقام الرسم جدولاً (لمن يفضّل الأرقام، وللنسخ والطباعة)"""
        data = getattr(self, "_dash_data", None)
        if not data:
            return None
        if key == "boxes":
            cols, rows = ("الصندوق", "الفاقد الحالي"), [(n, f"{v:.2f}") for n, v in data["boxes"]]
        elif key == "ratio":
            cols = ("الفترة",) + tuple(self.get_display_label(s) + " ‰" for s in self.WORKER_SECTIONS)
            rows = [(p,) + tuple("—" if data["ratios"][s][i] is None else f"{data['ratios'][s][i]:.2f}"
                                 for s in self.WORKER_SECTIONS) for i, p in enumerate(data["periods"])]
        elif key == "flow":
            cols = ("الفترة", "المبيعات", "الوارد", "الخياس")
            rows = [(p, f"{data['sales'][i]:.2f}", f"{data['inbound'][i]:.2f}", f"{data['khayas'][i]:.2f}")
                    for i, p in enumerate(data["periods"])]
        else:
            cols = ("الفترة", "رصيد الخزينة آخرها")
            rows = [(p, f"{data['treasury'][i]:.2f}") for i, p in enumerate(data["periods"])]
        win = ctk.CTkToplevel(self)
        win.title(title)
        win.geometry("560x460")
        win.transient(self)
        ctk.CTkLabel(win, text=title, font=("Cairo", 15, "bold"), text_color=UI_TITLE).pack(pady=(12, 6))
        frame = ttk.Frame(win)
        frame.pack(fill="both", expand=True, padx=14, pady=(0, 6))
        tree = self.create_standard_treeview(frame, cols, height=12)
        for c in cols:
            tree.column(c, width=150, anchor="center")
        for r in rows:
            tree.insert("", "end", values=r)
        ctk.CTkButton(win, text="🖨️ طباعة", width=120, height=34, font=("Cairo", 13, "bold"),
                      command=lambda: self.print_generic_table_screen(title, cols, [1.0] * len(cols), rows,
                                                                      "dashboard_" + key),
                      **BUTTON_STYLES["primary"]).pack(pady=(0, 10))
        return win

    # =========================================================================
    # --- فحص سلامة الحسابات: كل شاشة تطابق الأخرى في كل فترة (قراءة فقط) ---
    # =========================================================================
    _DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}")
    _PERIOD_RE = re.compile(r"^\d{4}-(0[1-9]|1[0-2])$")

    def statement_balance(self, account, from_m="", to_m="", period_rows_only=False):
        """رصيد كشف حساب كما تعرضه شاشة «كشف حساب» (بطبيعة الحساب مدين/دائن)"""
        debit = self.is_debit_nature_account(account)
        bal = 0.0
        for r in self.get_account_ledger_rows(account, from_m or "", to_m or ""):
            if period_rows_only and r.get("is_opening"):
                continue
            bal += (r["مدين"] - r["دائن"]) if debit else (r["دائن"] - r["مدين"])
        return round(bal, 2)

    def run_integrity_checks(self):
        """يطابق أرقام الشاشات بعضها ببعض في كل فترة، ويفحص سلامة القيود والبيانات.

        يرجع (النتائج، الملاحظات): النتائج {المجموعة: [عدد المطابق، [المخالفات]]}،
        والملاحظات أمور تستحق النظر وليست أخطاء حسابية. لا يغيّر أي بيانات،
        والفترة المعروضة تعود كما كانت حتى لو فشل فحص.
        """
        results, notes = {}, []

        def check(group, cond, detail):
            entry = results.setdefault(group, [0, []])
            if cond:
                entry[0] += 1
            else:
                entry[1].append(detail)

        def close(a, b, tol=0.011):
            return abs(round(a, 2) - round(b, 2)) <= tol

        active = [i for i in self.invoices.values() if i.get("settled_status") == "ACTIVE"]
        # الفترات الصالحة وحدها تُطابَق شاشاتها؛ الحركة بفترة تالفة تُكشف في «سلامة الحركات»
        periods = sorted({self.inv_period(i) for i in active if self._PERIOD_RE.match(self.inv_period(i) or "")})
        saved_month = self.current_display_month
        try:
            # ١) الخزينة: الدفتر = التقرير الشهري = كشف «حساب الخزينة»، وكل فترة تبدأ بنهاية سابقتها
            ledger = {r["period"]: r for r in self.get_treasury_ledger()}
            report = {r["period"]: r for r in self.get_monthly_report_rows()}
            prev = None
            for p in periods:
                if p not in ledger:
                    check("الخزينة", False, f"{p}: الفترة غائبة عن دفتر الخزينة")
                    continue
                closing = ledger[p]["closing"]
                if p in report:
                    check("الخزينة", close(report[p]["end"], closing),
                          f"{p}: التقرير الشهري {report[p]['end']:.2f} ≠ دفتر الخزينة {closing:.2f}")
                if prev in ledger:
                    check("الخزينة", close(ledger[p]["carry"], ledger[prev]["closing"]),
                          f"{p}: رصيد أول الفترة {ledger[p]['carry']:.2f} ≠ نهاية {prev} {ledger[prev]['closing']:.2f}")
                st = self.statement_balance("حساب الخزينة", to_m=p)
                check("الخزينة", close(st, closing),
                      f"{p}: كشف «حساب الخزينة» {st:.2f} ≠ دفتر الخزينة {closing:.2f}")
                prev = p

            # ٢) كل صندوق خياس: الفاقد الحالي في شاشة الخسائر = كشف حساب الصندوق لفترته،
            #    وحسابا الفاقد والمسترجع = كشفاهما
            boxes = self.get_khayas_box_categories()
            for cat in boxes:
                acc = self.get_box_account_name(cat)
                for p in periods:
                    cur = self.get_current_unclosed_khayas(cat, month=p)
                    st = -self.statement_balance(acc, from_m=p, to_m=p, period_rows_only=True)
                    check("صناديق الخياس ↔ كشوفها", close(cur, st),
                          f"{self.get_display_label(cat)} {p}: الفاقد الحالي {cur:.2f} ≠ كشف «{acc}» {st:.2f}")
                loss_acc = self.get_box_loss_account(cat)
                lt, ls = self.get_box_loss_total(cat), self.statement_balance(loss_acc)
                check("حسابات الفاقد والمسترجع", close(lt, ls),
                      f"{self.get_display_label(cat)}: شاشة الخسائر {lt:.2f} ≠ كشف «{loss_acc}» {ls:.2f}")
                rec = self.get_box_recovery_name(cat)
                if rec:
                    rt, rs = self.get_box_recovered_total(cat), self.statement_balance(rec)
                    check("حسابات الفاقد والمسترجع", close(rt, rs),
                          f"{self.get_display_label(cat)}: المسترجع {rt:.2f} ≠ كشف «{rec}» {rs:.2f}")
            total_loss = round(sum(self.get_box_loss_total(c) for c in boxes), 2)
            parent = self.statement_balance(self.LOSS_PARENT_ACCOUNT)
            check("حسابات الفاقد والمسترجع", close(total_loss, parent),
                  f"مجموع حسابات الفاقد {total_loss:.2f} ≠ كشف «{self.LOSS_PARENT_ACCOUNT}» {parent:.2f}")

            # ٣) جدول كل مرحلة = الفاقد الحالي + المُقفل لصندوقها في كل فترة
            for cat in self.get_all_stage_categories():
                if cat == "خياس الطقوم":
                    continue
                madin, qabd, _m = self.get_stage_config(cat)
                recover = self.TREE_RETURN_NAME if cat == "الكاستنج" else None
                extra = self.stage_row_extra(qabd, recover)
                sign = extra[2] if extra else -1
                for p in periods:
                    self.current_display_month = p
                    rows = self.collect_stage_ops_rows(madin, qabd, recover)
                    table = round(sum(g["مدين"] - g["دائن"] + sign * g["مسترجع"] for _r, _n, g in rows), 2)
                    box = self.get_box_khayas_cumulative(cat, month=p)
                    closed = self.get_box_closed_total(cat, month=p)
                    check("جداول المراحل ↔ صناديقها", close(table, box + closed),
                          f"{self.get_display_label(cat)} {p}: إجمالي الجدول {table:.2f} ≠ "
                          f"الفاقد الحالي {box:.2f} + المُقفل {closed:.2f}")
            self.current_display_month = saved_month

            # ٤) المبيعات: جدول العمليات = كشف «المبيعات» لكل فترة
            for p in periods:
                ops = round(sum(g["ذهب"] + g["فصوص"] + g["أحجار بعد الخصم"] + g["الماس"]
                                for g in self.get_sale_invoice_groups(p)), 2)
                st = self.statement_balance("المبيعات", from_m=p, to_m=p, period_rows_only=True)
                check("المبيعات", close(ops, st), f"{p}: جدول العمليات {ops:.2f} ≠ كشف «المبيعات» {st:.2f}")

            # ٥) المواد: الرصيد = كشف حسابها
            for mat, acc in (("فصوص وأحجار", "حساب فصوص وأحجار"), ("الماس", "حساب الألماس")):
                a, b = self.get_material_balance(mat), self.statement_balance(acc)
                check("المواد", close(a, b), f"{mat}: الرصيد {a:.2f} ≠ كشف «{acc}» {b:.2f}")

            # ٦) القيود اليومية: كل رقم قيد طرفان (مدين ودائن) بالوزن نفسه وفي الفترة نفسها
            legs_by_ref, no_ref = {}, 0
            for inv in active:
                if inv.get("النوع") not in self.JOURNAL_TYPES:
                    continue
                ref = inv.get("set_number") or ""
                if ref:
                    legs_by_ref.setdefault(ref, []).append(inv)
                else:
                    no_ref += 1
            for ref, legs in sorted(legs_by_ref.items()):
                debit = [l for l in legs if l["النوع"] == "قيد يومي مدين"]
                credit = [l for l in legs if l["النوع"] == "قيد يومي دائن"]
                if len(debit) != 1 or len(credit) != 1:
                    check("القيود اليومية", False,
                          f"{ref}: {len(debit)} طرف مدين و{len(credit)} طرف دائن (المفروض طرف لكلٍّ)")
                    continue
                d, c = debit[0], credit[0]
                check("القيود اليومية", close(d["الوزن"], c["الوزن"], tol=0.005)
                      and self.inv_period(d) == self.inv_period(c),
                      f"{ref}: المدين {d['الوزن']:.2f} ({self.inv_period(d)}) ≠ الدائن {c['الوزن']:.2f} "
                      f"({self.inv_period(c)})")
            if no_ref:
                notes.append(f"{no_ref} طرف قيد يومي بلا رقم قيد (قيود قديمة لا يمكن ربط طرفيها)")

            # ٧) سلامة كل حركة: تاريخ وفترة صحيحان ووزن رقمي غير سالب
            for inv in self.invoices.values():
                problems = []
                if not self._DATE_RE.match(str(inv.get("التاريخ") or "")):
                    problems.append(f"تاريخ غير صالح «{inv.get('التاريخ')}»")
                if not self._PERIOD_RE.match(self.inv_period(inv) or ""):
                    problems.append(f"فترة غير صالحة «{self.inv_period(inv)}»")
                w = inv.get("الوزن")
                if not isinstance(w, (int, float)) or w < 0:
                    problems.append(f"وزن غير صالح {w!r}")
                check("سلامة الحركات", not problems,
                      f"حركة {inv.get('رقم الفاتورة')} ({inv.get('الاسم')} — {inv.get('النوع')}): "
                      + "، ".join(problems))

            # ٨) الذاكرة = قاعدة البيانات (ما تراه الشاشات هو المحفوظ فعلاً)
            if getattr(self, "db_path", None) and os.path.exists(self.db_path):
                with sqlite3.connect(self.db_path) as conn:
                    db = {r[0]: r for r in conn.execute(
                        "SELECT invoice_id, name, op_type, weight, settled_status FROM invoices")}
                only_mem, only_db = set(self.invoices) - set(db), set(db) - set(self.invoices)
                check("الذاكرة = القاعدة", not only_mem and not only_db,
                      f"حركات في الشاشات لا في القاعدة: {len(only_mem)}، وفي القاعدة لا في الشاشات: {len(only_db)}")
                diff = [i for i in set(db) & set(self.invoices)
                        if (self.invoices[i].get("الاسم"), self.invoices[i].get("النوع"),
                            round(self.invoices[i].get("الوزن") or 0.0, 4), self.invoices[i].get("settled_status"))
                        != (db[i][1], db[i][2], round(db[i][3] or 0.0, 4), db[i][4])]
                check("الذاكرة = القاعدة", not diff, f"{len(diff)} حركة تختلف بين الشاشات والقاعدة (مثال {sorted(diff)[:3]})")

            # ملاحظة: أسماء في القيود غير مسجّلة في شجرة الحسابات (غالباً خطأ كتابة)
            known = set(self.get_journal_entry_account_options())
            unknown = sorted({i.get("الاسم") for i in active if i.get("النوع") in self.JOURNAL_TYPES
                              and i.get("الاسم") not in known})
            if unknown:
                notes.append("أسماء في القيود اليومية غير مسجّلة في شجرة الحسابات: " + "، ".join(unknown[:8])
                             + (" …" if len(unknown) > 8 else ""))
        finally:
            self.current_display_month = saved_month
        return results, notes

    def integrity_report_text(self, results, notes, seconds=None):
        bad = sum(len(v[1]) for v in results.values())
        good = sum(v[0] for v in results.values())
        lines = [f"فحص سلامة الحسابات — {datetime.datetime.now().strftime('%Y-%m-%d %H:%M')}",
                 ("✅ كل الحسابات متطابقة" if not bad else f"⚠️ {bad} مخالفة") + f" — {good} مطابقة"
                 + (f" ({seconds:.1f} ث)" if seconds is not None else ""), ""]
        for group, (ok_n, fails) in results.items():
            lines.append(f"{'✔' if not fails else '✘'} {group}: {ok_n} مطابق" + (f"، {len(fails)} مخالف" if fails else ""))
            lines.extend(f"     • {d}" for d in fails[:50])
            if len(fails) > 50:
                lines.append(f"     … و{len(fails) - 50} غيرها")
        if notes:
            lines.append("")
            lines.extend(f"ℹ️ {n}" for n in notes)
        return "\n".join(lines)

    def open_integrity_check_window(self):
        """نافذة «فحص سلامة الحسابات»: ملخص لكل مجموعة ثم تفصيل المخالفات بقيمها"""
        win = ctk.CTkToplevel(self)
        win.title("فحص سلامة الحسابات")
        win.geometry("920x720")
        win.transient(self)
        win.focus_force()

        ctk.CTkLabel(win, text="🩺 فحص سلامة الحسابات", font=("Cairo", 20, "bold"),
                     text_color=(UI["title"], "#C9D6E8")).pack(pady=(14, 0))
        ctk.CTkLabel(win, text="يطابق الخزينة والصناديق والكشوف والمبيعات والمواد والقيود في كل فترة — قراءة فقط",
                     font=("Cairo", 12), text_color=UI["muted"]).pack(pady=(0, 6))
        summary = ctk.CTkLabel(win, text="جاري الفحص…", font=("Cairo", 16, "bold"), corner_radius=10,
                               fg_color=(UI["surface_alt"], "#1D232B"), height=40)
        summary.pack(fill="x", padx=18, pady=6)

        btns = ctk.CTkFrame(win, fg_color="transparent")
        btns.pack(side="bottom", pady=(4, 12))
        frame = ttk.Frame(win)
        frame.pack(fill="x", padx=18, pady=4)
        cols = ("المجموعة", "المطابق", "المخالف")
        tree = self.create_standard_treeview(frame, cols, height=9)
        for c, w in zip(cols, (360, 120, 120)):
            tree.column(c, width=w, anchor="center")
        details = ctk.CTkTextbox(win, font=("Cairo", 13), wrap="word")
        details.pack(fill="both", expand=True, padx=18, pady=6)
        try:
            details._textbox.tag_configure("rtl", justify="right")
        except Exception:
            pass
        state = {"text": ""}

        def run():
            summary.configure(text="جاري الفحص…")
            win.update_idletasks()
            t0 = time.time()
            try:
                results, notes = self.run_integrity_checks()
            except Exception as e:
                log_cloud_error("تعذّر فحص سلامة الحسابات", e)
                summary.configure(text=f"تعذّر إكمال الفحص: {e}", text_color=UI["danger"])
                return
            seconds = time.time() - t0
            for item in tree.get_children():
                tree.delete(item)
            bad = 0
            for group, (ok_n, fails) in results.items():
                bad += len(fails)
                tree.insert("", "end", values=(("✔ " if not fails else "✘ ") + group, ok_n, len(fails)),
                            tags=("bad",) if fails else ())
            tree.tag_configure("bad", foreground=UI["danger"])
            good = sum(v[0] for v in results.values())
            summary.configure(
                text=(f"✅ كل الحسابات متطابقة — {good} مطابقة" if not bad
                      else f"⚠️ {bad} مخالفة تحتاج مراجعة — {good} مطابقة"),
                text_color=UI["success"] if not bad else UI["danger"])
            state["text"] = self.integrity_report_text(results, notes, seconds)
            details.configure(state="normal")
            details.delete("1.0", "end")
            details.insert("1.0", state["text"], "rtl")
            details.configure(state="disabled")

        def copy_report():
            if state["text"]:
                self.clipboard_clear()
                self.clipboard_append(state["text"])
                summary.configure(text=summary.cget("text") + "  —  نُسخ التقرير")

        for text, cmd, style in (("🔄 إعادة الفحص", run, "primary"), ("📋 نسخ التقرير", copy_report, "secondary"),
                                 ("إغلاق", win.destroy, "secondary")):
            ctk.CTkButton(btns, text=text, command=cmd, width=150, height=40, font=("Cairo", 14, "bold"),
                          **BUTTON_STYLES[style]).pack(side="left", padx=6)
        win.after(80, run)
        return win

    # =========================================================================
    # --- القيود اليومية: نظام محاسبي عام (من حساب مدين / إلى حساب دائن) يؤثر في أي حساب بالنظام ---
    # =========================================================================
    def get_journal_entry_account_options(self):
        """كل الحسابات المعروفة بالنظام + أي اسم جديد استُخدم سابقاً بقيد يومي (لخانتي المدين والدائن)"""
        return self.get_account_statement_options()

    def build_journal_entries_tab(self):
        tab = self.tabview.tab("القيود اليومية")

        ctk.CTkLabel(tab, text="📖 القيود اليومية", font=ctk.CTkFont(family="Cairo", size=18, weight="bold"), text_color="#d4af37").pack(pady=(15, 8))

        date_row = ctk.CTkFrame(tab, fg_color="transparent")
        date_row.pack(pady=6)
        ctk.CTkLabel(date_row, text="التاريخ:", font=("Cairo", 14, "bold"), text_color="#1f77b4").pack(side="right", padx=5)
        self.je_date = ctk.CTkEntry(date_row, font=("Cairo", 14), justify="center", width=140, height=38)
        self.je_date.insert(0, self.get_smart_default_date())
        self.je_date.pack(side="right", padx=5)

        self.je_invoice_display = ctk.CTkLabel(date_row, text=f"# {self.invoice_counter + 1}", font=("Cairo", 15, "bold"), text_color="#d4af37", fg_color=(UI["surface_alt"], "#1D232B"), corner_radius=6, width=90, height=38)
        self.je_invoice_display.pack(side="right", padx=5)
        ctk.CTkLabel(date_row, text="رقم الفاتورة:", font=("Cairo", 14, "bold"), text_color="#1f77b4").pack(side="right", padx=5)

        # ====== الصف الأول: من حساب (مدين) ======
        row1 = ctk.CTkFrame(tab, corner_radius=10)
        row1.pack(fill="x", padx=30, pady=8)
        ctk.CTkLabel(row1, text="من حساب (مدين):", font=("Cairo", 15, "bold"), text_color="#e74c3c").pack(side="right", padx=10, pady=12)
        self.je_from_name = ctk.CTkComboBox(row1, values=self.get_journal_entry_account_options(), font=("Cairo", 14), justify="right", width=280, height=38)
        self.je_from_name.set("")
        self.je_from_name.pack(side="right", padx=10, pady=12)
        self.bind_name_autocomplete(self.je_from_name, self.get_journal_entry_account_options)

        # ====== الصف الثاني: إلى حساب (دائن) ======
        row2 = ctk.CTkFrame(tab, corner_radius=10)
        row2.pack(fill="x", padx=30, pady=8)
        ctk.CTkLabel(row2, text="إلى حساب (دائن):", font=("Cairo", 15, "bold"), text_color="#2ecc71").pack(side="right", padx=10, pady=12)
        self.je_to_name = ctk.CTkComboBox(row2, values=self.get_journal_entry_account_options(), font=("Cairo", 14), justify="right", width=280, height=38)
        self.je_to_name.set("")
        self.je_to_name.pack(side="right", padx=10, pady=12)
        self.bind_name_autocomplete(self.je_to_name, self.get_journal_entry_account_options)

        amount_row = ctk.CTkFrame(tab, fg_color="transparent")
        amount_row.pack(pady=10)
        ctk.CTkLabel(amount_row, text="الوزن / القيمة:", font=("Cairo", 15, "bold"), text_color="#1f77b4").pack(side="right", padx=8)
        self.je_amount = ctk.CTkEntry(amount_row, justify="center", font=("Cairo", 15), width=140, height=40)
        self.je_amount.pack(side="right", padx=8)

        # البيان: سبب القيد يُحفظ على طرفيه ويظهر في الجدول وكشف الحساب والطباعة
        note_row = ctk.CTkFrame(tab, fg_color="transparent")
        note_row.pack(pady=(0, 4))
        ctk.CTkLabel(note_row, text="البيان:", font=("Cairo", 15, "bold"), text_color="#1f77b4").pack(side="right", padx=8)
        self.je_note = ctk.CTkEntry(note_row, justify="right", font=("Cairo", 14), width=420, height=38,
                                    placeholder_text="سبب القيد (اختياري)")
        self.je_note.pack(side="right", padx=8)

        btn_submit = ctk.CTkButton(tab, text="✅ ترحيل العملية", font=ctk.CTkFont(family="Cairo", size=16, weight="bold"), height=46, fg_color="#144d75", hover_color="#0d3350", command=self.submit_journal_entry)
        btn_submit.pack(pady=15)

        self.lbl_je_status = ctk.CTkLabel(tab, text="", font=("Cairo", 13, "bold"), text_color="#2ecc71")
        self.lbl_je_status.pack()

        ctk.CTkLabel(tab, text="آخر القيود اليومية المرحّلة", font=("Cairo", 14, "bold"), text_color="#d4af37").pack(pady=(15, 4))
        self.je_table_frame = ttk.Frame(tab)
        self.je_table_frame.pack(fill="both", expand=True, padx=20, pady=(0, 8))
        self.je_tree = None

        btn_print_je = ctk.CTkButton(tab, text="🖨️ طباعة القيود اليومية", font=("Cairo", 14, "bold"), fg_color="#144d75", hover_color="#0d3350", height=40, command=self.print_journal_entries_screen)
        btn_print_je.pack(pady=(0, 15))

        self.refresh_journal_entries_table()

    def print_journal_entries_screen(self):
        cols = ("التاريخ", "من حساب (مدين)", "إلى حساب (دائن)", "القيمة", "البيان")
        col_ratios = [1.0, 1.3, 1.3, 0.8, 1.4]
        debit_by_ref, credit_by_ref = {}, {}
        for inv in self.invoices.values():
            if inv.get("settled_status") != "ACTIVE": continue
            ref = inv.get("set_number", "")
            if inv.get("النوع") == "قيد يومي مدين":
                debit_by_ref[ref] = inv
            elif inv.get("النوع") == "قيد يومي دائن":
                credit_by_ref[ref] = inv
        refs = sorted(set(debit_by_ref) | set(credit_by_ref),
                      key=lambda r: (debit_by_ref.get(r) or credit_by_ref.get(r)).get("التاريخ", ""))
        rows = []
        for ref in refs:
            d = debit_by_ref.get(ref)
            cr = credit_by_ref.get(ref)
            base = d or cr
            rows.append((base.get("التاريخ", "")[:16], d.get("الاسم", "-") if d else "-", cr.get("الاسم", "-") if cr else "-",
                         f"{base.get('الوزن', 0):.2f}", self.journal_note(d, cr)))
        self.print_generic_table_screen("📖 القيود اليومية", cols, col_ratios, rows, "journal_entries_screen")

    def submit_journal_entry(self):
        from_name = self.je_from_name.get().strip()
        to_name = self.je_to_name.get().strip()
        date_val = self.je_date.get().strip()

        if not from_name or not to_name:
            messagebox.showwarning("تنبيه", "الرجاء إدخال اسم حساب المدين واسم حساب الدائن.")
            return
        if from_name == to_name:
            messagebox.showwarning("تنبيه", "لا يمكن أن يكون حساب المدين وحساب الدائن نفس الاسم.")
            return
        date_val = self.read_entry_date(date_val)
        if not date_val:
            return
        note = self.je_note.get().strip() if hasattr(self, "je_note") else ""
        # اسم غير مسجّل غالباً خطأ كتابة: قيدٌ عليه يُنشئ حساباً وهمياً لا يظهر في
        # أرصدة الموردين ولا الصناديق. لا نمنعه (قد يكون حساباً جديداً مقصوداً)، بل نؤكّد
        known = set(self.get_journal_entry_account_options())
        unknown = [n for n in (from_name, to_name) if n not in known]
        if unknown and not messagebox.askyesno(
                "اسم غير مسجّل",
                "الاسم التالي غير مسجّل في شجرة الحسابات:\n"
                + "\n".join(f"• {n}" for n in unknown)
                + "\n\nتأكد من كتابته كما هو مسجّل (مثلاً اسم المورد).\n"
                  "هل تريد المتابعة وإنشاء حساب جديد بهذا الاسم؟"):
            return
        try:
            amount = round(float(self.je_amount.get().strip()), 2)
            if amount <= 0: raise ValueError
        except ValueError:
            messagebox.showerror("خطأ", "الرجاء إدخال قيمة صحيحة أكبر من صفر.")
            return

        if not messagebox.askyesno("تأكيد الترحيل", f"هل أنت متأكد من ترحيل هذا القيد اليومي؟\nمن حساب (مدين): {from_name}\nإلى حساب (دائن): {to_name}\nالقيمة: {amount:.2f}"
                                   + (f"\nالبيان: {note}" if note else "")):
            return

        full_dt = f"{date_val} {datetime.datetime.now().strftime('%H:%M:%S')}"
        entry_ref = f"JE-{self.invoice_counter + 1}"

        self.invoice_counter += 1
        inv_from = {"رقم الفاتورة": self.invoice_counter, "التاريخ": full_dt, "الاسم": from_name,
                    "النوع": "قيد يومي مدين", "الوزن": amount, "البيان": note, "settled_status": "ACTIVE",
                    "trees_count": 0.0, "قبل": 0.0, "بعد": 0.0, "set_number": entry_ref}
        self.invoices[self.invoice_counter] = inv_from
        self.save_invoice_to_db(self.invoice_counter, inv_from)

        self.invoice_counter += 1
        inv_to = {"رقم الفاتورة": self.invoice_counter, "التاريخ": full_dt, "الاسم": to_name,
                  "النوع": "قيد يومي دائن", "الوزن": amount, "البيان": note, "settled_status": "ACTIVE",
                  "trees_count": 0.0, "قبل": 0.0, "بعد": 0.0, "set_number": entry_ref}
        self.invoices[self.invoice_counter] = inv_to
        self.save_invoice_to_db(self.invoice_counter, inv_to)

        self.je_from_name.set("")
        self.je_to_name.set("")
        self.je_amount.delete(0, 'end')
        if hasattr(self, "je_note"):
            self.je_note.delete(0, 'end')

        self.register_operation_period(date_val)
        self.recalculate_all()
        self.lbl_je_status.configure(text="✅ تم ترحيل القيد اليومي بنجاح")
        self.after(2500, lambda: self.lbl_je_status.configure(text=""))
        if messagebox.askyesno("طباعة", "هل تريد طباعة القيد؟"):
            self.print_single_journal_entry(entry_ref)

    def print_single_journal_entry(self, entry_ref):
        """يطبع قيداً يومياً واحداً بعينه بقالب فاتورة (من حساب / إلى حساب / القيمة / التاريخ)"""
        debit_inv = credit_inv = None
        for inv in self.invoices.values():
            if inv.get("set_number") != entry_ref: continue
            if inv.get("النوع") == "قيد يومي مدين": debit_inv = inv
            elif inv.get("النوع") == "قيد يومي دائن": credit_inv = inv
        if not debit_inv or not credit_inv:
            return
        cols = ("رقم القيد", "التاريخ", "من حساب (مدين)", "إلى حساب (دائن)", "القيمة", "البيان")
        col_ratios = [0.8, 1.1, 1.3, 1.3, 0.8, 1.0]
        rows = [(entry_ref, debit_inv["التاريخ"][:16], debit_inv["الاسم"], credit_inv["الاسم"],
                 f"{debit_inv['الوزن']:.2f}", self.journal_note(debit_inv, credit_inv) or "قيد يومي")]
        self.print_generic_table_screen("📖 فاتورة قيد يومي", cols, col_ratios, rows, "journal_entry_operation")

    @staticmethod
    def journal_note(debit, credit):
        """بيان القيد من أي طرفيه (القيود القديمة بلا بيان تبقى فارغة)"""
        for leg in (debit, credit):
            text = str((leg or {}).get("البيان") or "").strip()
            if text:
                return text
        return ""

    def refresh_journal_entries_table(self):
        if not hasattr(self, 'je_table_frame') or not self.je_table_frame:
            return
        for widget in self.je_table_frame.winfo_children():
            widget.destroy()

        if hasattr(self, 'je_invoice_display'):
            self.je_invoice_display.configure(text=f"# {self.invoice_counter + 1}")
        if hasattr(self, 'je_from_name'):
            self.je_from_name.configure(values=self.get_journal_entry_account_options())
        if hasattr(self, 'je_to_name'):
            self.je_to_name.configure(values=self.get_journal_entry_account_options())

        cols = ("التاريخ", "من حساب (مدين)", "إلى حساب (دائن)", "القيمة", "البيان")
        self.je_tree = self.create_standard_treeview(self.je_table_frame, cols, height=10)
        for c in cols:
            w = 220 if "حساب" in c else 260 if c == "البيان" else 150
            self.je_tree.column(c, width=w, anchor="center")

        debit_by_ref, credit_by_ref = {}, {}
        for inv in self.invoices.values():
            if inv.get("settled_status") != "ACTIVE": continue
            ref = inv.get("set_number", "")
            if inv.get("النوع") == "قيد يومي مدين":
                debit_by_ref[ref] = inv
            elif inv.get("النوع") == "قيد يومي دائن":
                credit_by_ref[ref] = inv

        refs = sorted(set(debit_by_ref) | set(credit_by_ref),
                      key=lambda r: (debit_by_ref.get(r) or credit_by_ref.get(r)).get("التاريخ", ""), reverse=True)

        for ref in refs[:150]:
            d = debit_by_ref.get(ref)
            cr = credit_by_ref.get(ref)
            base = d or cr
            self.je_tree.insert("", "end", values=(
                base.get("التاريخ", ""), d.get("الاسم", "-") if d else "-", cr.get("الاسم", "-") if cr else "-",
                f"{base.get('الوزن', 0):.2f}", self.journal_note(d, cr)
            ))

    # =========================================================================
    # --- شاشة الخسائر: إقفال صناديق الخياس (الكاستنج/التلميع/التلميع-البف) عبر قيد يومي ---
    # =========================================================================
    def build_losses_tab(self):
        """شاشة الخسائر: شريط أدوات واحد أعلاها، ثم بطاقة لكل صندوق خياس.

        كل بطاقة: الخياس الحالي والمُقفل جنباً إلى جنب، وزرّا الإقفال وكشف
        الحساب — بلا نصوص تفصيلية تزحم البطاقة (التفصيل في كشف الحساب).
        """
        outer = self.tabview.tab("شاشة الخسائر")
        try:
            outer.configure(fg_color=(UI["canvas"], "#10141A"))
        except Exception:
            pass

        # ====== شريط الأدوات: الفترة + نطاق كشف الحساب + الكشف والطباعة ======
        bar = ctk.CTkFrame(outer, corner_radius=12, fg_color=(UI["surface"], "#171C23"),
                           border_width=1, border_color=(UI["line"], "#2A313B"))
        bar.pack(fill="x", padx=16, pady=(8, 6))

        def bar_label(text):
            ctk.CTkLabel(bar, text=text, font=("Cairo", 13, "bold"),
                         text_color=(UI["primary"], "#9CC0F5")).pack(side="right", padx=(10, 4), pady=10)

        # شريط اختيار الفترة: يعرض الفترات المسجّلة فقط، وكل صندوق يُعرض
        # بأرقام تلك الفترة وحدها
        bar_label("الفترة:")
        self.combo_losses_period = ctk.CTkComboBox(
            bar, values=self.get_recorded_periods(), font=("Cairo", 14),
            width=130, height=34, justify="center", state="readonly",
            command=lambda _v: self.refresh_losses_tab())
        self.combo_losses_period.set(self.current_display_month)
        self.combo_losses_period.pack(side="right", padx=4)
        ctk.CTkButton(bar, text="🔍 بحث", font=("Cairo", 13, "bold"),
                      fg_color=UI["success"], hover_color=UI["success_hover"], width=80, height=34,
                      command=self.refresh_losses_tab).pack(side="right", padx=4)

        ctk.CTkFrame(bar, width=1, height=26, fg_color=(UI["line"], "#2A313B")).pack(side="right", padx=10)
        bar_label("كشف الحساب من:")
        self.losses_from_month = ctk.CTkEntry(bar, placeholder_text="YYYY-MM", font=("Cairo", 13),
                                              justify="center", width=96, height=34)
        self.losses_from_month.pack(side="right", padx=4)
        bar_label("إلى:")
        self.losses_to_month = ctk.CTkEntry(bar, placeholder_text="YYYY-MM", font=("Cairo", 13),
                                            justify="center", width=96, height=34)
        self.losses_to_month.pack(side="right", padx=4)
        ctk.CTkButton(bar, text="↺ الكل", font=("Cairo", 13, "bold"), fg_color=UI["neutral"],
                      hover_color=UI["neutral_hover"], width=70, height=34,
                      command=self.clear_losses_period).pack(side="right", padx=4)

        ctk.CTkButton(bar, text="🖨️ طباعة", font=("Cairo", 13, "bold"), fg_color=UI["navy"],
                      hover_color=UI["navy_hover"], width=100, height=34,
                      command=self.print_losses_screen).pack(side="left", padx=(10, 4))
        ctk.CTkButton(bar, text="📋 كشف حساب الخسائر", font=("Cairo", 13, "bold"), fg_color=UI["primary"],
                      hover_color=UI["primary_hover"], width=170, height=34,
                      command=self.open_losses_statement).pack(side="left", padx=4)

        # البطاقات: إطار يُمرَّر فقط إذا زادت الأقسام المضافة عن مساحة الشاشة
        tab = ctk.CTkScrollableFrame(outer, fg_color="transparent")
        tab.pack(fill="both", expand=True, padx=8, pady=(0, 6))
        self.losses_cards_frame = ctk.CTkFrame(tab, fg_color="transparent")
        self.losses_cards_frame.pack(fill="x", padx=6, pady=4)

        self.losses_card_widgets = {}
        self.refresh_losses_cards()
        self.refresh_losses_tab()

    def clear_losses_period(self):
        self.losses_from_month.delete(0, 'end')
        self.losses_to_month.delete(0, 'end')

    def open_account_statement(self, account_key):
        """يفتح شاشة كشف حساب على حساب معيّن (بنطاق الفترات المكتوب في شاشة الخسائر إن وُجد)"""
        from_m = self.losses_from_month.get().strip() if hasattr(self, 'losses_from_month') else ""
        to_m = self.losses_to_month.get().strip() if hasattr(self, 'losses_to_month') else ""
        self.navigate_to_screen("كشف حساب")
        if hasattr(self, 'kh_account_name'):
            self.kh_account_name.set(account_key)
            if hasattr(self, 'kh_from_month'):
                self.kh_from_month.delete(0, 'end')
                if from_m: self.kh_from_month.insert(0, from_m)
            if hasattr(self, 'kh_to_month'):
                self.kh_to_month.delete(0, 'end')
                if to_m: self.kh_to_month.insert(0, to_m)
            self.refresh_account_statement()

    def open_box_statement(self, cat):
        box_account = self.get_box_account_name(cat)
        from_m = self.losses_from_month.get().strip() if hasattr(self, 'losses_from_month') else ""
        to_m = self.losses_to_month.get().strip() if hasattr(self, 'losses_to_month') else ""
        self.navigate_to_screen("كشف حساب")
        if hasattr(self, 'kh_account_name'):
            self.kh_account_name.set(box_account)
            if hasattr(self, 'kh_from_month'):
                self.kh_from_month.delete(0, 'end')
                if from_m: self.kh_from_month.insert(0, from_m)
            if hasattr(self, 'kh_to_month'):
                self.kh_to_month.delete(0, 'end')
                if to_m: self.kh_to_month.insert(0, to_m)
            self.refresh_account_statement()

    def refresh_losses_cards(self):
        """يعيد بناء لوحات شاشة الخسائر، متضمّناً أي قسم أُضيف ديناميكياً من شجرة الحسابات"""
        for widget in self.losses_cards_frame.winfo_children():
            widget.destroy()
        self.losses_card_widgets = {}

        icons = {"الكاستنج": "🏗️", "المصنعين": "👨‍🏭", "المركبين": "🔧", "التلميع": "✨",
                 "التلميع/البف": "🪄", "خياس الطقوم": "💍"}
        box_defs = [(cat, icons.get(cat, "➕")) for cat in self.get_khayas_box_categories()]

        n_cols = 3
        for c in range(n_cols):
            self.losses_cards_frame.grid_columnconfigure(c, weight=1, uniform="loss_cards")
        for i, (cat, icon) in enumerate(box_defs):
            row, col = divmod(i, n_cols)
            card = ctk.CTkFrame(self.losses_cards_frame, corner_radius=14, border_width=1,
                                border_color=(UI["line"], "#2A313B"), fg_color=(UI["surface"], "#171C23"))
            # من اليمين لليسار
            card.grid(row=row, column=n_cols - 1 - col, padx=8, pady=8, sticky="nsew")

            display_name = self.get_display_label(cat)
            ctk.CTkLabel(card, text=f"{icon}  صندوق خياس {display_name}",
                         font=ctk.CTkFont(family="Cairo", size=16, weight="bold"),
                         text_color=UI_TITLE).pack(pady=(12, 8))

            # أربعة أقسام لكل صندوق: الخياس الحالي، الفاقد (كل الفترات)، المسترجع، الصافي
            stats = ctk.CTkFrame(card, fg_color="transparent")
            stats.pack(fill="x", padx=12)
            stats.grid_columnconfigure((0, 1), weight=1, uniform="stat")

            def stat(row, col, title, fg, soft, account=None):
                box = ctk.CTkFrame(stats, corner_radius=10, fg_color=soft, border_width=1,
                                   border_color=(UI["line"], "#2A313B"))
                box.grid(row=row, column=col, padx=4, pady=4, sticky="nsew")
                title_lbl = ctk.CTkLabel(box, text=title, font=("Cairo", 12, "bold"), wraplength=170,
                                         text_color=(UI["muted"], "#9AA3AF"))
                title_lbl.pack(pady=(6, 0), padx=4)
                val = ctk.CTkLabel(box, text="0.00", font=("Cairo", 19, "bold"), text_color=fg)
                val.pack(pady=(0, 6))
                if account:
                    # النقر على القسم يفتح كشف حسابه (فاقد المرحلة أو مسترجعها أو المرحلة نفسها)
                    for w_ in (box, title_lbl, val):
                        w_.bind("<Button-1>", lambda _e, a=account: self.open_account_statement(a))
                        try:
                            w_.configure(cursor="hand2")
                        except Exception:
                            pass
                return val

            # من اليمين: العمود ١ ثم العمود ٠. عنوانا الفاقد والمسترجع اسما حسابيهما
            # كما في شجرة الحسابات وكشف الحساب (مثلاً «مسترجع كاستنج»)
            loss_account, recovery_account = self.get_box_loss_account(cat), self.get_box_recovery_name(cat)
            # الأقسام الأربعة بلون واحد هادئ (كانت أحمر وذهبي وأزرق وأخضر): العنوان يميّزها
            calm_fg, calm_bg = (UI["title"], "#C9D6E8"), (UI["surface_alt"], "#1D232B")
            lbl_current = stat(0, 1, "الفاقد الحالي", calm_fg, calm_bg, account=self.get_box_account_name(cat))
            lbl_loss = stat(0, 0, loss_account, calm_fg, calm_bg, account=loss_account)
            lbl_recovered = stat(1, 1, recovery_account, calm_fg, calm_bg, account=recovery_account)
            lbl_net = stat(1, 0, "الصافي (الفاقد − المسترجع)", calm_fg, calm_bg)
            ctk.CTkLabel(card, text="الفاقد الحالي للفترة المختارة — والبقية لكل الفترات", font=("Cairo", 11),
                         text_color=(UI["muted"], "#9AA3AF")).pack(pady=(2, 0))

            btns_row = ctk.CTkFrame(card, fg_color="transparent")
            btns_row.pack(pady=(10, 14))
            ctk.CTkButton(btns_row, text="🔒 إقفال الخياس", font=("Cairo", 13, "bold"), fg_color=UI["danger"],
                          hover_color=UI["danger_hover"], width=140, height=36,
                          command=lambda c=cat: self.close_khayas_box(c)).pack(side="right", padx=4)
            ctk.CTkButton(btns_row, text="📋 كشف حساب", font=("Cairo", 13, "bold"), fg_color=UI["primary"],
                          hover_color=UI["primary_hover"], width=120, height=36,
                          command=lambda c=cat: self.open_box_statement(c)).pack(side="right", padx=4)
            self.losses_card_widgets[cat] = {"current": lbl_current, "loss": lbl_loss,
                                             "recovered": lbl_recovered, "net": lbl_net}

    def get_unclosed_periods(self, cat):
        """الفترات **المنتهية** التي ما زال فيها خياس غير مُقفل لهذا القسم.

        الفترة الحالية مستثناة: عملها لم ينتهِ بعد فلا معنى لإقفالها.
        """
        current = self.current_display_month
        out = []
        for month in self.get_recorded_periods():
            if month >= current:
                continue
            remaining = self.get_current_unclosed_khayas(cat, month=month)
            if abs(remaining) >= 0.005:
                out.append((month, remaining))
        return sorted(out)

    def check_unclosed_previous_periods(self):
        """ينبّه عند وجود فترات سابقة لم يُقفل خياسها، ويعرض إقفالها فوراً.

        يُستدعى عند تغيير الفترة: فمن السهل أن ينتقل المستخدم لشهر جديد ناسياً
        إقفال خياس الشهر المنتهي، فيبقى معلّقاً بلا أثر محاسبي.
        """
        pending = []
        for cat in ("المصنعين", "المركبين"):
            for month, amount in self.get_unclosed_periods(cat):
                pending.append((cat, month, amount))
        if not pending:
            return

        lines = "\n".join(
            f"   • {self.get_display_label(c)} — فترة {m}: {en(a)} جم" for c, m, a in pending)
        if not messagebox.askyesno(
                "خياس فترات سابقة لم يُقفل",
                f"هناك خياس فعلي في فترات منتهية لم يُقفل بعد:\n\n{lines}\n\n"
                "الإقفال يُثبّت خياس كل فترة ويُرحّله لحساب فاقد القسم،\n"
                "وتبدأ الفترة الجديدة بخياس جديد خاص بها.\n\n"
                "هل تريد إقفالها الآن؟"):
            return

        # كل إقفال خطوة تراجع مستقلة (يفتحها close_split_khayas_box بعد تأكيده)
        for cat, month, _amount in pending:
            try:
                self.close_split_khayas_box(cat, month=month)
            except Exception as e:
                log_cloud_error(f"تعذّر إقفال خياس ({cat}) لفترة {month}", e)

    def get_recorded_periods(self):
        """الفترات التي سُجّلت فيها حركات فعلاً، الأحدث أولاً"""
        periods = {self.inv_period(inv) for inv in self.invoices.values()
                   if inv.get("settled_status") == "ACTIVE" and self.inv_period(inv)}
        periods.add(self.current_display_month)
        return sorted(periods, reverse=True)

    def refresh_losses_tab(self):
        if not hasattr(self, 'losses_card_widgets') or not self.losses_card_widgets:
            return

        # الفترة المختارة من شريط البحث، وإلا الفترة المعروضة حالياً
        month = self.current_display_month
        if hasattr(self, "combo_losses_period"):
            try:
                self.combo_losses_period.configure(values=self.get_recorded_periods())
                chosen = self.combo_losses_period.get().strip()
                if chosen:
                    month = chosen
            except Exception:
                pass

        for cat, widgets in self.losses_card_widgets.items():
            summary = self.get_box_loss_summary(cat, month=month)
            # العنوان داخل كل قسم، والرقم وحده هنا (التفصيل في كشف حساب الصندوق)
            for key in ("current", "loss", "recovered", "net"):
                widgets[key].configure(text=f"{summary[key]:.2f}")

    def _post_closing_entry(self, box_account_name, amount, bayan, full_dt, period=None, loss_account=None):
        """يسجّل قيد إقفال مزدوجاً (مدين الخسائر / دائن الصندوق أو العكس).

        الفصل في قيود منفصلة مقصود: يظهر في كشف حساب الخسائر سبب كل مبلغ
        (فاقد ٨/٤ أم خياس عمال) بدل مبلغ واحد مجمّع لا يُفسَّر لاحقاً.

        period: **فترة الشهر المُقفَل** لا الفترة المعروضة. بدون تمريرها كان
        القيد يُختم بالفترة التي تعمل فيها وقت الإقفال — فإقفال خياس شهر ٩
        من داخل شهر ١٠ كان يُسجَّل في شهر ١٠، فيختفي من سجل شهر ٩ ويُحمَّل
        على شهر ١٠ ظلماً.
        """
        if abs(amount) < 0.005:
            return
        entry_ref = f"JE-{self.invoice_counter + 1}"
        # الإقفال يُرحَّل لحساب فاقد المرحلة نفسها (لا لحساب خسائر عام)
        loss_account = loss_account or self.LOSS_PARENT_ACCOUNT
        if amount > 0:
            from_name, to_name = loss_account, box_account_name
        else:
            from_name, to_name = box_account_name, loss_account
        value = abs(amount)

        for name, op_type in ((from_name, "قيد يومي مدين"), (to_name, "قيد يومي دائن")):
            self.invoice_counter += 1
            inv = {"رقم الفاتورة": self.invoice_counter, "التاريخ": full_dt, "الاسم": name,
                   "النوع": op_type, "الوزن": value, "البيان": bayan, "settled_status": "ACTIVE",
                   "trees_count": 0.0, "قبل": 0.0, "بعد": 0.0, "set_number": entry_ref}
            if period:
                inv["period"] = period
            self.invoices[self.invoice_counter] = inv
            self.save_invoice_to_db(self.invoice_counter, inv)

    def close_split_khayas_box(self, cat, month=None):
        """إقفال خياس المصنعين/المركبين بمكوّنيه المفصولين في قيدين مستقلين.

        month: الفترة المراد إقفالها (الافتراضي: الفترة المعروضة).
        """
        month = month or self.current_display_month
        display_name = f"{self.get_display_label(cat)} — فترة {month}"
        # مكوّنات المعادلة المعتمدة: (ذهب/باقي − المرجع ٧٥٠) ثم خصم الخياس الموجب
        faqid_k, marja_k, pos_k, total_k = self.get_section_khayas_parts(
            cat, target_month=month)
        net_before_pos = round(faqid_k - marja_k, 2)
        already_closed = self.get_box_closed_total(cat, month=month)
        remaining = round(total_k - already_closed, 2)

        if abs(remaining) < 0.005:
            messagebox.showinfo("لا يوجد خياس",
                                f"لا يوجد خياس غير مُقفل حالياً لصندوق ({display_name}).")
            return

        if not messagebox.askyesno(
                "تأكيد الإقفال",
                f"إقفال خياس صندوق ({display_name}):\n\n"
                f"• ذهب/باقي: {en(faqid_k)} جم\n"
                f"• المرجع ٧٥٠: −{en(marja_k)} جم\n"
                f"• الخياس الموجب: −{en(pos_k)} جم\n"
                f"• الإجمالي: {en(total_k)} جم\n"
                f"• سبق إقفاله: {en(already_closed)} جم\n"
                f"• المتبقّي للإقفال الآن: {en(remaining)} جم\n\n"
                f"سيُرحَّل المتبقّي إلى حساب «{self.get_box_loss_account(cat)}» بقيدين منفصلين. هل تريد المتابعة؟"):
            return

        box_account_name = self.get_box_account_name(cat)
        # تاريخ القيد: آخر يوم في الشهر المُقفَل، فيظهر في نهاية سجل فترته
        # بدل أن يبدو حركةً من شهر لاحق
        full_dt = self.period_closing_datetime(month)
        self.push_undo(f"إقفال {self.get_display_label(cat)} {month}")

        # نوزّع المتبقّي على مكوّنَي المعادلة بنسبتهما، فلا يُقفل شيء أُقفل
        # سابقاً، ويبقى مجموع القيدين = المتبقّي بالضبط
        if abs(total_k) > 0.005:
            share_net = round(remaining * (net_before_pos / total_k), 2)
        else:
            share_net = remaining
        share_pos = round(remaining - share_net, 2)

        # قيدان يوضّحان سبب المبلغ في كشف الخسائر، ومجموعهما = الخياس الفعلي
        loss_account = self.get_box_loss_account(cat)
        self._post_closing_entry(box_account_name, share_net,
                                 f"إقفال خياس (ذهب/باقي − المرجع ٧٥٠) — فترة {month}",
                                 full_dt, period=month, loss_account=loss_account)
        self._post_closing_entry(box_account_name, share_pos,
                                 f"إقفال خصم الخياس الموجب — فترة {month}",
                                 full_dt, period=month, loss_account=loss_account)

        self.recalculate_all()
        messagebox.showinfo(
            "تم الإقفال",
            f"تم إقفال خياس صندوق ({display_name}):\n"
            f"(ذهب/باقي − المرجع ٧٥٠): {en(share_net)} جم  |  "
            f"خصم الخياس الموجب: {en(share_pos)} جم")
        self.refresh_losses_tab()

    def close_khayas_box(self, cat, month=None):
        # المصنعون والمركبون لهم مكوّنان مفصولان، فيُقفلان بمسار مستقل
        month = month or self.current_display_month
        if cat in ("المصنعين", "المركبين"):
            return self.close_split_khayas_box(cat, month=month)

        current = self.get_current_unclosed_khayas(cat, month=month)
        display_name = self.get_display_label(cat)
        if abs(current) < 0.005:
            messagebox.showinfo("لا يوجد خياس", f"لا يوجد فاقد حالي غير مُقفل لصندوق ({display_name}) في فترة {month}.")
            return
        box_account_name = self.get_box_account_name(cat)

        loss_account = self.get_box_loss_account(cat)
        if not messagebox.askyesno(
                "تأكيد الإقفال",
                f"إقفال الفاقد الحالي لصندوق ({display_name}) — فترة {month}: {current:.2f} جم\n\n"
                f"يُرحَّل إلى حساب «{loss_account}» بقيد يومي، ويبدأ الصندوق بفاقد جديد.\n"
                "هل تريد المتابعة؟"):
            return

        # القيد يُؤرَّخ في آخر الفترة المُقفَلة ويُختم بها، فيبقى في سجلّها
        full_dt = self.period_closing_datetime(month)
        self.push_undo(f"إقفال {display_name} {month}")
        entry_ref = f"JE-{self.invoice_counter + 1}"
        bayan = f"إقفال فاقد فترة {month}"
        amount = abs(current)

        # current موجب (فاقد عادي): مدين فاقد المرحلة / دائن المرحلة
        # current سالب (زيادة): عكسه — دائن فاقد المرحلة / مدين المرحلة
        if current > 0:
            from_name, to_name = loss_account, box_account_name
        else:
            from_name, to_name = box_account_name, loss_account

        self.invoice_counter += 1
        inv_from = {"رقم الفاتورة": self.invoice_counter, "التاريخ": full_dt, "الاسم": from_name,
                    "النوع": "قيد يومي مدين", "الوزن": amount, "البيان": bayan, "settled_status": "ACTIVE",
                    "trees_count": 0.0, "قبل": 0.0, "بعد": 0.0, "set_number": entry_ref, "period": month}
        self.invoices[self.invoice_counter] = inv_from
        self.save_invoice_to_db(self.invoice_counter, inv_from)

        self.invoice_counter += 1
        inv_to = {"رقم الفاتورة": self.invoice_counter, "التاريخ": full_dt, "الاسم": to_name,
                  "النوع": "قيد يومي دائن", "الوزن": amount, "البيان": bayan, "settled_status": "ACTIVE",
                  "trees_count": 0.0, "قبل": 0.0, "بعد": 0.0, "set_number": entry_ref, "period": month}
        self.invoices[self.invoice_counter] = inv_to
        self.save_invoice_to_db(self.invoice_counter, inv_to)

        self.recalculate_all()
        messagebox.showinfo("تم الإقفال", f"تم إقفال فاقد صندوق ({display_name}) وترحيله إلى «{loss_account}».")
        self.refresh_losses_tab()

    def open_losses_statement(self):
        self.navigate_to_screen("كشف حساب")
        if hasattr(self, 'kh_account_name'):
            self.kh_account_name.set("حساب الخسائر")
            self.refresh_account_statement()

    def print_losses_screen(self):
        """يولّد وعرض/يطبع صفحة PDF بنفس شكل شاشة الخسائر (لوحات لكل صندوق: الخياس الحالي + إجمالي المُقفل)"""
        if not REPORTLAB_AVAILABLE:
            messagebox.showerror("غير متاح", "ميزة الطباعة تحتاج تثبيت مكتبة reportlab أولاً:\npip install reportlab arabic-reshaper python-bidi")
            return
        out_dir = INVOICES_DIR
        out_path = os.path.join(out_dir, f"losses_screen_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}.pdf")

        from reportlab.lib.colors import Color
        PW, PH = A4
        M = 10 * mm
        border_color = Color(0.55, 0.10, 0.10)

        def txt(c, x, y, s, size=9, bold=False, align="right", color=None):
            c.setFont(_ARABIC_FONT_BOLD_NAME if bold else _ARABIC_FONT_NAME, size)
            if color: c.setFillColor(color)
            s = ar(s)
            if align == "right": c.drawRightString(x, y, s)
            elif align == "left": c.drawString(x, y, s)
            else: c.drawCentredString(x, y, s)
            if color: c.setFillColorRGB(0, 0, 0)

        c = pdf_canvas.Canvas(out_path, pagesize=A4)
        y = PH - M

        txt(c, M, y - 6, "Jadeite Factory", size=12, bold=True, align="left")
        txt(c, M, y - 13, "Saudi Arabia, Riyadh", size=8, align="left")
        txt(c, PW - M, y - 6, "مصنع جاديت للتصنيع", size=12, bold=True, align="right")
        txt(c, PW - M, y - 13, "المملكة العربية السعودية", size=8, align="right")
        logo_bottom = y - 13
        try:
            logo_bytes = base64.b64decode(APP_LOGO_B64)
            logo_img = ImageReader(io.BytesIO(logo_bytes))
            lw, lh = 45 * mm, 10 * mm
            logo_top = y - 4
            logo_bottom = logo_top - lh
            c.drawImage(logo_img, (PW - lw) / 2, logo_bottom, width=lw, height=lh, mask='auto', preserveAspectRatio=True)
        except Exception:
            pass
        y = min(y - 13, logo_bottom) - 9 * mm

        # الفترة نفسها المعروضة في الشاشة (شريط البحث)، وإلا الفترة الحالية
        month = self.current_display_month
        try:
            if hasattr(self, "combo_losses_period"):
                month = self.combo_losses_period.get().strip() or month
        except Exception:
            pass

        txt(c, PW / 2, y, "شاشة الخسائر - إقفال صناديق الخياس", size=17, bold=True, align="center", color=border_color)
        y -= 8 * mm
        txt(c, PW / 2, y, f"الفاقد الحالي لفترة {month} — والبقية لكل الفترات  |  "
                          f"تاريخ الطباعة: {datetime.datetime.now().strftime('%Y-%m-%d %H:%M')}", size=10, align="center")
        y -= 8 * mm

        box_defs = [(cat, self.get_display_label(cat)) for cat in self.get_khayas_box_categories()]

        n_cols = 3
        card_w = (PW - 2 * M - 2 * 6 * mm) / n_cols
        card_h = 40 * mm         # العنوان + الأقسام الأربعة
        gap = 6 * mm

        for i, (cat, disp) in enumerate(box_defs):
            row, col = divmod(i, n_cols)
            # من اليمين لليسار كما في الشاشة: أول صندوق في أقصى اليمين
            cx0 = M + (n_cols - 1 - col) * (card_w + gap)
            cy0 = y - row * (card_h + gap)
            c.setStrokeColor(border_color)
            c.rect(cx0, cy0 - card_h, card_w, card_h, fill=0, stroke=1)
            title = f"صندوق خياس {disp}"
            txt(c, cx0 + card_w / 2, cy0 - 8 * mm, title,
                size=12 if len(title) <= 22 else 10 if len(title) <= 26 else 8.5,
                bold=True, align="center", color=border_color)
            sm = self.get_box_loss_summary(cat, month=month)
            for k, (label, key) in enumerate((("الفاقد الحالي", "current"), (self.get_box_loss_account(cat), "loss"),
                                              (self.get_box_recovery_name(cat), "recovered"), ("الصافي", "net"))):
                txt(c, cx0 + card_w / 2, cy0 - (15 + 6 * k) * mm, f"{label}: {sm[key]:.2f}",
                    size=10, bold=(key == "net"), align="center")

        c.showPage()
        c.save()
        self._open_file(out_path)

    # =========================================================================
    # --- شجرة الحسابات: عرض هرمي لكل حسابات النظام مصنّفة، مع الانتقال المباشر لكشف حسابها ---
    # =========================================================================
    def build_chart_of_accounts_tab(self):
        tab = self.tabview.tab("الحسابات")

        ctk.CTkLabel(tab, text="🌳 الحسابات", font=ctk.CTkFont(family="Cairo", size=18, weight="bold"), text_color="#d4af37").pack(pady=(15, 8))
        ctk.CTkLabel(tab, text="اضغط مرتين على أي حساب فرعي لفتح كشف حسابه مباشرة", font=("Cairo", 12), text_color="#aaaaaa").pack(pady=(0, 8))

        tree_frame = ttk.Frame(tab)
        tree_frame.pack(fill="both", expand=True, padx=20, pady=10)

        # نمطها الخاص Accounts.Treeview (خط أكبر قليلاً): كانت تغيّر خط **كل** جداول
        # النظام وارتفاع صفوفها بمجرد فتح هذه الشاشة
        self.coa_tree = ttk.Treeview(tree_frame, show="tree", selectmode="browse",
                                     style="Accounts.Treeview")
        self.enable_row_hover(self.coa_tree)
        self.coa_tree.pack(side="right", fill="both", expand=True)
        vsb = self.make_scrollbar(tree_frame, "vertical", self.coa_tree.yview)
        vsb.pack(side="left", fill="y")
        self.coa_tree.configure(yscrollcommand=vsb.set)
        # ألوانها القديمة تُترجَم للون مقروء في كل مظهر (normalize_tree_tags)
        self.coa_tree.tag_configure("group", foreground="#d4af37")
        self.coa_tree.tag_configure("leaf", foreground="#1f77b4")
        self.style_tree_rows(self.coa_tree)

        self.coa_tree.bind("<Double-1>", self.on_coa_double_click)

        btn_row = ctk.CTkFrame(tab, fg_color="transparent")
        btn_row.pack(pady=(0, 12))
        ctk.CTkButton(btn_row, text="↺ تحديث الشجرة", font=("Cairo", 13, "bold"), fg_color="#1e8449", hover_color="#145a32", width=140, height=38, command=self.refresh_chart_of_accounts).pack(side="left", padx=5)
        ctk.CTkButton(btn_row, text="➕ إضافة حساب", font=("Cairo", 13, "bold"), fg_color="#1f77b4", hover_color="#144d75", width=140, height=38, command=self.open_add_account_dialog).pack(side="left", padx=5)
        ctk.CTkButton(btn_row, text="🗑️ حذف صندوق خياس", font=("Cairo", 13, "bold"), fg_color="#8b0000", hover_color="#a52a2a", width=170, height=38, command=self.delete_khayas_box_dialog).pack(side="left", padx=5)

        self.refresh_chart_of_accounts()

    def get_deletable_khayas_boxes(self):
        """كل صناديق الخياس قابلة للحذف — الأساسية والمضافة.

        تنبيه: حذف صندوق أساسي يحذف حركاته ومسترجعه ويغيّر رصيد الخزينة
        وإجمالي الفواقد، ويُخفي شاشته من مراحل التصنيع. نافذة الحذف تعرض
        عدد حركاته وتطلب تأكيدين قبل التنفيذ.
        """
        return list(self.get_all_stage_categories())

    def count_box_transactions(self, stage_name):
        """عدد الحركات المرتبطة بالصندوق (صرف/قبض/مسترجع/قيود حسابه)"""
        madin, qabd, mustarja = self.get_stage_config(stage_name)
        box_account = self.get_box_account_name(stage_name)
        n = 0
        for inv in self.invoices.values():
            t = inv.get("النوع")
            name = inv.get("الاسم")
            if t in (madin, qabd) or name == mustarja or name == box_account or name == stage_name:
                n += 1
        return n

    def delete_khayas_box_dialog(self):
        """حذف صندوق خياس مضاف، مع كل ما يخصه: حركاته ومسترجعه وحسابه وعمّاله"""
        boxes = self.get_deletable_khayas_boxes()
        if not boxes:
            messagebox.showinfo(
                "لا يوجد",
                "لا توجد صناديق خياس مضافة يمكن حذفها.\n\n"
                "الصناديق الأساسية (الكاستنج، التلميع، التلميع/البف، خياس الطقوم) "
                "مرتبطة بمنطق النظام ولا يمكن حذفها.")
            return

        win = ctk.CTkToplevel(self)
        win.title("حذف صندوق خياس")
        win.geometry("460x360")
        win.transient(self)
        win.grab_set()
        win.focus_force()

        ctk.CTkLabel(win, text="🗑️ حذف صندوق خياس", font=("Cairo", 18, "bold"),
                     text_color="#e74c3c").pack(pady=(16, 4))
        ctk.CTkLabel(win, text="سيُحذف الصندوق وكل ما يخصه نهائياً", font=("Cairo", 12),
                     text_color="#8b8f95").pack(pady=(0, 12))

        combo = ctk.CTkComboBox(win, values=boxes, font=("Cairo", 15), justify="right",
                                width=280, height=40, state="readonly")
        combo.set(boxes[0])
        combo.pack(pady=6)

        lbl_info = ctk.CTkLabel(win, text="", font=("Cairo", 12, "bold"), text_color="#e67e22",
                                wraplength=400, justify="center")
        lbl_info.pack(pady=10)

        def refresh_info(_=None):
            box = combo.get()
            n = self.count_box_transactions(box)
            lbl_info.configure(
                text=f"الحركات المرتبطة بهذا الصندوق: {n}" if n
                else "لا توجد حركات مرتبطة — الحذف آمن تماماً")

        combo.configure(command=refresh_info)
        refresh_info()

        def do_delete():
            box = combo.get()
            n = self.count_box_transactions(box)
            if not messagebox.askyesno(
                    "تأكيد الحذف النهائي",
                    f"سيتم حذف صندوق ({box}) نهائياً، ومعه:\n\n"
                    f"• {n} حركة مسجّلة (صرف/قبض/مسترجع/قيود)\n"
                    f"• حساب المسترجع الخاص به\n"
                    f"• شاشته في مراحل التصنيع وصناديق الخياس وشاشة الخسائر\n\n"
                    "لا يمكن التراجع عن هذه العملية. هل أنت متأكد؟", parent=win):
                return

            if n > 0 and not messagebox.askyesno(
                    "تحذير أخير",
                    f"هذا الصندوق عليه {n} حركة محاسبية مسجّلة.\n"
                    "حذفها سيغيّر رصيد الخزينة وإجمالي الفواقد.\n\n"
                    "هل تريد المتابعة فعلاً؟", parent=win):
                return

            self.perform_khayas_box_deletion(box)
            win.destroy()

        ctk.CTkButton(win, text="🗑️ حذف نهائياً", font=("Cairo", 15, "bold"), fg_color="#8b0000",
                      hover_color="#a52a2a", width=180, height=42, command=do_delete).pack(pady=8)
        ctk.CTkButton(win, text="إلغاء", font=("Cairo", 13), fg_color="#555555",
                      hover_color="#333333", width=120, height=34, command=win.destroy).pack()

    def perform_khayas_box_deletion(self, stage_name):
        """التنفيذ الفعلي للحذف: الحركات ثم الحسابات ثم إعادة بناء الشاشات"""
        # خطوة تراجع واحدة تضمّ الحركات والعمّال والقسم معاً
        step = self.push_undo(f"حذف صندوق ({stage_name})")
        if step is not None and stage_name in self.categories:
            step["cats"].append(stage_name)
        madin, qabd, mustarja = self.get_stage_config(stage_name)
        box_account = self.get_box_account_name(stage_name)

        # ١) حذف كل الحركات المرتبطة
        to_delete = [inv["رقم الفاتورة"] for inv in self.invoices.values()
                     if inv.get("النوع") in (madin, qabd)
                     or inv.get("الاسم") in (mustarja, box_account, stage_name)]
        blocked = 0
        for inv_id in to_delete:
            if not self.delete_invoice_from_db(inv_id):
                blocked += 1

        # ٢) حذف عمّال القسم من شجرة الحسابات
        for worker in list(self.categories.get(stage_name, [])):
            # هنا الحذف الكامل مقصود: المستخدم أكّد على عدد حركات الصندوق
            self.delete_worker_from_db(worker, stage_name, keep_transactions=False)
        self.categories.pop(stage_name, None)

        # ٣) حذف القسم نفسه
        if stage_name in self.categories.get("أقسام_خياس_إضافية", []):
            self.categories["أقسام_خياس_إضافية"].remove(stage_name)
        self.delete_worker_from_db(stage_name, "أقسام_خياس_إضافية")

        # ٤) إزالة إعداداته المحفوظة (لون التلوين مثلاً) حتى لا تتراكم
        try:
            self.set_setting(f"neg_color_{stage_name}", "")
        except Exception:
            pass

        # ٥) إعادة بناء كل الشاشات المرتبطة
        for fn in ("refresh_stage_buttons", "refresh_khayas_category_buttons",
                   "refresh_losses_cards", "refresh_chart_of_accounts"):
            if hasattr(self, fn):
                try:
                    getattr(self, fn)()
                except Exception as e:
                    log_cloud_error(f"تعذّر تحديث {fn} بعد حذف الصندوق", e)

        self.update_period_selector()
        self.recalculate_all()

        msg = f"تم حذف صندوق ({stage_name}) وكل ما يخصه."
        if blocked:
            msg += f"\n\nتنبيه: تعذّر حذف {blocked} حركة (التعديل مقفول من المدير)."
        messagebox.showinfo("تم الحذف", msg)

    def open_add_account_dialog(self):
        # تحديد الفرع المختار حالياً بالشجرة (إن وجد) لمعرفة نوع الحساب المطلوب إضافته
        selected_branch = None
        if hasattr(self, 'coa_tree') and self.coa_tree:
            sel = self.coa_tree.selection()
            if sel:
                item = sel[0]
                tags = self.coa_tree.item(item, "tags")
                if "group" in tags:
                    selected_branch = self.coa_tree.item(item, "text")
                else:
                    parent = self.coa_tree.parent(item)
                    if parent:
                        selected_branch = self.coa_tree.item(parent, "text")

        is_khayas_branch = bool(selected_branch and "صناديق الخياس" in selected_branch)

        win = ctk.CTkToplevel(self)
        win.title("إضافة حساب جديد")
        win.geometry("420x260")
        win.transient(self)
        win.grab_set()
        win.focus_force()

        ctk.CTkLabel(win, text="➕ إضافة حساب جديد", font=("Cairo", 16, "bold"), text_color="#d4af37").pack(pady=(20, 6))
        if selected_branch:
            ctk.CTkLabel(win, text=f"الفرع المحدد: {selected_branch}", font=("Cairo", 12, "bold"), text_color="#aaaaaa").pack(pady=(0, 6))
        if is_khayas_branch:
            ctk.CTkLabel(win, text="سيُضاف كصندوق خياس فعّال بصرف/قبض خاص به\nويظهر في مراحل التصنيع وصناديق الخياس وشاشة الخسائر", font=("Cairo", 11), text_color="#2ecc71").pack(pady=(0, 6))

        ctk.CTkLabel(win, text="اسم الحساب:", font=("Cairo", 13, "bold"), text_color="#1f77b4").pack(pady=(5, 3))
        entry = ctk.CTkEntry(win, font=("Cairo", 14), justify="right", width=280, height=38)
        entry.pack(pady=5)
        entry.focus_set()

        lbl_status = ctk.CTkLabel(win, text="", font=("Cairo", 12, "bold"), text_color="#e74c3c")
        lbl_status.pack(pady=3)

        def do_add():
            name = entry.get().strip()
            if not name:
                lbl_status.configure(text="الرجاء إدخال اسم الحساب.")
                return
            all_existing = self.get_account_statement_options()
            if name in all_existing:
                lbl_status.configure(text="هذا الاسم موجود مسبقاً كحساب بالنظام.")
                return

            if is_khayas_branch:
                self.categories.setdefault("أقسام_خياس_إضافية", []).append(name)
                self.save_name_to_db(name, "أقسام_خياس_إضافية")
                self.categories.setdefault(name, [])
                # إعادة بناء كل الشاشات المرتبطة لتضمين القسم الجديد فوراً
                if hasattr(self, 'refresh_stage_buttons'):
                    self.refresh_stage_buttons()
                if hasattr(self, 'refresh_khayas_category_buttons'):
                    self.refresh_khayas_category_buttons()
                if hasattr(self, 'refresh_losses_cards'):
                    self.refresh_losses_cards()
            else:
                self.categories.setdefault("حسابات إضافية", []).append(name)
                self.save_name_to_db(name, "حسابات إضافية")

            self.refresh_chart_of_accounts()
            if hasattr(self, 'refresh_journal_entries_table'):
                self.refresh_journal_entries_table()
            self.recalculate_all()
            extra_msg = "\nصار بإمكانك تسجيل صرف/قبض له من شاشة مراحل التصنيع." if is_khayas_branch else ""
            messagebox.showinfo("تم", f"تمت إضافة الحساب ({name}) بنجاح.{extra_msg}")
            win.destroy()

        entry.bind("<Return>", lambda e: do_add())
        ctk.CTkButton(win, text="✅ إضافة", font=("Cairo", 14, "bold"), fg_color="#1e8449", hover_color="#145a32", width=150, height=40, command=do_add).pack(pady=15)

    def refresh_chart_of_accounts(self):
        if not hasattr(self, 'coa_tree') or not self.coa_tree:
            return
        for item in self.coa_tree.get_children():
            self.coa_tree.delete(item)

        def add_group(label):
            return self.coa_tree.insert("", "end", text=label, open=True, tags=("group",))

        def add_leaf(parent, label, open_=False):
            return self.coa_tree.insert(parent, "end", text=label, open=open_, tags=("leaf",))

        # حساب الخزينة
        g_treasury = add_group("💰 حساب الخزينة")
        add_leaf(g_treasury, "حساب الخزينة")

        # حسابات المواد
        g_materials = add_group("📦 حسابات المواد")
        for acc in ["حساب الذهب", "حساب الألماس", "حساب فصوص وأحجار"]:
            add_leaf(g_materials, acc)

        # صناديق الخياس: كل مرحلة حسابها (الفاقد الحالي) ومعه حسابا «فاقد» و«مسترجع» المرحلة
        g_khayas = add_group("🏗️ صناديق الخياس")
        for cat in self.get_khayas_box_categories():
            stage = add_leaf(g_khayas, self.get_box_account_name(cat), open_=True)
            add_leaf(stage, self.get_box_loss_account(cat))
            recovery = self.get_box_recovery_name(cat)
            if recovery:
                add_leaf(stage, recovery)

        # حساب الخسائر: إجمالي حسابات فاقد المراحل (كشفه يجمعها كلها)
        g_losses = add_group("📉 حساب الخسائر (إجمالي فاقد المراحل)")
        add_leaf(g_losses, "حساب الخسائر")

        # رصيد افتتاحي: طرف القيود اليومية لربط أي حساب برصيده الافتتاحي
        g_opening = add_group("🔢 رصيد افتتاحي")
        add_leaf(g_opening, self.OPENING_ACCOUNT)

        # المبيعات
        g_sales = add_group("🧾 المبيعات")
        add_leaf(g_sales, "المبيعات")

        # حسابات الموردين
        g_suppliers = add_group("👥 حسابات الموردين")
        for acc in sorted(self.categories.get("الموردين", [])):
            add_leaf(g_suppliers, acc)

        # حسابات أُضيفت يدوياً من شجرة الحسابات
        manual_accounts = sorted(self.categories.get("حسابات إضافية", []))
        if manual_accounts:
            g_manual = add_group("➕ حسابات مُضافة يدوياً")
            for acc in manual_accounts:
                add_leaf(g_manual, acc)

        # حسابات أخرى (أي اسم جديد استُخدم بقيد يومي وليس ضمن ما سبق)
        known_names = set()
        for cat in self.get_khayas_box_categories():
            known_names.add(self.get_box_account_name(cat))
        known_names |= {"حساب الخزينة", "حساب الذهب", "حساب الألماس", "حساب فصوص وأحجار",
                         "حساب الخسائر", "المبيعات", self.OPENING_ACCOUNT} | set(self.get_all_mustarja_names())
        known_names |= set(self.get_all_loss_accounts())
        known_names |= set(self.categories.get("الموردين", []))
        known_names |= set(manual_accounts)

        extra_names = set()
        for inv in self.invoices.values():
            if inv.get("settled_status") != "ACTIVE": continue
            if inv.get("النوع") in ("قيد يومي مدين", "قيد يومي دائن"):
                nm = inv.get("الاسم", "")
                if nm and nm not in known_names:
                    extra_names.add(nm)
        if extra_names:
            g_other = add_group("🔹 حسابات أخرى (من القيود اليومية)")
            for acc in sorted(extra_names):
                add_leaf(g_other, acc)

    def on_coa_double_click(self, event=None):
        if not (hasattr(self, 'coa_tree') and self.coa_tree):
            return
        sel = self.coa_tree.selection()
        if not sel:
            return
        item = sel[0]
        if "leaf" not in self.coa_tree.item(item, "tags"):
            return
        account_name = self.coa_tree.item(item, "text")
        self.navigate_to_screen("كشف حساب")
        if hasattr(self, 'kh_account_name'):
            self.kh_account_name.set(account_name)
            self.refresh_account_statement()

    # =========================================================================
    # --- أرشيف الفواتير: بحث + عرض + إعادة معاينة/طباعة أي فاتورة مرحّلة سابقاً ---
    # =========================================================================
    def get_all_invoice_groups(self):
        """يرجع كل مجموعات فواتير المبيعات المرحّلة (فاتورة مستقلة لكل رقم تشغيل/تاريخ/اسم) للأرشفة والبحث"""
        sale_types = ["مبيعات ذهب", "مبيعات ذهب مع الماس", "مبيعات فصوص وأحجار", "مبيعات الماس"]
        seen = {}
        for inv in self.invoices.values():
            if inv.get("settled_status") not in ("ACTIVE", "SETTLED_INOUT"): continue
            if inv.get("النوع") not in sale_types: continue
            key = (inv.get("set_number", ""), inv.get("التاريخ", ""), inv.get("الاسم", ""))
            inv_no = inv.get("رقم الفاتورة", 0)
            if key not in seen or inv_no < seen[key]["invoice_no"]:
                seen[key] = {"set_number": key[0], "date": key[1], "name": key[2], "invoice_no": inv_no,
                             "manual_no": inv.get("رقم الفاتورة اليدوي", "") or ""}
        return sorted(seen.values(), key=lambda g: (g["date"], g["invoice_no"]), reverse=True)

    def build_invoice_archive_tab(self):
        tab = self.tabview.tab("أرشيف الفواتير")

        ctk.CTkLabel(tab, text="🗂️ أرشيف الفواتير", font=ctk.CTkFont(family="Cairo", size=18, weight="bold"), text_color="#d4af37").pack(pady=(15, 6))

        search_row = ctk.CTkFrame(tab, fg_color="transparent")
        search_row.pack(fill="x", padx=20, pady=6)

        ctk.CTkLabel(search_row, text="رقم الفاتورة:", font=("Cairo", 13, "bold"), text_color="#1f77b4").pack(side="right", padx=5)
        self.archive_search_invoice = ctk.CTkEntry(search_row, justify="center", font=("Cairo", 14), width=110, height=36)
        self.archive_search_invoice.pack(side="right", padx=5)

